#[derive(Clone, Copy)]
struct HashPatternPhysicalRange<'key> {
    prefix: &'key [u8],
    lower: Bound<&'key [u8]>,
    upper: Bound<&'key [u8]>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RelationalFormat {
    InlineRowV1,
    VersionChainV2,
}

impl RelationalFormat {
    const fn marker(self) -> &'static [u8] {
        match self {
            Self::InlineRowV1 => RELATIONAL_FORMAT_VALUE_V1,
            Self::VersionChainV2 => RELATIONAL_FORMAT_VALUE_V2,
        }
    }

    fn decode(marker: &[u8]) -> Result<Self, NativeRuntimeError> {
        match marker {
            RELATIONAL_FORMAT_VALUE_V1 => Ok(Self::InlineRowV1),
            RELATIONAL_FORMAT_VALUE_V2 => Ok(Self::VersionChainV2),
            _ => Err(NativeRuntimeError::InvalidRelationalTree),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StructureFormat {
    InlineStateV1,
    BTreeV1,
    BTreeV2,
    BTreeV3,
}

impl StructureFormat {
    const fn uses_legacy_collection_layout(self) -> bool {
        matches!(self, Self::BTreeV1 | Self::BTreeV2)
    }

    const fn uses_ordered_expiry_index(self) -> bool {
        matches!(self, Self::BTreeV2 | Self::BTreeV3)
    }

    const fn supports_collection_retirement(self) -> bool {
        matches!(self, Self::BTreeV2 | Self::BTreeV3)
    }

    const fn supports_materialized_collection_writes(self) -> bool {
        matches!(self, Self::BTreeV1 | Self::BTreeV2 | Self::BTreeV3)
    }

    const fn marker(self) -> Option<&'static [u8]> {
        match self {
            Self::InlineStateV1 => None,
            Self::BTreeV1 => Some(STRUCTURE_FORMAT_VALUE_V1),
            Self::BTreeV2 => Some(STRUCTURE_FORMAT_VALUE_V2),
            Self::BTreeV3 => Some(structure_v3::STRUCTURE_FORMAT_VALUE_V3),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum SearchFormat {
    InlineStateV1,
    InvertedBTreeV1,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum PhysicalSearchFormat {
    V1,
    V2,
    V3,
}

impl PhysicalSearchFormat {
    const fn admits_tombstones(self) -> bool {
        matches!(self, Self::V2 | Self::V3)
    }

    fn decode(marker: &[u8]) -> Result<Self, NativeRuntimeError> {
        match marker {
            SEARCH_FORMAT_VALUE_V1 => Ok(Self::V1),
            SEARCH_FORMAT_VALUE_V2 => Ok(Self::V2),
            SEARCH_FORMAT_VALUE_V3 => Ok(Self::V3),
            _ => Err(NativeRuntimeError::InvalidSearchTree),
        }
    }
}

/// Native runtime or recovery failure.
#[derive(Debug, Error)]
pub enum NativeRuntimeError {
    /// The shared Native resource governor rejected this unit of work.
    #[error(transparent)]
    ResourceAdmission(#[from] GovernorAdmissionError),
    /// The bounded shared admission queue rejected or cancelled this work.
    #[error(transparent)]
    ResourceQueue(#[from] GovernorQueueError),
    /// The shared persistent execution pool failed closed.
    #[error(transparent)]
    Execution(#[from] NativeExecutionError),
    /// Native binary-glob compilation, request validation, or matching failed.
    #[error(transparent)]
    HashPattern(#[from] HashPatternError),
    /// Native set-algebra request validation or execution failed.
    #[error(transparent)]
    SetAlgebra(#[from] SetAlgebraError),
    /// Native ANN validation, construction, or query failed.
    #[error(transparent)]
    Ann(#[from] hyphae_native_ann::AnnError),
    /// Filesystem operation outside the page/WAL files failed.
    #[error(transparent)]
    Io(#[from] std::io::Error),
    /// Native data-directory validation or single-writer ownership failed.
    #[error(transparent)]
    Directory(#[from] NativeDirectoryError),
    /// Native page storage failed.
    #[error(transparent)]
    Page(#[from] PageStoreError),
    /// Native buffer-pool access failed.
    #[error(transparent)]
    BufferPool(#[from] BufferPoolError),
    /// Native immutable blob storage failed.
    #[error(transparent)]
    Blob(#[from] BlobError),
    /// Native relational B+tree storage failed.
    #[error(transparent)]
    BTree(#[from] BTreeError),
    /// Native canonical row-record handling failed.
    #[error(transparent)]
    Record(#[from] RecordError),
    /// Native WAL framing failed.
    #[error(transparent)]
    Wal(#[from] WalError),
    /// Native WAL transaction semantics failed.
    #[error("native transaction WAL semantics failed: {0}")]
    WalSemantic(String),
    /// Native MVCC coordination failed.
    #[error(transparent)]
    Mvcc(#[from] MvccError),
    /// First-committer-wins rejected a stale logical write.
    #[error(transparent)]
    WriteConflict(#[from] WriteConflict),
    /// Native immutable root-manifest handling failed.
    #[error(transparent)]
    Manifest(#[from] ManifestError),
    /// Native durable snapshot-pin handling failed.
    #[error(transparent)]
    SnapshotPin(#[from] SnapshotPinError),
    /// Catalog definition validation failed.
    #[error(transparent)]
    Catalog(#[from] CatalogError),
    /// Engine-state codec or semantic validation failed.
    #[error("native engine state failed: {0}")]
    Model(String),
    /// A non-null native unique secondary-index key already identifies a row.
    #[error("native relational unique secondary index is violated")]
    UniqueSecondaryIndexViolation,
    /// One persisted relation CHECK predicate rejected a row.
    #[error("native relational CHECK constraint is violated")]
    CheckConstraintViolation,
    /// One immediate relation foreign key is violated.
    #[error("native relational FOREIGN KEY constraint is violated")]
    ForeignKeyConstraintViolation,
    /// The requested native secondary index does not exist in the current root.
    #[error("native relational secondary index {index} does not exist")]
    UnknownSecondaryIndex {
        /// Stable catalog identity requested by the caller.
        index: ObjectId,
    },
    /// The requested native relation does not exist in the current root.
    #[error("native relation {table} does not exist")]
    UnknownRelation {
        /// Stable catalog identity requested by the caller.
        table: ObjectId,
    },
    /// The requested data directory already exists.
    #[error("native data directory already exists")]
    DataDirectoryExists,
    /// A page-generation-like directory entry is not one canonical filename.
    #[error("native data directory contains a noncanonical page-generation entry")]
    UnexpectedPageGenerationEntry,
    /// A committed root is missing or has the wrong page kind.
    #[error("committed native root is missing or has the wrong page kind")]
    InvalidCommittedRoot,
    /// A committed page was created after the commit that references it.
    #[error("committed native page has a future creating CSN")]
    FuturePage,
    /// The catalog B+tree contains malformed or cross-linked namespace entries.
    #[error("native catalog B+tree namespace is invalid")]
    InvalidCatalogTree,
    /// Logical V2 catalog APIs require a `HYCAT006` catalog root.
    #[error("logical catalog V2 is unavailable on this legacy catalog snapshot")]
    CatalogV2Unavailable,
    /// One bounded catalog request has zero or above-contract limits.
    #[error("native catalog read limits are invalid")]
    InvalidCatalogReadLimit,
    /// A catalog snapshot belongs to another native directory lineage.
    #[error("native catalog snapshot belongs to another directory")]
    CatalogSnapshotMismatch,
    /// The relational B+tree contains malformed namespace keys or markers.
    #[error("native relational B+tree namespace is invalid")]
    InvalidRelationalTree,
    /// The structure B+tree contains malformed namespace keys or values.
    #[error("native structure B+tree namespace is invalid")]
    InvalidStructureTree,
    /// The lexical-search B+tree contains malformed metadata or postings.
    #[error("native lexical-search B+tree namespace is invalid")]
    InvalidSearchTree,
    /// The ANN B+tree namespace or canonical graph generation is invalid.
    #[error("native ANN tree is invalid")]
    InvalidAnnTree,
    /// The requested native ANN index does not exist.
    #[error("native ANN index {index} does not exist")]
    UnknownVectorIndex {
        /// Stable search-index identity requested by the caller.
        index: ObjectId,
    },
    /// An owned ANN read view requires one governor and matching worker pool.
    #[error("native ANN read view requires an installed governor and execution pool")]
    AnnReadViewExecutionAuthorityRequired,
    /// Governor replacement/removal is forbidden while owned ANN views live.
    #[error("native database has {count} outstanding ANN read view(s)")]
    OutstandingAnnReadViews {
        /// Distinct live owned view states; handle clones share one state.
        count: u64,
    },
    /// Governor replacement/removal is forbidden while detached writes live.
    #[error("native database has {count} outstanding detached write batch(es)")]
    OutstandingWriteBatches {
        /// Distinct live batch lineages; legacy rollback candidates share one.
        count: u64,
    },
    /// The database handle that owned an ANN read view has been dropped.
    #[error("native ANN read view owner database is closed")]
    AnnReadViewDatabaseClosed,
    /// Query scratch planning exceeded the representable memory domain.
    #[error("native ANN read view query scratch bound overflowed")]
    AnnReadViewQueryMemoryOverflow,
    /// One explicit per-query worker budget is zero or above class authority.
    #[error(
        "native ANN read view worker limit {requested} is outside the admitted maximum {maximum}"
    )]
    InvalidAnnReadViewWorkerLimit {
        /// Worker count requested for one query.
        requested: u64,
        /// Foreground class and execution-pool ceiling.
        maximum: u64,
    },
    /// A detached write mutation cannot be reapplied to the admitted base.
    #[error("native optimistic write batch contains an invalid mutation")]
    InvalidPreparedMutation,
    /// A structure value is not one canonical signed decimal integer.
    #[error("native structure value is not a canonical signed 64-bit integer")]
    StructureValueNotInteger,
    /// A signed structure counter operation exceeded the i64 domain.
    #[error("native signed 64-bit structure counter overflow")]
    StructureIntegerOverflow,
    /// One structure key was addressed through a different family.
    #[error("native structure key belongs to a different family")]
    StructureKindMismatch,
    /// The requested native hash does not exist.
    #[error("native structure hash does not exist")]
    UnknownStructureHash,
    /// The requested native set does not exist.
    #[error("native structure set does not exist")]
    UnknownStructureSet,
    /// The requested native list does not exist.
    #[error("native structure list does not exist")]
    UnknownStructureList,
    /// The requested native stream does not exist.
    #[error("native structure stream does not exist")]
    UnknownStructureStream,
    /// A native stream entry is empty, duplicate, oversized, or noncanonical.
    #[error("native structure stream entry is not canonical")]
    StructureStreamEntryNotCanonical,
    /// The requested native sorted set does not exist.
    #[error("native structure sorted set does not exist")]
    UnknownStructureSortedSet,
    /// A native sorted-set score is NaN or has a noncanonical encoding.
    #[error("native structure sorted-set score is not canonical")]
    StructureScoreNotCanonical,
    /// A native list cannot allocate another signed chunk identity.
    #[error("native structure list chunk identity space is exhausted")]
    StructureListIndexExhausted,
    /// The requested structure key already exists.
    #[error("native structure key already exists")]
    StructureKeyExists,
    /// Collection families are unavailable in a legacy whole-state directory.
    #[error("native collection families require the B+tree structure format")]
    LegacyStructureFamilyUnsupported,
    /// A composite structure identity cannot fit its canonical u32 length.
    #[error("native structure identity exceeds its canonical length field")]
    StructureIdentityTooLarge,
    /// One hash multi-field call exceeds its fixed position bound.
    #[error(
        "native hash field batch contains {requested} positions; maximum is {MAX_HASH_FIELD_BATCH_SIZE}"
    )]
    HashFieldBatchTooLarge {
        /// Rejected caller-supplied field-position count.
        requested: usize,
    },
    /// One hash mutation batch contains the same exact field more than once.
    #[error("native hash field mutation batch contains a duplicate field")]
    DuplicateHashField,
    /// One set multi-member call exceeds its fixed position bound.
    #[error(
        "native set member batch contains {requested} positions; maximum is {MAX_SET_MEMBER_BATCH_SIZE}"
    )]
    SetMemberBatchTooLarge {
        /// Rejected caller-supplied member-position count.
        requested: usize,
    },
    /// One set mutation batch contains the same exact member more than once.
    #[error("native set member mutation batch contains a duplicate member")]
    DuplicateSetMember,
    /// A durable expiry cleanup request is zero or exceeds its hard bound.
    #[error("native expiry sweep limit {requested} is outside 1..={MAX_EXPIRY_SWEEP_KEYS}")]
    InvalidExpirySweepLimit {
        /// Rejected caller-supplied key bound.
        requested: usize,
    },
    /// Structure reachability compaction requires a validated B+tree format.
    #[error("native structure compaction requires HYSTRBT2 or HYSTRBT3")]
    StructureCompactionUnsupported,
    /// Explicit structure migration accepts only a validated indexed V2 root.
    #[error("native structure V3 migration requires HYSTRBT2")]
    StructureV3MigrationUnsupported,
    /// HYSTRBT3 recovery is enabled before its mutation writer is activated.
    #[error("HYSTRBT3 structure mutations are not enabled")]
    StructureV3MutationUnsupported,
    /// Incremental retirement cleanup requires the incarnation-fenced format.
    #[error("native structure retirement cleanup requires HYSTRBT3")]
    StructureV3RetirementUnsupported,
    /// One retirement cleanup step is below the dual-index minimum or above its hard bound.
    #[error("native structure retirement entry budget {requested} is outside 2..=1024")]
    InvalidStructureRetirementLimit {
        /// Rejected caller-supplied physical-entry budget.
        requested: usize,
    },
    /// Search reachability compaction requires the native inverted B+tree.
    #[error("native search compaction requires a HYSEABT search root")]
    SearchCompactionUnsupported,
    /// An ANN foreground mutation would exceed the durable hard delta bound.
    #[error("native ANN delta exceeds its hard record or byte limit")]
    AnnDeltaLimitExceeded,
    /// ANN consolidation received a zero or above-contract work bound.
    #[error("native ANN consolidation bounds are invalid")]
    InvalidAnnConsolidationLimit,
    /// The captured ANN consolidation exceeds its caller-supplied work bound.
    #[error("native ANN consolidation capture exceeds its bounded work limit")]
    AnnConsolidationLimitExceeded,
    /// The selected ANN view has no delta to consolidate.
    #[error("native ANN consolidation requires a nonempty delta")]
    AnnConsolidationNotNeeded,
    /// The ANN base selected by a captured consolidation plan is no longer current.
    #[error("native ANN consolidation plan is stale")]
    AnnConsolidationStale,
    /// The empty ANN root captured by an initial bulk plan is no longer current.
    #[error("native ANN initial bulk publication plan is stale")]
    InitialAnnBulkStale,
    /// The durable V4 metadata entry cannot represent the requested child count.
    #[error(
        "native ANN initial bulk plan requires {requested} partitions; durable maximum is {maximum}"
    )]
    InitialAnnBulkPartitionLimit {
        /// Effective requested child generation count.
        requested: usize,
        /// Maximum child count representable by the current durable format.
        maximum: usize,
    },
    /// A search document or analyzed term cannot fit one canonical B+tree key.
    #[error("native search identity exceeds the canonical B+tree key limit")]
    SearchIdentityTooLarge,
    /// Recovered commit sequences are not contiguous.
    #[error("recovered native commit sequence is not contiguous")]
    NoncontiguousCommitSequence,
    /// A detached writer predates the oldest retained physical root.
    #[error(
        "native write snapshot CSN {read_csn} predates retained physical floor {retention_floor_csn}"
    )]
    SnapshotBelowRetentionFloor {
        /// Detached snapshot used to prepare the write.
        read_csn: Csn,
        /// Oldest physical root retained by the active page generation.
        retention_floor_csn: Csn,
    },
    /// A durable snapshot pin already owns the requested identity.
    #[error("native snapshot pin already exists")]
    SnapshotPinExists,
    /// No durable snapshot pin owns the requested identity.
    #[error("native snapshot pin does not exist")]
    UnknownSnapshotPin,
    /// A stable pin does not match retained manifest, WAL, page, or blob authority.
    #[error("native snapshot pin authority is invalid or incomplete")]
    InvalidSnapshotPinAuthority,
    /// A historical pin prevents retirement of its WAL or manifest authority.
    #[error("native historical snapshot pins block WAL retention")]
    SnapshotPinsBlockWalRetention,
    /// A historical pin prevents sole-current-root blob collection.
    #[error("native historical snapshot pins block blob collection")]
    SnapshotPinsBlockBlobCollection,
    /// A checkpoint does not match its manifest, WAL commit, or root set.
    #[error("native checkpoint does not match the verified manifest/WAL chain")]
    InvalidCheckpoint,
    /// No committed root set exists to checkpoint.
    #[error("native checkpoint requires at least one committed transaction")]
    NoCommittedState,
    /// Transaction identity space is exhausted.
    #[error("native transaction identity space is exhausted")]
    TransactionIdExhausted,
    /// A direct group-commit request is empty or exceeds its bounded cohort.
    #[error(
        "native group commit batch size {requested} is outside 1..={MAX_GROUP_COMMIT_BATCH_SIZE}"
    )]
    InvalidGroupCommitBatchSize {
        /// Rejected number of submitted transactions.
        requested: usize,
    },
    /// A transaction submitted to the group scheduler selected another class.
    #[error("native group commit accepts only group-durability transactions")]
    GroupCommitRequiresGroupDurability,
    /// A deterministic crash-matrix interruption was requested.
    #[error("native commit interrupted at {0:?}; reopen the data directory")]
    InjectedCrash(CommitBoundary),
    /// A deterministic group-commit interruption was requested.
    #[error("native group commit interrupted at {0:?}; reopen the data directory")]
    InjectedGroupCrash(GroupCommitBoundary),
    /// A deterministic checkpoint interruption was requested.
    #[error("native checkpoint interrupted at {0:?}; reopen the data directory")]
    InjectedCheckpointCrash(CheckpointBoundary),
    /// A deterministic snapshot-pin interruption was requested.
    #[error("native snapshot pin interrupted at {0:?}; reopen the data directory")]
    InjectedSnapshotPinCrash(SnapshotPinBoundary),
    /// A deterministic page-vacuum interruption was requested.
    #[error("native page vacuum interrupted at {0:?}; reopen the data directory")]
    InjectedVacuumCrash(VacuumBoundary),
    /// WAL retention requires a current-root checkpoint at the retention floor.
    #[error("native WAL retention requires the latest checkpoint at the current retention floor")]
    WalRetentionIneligible,
    /// A deterministic WAL-retention interruption was requested.
    #[error("native WAL retention interrupted at {0:?}; reopen the data directory")]
    InjectedWalRetentionCrash(WalRetentionBoundary),
    /// Blob collection requires one exact retained root and an empty WAL suffix.
    #[error("native blob collection requires one exact current retained root")]
    BlobCollectionIneligible,
    /// A deterministic immutable-blob collection interruption was requested.
    #[error("native blob collection interrupted at {0:?}; reopen the data directory")]
    InjectedBlobCollectionCrash(BlobCollectionBoundary),
    /// Test-only guard proving a path does not materialize all engine state.
    #[cfg(test)]
    #[error("unexpected complete native state materialization")]
    UnexpectedFullStateLoad,
}

impl NativeRuntimeError {
    /// Returns the underlying operating-system error kind when this failure is
    /// one of the runtime's explicit filesystem I/O variants.
    pub fn io_error_kind(&self) -> Option<std::io::ErrorKind> {
        match self {
            Self::Io(source)
            | Self::Directory(NativeDirectoryError::Io { source, .. })
            | Self::Page(PageStoreError::Io(source))
            | Self::BufferPool(BufferPoolError::Store(PageStoreError::Io(source)))
            | Self::Blob(BlobError::Io(source))
            | Self::BTree(
                BTreeError::Store(PageStoreError::Io(source))
                | BTreeError::BufferPool(BufferPoolError::Store(PageStoreError::Io(source))),
            )
            | Self::Wal(WalError::Io(source))
            | Self::Manifest(ManifestError::Io(source))
            | Self::SnapshotPin(SnapshotPinError::Io(source)) => Some(source.kind()),
            _ => None,
        }
    }

    /// Returns whether this runtime failure wraps an explicit filesystem I/O
    /// error rather than a codec, semantic, or corruption failure.
    pub fn is_io(&self) -> bool {
        self.io_error_kind().is_some()
    }

    /// Returns whether this runtime failure identifies malformed durable or
    /// logical authority rather than I/O, capacity, or operational state.
    pub fn is_corruption(&self) -> bool {
        match self {
            Self::Wal(source) => wal_error_is_corruption(source),
            Self::Page(source) => page_store_error_is_corruption(source),
            Self::BufferPool(BufferPoolError::Store(source)) => {
                page_store_error_is_corruption(source)
            }
            Self::Blob(source) => blob_error_is_corruption(source),
            Self::BTree(source) => btree_error_is_corruption(source),
            Self::Manifest(source) => manifest_error_is_corruption(source),
            Self::SnapshotPin(source) => snapshot_pin_error_is_corruption(source),
            Self::WalSemantic(_)
            | Self::Model(_)
            | Self::InvalidCatalogTree
            | Self::InvalidRelationalTree
            | Self::InvalidStructureTree
            | Self::InvalidSearchTree
            | Self::InvalidAnnTree
            | Self::InvalidCommittedRoot
            | Self::InvalidCheckpoint
            | Self::NoncontiguousCommitSequence
            | Self::FuturePage => true,
            Self::Record(source) => record_error_is_corruption(source),
            Self::Catalog(source) => catalog_error_is_corruption(source),
            _ => false,
        }
    }
}

fn wal_error_is_corruption(source: &WalError) -> bool {
    matches!(
        source,
        WalError::InvalidBlockLength { .. }
            | WalError::InvalidMagic
            | WalError::UnsupportedFormat { .. }
            | WalError::BlockSequenceMismatch { .. }
            | WalError::PreviousDigestMismatch { .. }
            | WalError::ReservedNonzero
            | WalError::BlockPayloadTooLarge { .. }
            | WalError::NonzeroPadding
            | WalError::BlockChecksumMismatch
            | WalError::BlockDigestMismatch
            | WalError::EmptyBlock
            | WalError::InvalidRecordLength { .. }
            | WalError::UnknownRecordKind(_)
            | WalError::UnknownEngineKind(_)
            | WalError::RecordReservedNonzero
            | WalError::RecordLsnMismatch { .. }
            | WalError::RecordChecksumMismatch { .. }
            | WalError::InvalidRetentionAnchorLength { .. }
            | WalError::InvalidRetentionAnchorPreamble
            | WalError::InvalidRetentionAnchorIdentity
            | WalError::RetentionAnchorChecksumMismatch
            | WalError::RetentionAnchorDigestMismatch
            | WalError::InvalidPhysicalBase
            | WalError::UnexpectedRetentionEntry
            | WalError::InvalidRetentionAnchorChain
            | WalError::RetentionAnchorLineageMismatch
    )
}

fn page_store_error_is_corruption(source: &PageStoreError) -> bool {
    match source {
        PageStoreError::Page(source) => matches!(
            source,
            hyphae_native_pages::PageError::InvalidLength { .. }
                | hyphae_native_pages::PageError::InvalidMagic
                | hyphae_native_pages::PageError::UnsupportedFormat { .. }
                | hyphae_native_pages::PageError::UnknownKind(_)
                | hyphae_native_pages::PageError::ReservedNonzero
                | hyphae_native_pages::PageError::PageIdMismatch { .. }
                | hyphae_native_pages::PageError::PayloadTooLarge { .. }
                | hyphae_native_pages::PageError::NonzeroPadding
                | hyphae_native_pages::PageError::ChecksumMismatch
                | hyphae_native_pages::PageError::DigestMismatch
        ),
        PageStoreError::InvalidFileLength { .. } | PageStoreError::PageOutsideBoundary(_) => true,
        PageStoreError::Io(_)
        | PageStoreError::Poisoned
        | PageStoreError::PageIdExhausted
        | PageStoreError::InvalidRollbackBoundary { .. } => false,
    }
}

fn blob_error_is_corruption(source: &BlobError) -> bool {
    matches!(
        source,
        BlobError::InvalidPreamble
            | BlobError::Identity(_)
            | BlobError::InvalidLength
            | BlobError::ChecksumMismatch
            | BlobError::IdentityMismatch
            | BlobError::UnexpectedDirectoryEntry
            | BlobError::IdentityCollision
            | BlobError::ReferenceOutsideBoundary(_)
            | BlobError::InconsistentGeneration
    )
}

fn btree_error_is_corruption(source: &BTreeError) -> bool {
    match source {
        BTreeError::Store(source) => page_store_error_is_corruption(source),
        BTreeError::BufferPool(BufferPoolError::Store(source)) => {
            page_store_error_is_corruption(source)
        }
        BTreeError::WrongPageKind
        | BTreeError::InvalidLength
        | BTreeError::InvalidPreamble
        | BTreeError::InvalidCount
        | BTreeError::NoncanonicalKeyOrder
        | BTreeError::InvalidSeparator
        | BTreeError::ZeroChild
        | BTreeError::HeightExceeded
        | BTreeError::Cycle
        | BTreeError::Unbalanced
        | BTreeError::FuturePage => true,
        BTreeError::BufferPool(_)
        | BTreeError::LengthOverflow
        | BTreeError::KeyTooLarge
        | BTreeError::EntryTooLarge
        | BTreeError::NoValidSplit
        | BTreeError::DuplicateKey
        | BTreeError::ForeignSegment
        | BTreeError::Cancelled
        | BTreeError::PrefixContentsChanged => false,
    }
}

fn manifest_error_is_corruption(source: &ManifestError) -> bool {
    matches!(
        source,
        ManifestError::Mvcc(
            MvccError::InvalidWalAnchor
                | MvccError::UncommittedRootSet
                | MvccError::InvalidStorageTransition
        ) | ManifestError::InvalidLength
            | ManifestError::InvalidPreamble
            | ManifestError::ChecksumMismatch
            | ManifestError::DigestMismatch
            | ManifestError::InvalidIdentity
            | ManifestError::InvalidStorageState
            | ManifestError::NoncanonicalRoots
            | ManifestError::InvalidChain
            | ManifestError::LineageMismatch
            | ManifestError::UnexpectedDirectoryEntry
    )
}

fn snapshot_pin_error_is_corruption(source: &SnapshotPinError) -> bool {
    matches!(
        source,
        SnapshotPinError::InvalidIdentity
            | SnapshotPinError::InvalidLength
            | SnapshotPinError::InvalidPreamble
            | SnapshotPinError::ChecksumMismatch
            | SnapshotPinError::FilenameIdentityMismatch
            | SnapshotPinError::LineageMismatch
            | SnapshotPinError::UnexpectedDirectoryEntry
    )
}

fn record_error_is_corruption(source: &RecordError) -> bool {
    matches!(
        source,
        RecordError::Truncated
            | RecordError::LengthMismatch
            | RecordError::UnknownFlags
            | RecordError::EmptyRegularRow
            | RecordError::ColumnCountOverflow
            | RecordError::LengthOverflow
            | RecordError::ZeroIdentity
            | RecordError::InvalidVersionWindow
            | RecordError::InvalidTombstone
            | RecordError::NoncanonicalNullBitmap
            | RecordError::InvalidOffsets
            | RecordError::NullHasBytes
            | RecordError::InvalidBlobReferenceLength
            | RecordError::InvalidRowVersionPointer
            | RecordError::InvalidTupleHeader
    )
}

fn catalog_error_is_corruption(source: &CatalogError) -> bool {
    match source {
        CatalogError::EmptyName
        | CatalogError::NameTooLong
        | CatalogError::DuplicateObjectId(_)
        | CatalogError::DuplicateName(_)
        | CatalogError::DuplicateColumnId(_)
        | CatalogError::DuplicateColumnName(_)
        | CatalogError::NoncanonicalColumnOrder
        | CatalogError::EmptyRelation
        | CatalogError::DuplicateFieldId(_)
        | CatalogError::DuplicateFieldName(_)
        | CatalogError::NoncanonicalFieldOrder
        | CatalogError::AnnRequiresVector
        | CatalogError::InvalidAnnM
        | CatalogError::InvalidAnnEfConstruction
        | CatalogError::InvalidAnnEfSearch
        | CatalogError::MissingPrimaryKeyColumn(_)
        | CatalogError::DuplicatePrimaryKeyColumn(_)
        | CatalogError::NullablePrimaryKeyColumn(_)
        | CatalogError::EmptySecondaryIndex
        | CatalogError::DuplicateSecondaryIndexColumn(_)
        | CatalogError::SelfReferentialSecondaryIndex
        | CatalogError::MissingSecondaryIndexRelation(_)
        | CatalogError::MissingSecondaryIndexColumn(_)
        | CatalogError::WrongObjectOwner
        | CatalogError::TooManyDefinitionItems
        | CatalogError::DefinitionTooLarge
        | CatalogError::InvalidDefinitionEncoding
        | CatalogError::InvalidCrossEngineLink
        | CatalogError::InvalidDefinitionVersion
        | CatalogError::InvalidObjectHierarchy
        | CatalogError::DuplicateAnalyzerFilter
        | CatalogError::InvalidSearchFieldPolicy
        | CatalogError::DuplicateVectorId(_)
        | CatalogError::DuplicateVectorName(_)
        | CatalogError::InvalidVectorPolicy
        | CatalogError::InvalidKeyspacePolicy
        | CatalogError::MissingDependencyTarget(_) => true,
        CatalogError::NativeType(source) => native_type_error_is_corruption(*source),
        CatalogError::VersionExhausted => false,
    }
}

fn native_type_error_is_corruption(source: hyphae_native_types::NativeTypeError) -> bool {
    !matches!(
        source,
        hyphae_native_types::NativeTypeError::ZeroIdentity(_)
            | hyphae_native_types::NativeTypeError::InvalidDecimalPrecision
            | hyphae_native_types::NativeTypeError::InvalidDecimalScale
            | hyphae_native_types::NativeTypeError::EmptyVector
            | hyphae_native_types::NativeTypeError::ScalarTypeMismatch
            | hyphae_native_types::NativeTypeError::NullRequiresRowBitmap
            | hyphae_native_types::NativeTypeError::ScalarOutOfRange
            | hyphae_native_types::NativeTypeError::UnsupportedOrderedType
            | hyphae_native_types::NativeTypeError::UnsupportedScalarType
            | hyphae_native_types::NativeTypeError::ScalarLengthExceeded
    )
}

impl From<WalSemanticError> for NativeRuntimeError {
    fn from(source: WalSemanticError) -> Self {
        Self::WalSemantic(source.to_string())
    }
}

impl From<ModelError> for NativeRuntimeError {
    fn from(source: ModelError) -> Self {
        match source {
            ModelError::UniqueSecondaryIndexViolation => Self::UniqueSecondaryIndexViolation,
            source => Self::Model(source.to_string()),
        }
    }
}

/// Deterministic commit boundary used by the native crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CommitBoundary {
    /// Large values are synchronized only under temporary blob names.
    BlobStaged,
    /// Immutable blobs are promoted but no pages or WAL transaction exist.
    BlobPromoted,
    /// New copy-on-write pages exist but have not been synchronized.
    PageAppended,
    /// New pages are synchronized but no WAL transaction exists.
    PageSynchronized,
    /// A complete WAL transaction is appended but not explicitly synchronized.
    WalAppended,
    /// The WAL transaction is synchronized but roots are not published in memory.
    WalSynchronized,
    /// The complete root set has been published.
    RootPublished,
}

#[derive(Clone, Copy)]
struct CommitInterruption {
    boundary: CommitBoundary,
    hook: Option<fn(CommitBoundary)>,
}

impl CommitInterruption {
    const fn returning(boundary: CommitBoundary) -> Self {
        Self {
            boundary,
            hook: None,
        }
    }

    const fn hooked(boundary: CommitBoundary, hook: fn(CommitBoundary)) -> Self {
        Self {
            boundary,
            hook: Some(hook),
        }
    }
}

/// Deterministic group-commit boundary used by the native crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum GroupCommitBoundary {
    /// At least one accepted WAL transaction is appended, but the cohort is incomplete.
    AdmittedWalPrefixAppended,
    /// Every accepted transaction is appended without a shared synchronization.
    CohortAppended,
    /// The page file is synchronized once, but the cohort WAL is not.
    PageSynchronized,
    /// The cohort WAL is synchronized once, but its final root is not visible.
    WalSynchronized,
    /// The final cohort root and conflict state are published.
    RootPublished,
}

/// Deterministic root-checkpoint boundary used by the native crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CheckpointBoundary {
    /// A synchronized create-new manifest exists only under its temporary name.
    ManifestStaged,
    /// The immutable manifest is published but not WAL-anchored.
    ManifestPublished,
    /// The WAL checkpoint record is appended but not explicitly synchronized.
    WalAppended,
    /// The manifest and its WAL checkpoint record are synchronized.
    WalSynchronized,
}

/// Deterministic durable snapshot-pin boundary used by the crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SnapshotPinBoundary {
    /// The complete pin record is synchronized only under its temporary name.
    RecordSynchronized,
    /// The immutable pin record is renamed and its directory synchronized.
    RecordPublished,
}

/// Deterministic WAL-retention boundary used by the crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum WalRetentionBoundary {
    /// A synchronized create-new anchor exists only under its temporary name.
    AnchorStaged,
    /// A synchronized `.pending` anchor exists while the old WAL remains.
    AnchorPending,
    /// The old WAL length is reset but not explicitly synchronized.
    WalReset,
    /// The empty WAL is synchronized and the writer uses the absolute base.
    WalSynchronized,
    /// The candidate anchor has its stable immutable filename.
    AnchorStabilized,
    /// Immutable manifest files below the anchor's base were removed.
    ManifestPrefixRemoved,
    /// Any prior stable anchor has been removed.
    PriorAnchorRemoved,
}

/// Deterministic page-generation vacuum boundary used by the crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum VacuumBoundary {
    /// The complete candidate exists only under its temporary filename.
    CandidateSynchronized,
    /// The candidate has its final generation filename but no WAL authority.
    CandidatePublished,
    /// The vacuum transaction is appended but not explicitly synchronized.
    WalAppended,
    /// WAL authority selects the new generation but roots are not in memory.
    WalSynchronized,
    /// The new roots and page store are active while the prior file remains.
    RootPublished,
    /// The prior page-file generation has been removed.
    PriorGenerationRemoved,
}

/// Deterministic immutable-blob collection boundary used by the crash matrix.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BlobCollectionBoundary {
    /// Complete root validation traced every live reference; no file was removed.
    ReferencesTraced,
    /// The first candidate file was removed without directory synchronization.
    FirstCandidateRemoved,
    /// Every candidate was removed without directory synchronization.
    AllCandidatesRemoved,
    /// The immutable blob namespace was synchronized where supported.
    DirectorySynchronized,
}

/// TTL state for one native structure key.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Ttl {
    /// No value exists for this key.
    Missing,
    /// The value exists without an expiry.
    Persistent,
    /// The value exists with this nonnegative remaining duration.
    RemainingMicros(i64),
}

/// Predicate evaluated by one native scalar `SET`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SetCondition {
    /// Always replace the visible value.
    Always,
    /// Apply only when no unexpired value exists.
    IfAbsent,
    /// Apply only when an unexpired value exists.
    IfPresent,
}

/// Result of evaluating one conditional scalar `SET`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SetOutcome {
    /// The private write set now contains the mutation.
    Applied,
    /// The condition was false and no mutation was added.
    NotApplied,
}

/// Result of one native hash-field upsert.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum HashSetOutcome {
    /// The field did not exist and increased the hash cardinality.
    Added,
    /// The field existed and its value was replaced.
    Updated,
}

/// One owned binary field/value update for a native hash batch.
pub type HashFieldUpdate = (Vec<u8>, Vec<u8>);

/// One native hash field/value pair in exact field-byte order.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct HashFieldEntry {
    field: Vec<u8>,
    value: Vec<u8>,
}

/// Execution evidence for one current-root physical hash scan.
#[derive(Clone, Debug, PartialEq)]
pub struct NativeHashScanExecutionReceipt {
    /// Immutable all-engine CSN used by the scan.
    pub snapshot_csn: Option<Csn>,
    /// Canonically ordered live field/value entries.
    pub entries: Vec<HashFieldEntry>,
    /// Live field cardinality declared by current hash metadata.
    pub declared_field_count: usize,
    /// Immutable leaf segments selected by the physical range plan.
    pub planned_segments: usize,
    /// Physical leaf entries covered before tombstone/TTL filtering.
    pub planned_physical_entries: usize,
    /// Segment-planning admission, absent on the direct path or without a governor.
    pub planning: Option<NativeEngineWorkReceipt>,
    /// Segment-execution admission, absent without an installed governor.
    pub execution: Option<NativeEngineWorkReceipt>,
    /// Compute and I/O workers reserved by the segment plan.
    pub planned_workers: u64,
    /// Persistent-pool batches that actually executed this scan.
    pub worker_batches: usize,
}

/// Execution evidence for one current-root physical set-member scan.
#[derive(Clone, Debug, PartialEq)]
pub struct NativeSetScanExecutionReceipt {
    /// Immutable all-engine CSN used by the scan.
    pub snapshot_csn: Option<Csn>,
    /// Canonically ordered live members.
    pub members: Vec<Vec<u8>>,
    /// Live member cardinality declared by current set metadata.
    pub declared_member_count: usize,
    /// Immutable leaf segments selected by the physical range plan.
    pub planned_segments: usize,
    /// Physical entries covered before tombstone filtering.
    pub planned_physical_entries: usize,
    /// Segment-planning admission, absent on the direct path or without a governor.
    pub planning: Option<NativeEngineWorkReceipt>,
    /// Segment-execution admission, absent without an installed governor.
    pub execution: Option<NativeEngineWorkReceipt>,
    /// Compute and I/O workers reserved by the segment plan.
    pub planned_workers: u64,
    /// Persistent-pool batches that actually executed this scan.
    pub worker_batches: usize,
}

fn empty_hash_scan_execution_receipt(
    snapshot_csn: Option<Csn>,
    declared_field_count: usize,
    planning: Option<NativeEngineWorkReceipt>,
) -> NativeHashScanExecutionReceipt {
    NativeHashScanExecutionReceipt {
        snapshot_csn,
        entries: Vec::new(),
        declared_field_count,
        planned_segments: 0,
        planned_physical_entries: 0,
        planning,
        execution: None,
        planned_workers: 0,
        worker_batches: 0,
    }
}

/// One canonical native stream field/value map.
pub type NativeStreamFields = Vec<(Vec<u8>, Vec<u8>)>;

/// One stable native stream ID and its canonical field/value map.
