    fn admit_foreground_point(&self) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        self.admit_database_work(
            WorkloadClass::ForegroundPoint,
            GovernorRequest {
                compute_threads: 1,
                io_slots: 1,
                memory_bytes: FOREGROUND_POINT_MEMORY_BYTES,
            },
        )
    }

    fn admit_foreground_bounded(
        &self,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        self.admit_foreground_bounded_with_cancellation(None)
    }

    fn admit_foreground_bounded_with_cancellation(
        &self,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        self.admit_database_work_with_cancellation(
            WorkloadClass::ForegroundBounded,
            GovernorRequest {
                compute_threads: 1,
                io_slots: 1,
                memory_bytes: FOREGROUND_BOUNDED_MEMORY_BYTES,
            },
            cancellation,
        )
    }

    fn admit_parallel_foreground_bounded(
        &self,
        memory_bytes: u64,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        self.admit_parallel_foreground_bounded_with_cancellation(memory_bytes, None)
    }

    fn admit_parallel_foreground_bounded_with_cancellation(
        &self,
        memory_bytes: u64,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        let compute_threads = self
            .resource_governor
            .as_ref()
            .zip(self.execution_pool.as_ref())
            .map_or(1, |(governor, execution_pool)| {
                governor
                    .policy()
                    .limit(WorkloadClass::ForegroundBounded)
                    .compute_threads
                    .min(
                        u64::try_from(execution_pool.topology().worker_count()).unwrap_or(u64::MAX),
                    )
                    .max(1)
            });
        self.admit_database_work_with_cancellation(
            WorkloadClass::ForegroundBounded,
            GovernorRequest {
                compute_threads,
                io_slots: 1,
                memory_bytes,
            },
            cancellation,
        )
    }

    fn admit_parallel_foreground_bounded_io(
        &self,
        memory_bytes: u64,
        maximum_workers: usize,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        let worker_limit = u64::try_from(maximum_workers).unwrap_or(u64::MAX).max(1);
        let workers = self
            .resource_governor
            .as_ref()
            .zip(self.execution_pool.as_ref())
            .map_or(1, |(governor, execution_pool)| {
                let class = governor.policy().limit(WorkloadClass::ForegroundBounded);
                governor
                    .policy()
                    .schedulable_compute_threads
                    .min(governor.policy().io_slots)
                    .min(class.compute_threads)
                    .min(class.io_slots)
                    .min(
                        u64::try_from(execution_pool.topology().worker_count()).unwrap_or(u64::MAX),
                    )
                    .min(worker_limit)
                    .max(1)
            });
        self.admit_database_work(
            WorkloadClass::ForegroundBounded,
            GovernorRequest {
                compute_threads: workers,
                io_slots: workers,
                memory_bytes,
            },
        )
    }

    fn admit_mutation_owned_with_wait(
        &self,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<Option<OwnedGovernorPermit>, NativeRuntimeError> {
        self.admit_database_work_at(
            WorkloadClass::Mutation,
            GovernorRequest {
                compute_threads: 1,
                io_slots: 1,
                memory_bytes: MUTATION_MEMORY_BYTES,
            },
            maximum_wait,
            cancellation,
        )
        .map(|permit| permit.map(DatabaseGovernorPermit::into_owned))
    }

    fn admit_scheduled_commit_execution(
        &self,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<Option<DatabaseGovernorPermit>, NativeRuntimeError> {
        let Some(governor) = &self.resource_governor else {
            return Ok(None);
        };
        let owned_cancellation;
        let cancellation = if let Some(cancellation) = cancellation {
            cancellation
        } else {
            owned_cancellation = governor.cancellation_token();
            &owned_cancellation
        };
        admit_governor_work(
            governor,
            maximum_wait,
            WorkloadClass::Mutation,
            GovernorRequest {
                compute_threads: 1,
                io_slots: 1,
                memory_bytes: 0,
            },
            Some(cancellation),
        )
        .map(Some)
    }

