    /// Returns a retained durable outcome by its opaque resolution identity.
    pub fn transaction_resolution(
        &self,
        resolution_id: TransactionId,
    ) -> Option<DurableTransactionResolution> {
        self.transaction_resolutions.get(&resolution_id).copied()
    }

    /// Returns a retained durable outcome for one principal/idempotency binding.
    pub fn transaction_resolution_for_token(
        &self,
        principal_hash: [u8; 32],
        idempotency_token: [u8; 32],
    ) -> Option<DurableTransactionResolution> {
        self.transaction_resolutions
            .values()
            .find(|resolution| {
                resolution.principal_hash == principal_hash
                    && resolution.idempotency_token == idempotency_token
            })
            .copied()
    }

    /// Returns recovered commit evidence for one stable runtime transaction.
    pub fn transaction_commit_receipt(
        &self,
        transaction_id: TransactionId,
    ) -> Option<CommitReceipt> {
        self.transaction_receipts.get(&transaction_id).copied()
    }

    /// Returns the latest semantically verified durable checkpoint authority.
    pub fn last_checkpoint_authority(&self) -> Option<(u64, [u8; 32])> {
        Some((
            self.last_checkpoint_visible_csn?.get(),
            self.last_checkpoint_manifest_digest?,
        ))
    }

    pub(crate) const fn last_checkpoint_manifest_digest(&self) -> Option<[u8; 32]> {
        self.last_checkpoint_manifest_digest
    }

    /// Looks up one current catalog definition by stable object identity.
    ///
    /// `HYCAT003` directories traverse the native catalog B+tree through the
    /// partitioned buffer pool. Legacy inline catalog roots remain readable.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot coordination, page, B+tree, definition,
    /// blob, or catalog-namespace corruption.
    pub fn catalog_object_latest(
        &self,
        id: ObjectId,
    ) -> Result<Option<CatalogObject>, NativeRuntimeError> {
        self.catalog_object_latest_identified(id)
            .map(|identified| identified.object)
    }

    /// Looks up one current catalog definition and returns the exact snapshot
    /// identity used by the bounded physical lookup.
    ///
    /// # Errors
    ///
    /// Returns the same storage and corruption failures as
    /// [`Self::catalog_object_latest`].
    pub fn catalog_object_latest_identified(
        &self,
        id: ObjectId,
    ) -> Result<IdentifiedCatalogObject, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        let snapshot = self.coordinator.snapshot(0)?;
        let object = snapshot
            .roots()
            .root(SLOT_CATALOG)
            .map(|root| self.catalog_object_at_root(root, id))
            .transpose()?
            .flatten();
        Ok(IdentifiedCatalogObject {
            visible_csn: snapshot.visible_csn,
            catalog_version: snapshot.catalog_version,
            root_digest: snapshot.roots().digest(),
            object,
        })
    }

    /// Looks up one current catalog definition by normalized qualified name.
    ///
    /// The name namespace resolves to a stable ID and the object namespace is
    /// checked on the same immutable root before returning the definition.
    ///
    /// # Errors
    ///
    /// Returns the same storage and corruption failures as
    /// [`Self::catalog_object_latest`].
    pub fn catalog_object_named_latest(
        &self,
        name: &QualifiedName,
    ) -> Result<Option<CatalogObject>, NativeRuntimeError> {
        self.catalog_object_named_latest_identified(name)
            .map(|identified| identified.object)
    }

    /// Looks up one current catalog definition by name and returns the exact
    /// snapshot identity used by the bounded physical lookup.
    ///
    /// # Errors
    ///
    /// Returns the same storage and corruption failures as
    /// [`Self::catalog_object_named_latest`].
    pub fn catalog_object_named_latest_identified(
        &self,
        name: &QualifiedName,
    ) -> Result<IdentifiedCatalogObject, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        let snapshot = self.coordinator.snapshot(0)?;
        let object = snapshot
            .roots()
            .root(SLOT_CATALOG)
            .map(|root| self.catalog_object_named_at_root(root, name))
            .transpose()?
            .flatten();
        Ok(IdentifiedCatalogObject {
            visible_csn: snapshot.visible_csn,
            catalog_version: snapshot.catalog_version,
            root_digest: snapshot.roots().digest(),
            object,
        })
    }

    /// Captures an immutable catalog-only snapshot without materializing any
    /// relational, structure, search, ANN, or complete catalog state.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot coordination failure.
    pub fn catalog_snapshot(&self) -> Result<NativeCatalogSnapshot, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        let snapshot = self.coordinator.snapshot(0)?;
        Ok(NativeCatalogSnapshot {
            identity: CatalogSnapshotIdentity {
                visible_csn: snapshot.visible_csn,
                catalog_version: snapshot.catalog_version,
                root_digest: snapshot.roots().digest(),
            },
            directory_lineage: self.directory_guard.identity().lineage().encode(),
            root: snapshot.roots().root(SLOT_CATALOG),
        })
    }

    /// Creates one generic logical catalog V2 object and publishes it through
    /// the ordinary durable root/WAL commit protocol.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid catalog semantics or commit persistence.
    pub fn create_catalog_object_v2(
        &mut self,
        object: LogicalCatalogObject,
        durability: DurabilityClass,
    ) -> Result<CommitReceipt, NativeRuntimeError> {
        self.create_catalog_objects_v2(vec![object], durability)
    }

    /// Creates multiple generic logical catalog V2 objects under one commit.
    ///
    /// Objects are admitted in input order so parent definitions may precede
    /// their dependents. Any invalid object aborts the private transaction and
    /// publishes none of the batch.
    ///
    /// # Errors
    ///
    /// Returns an error for an empty batch, invalid catalog semantics, or
    /// commit persistence.
    pub fn create_catalog_objects_v2(
        &mut self,
        objects: Vec<LogicalCatalogObject>,
        durability: DurabilityClass,
    ) -> Result<CommitReceipt, NativeRuntimeError> {
        if objects.is_empty() {
            return Err(WalSemanticError::InvalidSequence.into());
        }
        let mut transaction = self.begin(0, durability)?;
        for object in objects {
            transaction.create_catalog_object_v2(object)?;
        }
        transaction.commit()
    }

    /// Explicitly upgrades the current logical catalog to the scope-index format.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported root or commit failure.
    pub fn ensure_catalog_scope_index(
        &mut self,
        durability: DurabilityClass,
    ) -> Result<Option<CommitReceipt>, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_CATALOG) else {
            return Ok(None);
        };
        let marker = BTree::from_root(root)
            .get_cached_pinned(&self.pages, &self.buffer_pool, CATALOG_FORMAT_KEY)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if marker.bytes() == CATALOG_FORMAT_VALUE_V7 {
            return Ok(None);
        }
        if !matches!(
            marker.bytes(),
            CATALOG_FORMAT_VALUE_V3
                | CATALOG_FORMAT_VALUE_V4
                | CATALOG_FORMAT_VALUE_V5
                | CATALOG_FORMAT_VALUE_V6
        ) {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        let mut transaction = self.begin(0, durability)?;
        transaction.mutations.push(Mutation {
            engine: EngineKind::Kernel,
            opcode: Opcode::MigrateCatalogV7,
            target: None,
            key: Vec::new(),
            value: Vec::new(),
            expires_at_micros: None,
        });
        transaction.dirty[0] = true;
        transaction.commit().map(Some)
    }

    /// Lists lightweight logical V2 summaries through a bounded immutable-root
    /// traversal.
    ///
    /// # Errors
    ///
    /// Returns an error for zero/oversized limits, malformed cursor identity,
    /// unsupported legacy catalog roots, or durable catalog corruption.
    pub fn catalog_list(
        &self,
        snapshot: &NativeCatalogSnapshot,
        request: CatalogListRequest,
    ) -> Result<CatalogObjectPage, NativeRuntimeError> {
        self.require_catalog_snapshot(snapshot)?;
        validate_catalog_read_limits(request.item_limit, request.visit_limit, request.byte_limit)?;
        let mut page = CatalogObjectPage {
            snapshot: snapshot.identity,
            items: Vec::new(),
            continuation: None,
            stop: CatalogPageStop::Exhausted,
            visited: 0,
            returned_bytes: 0,
        };
        let resume = request.start_after;
        let Some(root) = snapshot.root else {
            return Ok(page);
        };
        self.require_catalog_v6(root)?;
        let start_key = request.start_after.map(catalog_object_key);
        let mut failure = None;
        let visit = BTree::from_root(root).visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &[CATALOG_OBJECT_PREFIX],
            start_key.as_deref(),
            |key, stored| {
                page.visited += 1;
                let decoded = (|| {
                    let id = decode_catalog_object_key(key)?;
                    let definition = decode_catalog_definition_storage_value(stored, &self.blobs)?;
                    let object = decode_logical_catalog_definition(&definition, id)?;
                    if request
                        .parent
                        .is_some_and(|parent| object.parent() != Some(parent))
                        || request.kind.is_some_and(|kind| object.kind() != kind)
                    {
                        if page.visited == request.visit_limit {
                            page.stop = CatalogPageStop::VisitLimit;
                            page.continuation = Some(id);
                            return Ok(ControlFlow::Break(()));
                        }
                        return Ok(ControlFlow::Continue(()));
                    }
                    let summary = logical_catalog_summary(&object);
                    let bytes = catalog_summary_bytes(&summary)?;
                    if page
                        .returned_bytes
                        .checked_add(bytes)
                        .is_none_or(|total| total > request.byte_limit)
                    {
                        page.stop = CatalogPageStop::ByteLimit;
                        page.continuation = page.items.last().map(|item| item.id).or(resume);
                        return Ok(ControlFlow::Break(()));
                    }
                    page.returned_bytes += bytes;
                    page.items.push(summary);
                    if page.items.len() == request.item_limit {
                        page.stop = CatalogPageStop::ItemLimit;
                        page.continuation = Some(id);
                        return Ok(ControlFlow::Break(()));
                    }
                    if page.visited == request.visit_limit {
                        page.stop = CatalogPageStop::VisitLimit;
                        page.continuation = Some(id);
                        return Ok(ControlFlow::Break(()));
                    }
                    Ok(ControlFlow::Continue(()))
                })();
                match decoded {
                    Ok(control) => control,
                    Err(error) => {
                        failure = Some(error);
                        ControlFlow::Break(())
                    }
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if visit.is_continue() {
            page.stop = CatalogPageStop::Exhausted;
            page.continuation = None;
        }
        Ok(page)
    }

    /// Lists only candidates reached from caller-authorized catalog scopes.
    ///
    /// Exact-object scopes use point reads. Subtree scopes use the durable
    /// ancestor-descendant namespace and instance scope uses the object
    /// namespace. Overlapping roots are merged and deduplicated in `ObjectId`
    /// order before filters are applied, so invisible global objects are never
    /// traversed or charged as work.
    ///
    /// # Errors
    ///
    /// Returns an error for noncanonical scopes, invalid bounds, an unsupported
    /// catalog root, or durable catalog corruption.
    pub fn catalog_visible_list(
        &self,
        snapshot: &NativeCatalogSnapshot,
        request: &CatalogVisibleListRequest,
    ) -> Result<CatalogVisibleObjectPage, NativeRuntimeError> {
        self.require_catalog_snapshot(snapshot)?;
        validate_catalog_read_limits(request.item_limit, request.visit_limit, request.byte_limit)?;
        if request.scopes.is_empty()
            || request.scopes.windows(2).any(|pair| pair[0] >= pair[1])
            || request.scopes.contains(&CatalogVisibleScope::Instance) && request.scopes.len() != 1
        {
            return Err(NativeRuntimeError::InvalidCatalogReadLimit);
        }
        let Some(root) = snapshot.root else {
            return Ok(CatalogVisibleObjectPage {
                items: Vec::new(),
                continuation: None,
                exhausted: true,
            });
        };
        self.require_catalog_v7(root)?;

        let tree = BTree::from_root(root);
        let mut traversal = request
            .scopes
            .iter()
            .copied()
            .map(|scope| {
                self.next_catalog_visible_id(tree, root, scope, request.start_after)
                    .map(|current| CatalogVisibleTraversal { scope, current })
            })
            .collect::<Result<Vec<_>, _>>()?;
        let mut items = Vec::new();
        let mut returned_bytes = 0_usize;
        let mut considered = 0_usize;
        let mut last_considered = None;
        while let Some(id) = traversal.iter().filter_map(|state| state.current).min() {
            for state in traversal
                .iter_mut()
                .filter(|state| state.current == Some(id))
            {
                state.current = self.next_catalog_visible_id(tree, root, state.scope, Some(id))?;
            }
            considered = considered.saturating_add(1);
            last_considered = Some(id);
            let object = self
                .logical_catalog_object_at_root(root, id)?
                .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
            if request
                .parent
                .is_some_and(|parent| object.parent() != Some(parent))
                || request.kind.is_some_and(|kind| object.kind() != kind)
            {
                if considered == request.visit_limit {
                    break;
                }
                continue;
            }
            let mut summary = logical_catalog_summary(&object);
            if let Some(parent) = summary.parent
                && !request.scopes.iter().copied().try_fold(
                    false,
                    |visible, scope| -> Result<bool, NativeRuntimeError> {
                        Ok(visible
                            || self
                                .catalog_object_is_in_visible_scope(tree, root, scope, parent)?)
                    },
                )?
            {
                summary.parent = None;
            }
            let bytes = catalog_summary_bytes(&summary)?;
            if returned_bytes
                .checked_add(bytes)
                .is_none_or(|total| total > request.byte_limit)
            {
                last_considered = items.last().map(|item: &CatalogObjectSummary| item.id);
                break;
            }
            returned_bytes += bytes;
            items.push(summary);
            if items.len() == request.item_limit || considered == request.visit_limit {
                break;
            }
        }
        let exhausted = traversal.iter().all(|state| state.current.is_none())
            && items.len() < request.item_limit;
        if !exhausted && last_considered.is_none() {
            return Err(NativeRuntimeError::InvalidCatalogReadLimit);
        }
        Ok(CatalogVisibleObjectPage {
            items,
            continuation: (!exhausted).then_some(last_considered).flatten(),
            exhausted,
        })
    }

    fn next_catalog_visible_id(
        &self,
        tree: BTree,
        root: PageId,
        scope: CatalogVisibleScope,
        after: Option<ObjectId>,
    ) -> Result<Option<ObjectId>, NativeRuntimeError> {
        match scope {
            CatalogVisibleScope::Object(id) => {
                if after.is_some_and(|after| id <= after) {
                    return Ok(None);
                }
                self.logical_catalog_object_at_root(root, id)
                    .map(|object| object.map(|_| id))
            }
            CatalogVisibleScope::Instance => {
                let start = after.map(catalog_object_key);
                let mut current = None;
                let mut failure = None;
                let _ = tree.visit_prefix_cached(
                    &self.pages,
                    &self.buffer_pool,
                    &[CATALOG_OBJECT_PREFIX],
                    start.as_deref(),
                    |key, _| match decode_catalog_object_key(key) {
                        Ok(id) => {
                            current = Some(id);
                            ControlFlow::Break(())
                        }
                        Err(error) => {
                            failure = Some(error);
                            ControlFlow::Break(())
                        }
                    },
                )?;
                failure.map_or(Ok(current), Err)
            }
            CatalogVisibleScope::Subtree(ancestor) => {
                let prefix = catalog_ancestor_descendant_prefix(ancestor);
                let start = after.map(|after| catalog_ancestor_descendant_key(ancestor, after));
                let mut current = None;
                let mut failure = None;
                let _ = tree.visit_prefix_cached(
                    &self.pages,
                    &self.buffer_pool,
                    &prefix,
                    start.as_deref(),
                    |key, value| match decode_catalog_ancestor_descendant_entry(key, value) {
                        Ok((found, descendant)) if found == ancestor => {
                            current = Some(descendant);
                            ControlFlow::Break(())
                        }
                        Ok(_) => {
                            failure = Some(NativeRuntimeError::InvalidCatalogTree);
                            ControlFlow::Break(())
                        }
                        Err(error) => {
                            failure = Some(error);
                            ControlFlow::Break(())
                        }
                    },
                )?;
                failure.map_or(Ok(current), Err)
            }
        }
    }

    fn catalog_object_is_in_visible_scope(
        &self,
        tree: BTree,
        root: PageId,
        scope: CatalogVisibleScope,
        object: ObjectId,
    ) -> Result<bool, NativeRuntimeError> {
        match scope {
            CatalogVisibleScope::Instance => {
                Ok(self.logical_catalog_object_at_root(root, object)?.is_some())
            }
            CatalogVisibleScope::Object(visible) => {
                Ok(visible == object
                    && self.logical_catalog_object_at_root(root, object)?.is_some())
            }
            CatalogVisibleScope::Subtree(ancestor) => {
                if tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &catalog_ancestor_descendant_key(ancestor, object),
                    )?
                    .is_some()
                {
                    Ok(self.logical_catalog_object_at_root(root, object)?.is_some())
                } else {
                    Ok(false)
                }
            }
        }
    }

    /// Describes one complete logical V2 object by stable identity.
    ///
    /// # Errors
    ///
    /// Returns an error for unsupported legacy roots or durable corruption.
    pub fn catalog_describe(
        &self,
        snapshot: &NativeCatalogSnapshot,
        id: ObjectId,
    ) -> Result<CatalogDescription, NativeRuntimeError> {
        self.require_catalog_snapshot(snapshot)?;
        let object = snapshot
            .root
            .map(|root| {
                self.require_catalog_v6(root)?;
                self.logical_catalog_object_at_root(root, id)
            })
            .transpose()?
            .flatten();
        Ok(CatalogDescription {
            snapshot: snapshot.identity,
            object,
        })
    }

    /// Resolves one logical V2 object by normalized qualified name.
    ///
    /// # Errors
    ///
    /// Returns an error for unsupported legacy roots or durable corruption.
    pub fn catalog_resolve(
        &self,
        snapshot: &NativeCatalogSnapshot,
        name: &QualifiedName,
    ) -> Result<CatalogDescription, NativeRuntimeError> {
        self.require_catalog_snapshot(snapshot)?;
        let object = snapshot
            .root
            .map(|root| {
                self.require_catalog_v6(root)?;
                self.logical_catalog_object_named_at_root(root, name)
            })
            .transpose()?
            .flatten();
        Ok(CatalogDescription {
            snapshot: snapshot.identity,
            object,
        })
    }

    /// Lists canonical outgoing dependencies or incoming dependents through a
    /// bounded derived namespace traversal.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid bounds, unsupported legacy roots, or
    /// malformed dependency namespace entries.
    pub fn catalog_dependencies(
        &self,
        snapshot: &NativeCatalogSnapshot,
        request: CatalogDependencyRequest,
    ) -> Result<CatalogDependencyPage, NativeRuntimeError> {
        self.require_catalog_snapshot(snapshot)?;
        validate_catalog_read_limits(request.item_limit, request.visit_limit, request.byte_limit)?;
        let mut page = CatalogDependencyPage {
            snapshot: snapshot.identity,
            items: Vec::new(),
            continuation: None,
            stop: CatalogPageStop::Exhausted,
            visited: 0,
            returned_bytes: 0,
        };
        let resume = request.start_after;
        let Some(root) = snapshot.root else {
            return Ok(page);
        };
        self.require_catalog_v6(root)?;
        let prefix = catalog_dependency_prefix(request.object, request.direction);
        let start_key = request.start_after.map(|adjacent| {
            catalog_dependency_cursor_key(request.object, request.direction, adjacent)
        });
        let mut failure = None;
        let visit = BTree::from_root(root).visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            start_key.as_deref(),
            |key, value| {
                page.visited += 1;
                match decode_catalog_dependency_entry(key, value, request.direction) {
                    Ok((edge, adjacent)) => {
                        const EDGE_BYTES: usize = 33;
                        if page.returned_bytes + EDGE_BYTES > request.byte_limit {
                            page.stop = CatalogPageStop::ByteLimit;
                            page.continuation = page
                                .items
                                .last()
                                .map(|edge| match request.direction {
                                    DependencyDirection::Outgoing => edge.prerequisite,
                                    DependencyDirection::Incoming => edge.dependent,
                                })
                                .or(resume);
                            return ControlFlow::Break(());
                        }
                        page.returned_bytes += EDGE_BYTES;
                        page.items.push(edge);
                        if page.items.len() == request.item_limit {
                            page.stop = CatalogPageStop::ItemLimit;
                            page.continuation = Some(adjacent);
                            return ControlFlow::Break(());
                        }
                        if page.visited == request.visit_limit {
                            page.stop = CatalogPageStop::VisitLimit;
                            page.continuation = Some(adjacent);
                            return ControlFlow::Break(());
                        }
                        ControlFlow::Continue(())
                    }
                    Err(error) => {
                        failure = Some(error);
                        ControlFlow::Break(())
                    }
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if visit.is_continue() {
            page.stop = CatalogPageStop::Exhausted;
            page.continuation = None;
        }
        Ok(page)
    }

    fn require_catalog_snapshot(
        &self,
        snapshot: &NativeCatalogSnapshot,
    ) -> Result<(), NativeRuntimeError> {
        if snapshot.directory_lineage != self.directory_guard.identity().lineage().encode() {
            return Err(NativeRuntimeError::CatalogSnapshotMismatch);
        }
        Ok(())
    }

    fn require_catalog_v6(&self, root: PageId) -> Result<(), NativeRuntimeError> {
        let page = self.buffer_pool.get_or_load(&self.pages, root)?;
        if !matches!(
            page.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::CatalogV2Unavailable);
        }
        let marker = BTree::from_root(root)
            .get_cached_pinned(&self.pages, &self.buffer_pool, CATALOG_FORMAT_KEY)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if matches!(
            marker.bytes(),
            CATALOG_FORMAT_VALUE_V6 | CATALOG_FORMAT_VALUE_V7
        ) {
            Ok(())
        } else if marker.bytes() == CATALOG_FORMAT_VALUE_V3
            || marker.bytes() == CATALOG_FORMAT_VALUE_V4
            || marker.bytes() == CATALOG_FORMAT_VALUE_V5
        {
            Err(NativeRuntimeError::CatalogV2Unavailable)
        } else {
            Err(NativeRuntimeError::InvalidCatalogTree)
        }
    }

    fn require_catalog_v7(&self, root: PageId) -> Result<(), NativeRuntimeError> {
        self.require_catalog_v6(root)?;
        let marker = BTree::from_root(root)
            .get_cached_pinned(&self.pages, &self.buffer_pool, CATALOG_FORMAT_KEY)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if marker.bytes() == CATALOG_FORMAT_VALUE_V7 {
            Ok(())
        } else {
            Err(NativeRuntimeError::CatalogV2Unavailable)
        }
    }

    fn require_delta_catalog_v6(&self, root: PageId) -> Result<(), NativeRuntimeError> {
        self.require_catalog_v6(root).map_err(|error| {
            if matches!(error, NativeRuntimeError::CatalogV2Unavailable) {
                NativeRuntimeError::InvalidPreparedMutation
            } else {
                error
            }
        })
    }

    fn logical_catalog_object_at_root(
        &self,
        root: PageId,
        id: ObjectId,
    ) -> Result<Option<LogicalCatalogObject>, NativeRuntimeError> {
        let Some(stored) = BTree::from_root(root).get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &catalog_object_key(id),
        )?
        else {
            return Ok(None);
        };
        let definition = decode_catalog_definition_storage_value(stored.bytes(), &self.blobs)?;
        decode_logical_catalog_definition(&definition, id).map(Some)
    }

    fn logical_catalog_object_named_at_root(
        &self,
        root: PageId,
        name: &QualifiedName,
    ) -> Result<Option<LogicalCatalogObject>, NativeRuntimeError> {
        let name_key = catalog_name_key_from_qualified(name)?;
        let tree = BTree::from_root(root);
        let Some(encoded_id) = tree.get_cached_pinned(&self.pages, &self.buffer_pool, &name_key)?
        else {
            return Ok(None);
        };
        let id = decode_catalog_name_value(encoded_id.bytes())?;
        let object = self
            .logical_catalog_object_at_root(root, id)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if catalog_name_key_from_qualified(object.name())? != name_key {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        Ok(Some(object))
    }

    fn catalog_object_named_at_root(
        &self,
        root: PageId,
        name: &QualifiedName,
    ) -> Result<Option<CatalogObject>, NativeRuntimeError> {
        let frame = self.buffer_pool.get_or_load(&self.pages, root)?;
        if frame.page().kind() == PageKind::CatalogRoot {
            let catalog = CatalogState::decode(frame.page().payload())?;
            let identity = catalog_name_identity_from_qualified(name)?;
            return Ok(catalog
                .objects
                .values()
                .find(|object| {
                    catalog_name_identity(object.header())
                        .is_ok_and(|candidate| candidate == identity)
                })
                .cloned());
        }
        if !matches!(
            frame.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        let name_key = catalog_name_key_from_qualified(name)?;
        let tree = BTree::from_root(root);
        let Some(encoded_id) = tree.get_cached_pinned(&self.pages, &self.buffer_pool, &name_key)?
        else {
            return Ok(None);
        };
        if encoded_id.bytes().len() != 16 {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        let id = ObjectId::new(u128::from_be_bytes(
            encoded_id
                .bytes()
                .try_into()
                .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
        ))
        .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
        let Some(object) = self.catalog_object_at_root(root, id)? else {
            if self.logical_catalog_object_at_root(root, id)?.is_some() {
                return Ok(None);
            }
            return Err(NativeRuntimeError::InvalidCatalogTree);
        };
        if catalog_name_key(object.header())? != name_key {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        Ok(Some(object))
    }

    fn delta_catalog_object_at_root(
        &self,
        batch: &NativeWriteBatch,
        root: PageId,
        id: ObjectId,
        already_planned_bytes: u64,
    ) -> Result<Option<(CatalogObject, u64)>, NativeRuntimeError> {
        let frame = self.buffer_pool.get_or_load(&self.pages, root)?;
        if !matches!(
            frame.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let Some(stored) = BTree::from_root(root).get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &catalog_object_key(id),
        )?
        else {
            return Ok(None);
        };
        let envelope = decode_delta_catalog_definition(stored.bytes())?;
        let retained_bytes = delta_catalog_definition_charge(envelope.logical_bytes());
        Self::ensure_delta_memory_growth(
            batch,
            already_planned_bytes.saturating_add(retained_bytes),
        )?;
        let definition = envelope.materialize(&self.blobs)?;
        if definition.starts_with(b"HYCOBJ02") {
            return Ok(None);
        }
        let object = CatalogObject::decode_definition(&definition)?;
        if object.header().id != id {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        Ok(Some((object, retained_bytes)))
    }

    fn delta_catalog_object_named_at_root(
        &self,
        batch: &NativeWriteBatch,
        root: PageId,
        name: &QualifiedName,
    ) -> Result<Option<(CatalogObject, u64)>, NativeRuntimeError> {
        let frame = self.buffer_pool.get_or_load(&self.pages, root)?;
        if !matches!(
            frame.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let name_key = catalog_name_key_from_qualified(name)?;
        let tree = BTree::from_root(root);
        let Some(encoded_id) = tree.get_cached_pinned(&self.pages, &self.buffer_pool, &name_key)?
        else {
            return Ok(None);
        };
        let id = decode_catalog_name_value(encoded_id.bytes())?;
        let object = self
            .delta_catalog_object_at_root(batch, root, id, 0)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if catalog_name_key(object.0.header())? != name_key {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        Ok(Some(object))
    }

    fn delta_catalog_secondary_indexes_at_root(
        &self,
        batch: &NativeWriteBatch,
        root: PageId,
        relation: ObjectId,
        relation_bytes: u64,
    ) -> Result<Vec<(CatalogObject, u64)>, NativeRuntimeError> {
        let frame = self.buffer_pool.get_or_load(&self.pages, root)?;
        if !matches!(
            frame.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let tree = BTree::from_root(root);
        let marker = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, CATALOG_FORMAT_KEY)?
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        if !matches!(
            marker.bytes(),
            CATALOG_FORMAT_VALUE_V4
                | CATALOG_FORMAT_VALUE_V5
                | CATALOG_FORMAT_VALUE_V6
                | CATALOG_FORMAT_VALUE_V7
        ) {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let prefix = catalog_relation_index_prefix(relation);
        let mut count = 0_usize;
        let mut failure = None;
        let _ = tree.visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            None,
            |key, value| {
                if key.len() != 33 || !value.is_empty() {
                    failure = Some(NativeRuntimeError::InvalidCatalogTree);
                    return ControlFlow::Break(());
                }
                count = count.saturating_add(1);
                ControlFlow::Continue(())
            },
        )?;
        if let Some(failure) = failure {
            return Err(failure);
        }
        let identities_bytes = u64::try_from(count)
            .unwrap_or(u64::MAX)
            .saturating_mul(DELTA_TREE_ENTRY_OVERHEAD.saturating_add(
                u64::try_from(std::mem::size_of::<ObjectId>()).unwrap_or(u64::MAX),
            ));
        Self::ensure_delta_memory_growth(batch, relation_bytes.saturating_add(identities_bytes))?;
        let mut identities = Vec::with_capacity(count);
        let _ =
            tree.visit_prefix_cached(&self.pages, &self.buffer_pool, &prefix, None, |key, _| {
                let decoded = key[17..]
                    .try_into()
                    .map(u128::from_be_bytes)
                    .map_err(|_| ())
                    .and_then(|encoded| ObjectId::new(encoded).map_err(|_| ()));
                if let Ok(index) = decoded {
                    identities.push(index);
                } else {
                    failure = Some(NativeRuntimeError::InvalidCatalogTree);
                    return ControlFlow::Break(());
                }
                ControlFlow::Continue(())
            })?;
        if let Some(failure) = failure {
            return Err(failure);
        }
        let mut planned_bytes = relation_bytes.saturating_add(identities_bytes);
        let mut indexes = Vec::with_capacity(count);
        for index in identities {
            let (object, retained_bytes) = self
                .delta_catalog_object_at_root(batch, root, index, planned_bytes)?
                .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
            if !matches!(
                &object,
                CatalogObject::SecondaryIndex(definition)
                    if definition.relation == relation
            ) {
                return Err(NativeRuntimeError::InvalidCatalogTree);
            }
            planned_bytes = planned_bytes.saturating_add(retained_bytes);
            indexes.push((object, retained_bytes));
        }
        Ok(indexes)
    }

    fn require_delta_relation_without_foreign_keys(
        &self,
        batch: &NativeWriteBatch,
        root: PageId,
        relation: ObjectId,
    ) -> Result<(), NativeRuntimeError> {
        let Some(CatalogObject::Relation(definition)) = batch.state.catalog.object(relation) else {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        };
        if !definition.foreign_keys.is_empty() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let tree = BTree::from_root(root);
        let prefix = catalog_dependency_prefix(relation, DependencyDirection::Incoming);
        let mut count = 0_usize;
        let mut failure = None;
        let _ = tree.visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            None,
            |key, value| {
                match decode_catalog_dependency_entry(key, value, DependencyDirection::Incoming) {
                    Ok(_) => count = count.saturating_add(1),
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                }
                ControlFlow::Continue(())
            },
        )?;
        if let Some(failure) = failure {
            return Err(failure);
        }
        let identities_bytes = u64::try_from(count)
            .unwrap_or(u64::MAX)
            .saturating_mul(DELTA_TREE_ENTRY_OVERHEAD.saturating_add(
                u64::try_from(std::mem::size_of::<ObjectId>()).unwrap_or(u64::MAX),
            ));
        Self::ensure_delta_memory_growth(batch, identities_bytes)?;
        let mut adjacent = Vec::with_capacity(count);
        let _ = tree.visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            None,
            |key, value| {
                match decode_catalog_dependency_entry(key, value, DependencyDirection::Incoming) {
                    Ok((_, object)) => adjacent.push(object),
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                }
                ControlFlow::Continue(())
            },
        )?;
        if let Some(failure) = failure {
            return Err(failure);
        }
        let mut planned = identities_bytes;
        for object in adjacent {
            let Some((object, retained_bytes)) =
                self.delta_catalog_object_at_root(batch, root, object, planned)?
            else {
                return Err(NativeRuntimeError::InvalidPreparedMutation);
            };
            planned = planned.saturating_add(retained_bytes);
            if matches!(object, CatalogObject::Relation(_)) {
                return Err(NativeRuntimeError::InvalidPreparedMutation);
            }
        }
        Ok(())
    }

    fn catalog_object_at_root(
        &self,
        root: PageId,
        id: ObjectId,
    ) -> Result<Option<CatalogObject>, NativeRuntimeError> {
        let frame = self.buffer_pool.get_or_load(&self.pages, root)?;
        if frame.page().kind() == PageKind::CatalogRoot {
            return Ok(CatalogState::decode(frame.page().payload())?
                .object(id)
                .cloned());
        }
        if !matches!(
            frame.page().kind(),
            PageKind::BTreeLeaf | PageKind::BTreeInternal
        ) {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        let Some(stored) = BTree::from_root(root).get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &catalog_object_key(id),
        )?
        else {
            return Ok(None);
        };
        let definition = decode_catalog_definition_storage_value(stored.bytes(), &self.blobs)?;
        if definition.starts_with(b"HYCOBJ02") {
            return Ok(None);
        }
        let object = CatalogObject::decode_definition(&definition)?;
        if object.header().id != id {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        Ok(Some(object))
    }

    /// Materializes one immutable all-engine read snapshot.
    ///
    /// # Errors
    ///
    /// Returns an error for synchronization, page, root, or state corruption.
    pub fn snapshot(&self, logical_time_micros: i64) -> Result<NativeSnapshot, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        self.snapshot_unadmitted(logical_time_micros)
    }

    fn snapshot_unadmitted(
        &self,
        logical_time_micros: i64,
    ) -> Result<NativeSnapshot, NativeRuntimeError> {
        let metadata = self.coordinator.snapshot(logical_time_micros)?;
        let digest = metadata.roots().digest();
        let cached = self
            .snapshot_state_cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .as_ref()
            .and_then(|(key, state)| (*key == digest).then(|| Arc::clone(state)));
        let state = if let Some(state) = cached {
            state
        } else {
            let state = Arc::new(load_state(&self.pages, &self.blobs, metadata.roots())?);
            *self
                .snapshot_state_cache
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) =
                Some((digest, Arc::clone(&state)));
            state
        };
        Ok(NativeSnapshot { metadata, state })
    }

    /// Returns the number of verified durable snapshot pins.
    pub fn snapshot_pin_count(&self) -> usize {
        self.snapshot_pins.len()
    }

    /// Checkpoints and durably pins the current committed all-engine state.
    ///
    /// # Errors
    ///
    /// Returns an error for an empty database, duplicate identity, checkpoint
    /// failure, or uncertain pin publication.
    pub fn pin_current(
        &mut self,
        id: SnapshotPinId,
        logical_time_micros: i64,
    ) -> Result<SnapshotPinReceipt, NativeRuntimeError> {
        self.pin_current_at(id, logical_time_micros, None)
    }

    /// Checkpoints and pins the current state with one deterministic
    /// interruption.
    ///
    /// After an injected interruption the caller must drop this handle and
    /// reopen the data directory.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::InjectedSnapshotPinCrash`] at the
    /// requested boundary, or the same errors as [`Self::pin_current`].
    pub fn pin_current_with_interruption(
        &mut self,
        id: SnapshotPinId,
        logical_time_micros: i64,
        boundary: SnapshotPinBoundary,
    ) -> Result<SnapshotPinReceipt, NativeRuntimeError> {
        self.pin_current_at(id, logical_time_micros, Some(boundary))
    }

    fn pin_current_at(
        &mut self,
        id: SnapshotPinId,
        logical_time_micros: i64,
        interruption: Option<SnapshotPinBoundary>,
    ) -> Result<SnapshotPinReceipt, NativeRuntimeError> {
        let _permit = self.admit_administrative_owned()?;
        if self.snapshot_pins.get(id).is_some() {
            return Err(NativeRuntimeError::SnapshotPinExists);
        }
        let checkpoint = self.checkpoint_at(None)?;
        let manifest = self
            .manifests
            .current()
            .ok_or(NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        if manifest.generation() != checkpoint.manifest_generation
            || manifest.digest() != checkpoint.manifest_digest
        {
            return Err(NativeRuntimeError::InvalidSnapshotPinAuthority);
        }
        let roots = self
            .coordinator
            .snapshot(logical_time_micros)?
            .roots()
            .clone();
        let pin = SnapshotPin::from_manifest(
            id,
            logical_time_micros,
            self.directory_guard.identity().lineage(),
            manifest,
            &roots,
        )?;
        let staged = self
            .snapshot_pins
            .stage(pin, true)
            .map_err(|error| match error {
                SnapshotPinError::PublicationTargetExists => NativeRuntimeError::SnapshotPinExists,
                error => NativeRuntimeError::SnapshotPin(error),
            })?;
        interrupt_snapshot_pin(interruption, SnapshotPinBoundary::RecordSynchronized)?;
        let pin = self.snapshot_pins.publish(staged, true)?;
        interrupt_snapshot_pin(interruption, SnapshotPinBoundary::RecordPublished)?;
        Ok(snapshot_pin_receipt(&pin))
    }

    /// Materializes one exact durable historical all-engine snapshot.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown pin or any manifest, page, root, blob,
    /// or lineage divergence.
    pub fn open_pinned_snapshot(
        &self,
        id: SnapshotPinId,
    ) -> Result<NativeSnapshot, NativeRuntimeError> {
        let _permit = self.admit_administrative_owned()?;
        let pin = self
            .snapshot_pins
            .get(id)
            .ok_or(NativeRuntimeError::UnknownSnapshotPin)?;
        let manifest = manifest_by_generation(
            &self.manifests.recovery().manifests,
            pin.manifest_generation(),
        )
        .cloned()
        .ok_or(NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        if !pin.matches_manifest(&manifest) {
            return Err(NativeRuntimeError::InvalidSnapshotPinAuthority);
        }
        let roots = manifest.to_root_set()?;
        let pages = PageStore::open_generation(
            page_generation_path(&self.data_directory, pin.page_generation()),
            pin.page_generation(),
        )
        .map_err(|_| NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        validate_roots(&pages, &self.blobs, &roots, pin.visible_csn())
            .map_err(|_| NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        let state = Arc::new(load_state(&pages, &self.blobs, &roots)?);
        let metadata = Snapshot::from_committed_root(roots, pin.logical_time_micros())?;
        Ok(NativeSnapshot { metadata, state })
    }

    /// Durably removes one snapshot retention claim without collecting files.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown identity or uncertain file removal.
    pub fn unpin(&mut self, id: SnapshotPinId) -> Result<SnapshotUnpinReceipt, NativeRuntimeError> {
        let _permit = self.admit_administrative_owned()?;
        let pin = self
            .snapshot_pins
            .remove(id, true)?
            .ok_or(NativeRuntimeError::UnknownSnapshotPin)?;
        Ok(SnapshotUnpinReceipt {
            id: pin.id(),
            visible_csn: pin.visible_csn(),
            page_generation: pin.page_generation(),
            parent_directory_sync_supported: cfg!(unix),
        })
    }

    /// Removes complete inactive page generations that no stable pin retains.
    ///
    /// # Errors
    ///
    /// Returns an error for a noncanonical entry, deletion failure, byte-count
    /// overflow, or uncertain directory synchronization.
    pub fn collect_retired_page_generations(
        &mut self,
    ) -> Result<PageGenerationCollectionReceipt, NativeRuntimeError> {
        let _permit = self.admit_administrative_owned()?;
        collect_page_generation_files(
            &self.data_directory,
            self.pages.generation(),
            &self.snapshot_pins.pinned_generations(),
        )
    }

    /// Binds one parameterized SQL `SELECT` against only the current catalog.
    ///
    /// Unlike [`Self::snapshot`], this does not materialize any relational,
    /// structure, or search state.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot coordination, catalog corruption,
    /// unsupported syntax, or an unknown relation.
    pub fn prepare_sql_latest(&self, statement: &str) -> Result<PreparedStatement, SqlError> {
        let _permit = self.admit_foreground_bounded()?;
        let metadata = self
            .coordinator
            .snapshot(0)
            .map_err(NativeRuntimeError::from)?;
        if let Some(prepared) = self
            .sql_plan_cache()
            .lookup(metadata.catalog_version, statement)
        {
            return Ok(prepared);
        }
        let catalog = load_catalog_state(&self.pages, &self.blobs, metadata.roots())?;
        let ordered_secondary_indexes = self.ordered_secondary_indexes_at(&metadata, &catalog)?;
        let prepared = sql::prepare_catalog(
            metadata.catalog_version,
            &catalog,
            &ordered_secondary_indexes,
            statement,
        )?;
        self.sql_plan_cache().insert(statement, prepared.clone());
        Ok(prepared)
    }

    /// Parses and binds one SQL statement against the current catalog.
    ///
    /// Read bindings retain their prepared plan; write bindings retain the
    /// parsed statement plus every relation, index, and foreign-key dependency
    /// that execution may touch.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot coordination, malformed SQL, invalid
    /// parameters, or an unresolved catalog dependency.
    pub fn bind_sql_latest(
        &self,
        statement: &str,
        parameters: &[SqlValue],
    ) -> Result<BoundSqlStatement, SqlError> {
        let _permit = self.admit_foreground_bounded()?;
        let metadata = self
            .coordinator
            .snapshot(0)
            .map_err(NativeRuntimeError::from)?;
        let catalog = load_catalog_state(&self.pages, &self.blobs, metadata.roots())?;
        let ordered_secondary_indexes = self.ordered_secondary_indexes_at(&metadata, &catalog)?;
        sql::bind_catalog(
            metadata.catalog_version,
            &catalog,
            &ordered_secondary_indexes,
            statement,
            parameters,
        )
    }

    /// Executes one current catalog-bound SQL plan through physical roots.
    ///
    /// The execution captures one root-set snapshot and does not materialize
    /// complete engine state.
    ///
    /// # Errors
    ///
    /// Returns an error for a stale catalog binding, invalid parameters,
    /// missing index metadata, or physical storage corruption.
    pub fn execute_prepared_latest(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
    ) -> Result<SqlResult, SqlError> {
        self.execute_prepared_latest_profiled(prepared, parameters)
            .map(|receipt| receipt.result)
    }

    /// Executes a current catalog-bound SQL plan and reports its physical path.
    ///
    /// Large bounded primary-key scans reserve one parent governor request and
    /// may subdivide it across the persistent NUMA-aware execution pool. Small
    /// operations retain the direct single-worker path.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::execute_prepared_latest`], including
    /// fail-closed governor admission errors.
    pub fn execute_prepared_latest_profiled(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
    ) -> Result<NativeSqlExecutionReceipt, SqlError> {
        self.execute_prepared_latest_profiled_with_checkpoint(prepared, parameters, || true)
    }

    /// Executes a current catalog-bound SQL plan with a cooperative checkpoint.
    ///
    /// The callback runs during bounded scan, join, and vector-batch loops.
    /// Returning `false` interrupts execution before a partial result is returned.
    ///
    /// # Errors
    ///
    /// Returns the profiled execution errors or [`SqlError::ExecutionInterrupted`].
    pub fn execute_prepared_latest_profiled_with_checkpoint(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
        mut checkpoint: impl FnMut() -> bool,
    ) -> Result<NativeSqlExecutionReceipt, SqlError> {
        let permit = match prepared.parallel_scan_limit() {
            Some(limit) => self.admit_parallel_foreground_bounded_io(
                segmented_result_memory_bytes(limit),
                limit.div_ceil(sql::SQL_VECTOR_PATH_THRESHOLD),
            )?,
            None => self.admit_foreground_bounded()?,
        };
        let metadata = self
            .coordinator
            .snapshot(0)
            .map_err(NativeRuntimeError::from)?;
        let snapshot_csn = metadata
            .visible_csn
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let catalog_version = metadata.catalog_version;
        let root_digest = metadata.roots().digest();
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (result, profile) = sql::execute_prepared_latest(
            self,
            &metadata,
            prepared,
            parameters,
            permit.as_ref().map(DatabaseGovernorPermit::permit),
            &mut checkpoint,
        )?;
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSqlExecutionReceipt {
            snapshot_csn,
            catalog_version,
            root_digest,
            path: profile.path,
            candidate_rows: profile.candidate_rows,
            index_stream_rows: profile.index_stream_rows,
            intersection_start_rows: profile.intersection_start_rows,
            join_right_probes: profile.join_right_probes,
            vector_batches: profile.vector_batches,
            planned_workers: planned_workers.max(profile.planned_workers),
            worker_batches: profile.worker_batches,
            execution,
            result,
        })
    }

    /// Executes one current catalog-bound SQL plan and returns the exact CSN
    /// and catalog version used by physical execution.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::execute_prepared_latest`].
    pub fn execute_prepared_latest_identified(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
    ) -> Result<(Csn, CatalogVersion, [u8; 32], SqlResult), SqlError> {
        self.execute_prepared_latest_profiled(prepared, parameters)
            .map(|receipt| {
                (
                    receipt.snapshot_csn,
                    receipt.catalog_version,
                    receipt.root_digest,
                    receipt.result,
                )
            })
    }

    /// Executes one current prepared plan with cooperative loop checkpoints.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::execute_prepared_latest_profiled_with_checkpoint`].
    pub fn execute_prepared_latest_identified_with_checkpoint(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
        checkpoint: impl FnMut() -> bool,
    ) -> Result<(Csn, CatalogVersion, [u8; 32], SqlResult), SqlError> {
        self.execute_prepared_latest_profiled_with_checkpoint(prepared, parameters, checkpoint)
            .map(|receipt| {
                (
                    receipt.snapshot_csn,
                    receipt.catalog_version,
                    receipt.root_digest,
                    receipt.result,
                )
            })
    }

    pub(crate) fn execute_prepared_latest_with_csn(
        &self,
        prepared: &PreparedStatement,
        parameters: &[SqlValue],
    ) -> Result<(Csn, SqlResult), SqlError> {
        self.execute_prepared_latest_identified(prepared, parameters)
            .map(|(csn, _, _, result)| (csn, result))
    }

    /// Performs an owned primary-key lookup through the current relational
    /// B+tree root without materializing the complete relation state.
    ///
    /// # Errors
    ///
    /// Returns an error for page or B+tree corruption.
    pub fn select_latest_relational(
        &self,
        table: ObjectId,
        primary_key: &[u8],
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        let snapshot = self.coordinator.snapshot(0)?;
        self.select_relational_at(&snapshot, table, primary_key)
    }

    fn select_relational_at(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        primary_key: &[u8],
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            return Ok(None);
        };
        let encoded = BTree::from_root(root).get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &relational_row_key(table, primary_key),
        )?;
        encoded
            .map(|encoded| {
                let context = RelationalReadContext {
                    pages: &self.pages,
                    pool: &self.buffer_pool,
                    blobs: &self.blobs,
                    format: self.relational_format,
                    visible_csn: snapshot.visible_csn,
                };
                decode_relational_value_cached(&context, table, primary_key, encoded.bytes())
            })
            .transpose()
            .map(Option::flatten)
    }

    fn select_delta_relational_value_at(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        primary_key: &[u8],
    ) -> Result<Option<DeltaRelationalValue>, NativeRuntimeError> {
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            return Ok(None);
        };
        let Some(encoded) = BTree::from_root(root).get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &relational_row_key(table, primary_key),
        )?
        else {
            return Ok(None);
        };
        match self.relational_format {
            RelationalFormat::InlineRowV1 => {
                let row = RowRecordView::decode(encoded.bytes())?;
                if row.row_id() != relational_row_id(table, primary_key)?
                    || !row.is_visible_at(snapshot.visible_csn)
                {
                    return Ok(None);
                }
                decode_delta_relational_row_value(row, primary_key)
            }
            RelationalFormat::VersionChainV2 => {
                let mut page_id = RowVersionPointer::decode(encoded.bytes())?.page_id;
                let mut stack_visited = [0_u64; 64];
                let mut overflow_visited = None;
                let mut depth = 0_usize;
                let mut newer_begin = None;
                loop {
                    track_version_page(page_id, depth, &mut stack_visited, &mut overflow_visited)?;
                    let frame = self.buffer_pool.get_or_load(&self.pages, page_id)?;
                    let page = frame.page();
                    if page.kind() != PageKind::VersionChain {
                        return Err(NativeRuntimeError::InvalidRelationalTree);
                    }
                    let row = RowRecordView::decode(page.payload())?;
                    validate_version_page(
                        page,
                        row,
                        table,
                        primary_key,
                        snapshot.visible_csn,
                        newer_begin,
                    )?;
                    if row.is_visible_at(snapshot.visible_csn) {
                        return decode_delta_relational_row_value(row, primary_key);
                    }
                    newer_begin = Some(row.begin_csn());
                    page_id = page
                        .next()
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                    depth = depth
                        .checked_add(1)
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                }
            }
        }
    }

    fn ordered_secondary_indexes_at(
        &self,
        snapshot: &Snapshot,
        catalog: &CatalogState,
    ) -> Result<BTreeSet<ObjectId>, NativeRuntimeError> {
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            if catalog
                .objects
                .values()
                .any(|object| matches!(object, CatalogObject::SecondaryIndex(_)))
            {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
            return Ok(BTreeSet::new());
        };
        let tree = BTree::from_root(root);
        let mut ordered = BTreeSet::new();
        for (index, object) in &catalog.objects {
            let CatalogObject::SecondaryIndex(definition) = object else {
                continue;
            };
            let metadata = tree
                .get_cached_pinned(
                    &self.pages,
                    &self.buffer_pool,
                    &relational_secondary_index_key(*index),
                )?
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let (relation, unique, nulls_distinct, layout) =
                decode_secondary_index_metadata(metadata.bytes())?;
            if relation != definition.relation
                || unique != definition.unique
                || nulls_distinct != definition.nulls_distinct
            {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
            if layout == SecondaryIndexLayout::OrderedV2 {
                ordered.insert(*index);
            }
        }
        Ok(ordered)
    }

    /// Scans visible current rows in canonical primary-key order without
    /// materializing the complete relation.
    ///
    /// `start_after` is an exclusive canonical primary-key cursor. A zero
    /// `limit` validates relation identity and returns no rows.
    ///
    /// # Errors
    ///
    /// Returns an error when the relation does not exist or when a reached
    /// physical key, row, page, blob, or version chain is malformed.
    pub fn scan_latest_relational(
        &self,
        table: ObjectId,
        start_after: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<RelationalScanRow>, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        self.scan_relational_at(&snapshot, table, start_after, limit)
    }

    /// Scans one bounded current primary-key range without materializing the
    /// complete relation.
    ///
    /// Bounds contain canonical primary-key bytes, not full physical keys.
    /// A zero `limit` validates relation identity and returns no rows.
    ///
    /// # Errors
    ///
    /// Returns an error when the relation does not exist or when a reached
    /// physical key, row, page, blob, or version chain is malformed.
    pub fn scan_latest_relational_range(
        &self,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        limit: usize,
    ) -> Result<Vec<RelationalScanRow>, NativeRuntimeError> {
        Ok(self
            .scan_latest_relational_range_profiled(table, lower, upper, limit)?
            .rows)
    }

    /// Scans one bounded primary-key range and reports whether the direct or
    /// immutable-segment physical path executed.
    ///
    /// # Errors
    ///
    /// Returns an error when the relation does not exist, resource admission
    /// fails, or a reached physical key, row, page, blob, or version chain is
    /// malformed.
    pub fn scan_latest_relational_range_profiled(
        &self,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        limit: usize,
    ) -> Result<NativeRelationalScanExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        if limit <= RELATIONAL_SEGMENT_SCAN_THRESHOLD {
            let rows = self.scan_relational_range_at(&snapshot, table, lower, upper, limit)?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeRelationalScanExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                rows,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        let (tree, prefix) = self.relational_table_tree_at(&snapshot, table)?;
        let plan = self.plan_btree_segments(
            tree,
            prefix,
            map_primary_key_bound(table, lower),
            map_primary_key_bound(table, upper),
            NativeRuntimeError::InvalidRelationalTree,
        )?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        if plan.segments.is_empty() {
            return Ok(NativeRelationalScanExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                rows: Vec::new(),
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            FOREGROUND_BOUNDED_MEMORY_BYTES,
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (rows, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_relational_segment_plan_parallel(
                    &snapshot,
                    table,
                    plan,
                    limit,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_relational_segment_plan_serial(&snapshot, table, &plan, limit)?,
                0,
            ),
        };
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeRelationalScanExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            rows,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn scan_relational_at(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        start_after: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<RelationalScanRow>, NativeRuntimeError> {
        let lower = start_after.map_or(Bound::Unbounded, Bound::Excluded);
        self.scan_relational_range_at(snapshot, table, lower, Bound::Unbounded, limit)
    }

    fn scan_relational_range_at(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        limit: usize,
    ) -> Result<Vec<RelationalScanRow>, NativeRuntimeError> {
        self.scan_relational_range_at_profiled(snapshot, table, lower, upper, limit)
            .map(|(rows, _, _)| rows)
    }

    pub(crate) fn scan_relational_range_at_governed(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        limit: usize,
        permit: Option<&OwnedGovernorPermit>,
    ) -> Result<(Vec<RelationalScanRow>, u64, usize), NativeRuntimeError> {
        let (tree, prefix) = self.relational_table_tree_at(snapshot, table)?;
        if limit == 0 {
            return Ok((Vec::new(), 0, 0));
        }
        let plan = self.plan_btree_segments(
            tree,
            prefix,
            map_primary_key_bound(table, lower),
            map_primary_key_bound(table, upper),
            NativeRuntimeError::InvalidRelationalTree,
        )?;
        if plan.segments.is_empty() {
            return Ok((Vec::new(), 0, 0));
        }
        let planned_workers = permit.map_or(1, |permit| permit.request().compute_threads);
        let (rows, worker_batches) = match (self.execution_pool.as_deref(), permit) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_relational_segment_plan_parallel(
                    snapshot,
                    table,
                    plan,
                    limit,
                    execution_pool,
                    permit,
                )?,
            _ => (
                self.scan_relational_segment_plan_serial(snapshot, table, &plan, limit)?,
                0,
            ),
        };
        Ok((rows, planned_workers, worker_batches))
    }

    fn scan_relational_range_at_profiled(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        limit: usize,
    ) -> Result<(Vec<RelationalScanRow>, usize, usize), NativeRuntimeError> {
        let (tree, prefix) = self.relational_table_tree_at(snapshot, table)?;
        if limit == 0 {
            return Ok((Vec::new(), 0, 0));
        }
        let lower = map_primary_key_bound(table, lower);
        let upper = map_primary_key_bound(table, upper);
        if limit > RELATIONAL_SEGMENT_SCAN_THRESHOLD {
            return self
                .scan_relational_segments_at(snapshot, tree, table, prefix, lower, upper, limit);
        }
        let context = RelationalReadContext {
            pages: &self.pages,
            pool: &self.buffer_pool,
            blobs: &self.blobs,
            format: self.relational_format,
            visible_csn: snapshot.visible_csn,
        };
        let mut rows = Vec::with_capacity(limit.min(256));
        let mut scan_error = None;
        let _outcome = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            bound_as_slice(&lower),
            bound_as_slice(&upper),
            |physical_key, encoded| {
                let Some(primary_key) = physical_key.get(prefix.len()..) else {
                    scan_error = Some(NativeRuntimeError::InvalidRelationalTree);
                    return ControlFlow::Break(());
                };
                match decode_relational_value_cached(&context, table, primary_key, encoded) {
                    Ok(Some(row)) => {
                        rows.push(RelationalScanRow {
                            table,
                            primary_key: primary_key.to_vec(),
                            row,
                        });
                        if rows.len() == limit {
                            ControlFlow::Break(())
                        } else {
                            ControlFlow::Continue(())
                        }
                    }
                    Ok(None) => ControlFlow::Continue(()),
                    Err(error) => {
                        scan_error = Some(error);
                        ControlFlow::Break(())
                    }
                }
            },
        )?;
        if let Some(error) = scan_error {
            return Err(error);
        }
        Ok((rows, 0, 0))
    }

    #[allow(clippy::too_many_arguments)]
    fn scan_relational_segments_at(
        &self,
        snapshot: &Snapshot,
        tree: BTree,
        table: ObjectId,
        prefix: Vec<u8>,
        lower: Bound<Vec<u8>>,
        upper: Bound<Vec<u8>>,
        limit: usize,
    ) -> Result<(Vec<RelationalScanRow>, usize, usize), NativeRuntimeError> {
        let plan = self.plan_btree_segments(
            tree,
            prefix,
            lower,
            upper,
            NativeRuntimeError::InvalidRelationalTree,
        )?;
        let rows = self.scan_relational_segment_plan_serial(snapshot, table, &plan, limit)?;
        Ok((rows, plan.segments.len(), plan.physical_entries))
    }

    fn plan_btree_segments(
        &self,
        tree: BTree,
        prefix: Vec<u8>,
        lower: Bound<Vec<u8>>,
        upper: Bound<Vec<u8>>,
        invalid_tree: NativeRuntimeError,
    ) -> Result<NativeBTreeSegmentPlan, NativeRuntimeError> {
        let planned_lower = match lower {
            Bound::Unbounded => Bound::Included(prefix.clone()),
            bound => bound,
        };
        let planned_upper = match upper {
            Bound::Unbounded => {
                byte_prefix_successor(&prefix).map_or(Bound::Unbounded, Bound::Excluded)
            }
            bound => bound,
        };
        let segments = tree.plan_range_segments(
            &self.pages,
            bound_as_slice(&planned_lower),
            bound_as_slice(&planned_upper),
        )?;
        let mut planned_physical_entries = 0_usize;
        for segment in &segments {
            let Some(next) = planned_physical_entries.checked_add(segment.entry_count()) else {
                return Err(invalid_tree);
            };
            planned_physical_entries = next;
        }
        Ok(NativeBTreeSegmentPlan {
            tree,
            prefix,
            segments,
            physical_entries: planned_physical_entries,
        })
    }

    fn scan_relational_segment_plan_serial(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        plan: &NativeBTreeSegmentPlan,
        limit: usize,
    ) -> Result<Vec<RelationalScanRow>, NativeRuntimeError> {
        let context = RelationalReadContext {
            pages: &self.pages,
            pool: &self.buffer_pool,
            blobs: &self.blobs,
            format: self.relational_format,
            visible_csn: snapshot.visible_csn,
        };
        let mut rows = Vec::with_capacity(limit.min(1_024));
        'segments: for segment in &plan.segments {
            for (physical_key, encoded) in plan.tree.scan_planned_segment(&self.pages, segment)? {
                let Some(primary_key) = physical_key.get(plan.prefix.len()..) else {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                };
                if let Some(row) =
                    decode_relational_value_cached(&context, table, primary_key, &encoded)?
                {
                    rows.push(RelationalScanRow {
                        table,
                        primary_key: primary_key.to_vec(),
                        row,
                    });
                    if rows.len() == limit {
                        break 'segments;
                    }
                }
            }
        }
        Ok(rows)
    }

    fn scan_relational_segment_plan_parallel(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        plan: NativeBTreeSegmentPlan,
        limit: usize,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<RelationalScanRow>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let blobs = Arc::new(self.blobs.read_handle());
        let pool = Arc::clone(&self.buffer_pool);
        let prefix = Arc::new(plan.prefix);
        let tree = plan.tree;
        let format = self.relational_format;
        let visible_csn = snapshot.visible_csn;
        let (segment_rows, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    let context = RelationalReadContext {
                        pages: &pages,
                        pool: &pool,
                        blobs: &blobs,
                        format,
                        visible_csn,
                    };
                    tree.scan_planned_segment(&pages, &segment)?
                        .into_iter()
                        .filter_map(|(physical_key, encoded)| {
                            let Some(primary_key) = physical_key.get(prefix.len()..) else {
                                return Some(Err(NativeRuntimeError::InvalidRelationalTree));
                            };
                            match decode_relational_value_cached(
                                &context,
                                table,
                                primary_key,
                                &encoded,
                            ) {
                                Ok(Some(row)) => Some(Ok(RelationalScanRow {
                                    table,
                                    primary_key: primary_key.to_vec(),
                                    row,
                                })),
                                Ok(None) => None,
                                Err(error) => Some(Err(error)),
                            }
                        })
                        .collect::<Result<Vec<_>, _>>()
                },
            )?;
        let mut rows = segment_rows
            .into_iter()
            .collect::<Result<Vec<_>, NativeRuntimeError>>()?
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        rows.truncate(limit);
        Ok((rows, worker_batches))
    }

    fn relational_table_tree_at(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
    ) -> Result<(BTree, Vec<u8>), NativeRuntimeError> {
        let root = snapshot
            .roots()
            .root(SLOT_RELATIONAL)
            .ok_or(NativeRuntimeError::UnknownRelation { table })?;
        let tree = BTree::from_root(root);
        let table_marker = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &relational_table_key(table))?
            .ok_or(NativeRuntimeError::UnknownRelation { table })?;
        if !table_marker.bytes().is_empty() {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        let prefix = relational_row_key(table, &[]);
        Ok((tree, prefix))
    }

    pub(crate) fn visit_relational_range_at<E>(
        &self,
        snapshot: &Snapshot,
        table: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        mut visitor: impl FnMut(&[u8], &[u8]) -> Result<ControlFlow<()>, E>,
    ) -> Result<(), RelationalVisitError<E>> {
        let (tree, prefix) = self
            .relational_table_tree_at(snapshot, table)
            .map_err(RelationalVisitError::Runtime)?;
        let lower = map_primary_key_bound(table, lower);
        let upper = map_primary_key_bound(table, upper);
        let context = RelationalReadContext {
            pages: &self.pages,
            pool: &self.buffer_pool,
            blobs: &self.blobs,
            format: self.relational_format,
            visible_csn: snapshot.visible_csn,
        };
        let mut failure = None;
        let _outcome = tree
            .visit_prefix_range_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                bound_as_slice(&lower),
                bound_as_slice(&upper),
                |physical_key, encoded| {
                    let Some(primary_key) = physical_key.get(prefix.len()..) else {
                        failure = Some(RelationalVisitError::Runtime(
                            NativeRuntimeError::InvalidRelationalTree,
                        ));
                        return ControlFlow::Break(());
                    };
                    match decode_relational_value_cached(&context, table, primary_key, encoded) {
                        Ok(Some(row)) => match visitor(primary_key, &row) {
                            Ok(control) => control,
                            Err(error) => {
                                failure = Some(RelationalVisitError::Visitor(error));
                                ControlFlow::Break(())
                            }
                        },
                        Ok(None) => ControlFlow::Continue(()),
                        Err(error) => {
                            failure = Some(RelationalVisitError::Runtime(error));
                            ControlFlow::Break(())
                        }
                    }
                },
            )
            .map_err(NativeRuntimeError::from)
            .map_err(RelationalVisitError::Runtime)?;
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(())
    }

    /// Performs an exact current secondary-index lookup through the relational
    /// B+tree without materializing the complete relation state.
    ///
    /// Results are ordered by canonical primary-key bytes.
    ///
    /// # Errors
    ///
    /// Returns an error when the index does not exist or when physical
    /// metadata, entries, rows, pages, or version chains are malformed.
    pub fn select_latest_secondary_index(
        &self,
        index: ObjectId,
        index_key: &[u8],
    ) -> Result<Vec<SecondaryIndexRow>, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        self.select_secondary_index_at(&snapshot, index, index_key)
    }

    fn select_secondary_index_at(
        &self,
        snapshot: &Snapshot,
        index: ObjectId,
        index_key: &[u8],
    ) -> Result<Vec<SecondaryIndexRow>, NativeRuntimeError> {
        let mut rows = Vec::new();
        self.visit_secondary_index_at(snapshot, index, index_key, |table, primary_key, row| {
            rows.push(SecondaryIndexRow {
                table,
                primary_key: primary_key.to_vec(),
                row: row.to_vec(),
            });
            Ok(ControlFlow::Continue(()))
        })
        .map_err(|error| match error {
            RelationalVisitError::Runtime(error) | RelationalVisitError::Visitor(error) => error,
        })?;
        Ok(rows)
    }

    pub(crate) fn estimate_secondary_index_rows_at(
        &self,
        snapshot: &Snapshot,
        index: ObjectId,
        index_key: &[u8],
    ) -> Result<usize, NativeRuntimeError> {
        let root = snapshot
            .roots()
            .root(SLOT_RELATIONAL)
            .ok_or(NativeRuntimeError::UnknownSecondaryIndex { index })?;
        let tree = BTree::from_root(root);
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &relational_secondary_index_key(index),
            )?
            .ok_or(NativeRuntimeError::UnknownSecondaryIndex { index })?;
        let (_, _, _, layout) = decode_secondary_index_metadata(metadata.bytes())?;
        let prefix = relational_secondary_entry_prefix(index, layout, index_key)?;
        let upper =
            byte_prefix_successor(&prefix).ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        tree.plan_range_segments(
            &self.pages,
            Bound::Included(prefix.as_slice()),
            Bound::Excluded(upper.as_slice()),
        )?
        .into_iter()
        .try_fold(0_usize, |total, segment| {
            total
                .checked_add(segment.entry_count())
                .ok_or(NativeRuntimeError::InvalidRelationalTree)
        })
    }

    pub(crate) fn visit_secondary_index_at<E>(
        &self,
        snapshot: &Snapshot,
        index: ObjectId,
        index_key: &[u8],
        mut visitor: impl FnMut(ObjectId, &[u8], &[u8]) -> Result<ControlFlow<()>, E>,
    ) -> Result<(), RelationalVisitError<E>> {
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            return Err(RelationalVisitError::Runtime(
                NativeRuntimeError::UnknownSecondaryIndex { index },
            ));
        };
        let tree = BTree::from_root(root);
        let (table, layout) = {
            let metadata = tree
                .get_cached_pinned(
                    &self.pages,
                    &self.buffer_pool,
                    &relational_secondary_index_key(index),
                )
                .map_err(NativeRuntimeError::from)
                .map_err(RelationalVisitError::Runtime)?
                .ok_or(NativeRuntimeError::UnknownSecondaryIndex { index })
                .map_err(RelationalVisitError::Runtime)?;
            let (table, _, _, layout) = decode_secondary_index_metadata(metadata.bytes())
                .map_err(RelationalVisitError::Runtime)?;
            (table, layout)
        };
        let prefix = relational_secondary_entry_prefix(index, layout, index_key)
            .map_err(RelationalVisitError::Runtime)?;
        let context = RelationalReadContext {
            pages: &self.pages,
            pool: &self.buffer_pool,
            blobs: &self.blobs,
            format: self.relational_format,
            visible_csn: snapshot.visible_csn,
        };
        let mut failure = None;
        let _outcome = tree
            .visit_prefix_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                None,
                |physical_key, marker| {
                    let row_result = (|| {
                        let identity = physical_key
                            .get(17..)
                            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        let (stored_index_key, primary_key) =
                            decode_secondary_index_entry_identity(layout, identity)?;
                        if stored_index_key != index_key {
                            return Err(NativeRuntimeError::InvalidRelationalTree);
                        }
                        match marker {
                            [RELATIONAL_SECONDARY_ENTRY_TOMBSTONE] => {
                                return Ok(None);
                            }
                            [RELATIONAL_SECONDARY_ENTRY_LIVE] => {}
                            _ => return Err(NativeRuntimeError::InvalidRelationalTree),
                        }
                        let encoded_row = tree
                            .get_cached_pinned(
                                &self.pages,
                                &self.buffer_pool,
                                &relational_row_key(table, primary_key),
                            )?
                            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        let row = decode_relational_value_cached(
                            &context,
                            table,
                            primary_key,
                            encoded_row.bytes(),
                        )?
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        Ok(Some((primary_key, row)))
                    })();
                    match row_result {
                        Ok(None) => ControlFlow::Continue(()),
                        Ok(Some((primary_key, row))) => match visitor(table, primary_key, &row) {
                            Ok(control) => control,
                            Err(error) => {
                                failure = Some(RelationalVisitError::Visitor(error));
                                ControlFlow::Break(())
                            }
                        },
                        Err(error) => {
                            failure = Some(RelationalVisitError::Runtime(error));
                            ControlFlow::Break(())
                        }
                    }
                },
            )
            .map_err(NativeRuntimeError::from)
            .map_err(RelationalVisitError::Runtime)?;
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(())
    }

    pub(crate) fn visit_secondary_index_range_at<E>(
        &self,
        snapshot: &Snapshot,
        index: ObjectId,
        lower: Bound<&[u8]>,
        upper: Bound<&[u8]>,
        mut visitor: impl FnMut(ObjectId, &[u8], &[u8], &[u8]) -> Result<ControlFlow<()>, E>,
    ) -> Result<(), RelationalVisitError<E>> {
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            return Err(RelationalVisitError::Runtime(
                NativeRuntimeError::UnknownSecondaryIndex { index },
            ));
        };
        let tree = BTree::from_root(root);
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &relational_secondary_index_key(index),
            )
            .map_err(NativeRuntimeError::from)
            .map_err(RelationalVisitError::Runtime)?
            .ok_or(NativeRuntimeError::UnknownSecondaryIndex { index })
            .map_err(RelationalVisitError::Runtime)?;
        let (table, _, _, layout) = decode_secondary_index_metadata(metadata.bytes())
            .map_err(RelationalVisitError::Runtime)?;
        if layout != SecondaryIndexLayout::OrderedV2 {
            return Err(RelationalVisitError::Runtime(
                NativeRuntimeError::InvalidRelationalTree,
            ));
        }
        let prefix = relational_secondary_entry_namespace(index);
        let (physical_lower, physical_upper) =
            secondary_index_physical_bounds(&prefix, lower, upper)
                .map_err(RelationalVisitError::Runtime)?;
        let context = RelationalReadContext {
            pages: &self.pages,
            pool: &self.buffer_pool,
            blobs: &self.blobs,
            format: self.relational_format,
            visible_csn: snapshot.visible_csn,
        };
        let mut failure = None;
        let _outcome = tree
            .visit_prefix_range_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                bound_as_slice(&physical_lower),
                bound_as_slice(&physical_upper),
                |physical_key, marker| {
                    let row_result = (|| {
                        let identity = physical_key
                            .get(17..)
                            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        let (stored_index_key, primary_key) =
                            decode_secondary_index_entry_identity(layout, identity)?;
                        if !bytes_within_bounds(stored_index_key, &lower, &upper) {
                            return Err(NativeRuntimeError::InvalidRelationalTree);
                        }
                        match marker {
                            [RELATIONAL_SECONDARY_ENTRY_TOMBSTONE] => return Ok(None),
                            [RELATIONAL_SECONDARY_ENTRY_LIVE] => {}
                            _ => return Err(NativeRuntimeError::InvalidRelationalTree),
                        }
                        let encoded_row = tree
                            .get_cached_pinned(
                                &self.pages,
                                &self.buffer_pool,
                                &relational_row_key(table, primary_key),
                            )?
                            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        let row = decode_relational_value_cached(
                            &context,
                            table,
                            primary_key,
                            encoded_row.bytes(),
                        )?
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                        Ok(Some((stored_index_key, primary_key, row)))
                    })();
                    match row_result {
                        Ok(None) => ControlFlow::Continue(()),
                        Ok(Some((index_key, primary_key, row))) => {
                            match visitor(table, index_key, primary_key, &row) {
                                Ok(control) => control,
                                Err(error) => {
                                    failure = Some(RelationalVisitError::Visitor(error));
                                    ControlFlow::Break(())
                                }
                            }
                        }
                        Err(error) => {
                            failure = Some(RelationalVisitError::Runtime(error));
                            ControlFlow::Break(())
                        }
                    }
                },
            )
            .map_err(NativeRuntimeError::from)
            .map_err(RelationalVisitError::Runtime)?;
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(())
    }

    /// Reads one current structure value through its physical root.
    ///
    /// Expiry is evaluated against the supplied deterministic logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for page, B+tree, value-envelope, or blob corruption.
    pub fn get_latest_structure(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        Ok(self.latest_structure_entry(key)?.and_then(|entry| {
            entry
                .expires_at_micros
                .is_none_or(|expiry| expiry > logical_time_micros)
                .then_some(entry.value)
        }))
    }

    /// Returns current physical TTL state at deterministic logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for page, B+tree, value-envelope, or blob corruption.
    pub fn ttl_latest_structure(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        Ok(match self.latest_structure_entry(key)? {
            None => Ttl::Missing,
            Some(entry)
                if entry
                    .expires_at_micros
                    .is_some_and(|expiry| expiry <= logical_time_micros) =>
            {
                Ttl::Missing
            }
            Some(entry) => entry.expires_at_micros.map_or(Ttl::Persistent, |expiry| {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }),
        })
    }

    /// Tombstones at most `max_keys` due scalar values through one native
    /// transaction.
    ///
    /// The ordered durable expiry index is visited at the supplied
    /// deterministic logical time. An empty sweep writes no WAL record and
    /// advances no CSN.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::InvalidExpirySweepLimit`] outside
    /// `1..=4096`, or a storage, corruption, transaction, or durability error.
    pub fn expire_due_structures(
        &mut self,
        logical_time_micros: i64,
        max_keys: usize,
        durability: DurabilityClass,
    ) -> Result<ExpirySweepReceipt, NativeRuntimeError> {
        self.expire_due_structures_at(logical_time_micros, max_keys, durability, None)
    }

    fn expire_due_structures_at(
        &mut self,
        logical_time_micros: i64,
        max_keys: usize,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<ExpirySweepReceipt, NativeRuntimeError> {
        let _permit = self.admit_maintenance_owned()?;
        if !(1..=MAX_EXPIRY_SWEEP_KEYS).contains(&max_keys) {
            return Err(NativeRuntimeError::InvalidExpirySweepLimit {
                requested: max_keys,
            });
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let (due_keys, more_due) =
            self.due_structure_keys(&snapshot, logical_time_micros, max_keys)?;
        if due_keys.is_empty() {
            return Ok(ExpirySweepReceipt {
                expired_keys: 0,
                more_due: false,
                commit: None,
            });
        }
        let expired_keys = due_keys.len();
        let transaction = if matches!(
            self.structure_format,
            StructureFormat::BTreeV2 | StructureFormat::BTreeV3
        ) {
            let transaction_id = TransactionId::new(self.next_transaction_id)
                .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
            let root_transaction = self.coordinator.begin_write()?;
            if root_transaction.base_roots() != snapshot.roots() {
                return Err(NativeRuntimeError::InvalidPreparedMutation);
            }
            let mutations = due_keys.into_iter().map(due_structure_mutation).collect();
            let directory_identity = self.directory_identity().clone();
            NativeTransaction {
                pages: &mut self.pages,
                buffer_pool: self.buffer_pool.clone(),
                blobs: &mut self.blobs,
                wal: &mut self.wal,
                conflicts: &mut self.conflicts,
                relational_format: self.relational_format,
                structure_format: self.structure_format,
                search_format: self.search_format,
                root_transaction,
                conflict_read_csn: snapshot.visible_csn,
                transaction_id,
                next_transaction_id: &mut self.next_transaction_id,
                transaction_resolutions: &mut self.transaction_resolutions,
                transaction_receipts: &mut self.transaction_receipts,
                resolution: None,
                batch: NativeWriteBatch {
                    lineage: None,
                    directory_identity,
                    snapshot,
                    state: MaterializedState::default(),
                    mutations,
                    dirty: [false, false, true, false],
                    durability,
                    structure_format: self.structure_format,
                    search_format: self.search_format,
                    mode: NativeWriteBatchMode::PhysicalStructureExpiry,
                    delta_stage_active: false,
                    delta: None,
                    ann_consolidation: None,
                    ann_consolidation_structure: None,
                    ann_initial_bulk: None,
                    resource_permit: None,
                },
            }
        } else {
            let mut transaction = self.begin(logical_time_micros, durability)?;
            for due in due_keys {
                if due.kind != DueStructureKind::Scalar
                    || !transaction.delete_expired_structure(due.key)?
                {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
            transaction
        };
        let commit = match interruption {
            Some(boundary) => transaction.commit_with_interruption(boundary),
            None => transaction.commit(),
        }?;
        Ok(ExpirySweepReceipt {
            expired_keys,
            more_due,
            commit: Some(commit),
        })
    }

    /// Rebuilds the current `HYSTRBT2` or `HYSTRBT3` root without safe tombstones.
    ///
    /// Live physical entries are retained byte-for-byte. A root containing no
    /// tombstones is a no-op and advances neither the WAL nor the global CSN.
    /// Superseded pages remain in the append-only page file for historical
    /// roots; this operation is not physical file vacuum.
    ///
    /// # Errors
    ///
    /// V3 compaction retains and validates every active retirement record and
    /// its remaining child state. Returns
    /// [`NativeRuntimeError::StructureCompactionUnsupported`] for a legacy
    /// structure format, or a storage, corruption, synchronization,
    /// transaction, or durability error.
    pub fn compact_structure(
        &mut self,
        durability: DurabilityClass,
    ) -> Result<StructureCompactionReceipt, NativeRuntimeError> {
        self.compact_structure_at(durability, None)
    }

    fn compact_structure_at(
        &mut self,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<StructureCompactionReceipt, NativeRuntimeError> {
        let _permit = self.admit_maintenance_owned()?;
        if !matches!(
            self.structure_format,
            StructureFormat::BTreeV2 | StructureFormat::BTreeV3
        ) {
            return Err(NativeRuntimeError::StructureCompactionUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok(empty_structure_compaction_receipt());
        };
        let observation =
            observe_structure_compaction(&self.pages, &self.blobs, root, self.structure_format)?;
        let StructureCompactionObservation {
            scanned_entries,
            retained_entries,
            dropped_tombstones,
        } = observation;
        let reachable_pages_before = BTree::from_root(root).reachable_page_count(&self.pages)?;
        if dropped_tombstones == 0 {
            return Ok(StructureCompactionReceipt {
                scanned_entries,
                retained_entries,
                dropped_tombstones: 0,
                reachable_pages_before,
                reachable_pages_after: reachable_pages_before,
                pages_appended: 0,
                commit: None,
            });
        }

        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let root_transaction = self.coordinator.begin_write()?;
        if root_transaction.base_roots() != snapshot.roots() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let pages_before = self.pages.page_count();
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState::default(),
                mutations: vec![structure_compaction_mutation()],
                dirty: [false, false, true, false],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalStructureCompaction,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: None,
                resource_permit: None,
            },
        };
        let commit = commit_transaction_at(transaction, interruption)?;
        let pages_appended = self
            .pages
            .page_count()
            .checked_sub(pages_before)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let compacted_root = self
            .coordinator
            .snapshot(0)?
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let reachable_pages_after =
            BTree::from_root(compacted_root).reachable_page_count(&self.pages)?;
        Ok(StructureCompactionReceipt {
            scanned_entries,
            retained_entries,
            dropped_tombstones,
            reachable_pages_before,
            reachable_pages_after,
            pages_appended,
            commit: Some(commit),
        })
    }

    /// Atomically rewrites the current validated `HYSTRBT2` root as `HYSTRBT3`.
    ///
    /// The migration is explicit and complete-root: open never converts a
    /// directory implicitly. Logical state and existing blob references are
    /// preserved, canonical V2 tombstones are omitted, and the old immutable
    /// root remains available to retained snapshots. Structure mutations on
    /// the resulting V3 root remain disabled until the public V3 command path
    /// is activated.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::StructureV3MigrationUnsupported`] unless
    /// the current root is `HYSTRBT2`, or a validation, storage, transaction,
    /// synchronization, WAL, or durability error.
    pub fn migrate_structure_to_v3(
        &mut self,
        durability: DurabilityClass,
    ) -> Result<StructureV3MigrationReceipt, NativeRuntimeError> {
        self.migrate_structure_to_v3_at(durability, None)
    }

    fn migrate_structure_to_v3_at(
        &mut self,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<StructureV3MigrationReceipt, NativeRuntimeError> {
        let _permit = self.admit_maintenance_owned()?;
        if self.structure_format != StructureFormat::BTreeV2 {
            return Err(NativeRuntimeError::StructureV3MigrationUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let source_root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let source_tree = BTree::from_root(source_root);
        let source_entries = source_tree.scan(&self.pages)?.len();
        load_structure_state_root(&self.pages, &self.blobs, source_root)?;
        let reachable_pages_before = source_tree.reachable_page_count(&self.pages)?;

        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let root_transaction = self.coordinator.begin_write()?;
        if root_transaction.base_roots() != snapshot.roots() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let pages_before = self.pages.page_count();
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState::default(),
                mutations: vec![Mutation {
                    engine: EngineKind::Structure,
                    opcode: Opcode::MigrateStructureV3,
                    target: None,
                    key: Vec::new(),
                    value: Vec::new(),
                    expires_at_micros: None,
                }],
                dirty: [false, false, true, false],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalStructureMigrationV3,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: None,
                resource_permit: None,
            },
        };
        let commit = commit_transaction_at(transaction, interruption)?;
        self.structure_format = StructureFormat::BTreeV3;

        let pages_appended = self
            .pages
            .page_count()
            .checked_sub(pages_before)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let target_root = self
            .coordinator
            .snapshot(0)?
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let target_tree = BTree::from_root(target_root);
        let target_entries = target_tree.scan(&self.pages)?.len();
        let dropped_tombstones = source_entries
            .checked_sub(target_entries)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        structure_v3::load_structure_state_v3(&self.pages, &self.blobs, target_tree)?;
        let reachable_pages_after = target_tree.reachable_page_count(&self.pages)?;
        Ok(StructureV3MigrationReceipt {
            source_entries,
            target_entries,
            dropped_tombstones,
            reachable_pages_before,
            reachable_pages_after,
            pages_appended,
            commit,
        })
    }

    /// Reclaims one bounded step from the first active `HYSTRBT3` retirement.
    ///
    /// Retirement records are selected in canonical physical-key order. The
    /// shared maintenance governor is held across selection, page mutation,
    /// WAL durability, and publication. A request with no active retirement
    /// writes nothing and advances no CSN.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::StructureV3RetirementUnsupported`] unless
    /// the current root is `HYSTRBT3`,
    /// [`NativeRuntimeError::InvalidStructureRetirementLimit`] outside
    /// `2..=1024`, or a validation, storage, transaction, synchronization,
    /// WAL, or durability error.
    pub fn cleanup_structure_retirements(
        &mut self,
        entry_budget: usize,
        durability: DurabilityClass,
    ) -> Result<StructureRetirementCleanupReceipt, NativeRuntimeError> {
        self.cleanup_structure_retirements_at(entry_budget, durability, None)
    }

    #[allow(clippy::too_many_lines)]
    fn cleanup_structure_retirements_at(
        &mut self,
        entry_budget: usize,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<StructureRetirementCleanupReceipt, NativeRuntimeError> {
        let _permit = self.admit_maintenance_owned()?;
        if self.structure_format != StructureFormat::BTreeV3 {
            return Err(NativeRuntimeError::StructureV3RetirementUnsupported);
        }
        if !(2..=structure_v3::MAX_STRUCTURE_RETIREMENT_STEP_ENTRIES).contains(&entry_budget) {
            return Err(NativeRuntimeError::InvalidStructureRetirementLimit {
                requested: entry_budget,
            });
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(retirement_key) =
            structure_v3::next_active_retirement_key_v3(&self.pages, &self.buffer_pool, tree)?
        else {
            return Ok(StructureRetirementCleanupReceipt {
                retirement: None,
                entry_budget,
                processed_primary_entries: 0,
                physical_mutations: 0,
                more_remaining: false,
                more_retirements: false,
                pages_appended: 0,
                commit: None,
            });
        };
        let encoded_before = tree
            .get(&self.pages, &retirement_key)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let before = structure_v3::decode_retirement_record(&encoded_before)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let (collection_key, incarnation) = structure_v3::decode_retirement_key(&retirement_key)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let retirement = StructureRetirementIdentity {
            collection_key: collection_key.to_vec(),
            transaction_id: incarnation.transaction_id(),
            mutation_ordinal: incarnation.mutation_ordinal(),
        };

        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let root_transaction = self.coordinator.begin_write()?;
        if root_transaction.base_roots() != snapshot.roots() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let pages_before = self.pages.page_count();
        let encoded_budget = u32::try_from(entry_budget)
            .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?
            .to_le_bytes()
            .to_vec();
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState::default(),
                mutations: vec![Mutation {
                    engine: EngineKind::Structure,
                    opcode: Opcode::CleanupStructureRetirementV3,
                    target: None,
                    key: retirement_key.clone(),
                    value: encoded_budget,
                    expires_at_micros: None,
                }],
                dirty: [false, false, true, false],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalStructureRetirementV3,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: None,
                resource_permit: None,
            },
        };
        let commit = commit_transaction_at(transaction, interruption)?;

        let current_root = self
            .coordinator
            .snapshot(0)?
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let current_tree = BTree::from_root(current_root);
        let encoded_after = current_tree
            .get(&self.pages, &retirement_key)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let after = if is_structure_tombstone(&encoded_after) {
            None
        } else {
            Some(
                structure_v3::decode_retirement_record(&encoded_after)
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            )
        };
        let remaining_primary_entries = after
            .as_ref()
            .map_or(0, |record| record.remaining_primary_entries);
        let remaining_secondary_entries = after
            .as_ref()
            .map_or(0, |record| record.remaining_secondary_entries);
        let remaining_expiry_entries = after
            .as_ref()
            .map_or(0, |record| record.remaining_expiry_entries);
        let processed_primary = before
            .remaining_primary_entries
            .checked_sub(remaining_primary_entries)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let processed_secondary = before
            .remaining_secondary_entries
            .checked_sub(remaining_secondary_entries)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let processed_expiry = before
            .remaining_expiry_entries
            .checked_sub(remaining_expiry_entries)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let physical_mutations = processed_primary
            .checked_add(processed_secondary)
            .and_then(|count| count.checked_add(processed_expiry))
            .and_then(|count| count.checked_add(1))
            .and_then(|count| usize::try_from(count).ok())
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let processed_primary_entries = usize::try_from(processed_primary)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let more_remaining = after.is_some();
        let more_retirements = more_remaining
            || structure_v3::next_active_retirement_key_v3(
                &self.pages,
                &self.buffer_pool,
                current_tree,
            )?
            .is_some();
        let pages_appended = self
            .pages
            .page_count()
            .checked_sub(pages_before)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        Ok(StructureRetirementCleanupReceipt {
            retirement: Some(retirement),
            entry_budget,
            processed_primary_entries,
            physical_mutations,
            more_remaining,
            more_retirements,
            pages_appended,
            commit: Some(commit),
        })
    }

    /// Rebuilds the current native search root without reachable lexical tombstones.
    ///
    /// Live lexical, metadata, and ANN entries are retained byte-for-byte. A
    /// root containing no tombstones is a no-op and advances neither the WAL
    /// nor the global CSN. Superseded pages and source blobs remain subject to
    /// their separate retention and collection protocols.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::SearchCompactionUnsupported`] for a
    /// legacy inline search root, or a storage, corruption, synchronization,
    /// transaction, or durability error.
    pub fn compact_search(
        &mut self,
        durability: DurabilityClass,
    ) -> Result<SearchCompactionReceipt, NativeRuntimeError> {
        self.compact_search_at(durability, None)
    }

    #[allow(clippy::too_many_lines)]
    fn compact_search_at(
        &mut self,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<SearchCompactionReceipt, NativeRuntimeError> {
        let _permit = self.admit_maintenance_owned()?;
        if self.search_format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::SearchCompactionUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_SEARCH) else {
            return Ok(SearchCompactionReceipt {
                scanned_entries: 0,
                retained_entries: 0,
                dropped_tombstones: 0,
                reachable_pages_before: 0,
                reachable_pages_after: 0,
                pages_appended: 0,
                commit: None,
            });
        };
        let plan = plan_search_compaction(&self.pages, &self.blobs, root)?;
        let catalog = load_catalog_state(&self.pages, &self.blobs, snapshot.roots())?;
        ann_store::load(&self.pages, Some(root), &catalog)?;
        let reachable_pages_before = BTree::from_root(root).reachable_page_count(&self.pages)?;
        if plan.dropped_tombstones == 0 {
            return Ok(SearchCompactionReceipt {
                scanned_entries: plan.scanned_entries,
                retained_entries: plan.retained_entries.len(),
                dropped_tombstones: 0,
                reachable_pages_before,
                reachable_pages_after: reachable_pages_before,
                pages_appended: 0,
                commit: None,
            });
        }

        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let root_transaction = self.coordinator.begin_write()?;
        if root_transaction.base_roots() != snapshot.roots() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let pages_before = self.pages.page_count();
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState::default(),
                mutations: vec![Mutation {
                    engine: EngineKind::Search,
                    opcode: Opcode::CompactSearch,
                    target: None,
                    key: Vec::new(),
                    value: Vec::new(),
                    expires_at_micros: None,
                }],
                dirty: [false, false, false, true],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalSearchCompaction,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: None,
                resource_permit: None,
            },
        };
        let commit = match interruption {
            Some(boundary) => transaction.commit_with_interruption(boundary)?,
            None => transaction.commit()?,
        };
        let pages_appended = self
            .pages
            .page_count()
            .checked_sub(pages_before)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let compacted_root = self
            .coordinator
            .snapshot(0)?
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let reachable_pages_after =
            BTree::from_root(compacted_root).reachable_page_count(&self.pages)?;
        Ok(SearchCompactionReceipt {
            scanned_entries: plan.scanned_entries,
            retained_entries: plan.retained_entries.len(),
            dropped_tombstones: plan.dropped_tombstones,
            reachable_pages_before,
            reachable_pages_after,
            pages_appended,
            commit: Some(commit),
        })
    }

    /// Captures and builds one bounded replacement ANN base without holding
    /// writer admission or changing the current root.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown index, malformed root, invalid bounds,
    /// or a capture larger than either caller-supplied bound.
    pub fn plan_ann_consolidation(
        &self,
        index: ObjectId,
        max_vectors: usize,
        max_delta_records: usize,
    ) -> Result<AnnConsolidationPlan, NativeRuntimeError> {
        self.plan_ann_consolidation_with_control(index, max_vectors, max_delta_records, None)
    }

    /// Captures and builds one bounded replacement ANN base with cooperative
    /// cancellation across partition planning, child construction, and final
    /// candidate assembly.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::plan_ann_consolidation`], plus
    /// [`hyphae_native_ann::AnnError::BuildCancelled`] when cancellation is
    /// observed before a complete candidate is retained.
    pub fn plan_ann_consolidation_with_cancellation(
        &self,
        index: ObjectId,
        max_vectors: usize,
        max_delta_records: usize,
        cancellation: &GovernorCancellation,
    ) -> Result<AnnConsolidationPlan, NativeRuntimeError> {
        self.plan_ann_consolidation_with_control(
            index,
            max_vectors,
            max_delta_records,
            Some(cancellation),
        )
    }

    fn plan_ann_consolidation_with_control(
        &self,
        index: ObjectId,
        max_vectors: usize,
        max_delta_records: usize,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<AnnConsolidationPlan, NativeRuntimeError> {
        if max_vectors == 0
            || max_vectors > ann_store::MAX_ANN_CONSOLIDATION_VECTORS
            || max_delta_records == 0
            || max_delta_records > ann_store::MAX_ANN_DELTA_RECORDS
        {
            return Err(NativeRuntimeError::InvalidAnnConsolidationLimit);
        }
        if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
            return Err(hyphae_native_ann::AnnError::BuildCancelled.into());
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let roots = snapshot.roots();
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::UnknownVectorIndex { index })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, index)?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex { index });
        };
        let definition = ann_store::definition_from_search(&search_definition)?;
        let root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let load_plan = ann_store::plan_index_load_with_cancellation(
            &self.pages,
            &self.buffer_pool,
            root,
            index,
            definition,
            cancellation,
        )?;
        let retained_memory_bytes = partitioned_hnsw_build_memory_bytes(max_vectors, definition);
        let peak_memory_bytes = load_plan
            .hydration_memory_bytes()
            .saturating_add(retained_memory_bytes);
        let permit = self.admit_parallel_maintenance(
            peak_memory_bytes,
            max_vectors.min(MAX_INITIAL_ANN_BULK_PARTITIONS),
            cancellation,
        )?;
        let inner = ann_store::plan_consolidation(
            &self.pages,
            &self.buffer_pool,
            &load_plan,
            max_vectors,
            max_delta_records,
            ann_store::ConsolidationBuildExecution {
                pool: self.execution_pool.as_deref(),
                permit: permit.as_ref().map(DatabaseGovernorPermit::permit),
                cancellation,
            },
        )
        .map_err(|error| {
            if cancellation.is_some_and(GovernorCancellation::is_cancelled)
                && matches!(
                    &error,
                    NativeRuntimeError::ResourceQueue(GovernorQueueError::Cancelled)
                )
            {
                hyphae_native_ann::AnnError::BuildCancelled.into()
            } else {
                error
            }
        })?;
        let retained_memory_bytes =
            partitioned_hnsw_build_memory_bytes(inner.effective_vector_count(), definition);
        let resource_permit = permit
            .map(|permit| {
                permit
                    .retain_memory(retained_memory_bytes)
                    .map(DatabaseGovernorPermit::into_owned)
            })
            .transpose()?;
        Ok(AnnConsolidationPlan {
            inner,
            resource_permit,
        })
    }

    /// Returns a scheduler-compatible due signal from durable index metadata.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown index or malformed current root.
    pub fn ann_maintenance_status(
        &self,
        index: ObjectId,
    ) -> Result<AnnMaintenanceStatus, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        let roots = snapshot.roots();
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::UnknownVectorIndex { index })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, index)?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex { index });
        };
        let definition = ann_store::definition_from_search(&search_definition)?;
        let search_root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let plan = ann_store::plan_index_load(
            &self.pages,
            &self.buffer_pool,
            search_root,
            index,
            definition,
        )?;
        let status = ann_store::maintenance_status(&self.pages, &self.buffer_pool, &plan)?;
        Ok(AnnMaintenanceStatus {
            index_id: index,
            lifecycle: status.lifecycle,
            delta_records: status.delta_records,
            delta_bytes: status.delta_bytes,
            due: status.due,
        })
    }

    /// Builds a bounded consolidation plan only when policy marks it due.
    ///
    /// `None` is a scheduler no-op, not an error.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown or malformed ANN index, invalid bounds,
    /// or failure to read the current catalog, page, or ANN state.
    pub fn plan_due_ann_consolidation(
        &self,
        index: ObjectId,
        max_vectors: usize,
    ) -> Result<Option<AnnConsolidationPlan>, NativeRuntimeError> {
        let status = self.ann_maintenance_status(index)?;
        if !status.due {
            return Ok(None);
        }
        self.plan_ann_consolidation(
            index,
            max_vectors,
            usize::try_from(status.lifecycle.delta_max_entries)
                .map_err(|_| NativeRuntimeError::InvalidAnnConsolidationLimit)?,
        )
        .map(Some)
    }

    /// Atomically selects a captured ANN replacement through the ordinary root
    /// commit protocol.
    ///
    /// Unchanged captured object deltas are consumed. Object deltas written
    /// after capture remain above the replacement base. Publication rejects a
    /// plan whose selected base generation has changed.
    ///
    /// # Errors
    ///
    /// Returns an error for a stale plan, malformed root, persistence,
    /// synchronization, WAL, or MVCC publication failure.
    pub fn consolidate_ann(
        &mut self,
        plan: AnnConsolidationPlan,
        durability: DurabilityClass,
    ) -> Result<AnnConsolidationReceipt, NativeRuntimeError> {
        self.consolidate_ann_at(plan, durability, None)
    }

    /// Publishes ANN consolidation with one deterministic ordinary-commit
    /// interruption.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::InjectedCrash`] at the selected boundary,
    /// or the same failures as [`Self::consolidate_ann`].
    pub fn consolidate_ann_with_interruption(
        &mut self,
        plan: AnnConsolidationPlan,
        durability: DurabilityClass,
        boundary: CommitBoundary,
    ) -> Result<AnnConsolidationReceipt, NativeRuntimeError> {
        self.consolidate_ann_at(plan, durability, Some(boundary))
    }

    fn consolidate_ann_at(
        &mut self,
        plan: AnnConsolidationPlan,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<AnnConsolidationReceipt, NativeRuntimeError> {
        let retained_resource_permit = plan.resource_permit.clone();
        if self.search_format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::InvalidAnnTree);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let roots = snapshot.roots();
        let catalog_root =
            roots
                .root(SLOT_CATALOG)
                .ok_or(NativeRuntimeError::UnknownVectorIndex {
                    index: plan.inner.index(),
                })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, plan.inner.index())?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex {
                index: plan.inner.index(),
            });
        };
        if ann_store::definition_from_search(&search_definition)? != plan.inner.definition() {
            return Err(NativeRuntimeError::AnnConsolidationStale);
        }
        let root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let candidate_memory_is_accounted =
            self.ann_consolidation_candidate_memory_is_accounted(retained_resource_permit.as_ref());
        let (_publication_permit, consumed_delta_records, structural_plan) = self
            .admit_ann_consolidation_publication(
                root,
                &plan.inner,
                candidate_memory_is_accounted,
            )?;
        let previous_base_identity = plan.inner.base_identity();
        let index_id = plan.inner.index();
        let replacement_base_identity = plan.inner.replacement_identity();
        let effective_vector_count = plan.inner.effective_vector_count();
        let mutation_value = ann_store::encode_consolidation_mutation(&plan.inner);
        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let root_transaction = self.coordinator.begin_write()?;
        if root_transaction.base_roots() != snapshot.roots() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState::default(),
                mutations: vec![Mutation {
                    engine: EngineKind::Search,
                    opcode: Opcode::ConsolidateAnn,
                    target: Some(plan.inner.index()),
                    key: Vec::new(),
                    value: mutation_value,
                    expires_at_micros: None,
                }],
                dirty: [false, false, false, true],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalAnnConsolidation,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: Some(plan.inner),
                ann_consolidation_structure: Some(structural_plan),
                ann_initial_bulk: None,
                resource_permit: None,
            },
        };
        let commit = match interruption {
            Some(boundary) => transaction.commit_with_interruption(boundary)?,
            None => transaction.commit()?,
        };
        let after = self.observe_target_ann_index_unadmitted(index_id)?;
        Ok(AnnConsolidationReceipt {
            previous_base_identity,
            replacement_base_identity,
            consumed_delta_records,
            effective_vector_count,
            preserved_later_delta_records: after.delta_records,
            commit,
        })
    }

    fn observe_target_ann_index_unadmitted(
        &self,
        index: ObjectId,
    ) -> Result<ann_store::IndexObservation, NativeRuntimeError> {
        let current = self.coordinator.snapshot(0)?;
        let roots = current.roots();
        let search_root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::UnknownVectorIndex { index })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, index)?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex { index });
        };
        let definition = ann_store::definition_from_search(&search_definition)?;
        let plan = ann_store::plan_index_load(
            &self.pages,
            &self.buffer_pool,
            search_root,
            index,
            definition,
        )?;
        ann_store::observe_planned_index(&self.pages, &self.buffer_pool, &plan)
    }

    /// Returns the selected ANN generation and base-plus-delta physical counts.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown index or malformed current root.
    pub fn observe_ann_index(
        &self,
        index: ObjectId,
    ) -> Result<AnnIndexObservation, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        self.observe_ann_index_unadmitted(index)
    }

    fn observe_ann_index_unadmitted(
        &self,
        index: ObjectId,
    ) -> Result<AnnIndexObservation, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let catalog = load_catalog_state(&self.pages, &self.blobs, snapshot.roots())?;
        let observed = ann_store::observe(&self.pages, root, &catalog, index)?;
        Ok(AnnIndexObservation {
            base_identity: observed.base_identity,
            view_identity: observed.view_identity,
            base_vector_count: observed.base_vector_count,
            effective_vector_count: observed.effective_vector_count,
            delta_records: observed.delta_records,
            delta_bytes: observed.delta_bytes,
            generation_records: observed.generation_records,
            selected_generation_records: observed.selected_generation_records,
            lifecycle: observed.lifecycle,
            maintenance_due: observed.maintenance_due,
        })
    }

    fn due_structure_keys(
        &self,
        snapshot: &Snapshot,
        logical_time_micros: i64,
        max_keys: usize,
    ) -> Result<(Vec<DueStructureKey>, bool), NativeRuntimeError> {
        if !self.structure_format.uses_ordered_expiry_index() {
            let state = load_structure_state(&self.pages, &self.blobs, snapshot.roots())?;
            let mut due = state
                .entries
                .iter()
                .filter_map(|(key, entry)| {
                    entry
                        .expires_at_micros
                        .filter(|expiry| *expiry <= logical_time_micros)
                        .map(|expiry| (expiry, key.clone()))
                })
                .collect::<Vec<_>>();
            due.sort_unstable();
            let more_due = due.len() > max_keys;
            due.truncate(max_keys);
            return Ok((
                due.into_iter()
                    .map(|(_, key)| DueStructureKey {
                        kind: DueStructureKind::Scalar,
                        key,
                    })
                    .collect(),
                more_due,
            ));
        }
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok((Vec::new(), false));
        };
        let tree = BTree::from_root(root);
        let mut due = self.due_top_level_structure_keys(tree, logical_time_micros, max_keys)?;
        due.extend(self.due_hash_field_keys(tree, logical_time_micros, max_keys)?);
        due.sort_unstable_by(|left, right| {
            (&left.expiry, &left.namespace_order, &left.identity).cmp(&(
                &right.expiry,
                &right.namespace_order,
                &right.identity,
            ))
        });
        let more_due = due.len() > max_keys;
        due.truncate(max_keys);
        Ok((
            due.into_iter().map(|ordered| ordered.due).collect(),
            more_due,
        ))
    }

    fn due_top_level_structure_keys(
        &self,
        tree: BTree,
        logical_time_micros: i64,
        max_keys: usize,
    ) -> Result<Vec<OrderedDueStructure>, NativeRuntimeError> {
        let mut due = Vec::with_capacity(max_keys.saturating_add(1));
        let mut failure = None;
        let _outcome = tree.visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &[STRUCTURE_EXPIRY_PREFIX],
            None,
            |physical_key, marker| {
                let result = (|| {
                    let (expiry, key) = decode_structure_expiry_identity(
                        physical_key
                            .get(1..)
                            .ok_or(NativeRuntimeError::InvalidStructureTree)?,
                    )?;
                    if expiry > logical_time_micros {
                        return Ok(ControlFlow::Break(()));
                    }
                    let due_key = if self.structure_format == StructureFormat::BTreeV3
                        && !matches!(marker, [STRUCTURE_EXPIRY_TOMBSTONE | STRUCTURE_EXPIRY_LIVE])
                    {
                        let (validated_expiry, key, family) =
                            structure_v3::validate_due_collection_expiry_v3(
                                &self.pages,
                                &self.buffer_pool,
                                tree,
                                physical_key,
                                marker,
                            )?;
                        if validated_expiry != expiry {
                            return Err(NativeRuntimeError::InvalidStructureTree);
                        }
                        Some(DueStructureKey {
                            kind: match family {
                                structure_v3::StructureCollectionFamily::Hash => {
                                    DueStructureKind::Hash
                                }
                                structure_v3::StructureCollectionFamily::Set => {
                                    DueStructureKind::Set
                                }
                                structure_v3::StructureCollectionFamily::List => {
                                    DueStructureKind::List
                                }
                                structure_v3::StructureCollectionFamily::Stream => {
                                    DueStructureKind::Stream
                                }
                                structure_v3::StructureCollectionFamily::SortedSet => {
                                    DueStructureKind::SortedSet
                                }
                            },
                            key,
                        })
                    } else {
                        self.validate_due_structure_key(tree, expiry, key, marker)?
                    };
                    if let Some(due_key) = due_key {
                        due.push(OrderedDueStructure {
                            expiry,
                            namespace_order: 0,
                            identity: due_key.key.clone(),
                            due: due_key,
                        });
                    }
                    Ok(if due.len() > max_keys {
                        ControlFlow::Break(())
                    } else {
                        ControlFlow::Continue(())
                    })
                })();
                match result {
                    Ok(control) => control,
                    Err(error) => {
                        failure = Some(error);
                        ControlFlow::Break(())
                    }
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(due)
    }

    fn due_hash_field_keys(
        &self,
        tree: BTree,
        logical_time_micros: i64,
        max_keys: usize,
    ) -> Result<Vec<OrderedDueStructure>, NativeRuntimeError> {
        let mut due = Vec::with_capacity(max_keys.saturating_add(1));
        let mut failure = None;
        let _field_outcome = tree.visit_prefix_cached(
            &self.pages,
            &self.buffer_pool,
            &[STRUCTURE_HASH_FIELD_EXPIRY_PREFIX],
            None,
            |physical_key, marker| {
                let result = (|| {
                    let (expiry, key, field) = decode_structure_hash_field_expiry_identity(
                        physical_key
                            .get(1..)
                            .ok_or(NativeRuntimeError::InvalidStructureTree)?,
                    )?;
                    if expiry > logical_time_micros {
                        return Ok(ControlFlow::Break(()));
                    }
                    let due_key = if self.structure_format == StructureFormat::BTreeV3 {
                        if marker == [STRUCTURE_EXPIRY_TOMBSTONE] {
                            None
                        } else {
                            structure_v3::validate_due_hash_field_expiry_v3(
                                &self.pages,
                                &self.buffer_pool,
                                tree,
                                physical_key,
                                marker,
                                logical_time_micros,
                            )?
                            .map(|(validated_expiry, identity)| {
                                (
                                    validated_expiry,
                                    DueStructureKey {
                                        kind: DueStructureKind::HashField,
                                        key: identity,
                                    },
                                )
                            })
                            .map(|(validated_expiry, due)| {
                                if validated_expiry == expiry {
                                    Ok(due)
                                } else {
                                    Err(NativeRuntimeError::InvalidStructureTree)
                                }
                            })
                            .transpose()?
                        }
                    } else {
                        self.validate_due_hash_field(
                            tree,
                            expiry,
                            key,
                            field,
                            marker,
                            logical_time_micros,
                        )?
                    };
                    if let Some(due_key) = due_key {
                        due.push(OrderedDueStructure {
                            expiry,
                            namespace_order: 1,
                            identity: due_key.key.clone(),
                            due: due_key,
                        });
                    }
                    Ok(if due.len() > max_keys {
                        ControlFlow::Break(())
                    } else {
                        ControlFlow::Continue(())
                    })
                })();
                match result {
                    Ok(control) => control,
                    Err(error) => {
                        failure = Some(error);
                        ControlFlow::Break(())
                    }
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(due)
    }

    fn validate_due_structure_key(
        &self,
        tree: BTree,
        expiry: i64,
        key: &[u8],
        marker: &[u8],
    ) -> Result<Option<DueStructureKey>, NativeRuntimeError> {
        let (kind, actual_expiry) = match marker {
            [STRUCTURE_EXPIRY_TOMBSTONE] => return Ok(None),
            [STRUCTURE_EXPIRY_LIVE] => {
                let scalar = tree
                    .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                (
                    DueStructureKind::Scalar,
                    structure_value_expiry(scalar.bytes())?,
                )
            }
            [STRUCTURE_HASH_EXPIRY_LIVE] => {
                let metadata = tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_hash_meta_key(key),
                    )?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                (
                    DueStructureKind::Hash,
                    decode_live_hash_metadata(metadata.bytes())?
                        .ok_or(NativeRuntimeError::InvalidStructureTree)?
                        .expires_at_micros,
                )
            }
            [STRUCTURE_SET_EXPIRY_LIVE] => {
                let metadata = tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_set_meta_key(key),
                    )?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                (
                    DueStructureKind::Set,
                    decode_live_set_metadata(metadata.bytes())?
                        .ok_or(NativeRuntimeError::InvalidStructureTree)?
                        .expires_at_micros,
                )
            }
            [STRUCTURE_LIST_EXPIRY_LIVE] => {
                let metadata = tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_list_meta_key(key)?,
                    )?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                (
                    DueStructureKind::List,
                    decode_live_list_metadata(metadata.bytes())?
                        .ok_or(NativeRuntimeError::InvalidStructureTree)?
                        .expires_at_micros,
                )
            }
            [STRUCTURE_STREAM_EXPIRY_LIVE] => {
                let metadata = tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_stream_meta_key(key)?,
                    )?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                let expiry = match metadata.bytes() {
                    bytes if bytes.len() == 16 => Some(i64::from_be_bytes(
                        bytes[8..16]
                            .try_into()
                            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                    )),
                    _ => return Err(NativeRuntimeError::InvalidStructureTree),
                };
                (DueStructureKind::Stream, expiry)
            }
            [STRUCTURE_SORTED_SET_EXPIRY_LIVE] => {
                let metadata = tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_sorted_set_meta_key(key)?,
                    )?
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                (
                    DueStructureKind::SortedSet,
                    decode_sorted_set_metadata_state(metadata.bytes())?.1,
                )
            }
            _ => return Err(NativeRuntimeError::InvalidStructureTree),
        };
        if actual_expiry != Some(expiry) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(Some(DueStructureKey {
            kind,
            key: key.to_vec(),
        }))
    }

    fn validate_due_hash_field(
        &self,
        tree: BTree,
        expiry: i64,
        key: &[u8],
        field: &[u8],
        marker: &[u8],
        logical_time_micros: i64,
    ) -> Result<Option<DueStructureKey>, NativeRuntimeError> {
        match marker {
            [STRUCTURE_EXPIRY_TOMBSTONE] => return Ok(None),
            [STRUCTURE_HASH_FIELD_EXPIRY_LIVE] => {}
            _ => return Err(NativeRuntimeError::InvalidStructureTree),
        }
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_hash_meta_key(key),
            )?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let metadata = decode_live_hash_metadata(metadata.bytes())?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if metadata
            .expires_at_micros
            .is_some_and(|hash_expiry| hash_expiry <= logical_time_micros)
        {
            return Ok(None);
        }
        let field_value = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_hash_field_key(key, field)?,
            )?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if structure_value_expiry(field_value.bytes())? != Some(expiry) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(Some(DueStructureKey {
            kind: DueStructureKind::HashField,
            key: hash_field_identity(key, field)?,
        }))
    }

    fn latest_structure_entry(
        &self,
        key: &[u8],
    ) -> Result<Option<StructureEntry>, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok(None);
        };
        match self.structure_format {
            StructureFormat::InlineStateV1 => {
                let state = load_structure_state(&self.pages, &self.blobs, snapshot.roots())?;
                Ok(state.entries.get(key).cloned())
            }
            StructureFormat::BTreeV1 | StructureFormat::BTreeV2 | StructureFormat::BTreeV3 => {
                BTree::from_root(root)
                    .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
                    .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
                    .transpose()
                    .map(Option::flatten)
            }
        }
    }

    /// Reads one field directly through the current physical hash namespace.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, a scalar key, a missing hash, or
    /// any malformed B+tree, metadata, field envelope, or blob.
    pub fn hget_latest_hash(
        &self,
        key: &[u8],
        field: &[u8],
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        self.hget_latest_hash_at(key, field, i64::MIN)
    }

    /// Reads one current physical hash field at an explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another structure kind, a missing
    /// or expired hash, or malformed physical state.
    pub fn hget_latest_hash_at(
        &self,
        key: &[u8],
        field: &[u8],
        logical_time_micros: i64,
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::hash_get_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                field,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            if tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
                .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
                .transpose()?
                .flatten()
                .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_set_meta_key(key),
                    )?
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_list_meta_key(key)?,
                    )?
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_sorted_set_meta_key(key)?,
                    )?
                    .is_some()
            {
                return Err(NativeRuntimeError::StructureKindMismatch);
            }
            return Err(NativeRuntimeError::UnknownStructureHash);
        };
        let Some(metadata) = decode_live_hash_metadata(metadata.bytes())? else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        if !metadata.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureHash);
        }
        tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_field_key(key, field)?,
        )?
        .map(|encoded| {
            decode_hash_field_value_at(encoded.bytes(), &self.blobs, logical_time_micros)
        })
        .transpose()
        .map(Option::flatten)
    }

    /// Reads bounded fields directly through the current physical hash root.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an oversized batch, invalid
    /// identity, another structure kind, a missing hash, or malformed reached
    /// physical state.
    pub fn hget_many_latest_hash(
        &self,
        key: &[u8],
        fields: &[Vec<u8>],
    ) -> Result<Vec<Option<Vec<u8>>>, NativeRuntimeError> {
        self.hget_many_latest_hash_at(key, fields, i64::MIN)
    }

    /// Reads bounded current-root hash fields at explicit logical time.
    ///
    /// Duplicate fields preserve duplicate output positions. Every lookup
    /// uses the same captured structure root.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an oversized batch, invalid
    /// identity, another structure kind, a missing or expired hash, or
    /// malformed reached physical state.
    pub fn hget_many_latest_hash_at(
        &self,
        key: &[u8],
        fields: &[Vec<u8>],
        logical_time_micros: i64,
    ) -> Result<Vec<Option<Vec<u8>>>, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            validate_hash_field_positions(key, fields)?;
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::hash_get_many_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                fields,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        self.hash_get_many_in_tree_at(BTree::from_root(root), key, fields, logical_time_micros)
    }

    fn hash_get_many_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        fields: &[Vec<u8>],
        logical_time_micros: i64,
    ) -> Result<Vec<Option<Vec<u8>>>, NativeRuntimeError> {
        validate_hash_field_positions(key, fields)?;
        self.visible_hash_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let mut values = Vec::with_capacity(fields.len());
        for field in fields {
            let value = tree
                .get_cached_pinned(
                    &self.pages,
                    &self.buffer_pool,
                    &structure_hash_field_key(key, field)?,
                )?
                .map(|encoded| {
                    decode_hash_field_value_at(encoded.bytes(), &self.blobs, logical_time_micros)
                })
                .transpose()?
                .flatten();
            values.push(value);
        }
        Ok(values)
    }

    /// Reads one hash cardinality directly from its physical metadata.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, a scalar key, a missing hash, or
    /// malformed B+tree metadata.
    pub fn hlen_latest_hash(&self, key: &[u8]) -> Result<usize, NativeRuntimeError> {
        self.hlen_latest_hash_at(key, i64::MIN)
    }

    /// Reads one current physical hash cardinality at an explicit logical
    /// time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another structure kind, a missing
    /// or expired hash, or malformed physical state.
    pub fn hlen_latest_hash_at(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            return self.hlen_latest_hash_at_v3(key, logical_time_micros);
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            if tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
                .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
                .transpose()?
                .flatten()
                .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_set_meta_key(key),
                    )?
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_list_meta_key(key)?,
                    )?
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_sorted_set_meta_key(key)?,
                    )?
                    .is_some()
            {
                return Err(NativeRuntimeError::StructureKindMismatch);
            }
            return Err(NativeRuntimeError::UnknownStructureHash);
        };
        let Some(count) = decode_live_hash_metadata(metadata.bytes())? else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        if !count.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureHash);
        }
        let declared_count = usize::try_from(count.field_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let prefix = structure_hash_field_key(key, &[])?;
        let mut physical_count = 0_usize;
        let mut visible_count = 0_usize;
        let mut failure = None;
        let _ = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            Bound::Unbounded,
            Bound::Unbounded,
            |_physical_key, encoded| {
                match decode_hash_field_entry(encoded, &self.blobs) {
                    Ok(Some(entry)) => {
                        physical_count += 1;
                        if entry
                            .expires_at_micros
                            .is_none_or(|expiry| expiry > logical_time_micros)
                        {
                            visible_count += 1;
                        }
                    }
                    Ok(None) => {}
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                }
                ControlFlow::Continue(())
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if physical_count != declared_count {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(visible_count)
    }

    fn hlen_latest_hash_at_v3(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        structure_v3::hash_len_latest_at_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            BTree::from_root(root),
            key,
            logical_time_micros,
        )
    }

    /// Returns one current physical hash family's TTL at explicit logical
    /// time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage or malformed physical state.
    pub fn ttl_latest_hash(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::collection_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::Hash,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(encoded) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            return Ok(Ttl::Missing);
        };
        let Some(metadata) = decode_live_hash_metadata(encoded.bytes())? else {
            return Ok(Ttl::Missing);
        };
        Ok(match metadata.expires_at_micros {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    /// Returns one current physical hash field's TTL at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an invalid identity, or malformed
    /// physical state.
    pub fn ttl_latest_hash_field(
        &self,
        key: &[u8],
        field: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            validate_hash_field_identity(key, field)?;
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::hash_field_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                field,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        validate_hash_field_identity(key, field)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(encoded_metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            return Ok(Ttl::Missing);
        };
        let Some(metadata) = decode_live_hash_metadata(encoded_metadata.bytes())? else {
            return Ok(Ttl::Missing);
        };
        if metadata
            .expires_at_micros
            .is_some_and(|expiry| expiry <= logical_time_micros)
        {
            return Ok(Ttl::Missing);
        }
        let Some(encoded) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_field_key(key, field)?,
        )?
        else {
            return Ok(Ttl::Missing);
        };
        let Some(entry) = decode_hash_field_entry(encoded.bytes(), &self.blobs)? else {
            return Ok(Ttl::Missing);
        };
        Ok(match entry.expires_at_micros {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    /// Scans one bounded current hash-field range without materializing the
    /// complete hash.
    ///
    /// `start_after` is an exclusive exact-field cursor. A zero `limit`
    /// validates the hash and returns no entries.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, another structure
    /// kind, a missing hash, or malformed reached metadata, identity, value,
    /// page, or blob.
    pub fn hscan_latest_hash(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        self.hscan_latest_hash_at(key, start_after, limit, i64::MIN)
    }

    /// Scans one current physical hash-field range at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, another structure
    /// kind, a missing or expired hash, or malformed reached physical state.
    pub fn hscan_latest_hash_at(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        Ok(self
            .hscan_latest_hash_at_profiled(key, start_after, limit, logical_time_micros)?
            .entries)
    }

    /// Scans one current hash-field range and reports the direct or immutable
    /// segment physical execution path.
    ///
    /// # Errors
    ///
    /// Returns the same validation errors as [`Self::hscan_latest_hash_at`]
    /// plus resource admission or persistent execution failures.
    pub fn hscan_latest_hash_at_profiled(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<NativeHashScanExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let request = structure_v3::CollectionScanRequestV3::new(
                key,
                start_after,
                limit,
                logical_time_micros,
            );
            return self.hscan_latest_hash_at_v3(request, planning_permit);
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let metadata = self.visible_hash_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let declared_field_count = usize::try_from(metadata.field_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if limit <= STRUCTURE_SEGMENT_SCAN_THRESHOLD {
            let entries =
                self.hash_scan_in_tree_at(tree, key, start_after, limit, logical_time_micros)?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeHashScanExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                entries,
                declared_field_count,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        let prefix = structure_hash_field_key(key, &[])?;
        let lower = start_after
            .map(|field| structure_hash_field_key(key, field))
            .transpose()?
            .map_or(Bound::Unbounded, Bound::Excluded);
        let plan = self.plan_btree_segments(
            tree,
            prefix,
            lower,
            Bound::Unbounded,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        let verify_complete = start_after.is_none() && limit >= declared_field_count;
        if plan.segments.is_empty() {
            if verify_complete && declared_field_count != 0 {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            return Ok(empty_hash_scan_execution_receipt(
                snapshot.visible_csn,
                declared_field_count,
                planning,
            ));
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            FOREGROUND_BOUNDED_MEMORY_BYTES,
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_hash_segment_plan_parallel(
                    key,
                    logical_time_micros,
                    plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_hash_segment_plan_serial(key, logical_time_micros, &plan)?,
                0,
            ),
        };
        let entries =
            finalize_hash_segment_batches(batches, declared_field_count, verify_complete, limit)?;
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeHashScanExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            entries,
            declared_field_count,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn hscan_latest_hash_at_v3(
        &self,
        request: structure_v3::CollectionScanRequestV3<'_>,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeHashScanExecutionReceipt, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let result = structure_v3::hash_scan_latest_at_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            BTree::from_root(root),
            request,
        )?;
        let execution = planning_permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeHashScanExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            entries: result.entries,
            declared_field_count: result.declared_field_count,
            planned_segments: 0,
            planned_physical_entries: 0,
            planning: None,
            execution,
            planned_workers: 1,
            worker_batches: 0,
        })
    }

    #[cfg(test)]
    fn hash_scan_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        self.hash_scan_in_tree_at(tree, key, start_after, limit, i64::MIN)
    }

    fn hash_scan_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        let Some(metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        let Some(declared_count) = decode_live_hash_metadata(metadata.bytes())? else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        if !declared_count.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureHash);
        }
        let declared_count = usize::try_from(declared_count.field_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if limit == 0 {
            return Ok(Vec::new());
        }
        let prefix = structure_hash_field_key(key, &[])?;
        let lower_key = start_after
            .map(|field| structure_hash_field_key(key, field))
            .transpose()?;
        let lower = lower_key
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Excluded);
        let verify_complete = start_after.is_none() && limit >= declared_count;
        let mut live_count = 0_usize;
        let mut entries = Vec::with_capacity(limit.min(declared_count).min(256));
        let mut failure = None;
        let outcome = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            lower,
            Bound::Unbounded,
            |physical_key, encoded| {
                let decoded = decode_hash_scan_entry(
                    physical_key,
                    encoded,
                    key,
                    &self.blobs,
                    logical_time_micros,
                );
                let (physical_live, entry) = match decoded {
                    Ok(entry) => entry,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                if physical_live {
                    live_count += 1;
                    if live_count > declared_count {
                        failure = Some(NativeRuntimeError::InvalidStructureTree);
                        return ControlFlow::Break(());
                    }
                }
                let Some(entry) = entry else {
                    return ControlFlow::Continue(());
                };
                if entries.len() < limit {
                    entries.push(entry);
                }
                if entries.len() == limit && !verify_complete {
                    ControlFlow::Break(())
                } else {
                    ControlFlow::Continue(())
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if verify_complete && (outcome != ControlFlow::Continue(()) || live_count != declared_count)
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(entries)
    }

    fn scan_hash_segment_plan_serial(
        &self,
        key: &[u8],
        logical_time_micros: i64,
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<HashSegmentBatch>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                decode_hash_segment(
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    &self.blobs,
                    logical_time_micros,
                )
            })
            .collect()
    }

    fn scan_hash_segment_plan_parallel(
        &self,
        key: &[u8],
        logical_time_micros: i64,
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<HashSegmentBatch>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let blobs = Arc::new(self.blobs.read_handle());
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    decode_hash_segment(
                        tree.scan_planned_segment(&pages, &segment)?,
                        &key,
                        &blobs,
                        logical_time_micros,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    /// Scans one bounded current hash-field range in descending exact-byte
    /// order without materializing the complete hash.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, an invalid cursor
    /// identity, another structure kind, a missing hash, or malformed reached
    /// state.
    pub fn hscan_reverse_latest_hash(
        &self,
        key: &[u8],
        start_before: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        self.hscan_reverse_latest_hash_at(key, start_before, limit, i64::MIN)
    }

    /// Scans one descending current hash-field range at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, an invalid cursor
    /// identity, another structure kind, a missing or expired hash, or
    /// malformed reached physical state.
    pub fn hscan_reverse_latest_hash_at(
        &self,
        key: &[u8],
        start_before: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            let request = structure_v3::CollectionScanRequestV3::new(
                key,
                start_before,
                limit,
                logical_time_micros,
            );
            return Ok(structure_v3::hash_scan_reverse_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                request,
            )?
            .entries);
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        self.hash_scan_reverse_in_tree_at(
            BTree::from_root(root),
            key,
            start_before,
            limit,
            logical_time_micros,
        )
    }

    #[cfg(test)]
    fn hash_scan_reverse_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        start_before: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        self.hash_scan_reverse_in_tree_at(tree, key, start_before, limit, i64::MIN)
    }

    fn hash_scan_reverse_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        start_before: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
        let metadata = self.visible_hash_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let declared_count = usize::try_from(metadata.field_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let upper_key = start_before
            .map(|field| structure_hash_field_key(key, field))
            .transpose()?;
        if limit == 0 {
            return Ok(Vec::new());
        }
        let prefix = structure_hash_field_key(key, &[])?;
        let upper = upper_key
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Excluded);
        let verify_complete = start_before.is_none() && limit >= declared_count;
        let mut live_count = 0_usize;
        let mut entries = Vec::with_capacity(limit.min(declared_count).min(256));
        let mut failure = None;
        let outcome = tree.visit_prefix_range_cached_reverse(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            Bound::Unbounded,
            upper,
            |physical_key, encoded| {
                let decoded = decode_hash_scan_entry(
                    physical_key,
                    encoded,
                    key,
                    &self.blobs,
                    logical_time_micros,
                );
                let (physical_live, entry) = match decoded {
                    Ok(entry) => entry,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                if physical_live {
                    live_count += 1;
                    if live_count > declared_count {
                        failure = Some(NativeRuntimeError::InvalidStructureTree);
                        return ControlFlow::Break(());
                    }
                }
                let Some(entry) = entry else {
                    return ControlFlow::Continue(());
                };
                entries.push(entry);
                if entries.len() == limit && !verify_complete {
                    ControlFlow::Break(())
                } else {
                    ControlFlow::Continue(())
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if verify_complete && (outcome != ControlFlow::Continue(()) || live_count != declared_count)
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(entries)
    }

    /// Scans one bounded binary-glob page over the current physical hash.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, invalid
    /// request/key identities, another structure kind, a missing hash, an
    /// exhausted matcher budget, or malformed reached physical state.
    pub fn hscan_match_latest_hash(
        &self,
        key: &[u8],
        request: &HashPatternScanRequest,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        self.hscan_match_latest_hash_at(key, request, i64::MIN)
    }

    /// Scans one bounded binary-glob page at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for an unsupported structure format, invalid
    /// request/key identities, another structure kind, a missing or expired
    /// hash, an exhausted matcher budget, or malformed reached physical state.
    pub fn hscan_match_latest_hash_at(
        &self,
        key: &[u8],
        request: &HashPatternScanRequest,
        logical_time_micros: i64,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            validate_hash_pattern_identity(key, request)?;
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::hash_pattern_scan_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                request,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        self.hash_pattern_scan_in_tree_at(BTree::from_root(root), key, request, logical_time_micros)
    }

    #[cfg(test)]
    fn hash_pattern_scan_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        request: &HashPatternScanRequest,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        self.hash_pattern_scan_in_tree_at(tree, key, request, i64::MIN)
    }

    fn hash_pattern_scan_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        request: &HashPatternScanRequest,
        logical_time_micros: i64,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        validate_hash_pattern_identity(key, request)?;
        let metadata = self.visible_hash_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let declared_count = usize::try_from(metadata.field_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if request.compiled().is_exact_literal() {
            return self.hash_pattern_exact_in_tree(
                tree,
                key,
                request,
                declared_count,
                logical_time_micros,
            );
        }
        self.hash_pattern_range_in_tree(tree, key, request, declared_count, logical_time_micros)
    }

    fn hash_pattern_exact_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        request: &HashPatternScanRequest,
        declared_count: usize,
        logical_time_micros: i64,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        let field = request.compiled().leading_literal_prefix();
        if request.start_after().is_some_and(|cursor| field <= cursor) {
            return Ok(HashPatternScanPage::new(
                Vec::new(),
                None,
                HashPatternScanStop::Exhausted,
                0,
                0,
            ));
        }
        let physical_key = structure_hash_field_key(key, field)?;
        let Some(encoded) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &physical_key)?
        else {
            return Ok(HashPatternScanPage::new(
                Vec::new(),
                None,
                HashPatternScanStop::Exhausted,
                0,
                0,
            ));
        };
        let Some(entry) = decode_hash_field_entry(encoded.bytes(), &self.blobs)? else {
            return Ok(HashPatternScanPage::new(
                Vec::new(),
                None,
                HashPatternScanStop::Exhausted,
                1,
                0,
            ));
        };
        if declared_count == 0 {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if entry
            .expires_at_micros
            .is_some_and(|expiry| expiry <= logical_time_micros)
        {
            return Ok(HashPatternScanPage::new(
                Vec::new(),
                None,
                HashPatternScanStop::Exhausted,
                1,
                0,
            ));
        }
        let mut budget = HashPatternMatchBudget::new(request.match_step_limit());
        if !request.compiled().matches(field, &mut budget)? {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(HashPatternScanPage::new(
            vec![HashFieldEntry::new(field.to_vec(), entry.value)],
            None,
            HashPatternScanStop::Exhausted,
            1,
            budget.used(),
        ))
    }

    fn hash_pattern_range_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        request: &HashPatternScanRequest,
        declared_count: usize,
        logical_time_micros: i64,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        let hash_prefix = structure_hash_field_key(key, &[])?;
        let literal_prefix = request.compiled().leading_literal_prefix();
        let range_lower = (!literal_prefix.is_empty())
            .then(|| structure_hash_field_key(key, literal_prefix))
            .transpose()?;
        let range_upper = match range_lower.as_deref() {
            Some(lower) => {
                Some(byte_prefix_successor(lower).ok_or(NativeRuntimeError::InvalidStructureTree)?)
            }
            None => None,
        };
        let cursor_key = request
            .start_after()
            .map(|cursor| structure_hash_field_key(key, cursor))
            .transpose()?;
        if range_upper
            .as_ref()
            .is_some_and(|upper| cursor_key.as_ref().is_some_and(|cursor| cursor >= upper))
        {
            return Ok(HashPatternScanPage::new(
                Vec::new(),
                None,
                HashPatternScanStop::Exhausted,
                0,
                0,
            ));
        }
        let lower = hash_pattern_lower_bound(range_lower.as_deref(), cursor_key.as_deref());
        let upper = range_upper
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Excluded);
        self.visit_hash_pattern_range(
            tree,
            key,
            request,
            declared_count,
            logical_time_micros,
            HashPatternPhysicalRange {
                prefix: &hash_prefix,
                lower,
                upper,
            },
        )
    }

    fn visit_hash_pattern_range(
        &self,
        tree: BTree,
        key: &[u8],
        request: &HashPatternScanRequest,
        declared_count: usize,
        logical_time_micros: i64,
        range: HashPatternPhysicalRange<'_>,
    ) -> Result<HashPatternScanPage, NativeRuntimeError> {
        let mut budget = HashPatternMatchBudget::new(request.match_step_limit());
        let mut entries =
            Vec::with_capacity(request.output_limit().min(request.visit_limit()).min(256));
        let mut continuation = None;
        let mut stop = HashPatternScanStop::Exhausted;
        let mut visited = 0_usize;
        let mut live_count = 0_usize;
        let mut failure = None;
        let outcome = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            range.prefix,
            range.lower,
            range.upper,
            |physical_key, encoded| {
                let field = match decode_hash_scan_field_identity(physical_key, key) {
                    Ok(field) => field,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                visited += 1;
                continuation = Some(field.to_vec());
                let entry = match decode_hash_field_entry(encoded, &self.blobs) {
                    Ok(value) => value,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                if let Some(entry) = entry {
                    live_count += 1;
                    if live_count > declared_count {
                        failure = Some(NativeRuntimeError::InvalidStructureTree);
                        return ControlFlow::Break(());
                    }
                    if entry
                        .expires_at_micros
                        .is_some_and(|expiry| expiry <= logical_time_micros)
                    {
                        return if visited == request.visit_limit() {
                            stop = HashPatternScanStop::VisitLimit;
                            ControlFlow::Break(())
                        } else {
                            ControlFlow::Continue(())
                        };
                    }
                    match request.compiled().matches(field, &mut budget) {
                        Ok(true) => {
                            entries.push(HashFieldEntry::new(field.to_vec(), entry.value));
                        }
                        Ok(false) => {}
                        Err(error) => {
                            failure = Some(error.into());
                            return ControlFlow::Break(());
                        }
                    }
                }
                if entries.len() == request.output_limit() {
                    stop = HashPatternScanStop::OutputLimit;
                    ControlFlow::Break(())
                } else if visited == request.visit_limit() {
                    stop = HashPatternScanStop::VisitLimit;
                    ControlFlow::Break(())
                } else {
                    ControlFlow::Continue(())
                }
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if outcome == ControlFlow::Continue(()) {
            continuation = None;
        }
        let verify_complete = outcome == ControlFlow::Continue(())
            && request.start_after().is_none()
            && request.compiled().leading_literal_prefix().is_empty();
        if verify_complete && live_count != declared_count {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(HashPatternScanPage::new(
            entries,
            continuation,
            stop,
            visited,
            budget.used(),
        ))
    }

    fn visible_hash_metadata_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<HashMetadata, NativeRuntimeError> {
        let Some(encoded) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_hash_meta_key(key),
        )?
        else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        let Some(metadata) = decode_live_hash_metadata(encoded.bytes())? else {
            return self.hash_missing_or_kind_error(tree, key);
        };
        if !metadata.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureHash);
        }
        Ok(metadata)
    }

    fn hash_missing_or_kind_error<T>(
        &self,
        tree: BTree,
        key: &[u8],
    ) -> Result<T, NativeRuntimeError> {
        let scalar = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
            .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
            .transpose()?
            .flatten()
            .is_some();
        let set = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
            .is_some();
        let list = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_list_meta_key(key)?,
            )?
            .is_some();
        let sorted_set = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_sorted_set_meta_key(key)?,
            )?
            .is_some();
        if scalar || set || list || sorted_set {
            Err(NativeRuntimeError::StructureKindMismatch)
        } else {
            Err(NativeRuntimeError::UnknownStructureHash)
        }
    }

    /// Tests membership directly through the current physical set namespace.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, a scalar/hash key, a missing set,
    /// or malformed B+tree metadata/member data.
    pub fn sismember_latest_set(
        &self,
        key: &[u8],
        member: &[u8],
    ) -> Result<bool, NativeRuntimeError> {
        self.sismember_latest_set_at(key, member, i64::MIN)
    }

    /// Tests membership directly through the current physical set namespace
    /// at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another live structure kind, a
    /// missing or expired set, or malformed physical state.
    pub fn sismember_latest_set_at(
        &self,
        key: &[u8],
        member: &[u8],
        logical_time_micros: i64,
    ) -> Result<bool, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            validate_set_member_identity(key, member)?;
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::set_contains_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                member,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        validate_set_member_identity(key, member)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
        else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        let Some(metadata) = decode_live_set_metadata(metadata.bytes())? else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        if !metadata.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureSet);
        }
        tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_set_member_key(key, member)?,
        )?
        .map(|encoded| decode_set_member_value(encoded.bytes()))
        .transpose()
        .map(Option::unwrap_or_default)
    }

    /// Tests bounded membership positions through the current physical set
    /// namespace.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an oversized batch, invalid
    /// identities, another live structure kind, a missing set, or malformed
    /// reached physical state.
    pub fn smismember_latest_set(
        &self,
        key: &[u8],
        members: &[Vec<u8>],
    ) -> Result<Vec<bool>, NativeRuntimeError> {
        self.smismember_latest_set_at(key, members, i64::MIN)
    }

    /// Tests bounded membership positions at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an oversized batch, invalid
    /// identities, another live structure kind, a missing or expired set, or
    /// malformed reached physical state.
    pub fn smismember_latest_set_at(
        &self,
        key: &[u8],
        members: &[Vec<u8>],
        logical_time_micros: i64,
    ) -> Result<Vec<bool>, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            validate_set_member_positions(key, members)?;
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::set_contains_many_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                members,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        validate_set_member_positions(key, members)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let _metadata = self.visible_set_metadata_in_tree_at(tree, key, logical_time_micros)?;
        members
            .iter()
            .map(|member| {
                tree.get_cached_pinned(
                    &self.pages,
                    &self.buffer_pool,
                    &structure_set_member_key(key, member)?,
                )?
                .map(|encoded| decode_set_member_value(encoded.bytes()))
                .transpose()
                .map(Option::unwrap_or_default)
            })
            .collect()
    }

    /// Reads one set cardinality directly from its physical metadata.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, a scalar/hash key, a missing set,
    /// or malformed B+tree metadata.
    pub fn scard_latest_set(&self, key: &[u8]) -> Result<usize, NativeRuntimeError> {
        self.scard_latest_set_at(key, i64::MIN)
    }

    /// Reads one set cardinality directly from physical metadata at explicit
    /// logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another live structure kind, a
    /// missing or expired set, or malformed physical state.
    pub fn scard_latest_set_at(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::collection_cardinality_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::Set,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
        else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        let Some(metadata) = decode_live_set_metadata(metadata.bytes())? else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        if !metadata.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureSet);
        }
        usize::try_from(metadata.member_count).map_err(|_| NativeRuntimeError::InvalidStructureTree)
    }

    /// Scans one bounded current physical set-member range.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an invalid cursor identity,
    /// another live structure kind, a missing set, or malformed reached
    /// physical state.
    pub fn sscan_latest_set(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
    ) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
        self.sscan_latest_set_at(key, start_after, limit, i64::MIN)
    }

    /// Scans one bounded physical set-member range at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, an invalid cursor identity,
    /// another live structure kind, a missing or expired set, or malformed
    /// reached physical state.
    pub fn sscan_latest_set_at(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
        Ok(self
            .sscan_latest_set_at_profiled(key, start_after, limit, logical_time_micros)?
            .members)
    }

    /// Scans one current set-member range and reports the direct or immutable
    /// segment physical execution path.
    ///
    /// # Errors
    ///
    /// Returns the same validation errors as [`Self::sscan_latest_set_at`]
    /// plus resource admission or persistent execution failures.
    pub fn sscan_latest_set_at_profiled(
        &self,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<NativeSetScanExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let request = structure_v3::CollectionScanRequestV3::new(
                key,
                start_after,
                limit,
                logical_time_micros,
            );
            return self.sscan_latest_set_at_v3(request, planning_permit);
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        validate_set_scan_identity(key, start_after)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let metadata = self.visible_set_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let declared_member_count = usize::try_from(metadata.member_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if limit <= STRUCTURE_SEGMENT_SCAN_THRESHOLD {
            let members =
                self.set_scan_in_tree_at(tree, key, start_after, limit, logical_time_micros)?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeSetScanExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                members,
                declared_member_count,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        let prefix = structure_set_member_key(key, &[])?;
        let lower = start_after
            .map(|member| structure_set_member_key(key, member))
            .transpose()?
            .map_or(Bound::Unbounded, Bound::Excluded);
        let plan = self.plan_btree_segments(
            tree,
            prefix,
            lower,
            Bound::Unbounded,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        let verify_complete = start_after.is_none() && limit >= declared_member_count;
        if plan.segments.is_empty() {
            if verify_complete && declared_member_count != 0 {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            return Ok(NativeSetScanExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                members: Vec::new(),
                declared_member_count,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            FOREGROUND_BOUNDED_MEMORY_BYTES,
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => {
                self.scan_set_segment_plan_parallel(key, plan, execution_pool, permit.permit())?
            }
            _ => (self.scan_set_segment_plan_serial(key, &plan)?, 0),
        };
        let members =
            finalize_set_segment_batches(batches, declared_member_count, verify_complete, limit)?;
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSetScanExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            members,
            declared_member_count,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn sscan_latest_set_at_v3(
        &self,
        request: structure_v3::CollectionScanRequestV3<'_>,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeSetScanExecutionReceipt, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(request.logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let result = structure_v3::set_scan_latest_at_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            BTree::from_root(root),
            request,
        )?;
        let execution = planning_permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSetScanExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            members: result.members,
            declared_member_count: result.declared_member_count,
            planned_segments: 0,
            planned_physical_entries: 0,
            planning: None,
            execution,
            planned_workers: 1,
            worker_batches: 0,
        })
    }

    fn set_scan_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        start_after: Option<&[u8]>,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
        let metadata = self.visible_set_metadata_in_tree_at(tree, key, logical_time_micros)?;
        let declared_count = usize::try_from(metadata.member_count)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if limit == 0 {
            return Ok(Vec::new());
        }
        let prefix = structure_set_member_key(key, &[])?;
        let lower_key = start_after
            .map(|member| structure_set_member_key(key, member))
            .transpose()?;
        let lower = lower_key
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Excluded);
        let verify_complete = start_after.is_none() && limit >= declared_count;
        let mut live_count = 0_usize;
        let mut members = Vec::with_capacity(limit.min(declared_count).min(256));
        let mut failure = None;
        let outcome = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            lower,
            Bound::Unbounded,
            |physical_key, encoded| {
                let member = match decode_set_scan_member_identity(physical_key, key) {
                    Ok(member) => member,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                let live = match decode_set_member_value(encoded) {
                    Ok(live) => live,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                if live {
                    live_count += 1;
                    if live_count > declared_count {
                        failure = Some(NativeRuntimeError::InvalidStructureTree);
                        return ControlFlow::Break(());
                    }
                    members.push(member.to_vec());
                    if members.len() == limit && !verify_complete {
                        return ControlFlow::Break(());
                    }
                }
                ControlFlow::Continue(())
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if verify_complete && (outcome != ControlFlow::Continue(()) || live_count != declared_count)
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(members)
    }

    fn scan_set_segment_plan_serial(
        &self,
        key: &[u8],
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<SetSegmentBatch>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                decode_set_segment(plan.tree.scan_planned_segment(&self.pages, segment)?, key)
            })
            .collect()
    }

    fn scan_set_segment_plan_parallel(
        &self,
        key: &[u8],
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<SetSegmentBatch>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    decode_set_segment(tree.scan_planned_segment(&pages, &segment)?, &key)
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    /// Returns one current physical set family's TTL at explicit logical
    /// time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage or malformed physical state.
    pub fn ttl_latest_set(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::collection_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::Set,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(encoded) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
        else {
            return Ok(Ttl::Missing);
        };
        let Some(metadata) = decode_live_set_metadata(encoded.bytes())? else {
            return Ok(Ttl::Missing);
        };
        Ok(match metadata.expires_at_micros {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    fn visible_set_metadata_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<SetMetadata, NativeRuntimeError> {
        let Some(encoded) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
        else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        let Some(metadata) = decode_live_set_metadata(encoded.bytes())? else {
            return self.set_missing_or_kind_error(tree, key, logical_time_micros);
        };
        if !metadata.is_visible_at(logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureSet);
        }
        Ok(metadata)
    }

    fn set_missing_or_kind_error<T>(
        &self,
        tree: BTree,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<T, NativeRuntimeError> {
        let scalar = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
            .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
            .transpose()?
            .flatten()
            .is_some_and(|entry| {
                entry
                    .expires_at_micros
                    .is_none_or(|expiry| expiry > logical_time_micros)
            });
        let hash = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_hash_meta_key(key),
            )?
            .map(|encoded| decode_live_hash_metadata(encoded.bytes()))
            .transpose()?
            .flatten()
            .is_some_and(|metadata| metadata.is_visible_at(logical_time_micros));
        let list = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_list_meta_key(key)?,
            )?
            .is_some();
        let sorted_set = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_sorted_set_meta_key(key)?,
            )?
            .is_some();
        if scalar || hash || list || sorted_set {
            Err(NativeRuntimeError::StructureKindMismatch)
        } else {
            Err(NativeRuntimeError::UnknownStructureSet)
        }
    }

    /// Evaluates one bounded complete binary-set algebra request directly
    /// through the current physical structure root.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, invalid identities, another live
    /// structure family, exhausted output or visit bounds, or malformed
    /// reached physical state.
    pub fn set_algebra_latest_at(
        &self,
        request: &SetAlgebraRequest,
        logical_time_micros: i64,
    ) -> Result<SetAlgebraResult, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::set_algebra_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                request,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        validate_set_algebra_keys(request)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        self.set_algebra_in_tree(BTree::from_root(root), request, logical_time_micros)
    }

    fn set_algebra_in_tree(
        &self,
        tree: BTree,
        request: &SetAlgebraRequest,
        logical_time_micros: i64,
    ) -> Result<SetAlgebraResult, NativeRuntimeError> {
        let cardinalities =
            self.preflight_set_algebra_inputs(tree, request, logical_time_micros)?;
        match request.operation() {
            SetAlgebraOperation::Union => self.set_union_in_tree(tree, request, &cardinalities),
            SetAlgebraOperation::Intersection => {
                self.set_intersection_in_tree(tree, request, &cardinalities)
            }
            SetAlgebraOperation::Difference => {
                self.set_difference_in_tree(tree, request, &cardinalities)
            }
        }
    }

    fn preflight_set_algebra_inputs(
        &self,
        tree: BTree,
        request: &SetAlgebraRequest,
        logical_time_micros: i64,
    ) -> Result<Vec<Option<usize>>, NativeRuntimeError> {
        let mut cardinalities = Vec::with_capacity(request.keys().len());
        for key in request.keys() {
            let metadata = tree.get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_set_meta_key(key),
            )?;
            if let Some(encoded) = metadata
                && let Some(metadata) = decode_live_set_metadata(encoded.bytes())?
                && metadata.is_visible_at(logical_time_micros)
            {
                cardinalities.push(Some(
                    usize::try_from(metadata.member_count)
                        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                ));
                continue;
            }
            if self.non_set_structure_exists_in_tree(tree, key, logical_time_micros)? {
                return Err(NativeRuntimeError::StructureKindMismatch);
            }
            cardinalities.push(None);
        }
        Ok(cardinalities)
    }

    fn non_set_structure_exists_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<bool, NativeRuntimeError> {
        let scalar = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
            .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
            .transpose()?
            .flatten()
            .is_some_and(|entry| {
                entry
                    .expires_at_micros
                    .is_none_or(|expiry| expiry > logical_time_micros)
            });
        let hash = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_hash_meta_key(key),
            )?
            .map(|encoded| decode_live_hash_metadata(encoded.bytes()))
            .transpose()?
            .flatten()
            .is_some_and(|metadata| {
                metadata
                    .expires_at_micros
                    .is_none_or(|expiry| expiry > logical_time_micros)
            });
        let list = match tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_list_meta_key(key)?,
        )? {
            Some(encoded) => decode_live_list_metadata(encoded.bytes())?.is_some(),
            None => false,
        };
        let sorted_set = match tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_sorted_set_meta_key(key)?,
        )? {
            Some(encoded) => {
                decode_sorted_set_metadata(encoded.bytes())?;
                true
            }
            None => false,
        };
        Ok(scalar || hash || list || sorted_set)
    }

    fn set_union_in_tree(
        &self,
        tree: BTree,
        request: &SetAlgebraRequest,
        cardinalities: &[Option<usize>],
    ) -> Result<SetAlgebraResult, NativeRuntimeError> {
        let mut execution = SetAlgebraExecution::new(request);
        for (key, cardinality) in request.keys().iter().zip(cardinalities) {
            if let Some(cardinality) = cardinality {
                self.visit_live_set_members(
                    tree,
                    key,
                    *cardinality,
                    &mut execution,
                    |member, execution| execution.insert(member).map_err(Into::into),
                )?;
            }
        }
        Ok(execution.finish())
    }

    fn set_intersection_in_tree(
        &self,
        tree: BTree,
        request: &SetAlgebraRequest,
        cardinalities: &[Option<usize>],
    ) -> Result<SetAlgebraResult, NativeRuntimeError> {
        if cardinalities
            .iter()
            .any(|cardinality| cardinality.is_none_or(|count| count == 0))
        {
            return Ok(SetAlgebraExecution::new(request).finish());
        }
        let (source_position, source_count) = cardinalities
            .iter()
            .enumerate()
            .filter_map(|(position, cardinality)| cardinality.map(|count| (position, count)))
            .min_by_key(|(position, count)| (*count, *position))
            .ok_or(SetAlgebraError::InvalidKeyCount { requested: 0 })?;
        let source_key = &request.keys()[source_position];
        let mut execution = SetAlgebraExecution::new(request);
        self.visit_live_set_members(
            tree,
            source_key,
            source_count,
            &mut execution,
            |member, execution| {
                for (position, key) in request.keys().iter().enumerate() {
                    if position != source_position
                        && !self.set_member_live_in_tree(tree, key, member, execution)?
                    {
                        return Ok(());
                    }
                }
                execution.insert(member).map_err(Into::into)
            },
        )?;
        Ok(execution.finish())
    }

    fn set_difference_in_tree(
        &self,
        tree: BTree,
        request: &SetAlgebraRequest,
        cardinalities: &[Option<usize>],
    ) -> Result<SetAlgebraResult, NativeRuntimeError> {
        let Some(first_count) = cardinalities[0] else {
            return Ok(SetAlgebraExecution::new(request).finish());
        };
        let mut execution = SetAlgebraExecution::new(request);
        self.visit_live_set_members(
            tree,
            &request.keys()[0],
            first_count,
            &mut execution,
            |member, execution| {
                for (key, cardinality) in request.keys()[1..].iter().zip(&cardinalities[1..]) {
                    if cardinality.is_some()
                        && self.set_member_live_in_tree(tree, key, member, execution)?
                    {
                        return Ok(());
                    }
                }
                execution.insert(member).map_err(Into::into)
            },
        )?;
        Ok(execution.finish())
    }

    fn set_member_live_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        member: &[u8],
        execution: &mut SetAlgebraExecution<'_>,
    ) -> Result<bool, NativeRuntimeError> {
        execution.consume_visit()?;
        tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_set_member_key(key, member)?,
        )?
        .map(|encoded| decode_set_member_value(encoded.bytes()))
        .transpose()
        .map(Option::unwrap_or_default)
    }

    fn visit_live_set_members(
        &self,
        tree: BTree,
        key: &[u8],
        declared_count: usize,
        execution: &mut SetAlgebraExecution<'_>,
        mut on_live: impl FnMut(&[u8], &mut SetAlgebraExecution<'_>) -> Result<(), NativeRuntimeError>,
    ) -> Result<(), NativeRuntimeError> {
        let prefix = structure_set_member_key(key, &[])?;
        let mut live_count = 0_usize;
        let mut failure = None;
        let outcome = tree.visit_prefix_range_cached(
            &self.pages,
            &self.buffer_pool,
            &prefix,
            Bound::Unbounded,
            Bound::Unbounded,
            |physical_key, encoded| {
                if let Err(error) = execution.consume_visit() {
                    failure = Some(error.into());
                    return ControlFlow::Break(());
                }
                let member = match decode_set_scan_member_identity(physical_key, key) {
                    Ok(member) => member,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                let live = match decode_set_member_value(encoded) {
                    Ok(live) => live,
                    Err(error) => {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                };
                if live {
                    live_count += 1;
                    if live_count > declared_count {
                        failure = Some(NativeRuntimeError::InvalidStructureTree);
                        return ControlFlow::Break(());
                    }
                    if let Err(error) = on_live(member, execution) {
                        failure = Some(error);
                        return ControlFlow::Break(());
                    }
                }
                ControlFlow::Continue(())
            },
        )?;
        if let Some(error) = failure {
            return Err(error);
        }
        if outcome == ControlFlow::Break(()) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if live_count != declared_count {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    /// Reads a bounded inclusive stream-ID range from the latest physical root.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, a missing stream, or malformed state.
    pub fn xrange_latest_stream(
        &self,
        key: &[u8],
        start: u64,
        end: u64,
        limit: usize,
    ) -> Result<Vec<(u64, model::StreamFields)>, NativeRuntimeError> {
        self.xrange_latest_stream_at(key, start, end, limit, i64::MIN)
    }

    /// Reads a bounded stream range at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for a missing/due stream or malformed state.
    pub fn xrange_latest_stream_at(
        &self,
        key: &[u8],
        start: u64,
        end: u64,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<Vec<(u64, model::StreamFields)>, NativeRuntimeError> {
        Ok(self
            .xrange_latest_stream_at_profiled(key, start, end, limit, logical_time_micros)?
            .entries)
    }

    /// Reads a current stream-ID range and reports the direct or immutable
    /// segment physical execution path.
    ///
    /// # Errors
    ///
    /// Returns the same validation errors as [`Self::xrange_latest_stream_at`]
    /// plus resource admission or persistent execution failures.
    pub fn xrange_latest_stream_at_profiled(
        &self,
        key: &[u8],
        start: u64,
        end: u64,
        limit: usize,
        logical_time_micros: i64,
    ) -> Result<NativeStreamRangeExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            return self.xrange_latest_stream_at_profiled_v3(
                structure_v3::StreamRangeRequestV3 {
                    key,
                    start,
                    end,
                    limit,
                    logical_time_micros,
                },
                planning_permit,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let last = self.visible_stream_last_id_in_tree_at(tree, key, logical_time_micros)?;
        let effective_end = end.min(last);
        let range_width = effective_end
            .checked_sub(start)
            .and_then(|width| width.checked_add(1))
            .unwrap_or(0);
        if limit <= STRUCTURE_SEGMENT_SCAN_THRESHOLD
            && range_width <= STRUCTURE_SEGMENT_SCAN_THRESHOLD as u64
        {
            let entries = self.stream_range_in_tree(tree, key, start, effective_end, limit)?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeStreamRangeExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                entries,
                declared_last_id: last,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        if limit == 0 || start > effective_end {
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeStreamRangeExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                entries: Vec::new(),
                declared_last_id: last,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_stream_range_segments(StreamRangeSegmentRequest {
            snapshot_csn: snapshot.visible_csn,
            tree,
            key,
            start,
            end: effective_end,
            last_id: last,
            limit,
            planning_permit,
        })
    }

    fn execute_stream_range_segments(
        &self,
        request: StreamRangeSegmentRequest<'_>,
    ) -> Result<NativeStreamRangeExecutionReceipt, NativeRuntimeError> {
        let prefix = structure_stream_entry_prefix(request.key)?;
        let plan = self.plan_btree_segments(
            request.tree,
            prefix,
            Bound::Included(structure_stream_entry_key(request.key, request.start)?),
            Bound::Included(structure_stream_entry_key(request.key, request.end)?),
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        if plan.segments.is_empty() {
            return Ok(NativeStreamRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries: Vec::new(),
                declared_last_id: request.last_id,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            FOREGROUND_BOUNDED_MEMORY_BYTES,
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_stream_segment_plan_parallel(
                    request.key,
                    plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (self.scan_stream_segment_plan_serial(request.key, &plan)?, 0),
        };
        let mut entries = batches.into_iter().flatten().collect::<Vec<_>>();
        entries.truncate(request.limit);
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeStreamRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            entries,
            declared_last_id: request.last_id,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn xrange_latest_stream_at_profiled_v3(
        &self,
        request: structure_v3::StreamRangeRequestV3<'_>,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeStreamRangeExecutionReceipt, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(request.logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let plan = structure_v3::prepare_stream_range_latest_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            tree,
            request,
        )?;
        if plan.empty
            || (request.limit <= STRUCTURE_SEGMENT_SCAN_THRESHOLD
                && plan.range_width <= STRUCTURE_SEGMENT_SCAN_THRESHOLD as u64)
        {
            let entries = structure_v3::stream_range_latest_at_v3(
                &self.pages,
                &self.buffer_pool,
                tree,
                request.key,
                &plan,
                request.limit,
            )?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeStreamRangeExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                entries,
                declared_last_id: plan.last_id,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_stream_range_segments_v3(
            snapshot.visible_csn,
            tree,
            request,
            &plan,
            planning_permit,
        )
    }

    fn execute_stream_range_segments_v3(
        &self,
        snapshot_csn: Option<Csn>,
        tree: BTree,
        request: structure_v3::StreamRangeRequestV3<'_>,
        plan: &structure_v3::StreamRangePlanV3,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeStreamRangeExecutionReceipt, NativeRuntimeError> {
        let segment_plan = self.plan_btree_segments(
            tree,
            plan.prefix.clone(),
            plan.lower.clone(),
            plan.upper.clone(),
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        if segment_plan.segments.is_empty() {
            let entries =
                structure_v3::finalize_stream_segment_batches_v3(Vec::new(), plan, request.limit)?;
            return Ok(NativeStreamRangeExecutionReceipt {
                snapshot_csn,
                entries,
                declared_last_id: plan.last_id,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = segment_plan.segments.len();
        let planned_physical_entries = segment_plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            FOREGROUND_BOUNDED_MEMORY_BYTES,
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_stream_segment_plan_v3_parallel(
                    request.key,
                    plan.incarnation,
                    plan.last_id,
                    segment_plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_stream_segment_plan_v3_serial(
                    request.key,
                    plan.incarnation,
                    plan.last_id,
                    &segment_plan,
                )?,
                0,
            ),
        };
        let entries =
            structure_v3::finalize_stream_segment_batches_v3(batches, plan, request.limit)?;
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeStreamRangeExecutionReceipt {
            snapshot_csn,
            entries,
            declared_last_id: plan.last_id,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn visible_stream_last_id_in_tree_at(
        &self,
        tree: BTree,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<u64, NativeRuntimeError> {
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_stream_meta_key(key)?,
            )?
            .ok_or(NativeRuntimeError::UnknownStructureStream)?;
        if is_structure_tombstone(metadata.bytes()) {
            return Err(NativeRuntimeError::UnknownStructureStream);
        }
        let (last, expiry) = decode_stream_metadata(metadata.bytes())?;
        if expiry.is_some_and(|expiry| expiry <= logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureStream);
        }
        Ok(last)
    }

    fn stream_range_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        start: u64,
        end: u64,
        limit: usize,
    ) -> Result<Vec<NativeStreamEntry>, NativeRuntimeError> {
        if limit == 0 || start > end {
            return Ok(Vec::new());
        }
        let mut entries = Vec::new();
        for id in start..=end {
            if entries.len() == limit {
                break;
            }
            if let Some(value) = tree.get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_stream_entry_key(key, id)?,
            )? {
                if is_structure_tombstone(value.bytes()) {
                    continue;
                }
                let (payload_id, fields) = decode_stream_wal_entry(value.bytes())?;
                if payload_id != id {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
                entries.push((id, fields));
            }
        }
        Ok(entries)
    }

    fn scan_stream_segment_plan_serial(
        &self,
        key: &[u8],
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<Vec<NativeStreamEntry>>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                decode_stream_segment(plan.tree.scan_planned_segment(&self.pages, segment)?, key)
            })
            .collect()
    }

    fn scan_stream_segment_plan_parallel(
        &self,
        key: &[u8],
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<Vec<NativeStreamEntry>>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    decode_stream_segment(tree.scan_planned_segment(&pages, &segment)?, &key)
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    fn scan_stream_segment_plan_v3_serial(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        last_id: u64,
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<structure_v3::StreamSegmentBatchV3>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                structure_v3::decode_stream_segment_v3(
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    incarnation,
                    last_id,
                )
            })
            .collect()
    }

    fn scan_stream_segment_plan_v3_parallel(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        last_id: u64,
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<structure_v3::StreamSegmentBatchV3>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    structure_v3::decode_stream_segment_v3(
                        tree.scan_planned_segment(&pages, &segment)?,
                        &key,
                        incarnation,
                        last_id,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    /// Returns one current physical stream family's TTL at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage or malformed physical state.
    pub fn ttl_latest_stream(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::collection_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::Stream,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok(Ttl::Missing);
        };
        let tree = BTree::from_root(root);
        let Some(metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_stream_meta_key(key)?,
        )?
        else {
            return Ok(Ttl::Missing);
        };
        if is_structure_tombstone(metadata.bytes()) {
            return Ok(Ttl::Missing);
        }
        let expiry = match metadata.bytes().len() {
            8 => None,
            16 => Some(i64::from_be_bytes(
                metadata.bytes()[8..16]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            )),
            _ => return Err(NativeRuntimeError::InvalidStructureTree),
        };
        Ok(match expiry {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    /// Reads one list cardinality directly from its physical metadata.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing list, or
    /// malformed metadata.
    pub fn llen_latest_list(&self, key: &[u8]) -> Result<usize, NativeRuntimeError> {
        self.llen_latest_list_at(key, i64::MIN)
    }

    /// Reads one list cardinality directly from physical metadata at explicit
    /// logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing or due
    /// list, or malformed metadata.
    pub fn llen_latest_list_at(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        self.llen_latest_list_at_unadmitted(key, logical_time_micros)
    }

    fn llen_latest_list_at_unadmitted(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::collection_cardinality_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::List,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_list_meta_key(key)?,
            )?
            .map(|encoded| decode_live_list_metadata(encoded.bytes()))
            .transpose()?
            .flatten();
        let Some(metadata) =
            metadata.filter(|metadata| metadata.is_visible_at(logical_time_micros))
        else {
            if tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
                .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
                .transpose()?
                .flatten()
                .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_hash_meta_key(key),
                    )?
                    .map(|encoded| decode_live_hash_metadata(encoded.bytes()))
                    .transpose()?
                    .flatten()
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_set_meta_key(key),
                    )?
                    .is_some()
                || tree
                    .get_cached_pinned(
                        &self.pages,
                        &self.buffer_pool,
                        &structure_sorted_set_meta_key(key)?,
                    )?
                    .is_some()
            {
                return Err(NativeRuntimeError::StructureKindMismatch);
            }
            return Err(NativeRuntimeError::UnknownStructureList);
        };
        usize::try_from(metadata.length).map_err(|_| NativeRuntimeError::InvalidStructureTree)
    }

    /// Reads an inclusive signed-index range through physical list chunks.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing list, or
    /// malformed metadata, chunk, envelope, page, or blob state.
    pub fn lrange_latest_list(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
    ) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
        Ok(self
            .lrange_latest_list_at_profiled(key, start, stop, i64::MIN)?
            .values)
    }

    /// Reads an inclusive signed-index range through physical list chunks at
    /// explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing or due
    /// list, or malformed metadata, chunk, envelope, page, or blob state.
    pub fn lrange_latest_list_at(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
        logical_time_micros: i64,
    ) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
        Ok(self
            .lrange_latest_list_at_profiled(key, start, stop, logical_time_micros)?
            .values)
    }

    /// Reads an inclusive signed-index range and reports whether it used the
    /// direct chunk walk or governed immutable B+tree leaf segments.
    ///
    /// Large ranges are segmented only when they cover at least half of the
    /// live list. Narrow ranges retain the head/tail direct walk until list
    /// chunks carry persisted logical prefix-count summaries.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::lrange_latest_list_at`] plus
    /// resource admission or persistent execution failures.
    pub fn lrange_latest_list_at_profiled(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
        logical_time_micros: i64,
    ) -> Result<NativeListRangeExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            return self.lrange_latest_list_at_profiled_v3(
                structure_v3::ListRangeRequestV3 {
                    key,
                    start,
                    stop,
                    logical_time_micros,
                },
                planning_permit,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        self.list_range_profiled_at(ListRangeRequest {
            snapshot_csn: snapshot.visible_csn,
            tree,
            key: key.to_vec(),
            logical_time_micros,
            start,
            stop,
            planning_permit,
        })
    }

    fn lrange_latest_list_at_profiled_v3(
        &self,
        request: structure_v3::ListRangeRequestV3<'_>,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeListRangeExecutionReceipt, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(request.logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let plan = structure_v3::prepare_list_range_latest_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            tree,
            request,
        )?;
        let requested = plan
            .normalized
            .map_or(0, |(range_start, range_stop)| range_stop - range_start + 1);
        if requested == 0
            || requested <= STRUCTURE_SEGMENT_SCAN_THRESHOLD
            || requested.saturating_mul(2) < plan.element_count
        {
            let values = structure_v3::list_range_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                tree,
                request.key,
                &plan,
            )?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeListRangeExecutionReceipt {
                snapshot_csn: snapshot.visible_csn,
                values,
                declared_length: plan.element_count,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_list_range_segments_v3(
            snapshot.visible_csn,
            tree,
            request.key,
            requested,
            &plan,
            planning_permit,
        )
    }

    fn execute_list_range_segments_v3(
        &self,
        snapshot_csn: Option<Csn>,
        tree: BTree,
        key: &[u8],
        requested: usize,
        plan: &structure_v3::ListRangePlanV3,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeListRangeExecutionReceipt, NativeRuntimeError> {
        let segment_plan = self.plan_btree_segments(
            tree,
            plan.prefix.clone(),
            plan.lower.clone(),
            plan.upper.clone(),
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        if segment_plan.segments.is_empty() {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let planned_segments = segment_plan.segments.len();
        let planned_physical_entries = segment_plan.physical_entries;
        let memory_bytes = plan
            .logical_value_bytes
            .saturating_add(segmented_result_memory_bytes(planned_physical_entries));
        let permit = self.admit_parallel_foreground_bounded_io(memory_bytes, planned_segments)?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_list_segment_plan_v3_parallel(
                    key,
                    plan.incarnation,
                    segment_plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_list_segment_plan_v3_serial(key, plan.incarnation, &segment_plan)?,
                0,
            ),
        };
        let all_values = structure_v3::finalize_list_segment_batches_v3(batches, plan)?;
        let (range_start, _) = plan
            .normalized
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let values = all_values
            .into_iter()
            .skip(range_start)
            .take(requested)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeListRangeExecutionReceipt {
            snapshot_csn,
            values,
            declared_length: plan.element_count,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn list_range_profiled_at(
        &self,
        request: ListRangeRequest,
    ) -> Result<NativeListRangeExecutionReceipt, NativeRuntimeError> {
        let metadata_key = structure_list_meta_key(&request.key)?;
        let metadata = request
            .tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
            .map(|encoded| decode_live_list_metadata(encoded.bytes()))
            .transpose()?
            .flatten();
        let Some(metadata) =
            metadata.filter(|metadata| metadata.is_visible_at(request.logical_time_micros))
        else {
            return match self
                .llen_latest_list_at_unadmitted(&request.key, request.logical_time_micros)
            {
                Err(error) => Err(error),
                Ok(_) => Err(NativeRuntimeError::InvalidStructureTree),
            };
        };
        let length = usize::try_from(metadata.length)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let Some((range_start, range_stop)) =
            normalize_list_range(length, request.start, request.stop)
        else {
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeListRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                values: Vec::new(),
                declared_length: length,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        };
        let requested = range_stop - range_start + 1;
        if metadata.value_bytes.is_none()
            || requested <= STRUCTURE_SEGMENT_SCAN_THRESHOLD
            || requested.saturating_mul(2) < length
        {
            let values = if range_start <= length - 1 - range_stop {
                read_list_range_from_head(
                    self,
                    request.tree,
                    &request.key,
                    metadata,
                    range_start,
                    range_stop,
                )?
            } else {
                read_list_range_from_tail(
                    self,
                    request.tree,
                    &request.key,
                    metadata,
                    range_start,
                    range_stop,
                )?
            };
            if values.len() != requested {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeListRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                values,
                declared_length: length,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_list_range_segments(request, metadata, length, range_start, requested)
    }

    fn execute_list_range_segments(
        &self,
        request: ListRangeRequest,
        metadata: ListMetadata,
        declared_length: usize,
        range_start: usize,
        requested: usize,
    ) -> Result<NativeListRangeExecutionReceipt, NativeRuntimeError> {
        let declared_value_bytes = metadata
            .value_bytes
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let prefix = structure_list_chunk_prefix(&request.key)?;
        let lower = Bound::Included(structure_list_chunk_key(&request.key, metadata.head_chunk)?);
        let upper = Bound::Included(structure_list_chunk_key(&request.key, metadata.tail_chunk)?);
        let plan = self.plan_btree_segments(
            request.tree,
            prefix,
            lower,
            upper,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        if plan.segments.is_empty() {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let memory_bytes = declared_value_bytes
            .saturating_add(segmented_result_memory_bytes(planned_physical_entries));
        let permit = self.admit_parallel_foreground_bounded_io(memory_bytes, planned_segments)?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_list_segment_plan_parallel(
                    &request.key,
                    plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (self.scan_list_segment_plan_serial(&request.key, &plan)?, 0),
        };
        let values = finalize_list_segment_batches(
            batches,
            metadata,
            declared_length,
            declared_value_bytes,
        )?;
        let values = values
            .into_iter()
            .skip(range_start)
            .take(requested)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeListRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            values,
            declared_length,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn scan_list_segment_plan_serial(
        &self,
        key: &[u8],
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<ListChunkBatch>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                decode_list_segment(
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    &self.blobs,
                )
            })
            .collect()
    }

    fn scan_list_segment_plan_parallel(
        &self,
        key: &[u8],
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<ListChunkBatch>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let blobs = Arc::new(self.blobs.read_handle());
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    decode_list_segment(tree.scan_planned_segment(&pages, &segment)?, &key, &blobs)
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    fn scan_list_segment_plan_v3_serial(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<structure_v3::ListSegmentBatchV3>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                structure_v3::decode_list_segment_v3(
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    incarnation,
                    &self.blobs,
                )
            })
            .collect()
    }

    fn scan_list_segment_plan_v3_parallel(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<structure_v3::ListSegmentBatchV3>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let blobs = Arc::new(self.blobs.read_handle());
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    structure_v3::decode_list_segment_v3(
                        tree.scan_planned_segment(&pages, &segment)?,
                        &key,
                        incarnation,
                        &blobs,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    /// Returns one current physical list family's TTL at explicit logical
    /// time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage or malformed physical state.
    pub fn ttl_latest_list(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::collection_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::List,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let Some(encoded) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_list_meta_key(key)?,
        )?
        else {
            return Ok(Ttl::Missing);
        };
        let Some(metadata) = decode_live_list_metadata(encoded.bytes())? else {
            return Ok(Ttl::Missing);
        };
        Ok(match metadata.expires_at_micros {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    /// Reads one member score through the current physical membership index.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata/member state.
    pub fn zscore_latest_sorted_set(
        &self,
        key: &[u8],
        member: &[u8],
    ) -> Result<Option<f64>, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::sorted_set_score_latest_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                member,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let metadata_key = structure_sorted_set_meta_key(key)?;
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(tree, key);
        };
        decode_sorted_set_metadata(metadata.bytes())?;
        tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_sorted_set_member_key(key, member)?,
        )?
        .map(|encoded| decode_sorted_set_score(encoded.bytes()))
        .transpose()
        .map(|score| score.flatten().map(SortedSetScore::value))
    }

    /// Reads exact sorted-set cardinality through physical metadata.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata.
    pub fn zcard_latest_sorted_set(&self, key: &[u8]) -> Result<usize, NativeRuntimeError> {
        self.zcard_latest_sorted_set_at(key, i64::MIN)
    }

    /// Reads sorted-set cardinality at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing/due set,
    /// or malformed metadata.
    pub fn zcard_latest_sorted_set_at(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<usize, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::collection_cardinality_latest_at_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::SortedSet,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let metadata_key = structure_sorted_set_meta_key(key)?;
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(tree, key);
        };
        if is_structure_tombstone(metadata.bytes()) {
            return Err(NativeRuntimeError::UnknownStructureSortedSet);
        }
        let (count, expiry) = decode_sorted_set_metadata_state(metadata.bytes())?;
        if expiry.is_some_and(|expiry| expiry <= logical_time_micros) {
            return Err(NativeRuntimeError::UnknownStructureSortedSet);
        }
        usize::try_from(count).map_err(|_| NativeRuntimeError::InvalidStructureTree)
    }

    /// Returns one current physical sorted-set family's TTL at explicit logical time.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage or malformed physical state.
    pub fn ttl_latest_sorted_set(
        &self,
        key: &[u8],
        logical_time_micros: i64,
    ) -> Result<Ttl, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(logical_time_micros)?;
            let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
                return Ok(Ttl::Missing);
            };
            return structure_v3::collection_ttl_latest_v3(
                &self.pages,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                structure_v3::StructureCollectionFamily::SortedSet,
                logical_time_micros,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok(Ttl::Missing);
        };
        let tree = BTree::from_root(root);
        let Some(metadata) = tree.get_cached_pinned(
            &self.pages,
            &self.buffer_pool,
            &structure_sorted_set_meta_key(key)?,
        )?
        else {
            return Ok(Ttl::Missing);
        };
        if is_structure_tombstone(metadata.bytes()) {
            return Ok(Ttl::Missing);
        }
        let (_, expiry) = decode_sorted_set_metadata_state(metadata.bytes())?;
        Ok(match expiry {
            None => Ttl::Persistent,
            Some(expiry) if expiry > logical_time_micros => {
                Ttl::RemainingMicros(expiry.saturating_sub(logical_time_micros))
            }
            Some(_) => Ttl::Missing,
        })
    }

    /// Reads one member's zero-based ascending rank through both physical
    /// sorted-set indexes.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata/index state.
    pub fn zrank_latest_sorted_set(
        &self,
        key: &[u8],
        member: &[u8],
    ) -> Result<Option<usize>, NativeRuntimeError> {
        self.sorted_set_rank_latest(key, member, false)
    }

    /// Reads one member's zero-based descending rank through both physical
    /// sorted-set indexes.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata/index state.
    pub fn zrevrank_latest_sorted_set(
        &self,
        key: &[u8],
        member: &[u8],
    ) -> Result<Option<usize>, NativeRuntimeError> {
        self.sorted_set_rank_latest(key, member, true)
    }

    fn sorted_set_rank_latest(
        &self,
        key: &[u8],
        member: &[u8],
        reverse: bool,
    ) -> Result<Option<usize>, NativeRuntimeError> {
        let _permit = self.admit_foreground_point()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return structure_v3::sorted_set_rank_latest_v3(
                &self.pages,
                &self.blobs,
                &self.buffer_pool,
                BTree::from_root(root),
                key,
                member,
                reverse,
            );
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        self.sorted_set_rank_in_tree(BTree::from_root(root), key, member, reverse)
    }

    fn sorted_set_rank_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        member: &[u8],
        reverse: bool,
    ) -> Result<Option<usize>, NativeRuntimeError> {
        let metadata_key = structure_sorted_set_meta_key(key)?;
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(tree, key);
        };
        let length = usize::try_from(decode_sorted_set_metadata(metadata.bytes())?)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let member_key = structure_sorted_set_member_key(key, member)?;
        let Some(encoded_score) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &member_key)?
        else {
            return Ok(None);
        };
        let Some(score) = decode_sorted_set_score(encoded_score.bytes())? else {
            return Ok(None);
        };
        if length == 0 {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let target = structure_sorted_set_order_key(key, score, member)?;
        let prefix = structure_sorted_set_order_prefix(key)?;
        let mut live_rank = 0_usize;
        let mut rank = None;
        let mut failure = None;
        let mut visitor = |physical_key: &[u8], value: &[u8]| {
            let decoded = (|| {
                let (found_key, found_score, found_member) =
                    decode_sorted_set_order_identity(&physical_key[1..])?;
                let live = decode_set_member_value(value)?;
                Ok::<_, NativeRuntimeError>((found_key, found_score, found_member, live))
            })();
            let (found_key, found_score, found_member, live) = match decoded {
                Ok(decoded) => decoded,
                Err(error) => {
                    failure = Some(error);
                    return ControlFlow::Break(());
                }
            };
            if found_key != key || (live && found_member == member && found_score != score) {
                failure = Some(NativeRuntimeError::InvalidStructureTree);
                return ControlFlow::Break(());
            }
            if physical_key == target.as_slice() {
                if !live || found_score != score || found_member != member {
                    failure = Some(NativeRuntimeError::InvalidStructureTree);
                    return ControlFlow::Break(());
                }
                if live_rank >= length {
                    failure = Some(NativeRuntimeError::InvalidStructureTree);
                    return ControlFlow::Break(());
                }
                rank = Some(live_rank);
                return ControlFlow::Break(());
            }
            if live {
                live_rank += 1;
                if live_rank >= length {
                    failure = Some(NativeRuntimeError::InvalidStructureTree);
                    return ControlFlow::Break(());
                }
            }
            ControlFlow::Continue(())
        };
        let _visit = if reverse {
            tree.visit_prefix_range_cached_reverse(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                Bound::Included(target.as_slice()),
                Bound::Unbounded,
                &mut visitor,
            )?
        } else {
            tree.visit_prefix_range_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                Bound::Unbounded,
                Bound::Included(target.as_slice()),
                &mut visitor,
            )?
        };
        if let Some(error) = failure {
            return Err(error);
        }
        rank.map(Some)
            .ok_or(NativeRuntimeError::InvalidStructureTree)
    }

    /// Reads an inclusive signed-rank range through the ordered physical index.
    ///
    /// Traversal stops after the last requested live rank and does not
    /// materialize the complete sorted set.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata/index state.
    pub fn zrange_latest_sorted_set(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        Ok(self
            .zrange_latest_sorted_set_profiled(key, start, stop)?
            .entries)
    }

    /// Reads an ascending signed-rank range and reports whether it used the
    /// direct visitor or governed immutable leaf segments.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::zrange_latest_sorted_set`] plus
    /// resource admission or persistent execution failures.
    pub fn zrange_latest_sorted_set_profiled(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        self.sorted_set_rank_range_latest_profiled(key, start, stop, SortedSetDirection::Ascending)
    }

    /// Reads an inclusive signed-rank range in descending order through the
    /// ordered physical index.
    ///
    /// Traversal starts at the ordered prefix tail, stops after the last
    /// requested live rank, and does not materialize the complete sorted set.
    ///
    /// # Errors
    ///
    /// Returns an error for legacy storage, another family, a missing sorted
    /// set, or malformed metadata/index state.
    pub fn zrevrange_latest_sorted_set(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        Ok(self
            .zrevrange_latest_sorted_set_profiled(key, start, stop)?
            .entries)
    }

    /// Reads a descending signed-rank range and reports whether it used the
    /// direct visitor or governed immutable leaf segments.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::zrevrange_latest_sorted_set`] plus
    /// resource admission or persistent execution failures.
    pub fn zrevrange_latest_sorted_set_profiled(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        self.sorted_set_rank_range_latest_profiled(key, start, stop, SortedSetDirection::Descending)
    }

    fn sorted_set_rank_range_latest_profiled(
        &self,
        key: &[u8],
        start: i64,
        stop: i64,
        direction: SortedSetDirection,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return self.sorted_set_rank_range_profiled_v3(SortedSetRankRangeRequest {
                snapshot_csn: snapshot.visible_csn,
                tree: BTree::from_root(root),
                key: key.to_vec(),
                start,
                stop,
                direction,
                planning_permit,
            });
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        self.sorted_set_rank_range_profiled_at(SortedSetRankRangeRequest {
            snapshot_csn: snapshot.visible_csn,
            tree,
            key: key.to_vec(),
            start,
            stop,
            direction,
            planning_permit,
        })
    }

    fn sorted_set_rank_range_profiled_v3(
        &self,
        request: SortedSetRankRangeRequest,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let plan = structure_v3::prepare_sorted_set_order_plan_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            request.tree,
            &request.key,
            None,
        )?;
        let Some((range_start, range_stop)) =
            normalize_list_range(plan.member_count, request.start, request.stop)
        else {
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_sorted_set_range_receipt(
                request.snapshot_csn,
                Vec::new(),
                execution,
            ));
        };
        let requested = range_stop - range_start + 1;
        if requested <= STRUCTURE_SEGMENT_SCAN_THRESHOLD
            || requested.saturating_mul(2) < plan.member_count
        {
            let entries = structure_v3::sorted_set_rank_range_latest_v3(
                &self.pages,
                &self.buffer_pool,
                request.tree,
                &request.key,
                &plan,
                structure_v3::SortedSetRankRangeRequestV3 {
                    start: request.start,
                    stop: request.stop,
                    direction: request.direction,
                },
            )?;
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_sorted_set_range_receipt(
                request.snapshot_csn,
                entries,
                execution,
            ));
        }
        self.execute_sorted_set_rank_segments_v3(request, &plan, range_start, requested)
    }

    fn execute_sorted_set_rank_segments_v3(
        &self,
        request: SortedSetRankRangeRequest,
        order_plan: &structure_v3::SortedSetOrderPlanV3,
        range_start: usize,
        requested: usize,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let mut plan = self.plan_btree_segments(
            request.tree,
            order_plan.prefix.clone(),
            Bound::Unbounded,
            Bound::Unbounded,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        if request.direction == SortedSetDirection::Descending {
            plan.segments.reverse();
        }
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            segmented_result_memory_bytes(planned_physical_entries),
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = self.scan_sorted_set_segment_plan_v3(
            &request.key,
            order_plan.incarnation,
            request.direction,
            plan,
            permit.as_ref(),
            planned_workers,
        )?;
        let live_entries = batches
            .into_iter()
            .flat_map(|batch| batch.entries)
            .collect::<Vec<_>>();
        if live_entries.len() != order_plan.member_count {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let entries = live_entries
            .into_iter()
            .skip(range_start)
            .take(requested)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSortedSetRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            entries,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn sorted_set_rank_range_profiled_at(
        &self,
        request: SortedSetRankRangeRequest,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let metadata_key = structure_sorted_set_meta_key(&request.key)?;
        let Some(metadata) =
            request
                .tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(request.tree, &request.key);
        };
        let length = usize::try_from(decode_sorted_set_metadata(metadata.bytes())?)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let Some((range_start, range_stop)) =
            normalize_list_range(length, request.start, request.stop)
        else {
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeSortedSetRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries: Vec::new(),
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        };
        let requested = range_stop - range_start + 1;
        if requested <= STRUCTURE_SEGMENT_SCAN_THRESHOLD || requested.saturating_mul(2) < length {
            let entries = self.sorted_set_rank_range_in_tree(
                request.tree,
                &request.key,
                request.start,
                request.stop,
                request.direction,
            )?;
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeSortedSetRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_sorted_set_rank_segments(request, length, range_start, requested)
    }

    fn execute_sorted_set_rank_segments(
        &self,
        request: SortedSetRankRangeRequest,
        declared_length: usize,
        range_start: usize,
        requested: usize,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let prefix = structure_sorted_set_order_prefix(&request.key)?;
        let mut plan = self.plan_btree_segments(
            request.tree,
            prefix,
            Bound::Unbounded,
            Bound::Unbounded,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        if request.direction == SortedSetDirection::Descending {
            plan.segments.reverse();
        }
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            segmented_result_memory_bytes(planned_physical_entries),
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_sorted_set_segment_plan_parallel(
                    &request.key,
                    request.direction,
                    plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_sorted_set_segment_plan_serial(&request.key, request.direction, &plan)?,
                0,
            ),
        };
        let live_entries: Vec<_> = batches.into_iter().flatten().collect();
        if live_entries.len() != declared_length {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let entries = live_entries
            .into_iter()
            .skip(range_start)
            .take(requested)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSortedSetRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            entries,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn sorted_set_rank_range_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        start: i64,
        stop: i64,
        direction: SortedSetDirection,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        let metadata_key = structure_sorted_set_meta_key(key)?;
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(tree, key);
        };
        let length = usize::try_from(decode_sorted_set_metadata(metadata.bytes())?)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        let Some((range_start, range_stop)) = normalize_list_range(length, start, stop) else {
            return Ok(Vec::new());
        };
        let prefix = structure_sorted_set_order_prefix(key)?;
        let mut live_rank = 0_usize;
        let mut entries = Vec::with_capacity(range_stop - range_start + 1);
        let mut failure = None;
        let mut visitor = |physical_key: &[u8], value: &[u8]| {
            let decoded = (|| {
                let (_, score, member) = decode_sorted_set_order_identity(&physical_key[1..])?;
                let live = decode_set_member_value(value)?;
                Ok::<_, NativeRuntimeError>((score, member, live))
            })();
            let (score, member, live) = match decoded {
                Ok(decoded) => decoded,
                Err(error) => {
                    failure = Some(error);
                    return ControlFlow::Break(());
                }
            };
            if !live {
                return ControlFlow::Continue(());
            }
            if live_rank >= range_start {
                entries.push(SortedSetEntry {
                    member: member.to_vec(),
                    score,
                });
            }
            if live_rank == range_stop {
                return ControlFlow::Break(());
            }
            live_rank += 1;
            ControlFlow::Continue(())
        };
        let _visit = match direction {
            SortedSetDirection::Ascending => tree.visit_prefix_range_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                Bound::Unbounded,
                Bound::Unbounded,
                &mut visitor,
            )?,
            SortedSetDirection::Descending => tree.visit_prefix_range_cached_reverse(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                Bound::Unbounded,
                Bound::Unbounded,
                &mut visitor,
            )?,
        };
        if let Some(error) = failure {
            return Err(error);
        }
        if entries.len() != range_stop - range_start + 1 {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(entries)
    }

    /// Reads a bounded ascending score range through the ordered physical
    /// sorted-set index.
    ///
    /// Traversal prunes by the canonical score bytes, counts offset only
    /// across live entries, and stops after `limit` results.
    ///
    /// # Errors
    ///
    /// Returns an error for `NaN` bounds, legacy storage, another structure
    /// family, a missing sorted set, or malformed metadata/index state.
    pub fn zrange_by_score_latest_sorted_set(
        &self,
        key: &[u8],
        lower: Bound<f64>,
        upper: Bound<f64>,
        offset: usize,
        limit: usize,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        Ok(self
            .zrange_by_score_latest_sorted_set_profiled(key, lower, upper, offset, limit)?
            .entries)
    }

    /// Reads an ascending score range and reports its direct or immutable
    /// segment physical path.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Self::zrange_by_score_latest_sorted_set`]
    /// plus resource admission or persistent execution failures.
    pub fn zrange_by_score_latest_sorted_set_profiled(
        &self,
        key: &[u8],
        lower: Bound<f64>,
        upper: Bound<f64>,
        offset: usize,
        limit: usize,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        self.sorted_set_score_range_latest_profiled(
            key,
            lower,
            upper,
            offset,
            limit,
            SortedSetDirection::Ascending,
        )
    }

    /// Reads a bounded descending score range through the ordered physical
    /// sorted-set index.
    ///
    /// Traversal prunes by the canonical score bytes, counts offset only
    /// across live entries in descending order, and stops after `limit`
    /// results.
    ///
    /// # Errors
    ///
    /// Returns an error for `NaN` bounds, legacy storage, another structure
    /// family, a missing sorted set, or malformed metadata/index state.
    pub fn zrevrange_by_score_latest_sorted_set(
        &self,
        key: &[u8],
        lower: Bound<f64>,
        upper: Bound<f64>,
        offset: usize,
        limit: usize,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        Ok(self
            .zrevrange_by_score_latest_sorted_set_profiled(key, lower, upper, offset, limit)?
            .entries)
    }

    /// Reads a descending score range and reports its direct or immutable
    /// segment physical path.
    ///
    /// # Errors
    ///
    /// Returns the same errors as
    /// [`Self::zrevrange_by_score_latest_sorted_set`] plus resource admission
    /// or persistent execution failures.
    pub fn zrevrange_by_score_latest_sorted_set_profiled(
        &self,
        key: &[u8],
        lower: Bound<f64>,
        upper: Bound<f64>,
        offset: usize,
        limit: usize,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        self.sorted_set_score_range_latest_profiled(
            key,
            lower,
            upper,
            offset,
            limit,
            SortedSetDirection::Descending,
        )
    }

    fn sorted_set_score_range_latest_profiled(
        &self,
        key: &[u8],
        lower: Bound<f64>,
        upper: Bound<f64>,
        offset: usize,
        limit: usize,
        direction: SortedSetDirection,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        let (lower, upper) = canonical_sorted_set_score_bounds(lower, upper)?;
        if self.structure_format == StructureFormat::BTreeV3 {
            let snapshot = self.coordinator.snapshot(0)?;
            let root = snapshot
                .roots()
                .root(SLOT_STRUCTURE)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            return self.sorted_set_score_range_profiled_v3(SortedSetScoreRangeRequest {
                snapshot_csn: snapshot.visible_csn,
                tree: BTree::from_root(root),
                key: key.to_vec(),
                bounds: (lower, upper),
                offset,
                limit,
                direction,
                planning_permit,
            });
        }
        if !self.structure_format.uses_legacy_collection_layout() {
            return Err(NativeRuntimeError::LegacyStructureFamilyUnsupported);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        self.sorted_set_score_range_profiled_at(SortedSetScoreRangeRequest {
            snapshot_csn: snapshot.visible_csn,
            tree,
            key: key.to_vec(),
            bounds: (lower, upper),
            offset,
            limit,
            direction,
            planning_permit,
        })
    }

    fn sorted_set_score_range_profiled_v3(
        &self,
        request: SortedSetScoreRangeRequest,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let plan = structure_v3::prepare_sorted_set_order_plan_v3(
            &self.pages,
            &self.blobs,
            &self.buffer_pool,
            request.tree,
            &request.key,
            Some(request.bounds),
        )?;
        let direct_work =
            request.offset.saturating_add(request.limit) <= STRUCTURE_SEGMENT_SCAN_THRESHOLD;
        if direct_work
            || request.limit == 0
            || sorted_set_score_range_is_empty(&request.bounds.0, &request.bounds.1)
        {
            let entries = structure_v3::sorted_set_score_range_latest_v3(
                &self.pages,
                &self.buffer_pool,
                request.tree,
                &request.key,
                &plan,
                structure_v3::SortedSetScoreRangeRequestV3 {
                    offset: request.offset,
                    limit: request.limit,
                    direction: request.direction,
                },
            )?;
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_sorted_set_range_receipt(
                request.snapshot_csn,
                entries,
                execution,
            ));
        }
        self.execute_sorted_set_score_segments_v3(request, &plan)
    }

    fn execute_sorted_set_score_segments_v3(
        &self,
        request: SortedSetScoreRangeRequest,
        order_plan: &structure_v3::SortedSetOrderPlanV3,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let mut plan = self.plan_btree_segments(
            request.tree,
            order_plan.prefix.clone(),
            order_plan.lower.clone(),
            order_plan.upper.clone(),
            NativeRuntimeError::InvalidStructureTree,
        )?;
        if request.direction == SortedSetDirection::Descending {
            plan.segments.reverse();
        }
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        if plan.segments.is_empty() {
            return Ok(NativeSortedSetRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries: Vec::new(),
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            segmented_result_memory_bytes(planned_physical_entries),
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = self.scan_sorted_set_segment_plan_v3(
            &request.key,
            order_plan.incarnation,
            request.direction,
            plan,
            permit.as_ref(),
            planned_workers,
        )?;
        let live_entries = batches
            .into_iter()
            .flat_map(|batch| batch.entries)
            .collect::<Vec<_>>();
        if live_entries.len() > order_plan.member_count
            || (matches!(request.bounds.0, Bound::Unbounded)
                && matches!(request.bounds.1, Bound::Unbounded)
                && live_entries.len() != order_plan.member_count)
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let entries = live_entries
            .into_iter()
            .skip(request.offset)
            .take(request.limit)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSortedSetRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            entries,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn sorted_set_score_range_profiled_at(
        &self,
        request: SortedSetScoreRangeRequest,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let metadata_key = structure_sorted_set_meta_key(&request.key)?;
        let Some(metadata) =
            request
                .tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(request.tree, &request.key);
        };
        decode_sorted_set_metadata(metadata.bytes())?;
        let direct_work =
            request.offset.saturating_add(request.limit) <= STRUCTURE_SEGMENT_SCAN_THRESHOLD;
        if direct_work
            || request.limit == 0
            || sorted_set_score_range_is_empty(&request.bounds.0, &request.bounds.1)
        {
            let entries = self.sorted_set_score_range_in_tree(
                request.tree,
                &request.key,
                request.bounds,
                request.offset,
                request.limit,
                request.direction,
            )?;
            let execution = request.planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(NativeSortedSetRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries,
                planned_segments: 0,
                planned_physical_entries: 0,
                planning: None,
                execution,
                planned_workers: 1,
                worker_batches: 0,
            });
        }
        self.execute_sorted_set_score_segments(request)
    }

    fn execute_sorted_set_score_segments(
        &self,
        request: SortedSetScoreRangeRequest,
    ) -> Result<NativeSortedSetRangeExecutionReceipt, NativeRuntimeError> {
        let range =
            sorted_set_score_physical_bounds(&request.key, request.bounds.0, request.bounds.1)?;
        let mut plan = self.plan_btree_segments(
            request.tree,
            range.prefix,
            range.lower,
            range.upper,
            NativeRuntimeError::InvalidStructureTree,
        )?;
        if request.direction == SortedSetDirection::Descending {
            plan.segments.reverse();
        }
        let planning = request.planning_permit.map(DatabaseGovernorPermit::finish);
        if plan.segments.is_empty() {
            return Ok(NativeSortedSetRangeExecutionReceipt {
                snapshot_csn: request.snapshot_csn,
                entries: Vec::new(),
                planned_segments: 0,
                planned_physical_entries: 0,
                planning,
                execution: None,
                planned_workers: 0,
                worker_batches: 0,
            });
        }
        let planned_segments = plan.segments.len();
        let planned_physical_entries = plan.physical_entries;
        let permit = self.admit_parallel_foreground_bounded_io(
            segmented_result_memory_bytes(planned_physical_entries),
            planned_segments,
        )?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_sorted_set_segment_plan_parallel(
                    &request.key,
                    request.direction,
                    plan,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_sorted_set_segment_plan_serial(&request.key, request.direction, &plan)?,
                0,
            ),
        };
        let entries = batches
            .into_iter()
            .flatten()
            .skip(request.offset)
            .take(request.limit)
            .collect();
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeSortedSetRangeExecutionReceipt {
            snapshot_csn: request.snapshot_csn,
            entries,
            planned_segments,
            planned_physical_entries,
            planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    fn scan_sorted_set_segment_plan_serial(
        &self,
        key: &[u8],
        direction: SortedSetDirection,
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<Vec<SortedSetEntry>>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                decode_sorted_set_segment(
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    direction,
                )
            })
            .collect()
    }

    fn scan_sorted_set_segment_plan_v3(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        direction: SortedSetDirection,
        plan: NativeBTreeSegmentPlan,
        permit: Option<&DatabaseGovernorPermit>,
        planned_workers: u64,
    ) -> Result<(Vec<structure_v3::SortedSetSegmentBatchV3>, usize), NativeRuntimeError> {
        match (self.execution_pool.as_deref(), permit) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_sorted_set_segment_plan_v3_parallel(
                    key,
                    incarnation,
                    direction,
                    plan,
                    execution_pool,
                    permit.permit(),
                ),
            _ => Ok((
                self.scan_sorted_set_segment_plan_v3_serial(key, incarnation, direction, &plan)?,
                0,
            )),
        }
    }

    fn scan_sorted_set_segment_plan_v3_serial(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        direction: SortedSetDirection,
        plan: &NativeBTreeSegmentPlan,
    ) -> Result<Vec<structure_v3::SortedSetSegmentBatchV3>, NativeRuntimeError> {
        plan.segments
            .iter()
            .map(|segment| {
                structure_v3::decode_sorted_set_segment_v3(
                    &self.pages,
                    &self.buffer_pool,
                    plan.tree,
                    plan.tree.scan_planned_segment(&self.pages, segment)?,
                    key,
                    incarnation,
                    direction,
                )
            })
            .collect()
    }

    fn scan_sorted_set_segment_plan_v3_parallel(
        &self,
        key: &[u8],
        incarnation: structure_v3::StructureIncarnation,
        direction: SortedSetDirection,
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<structure_v3::SortedSetSegmentBatchV3>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let pool = Arc::clone(&self.buffer_pool);
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    structure_v3::decode_sorted_set_segment_v3(
                        &pages,
                        &pool,
                        tree,
                        tree.scan_planned_segment(&pages, &segment)?,
                        &key,
                        incarnation,
                        direction,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    fn scan_sorted_set_segment_plan_parallel(
        &self,
        key: &[u8],
        direction: SortedSetDirection,
        plan: NativeBTreeSegmentPlan,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<Vec<SortedSetEntry>>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let key = Arc::new(key.to_vec());
        let tree = plan.tree;
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                plan.segments,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |segment| {
                    decode_sorted_set_segment(
                        tree.scan_planned_segment(&pages, &segment)?,
                        &key,
                        direction,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    fn sorted_set_score_range_in_tree(
        &self,
        tree: BTree,
        key: &[u8],
        bounds: (Bound<SortedSetScore>, Bound<SortedSetScore>),
        offset: usize,
        limit: usize,
        direction: SortedSetDirection,
    ) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
        let (lower, upper) = bounds;
        let metadata_key = structure_sorted_set_meta_key(key)?;
        let Some(metadata) =
            tree.get_cached_pinned(&self.pages, &self.buffer_pool, &metadata_key)?
        else {
            return self.sorted_set_missing_or_kind_error(tree, key);
        };
        decode_sorted_set_metadata(metadata.bytes())?;
        if limit == 0 || sorted_set_score_range_is_empty(&lower, &upper) {
            return Ok(Vec::new());
        }

        let prefix = structure_sorted_set_order_prefix(key)?;
        let lower_key = match lower {
            Bound::Included(score) => Some(structure_sorted_set_score_prefix(key, score)?),
            Bound::Excluded(score) => Some(
                byte_prefix_successor(&structure_sorted_set_score_prefix(key, score)?)
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?,
            ),
            Bound::Unbounded => None,
        };
        let upper_key = match upper {
            Bound::Included(score) => Some(
                byte_prefix_successor(&structure_sorted_set_score_prefix(key, score)?)
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?,
            ),
            Bound::Excluded(score) => Some(structure_sorted_set_score_prefix(key, score)?),
            Bound::Unbounded => None,
        };
        let lower_bound = lower_key
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Included);
        let upper_bound = upper_key
            .as_deref()
            .map_or(Bound::Unbounded, Bound::Excluded);

        let mut skipped = 0_usize;
        let mut entries = Vec::new();
        let mut failure = None;
        let mut visitor = |physical_key: &[u8], value: &[u8]| {
            let (score, member) = match decode_live_sorted_set_order_entry(key, physical_key, value)
            {
                Ok(Some(decoded)) => decoded,
                Ok(None) => return ControlFlow::Continue(()),
                Err(error) => {
                    failure = Some(error);
                    return ControlFlow::Break(());
                }
            };
            if skipped < offset {
                skipped += 1;
                return ControlFlow::Continue(());
            }
            entries.push(SortedSetEntry {
                member: member.to_vec(),
                score,
            });
            if entries.len() == limit {
                ControlFlow::Break(())
            } else {
                ControlFlow::Continue(())
            }
        };
        let _visit = match direction {
            SortedSetDirection::Ascending => tree.visit_prefix_range_cached(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                lower_bound,
                upper_bound,
                &mut visitor,
            )?,
            SortedSetDirection::Descending => tree.visit_prefix_range_cached_reverse(
                &self.pages,
                &self.buffer_pool,
                &prefix,
                lower_bound,
                upper_bound,
                &mut visitor,
            )?,
        };
        if let Some(error) = failure {
            return Err(error);
        }
        Ok(entries)
    }

    fn sorted_set_missing_or_kind_error<T>(
        &self,
        tree: BTree,
        key: &[u8],
    ) -> Result<T, NativeRuntimeError> {
        let scalar = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_key(key))?
            .map(|encoded| decode_structure_value(encoded.bytes(), &self.blobs))
            .transpose()?
            .flatten()
            .is_some();
        let hash = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_hash_meta_key(key),
            )?
            .map(|encoded| decode_live_hash_metadata(encoded.bytes()))
            .transpose()?
            .flatten()
            .is_some();
        let set = tree
            .get_cached_pinned(&self.pages, &self.buffer_pool, &structure_set_meta_key(key))?
            .is_some();
        let list = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &structure_list_meta_key(key)?,
            )?
            .is_some();
        if scalar || hash || set || list {
            Err(NativeRuntimeError::StructureKindMismatch)
        } else {
            Err(NativeRuntimeError::UnknownStructureSortedSet)
        }
    }

    /// Executes BM25 matching through the current physical inverted index.
    ///
    /// Native B+tree directories resolve only the query terms' posting
    /// ranges. Legacy inline directories retain their historical materialized
    /// fallback.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown collection, oversized query term, or
    /// malformed B+tree metadata, posting, document envelope, page, or blob.
    pub fn match_latest_text(
        &self,
        index: ObjectId,
        query: &str,
        limit: usize,
    ) -> Result<Vec<MatchHit>, NativeRuntimeError> {
        Ok(self.match_latest_text_profiled(index, query, limit)?.hits)
    }

    pub(crate) fn match_latest_text_with_csn(
        &self,
        index: ObjectId,
        query: &str,
        limit: usize,
    ) -> Result<(Csn, Vec<MatchHit>), NativeRuntimeError> {
        let receipt = self.match_latest_text_profiled(index, query, limit)?;
        let visible_csn = receipt
            .snapshot_csn
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        Ok((visible_csn, receipt.hits))
    }

    /// Executes current-root BM25 matching and reports the selected direct or
    /// immutable-segment physical path.
    ///
    /// # Errors
    ///
    /// Returns the same validation failures as [`Self::match_latest_text`]
    /// plus resource admission or persistent execution failures.
    pub fn match_latest_text_profiled(
        &self,
        index: ObjectId,
        query: &str,
        limit: usize,
    ) -> Result<NativeLexicalSearchExecutionReceipt, NativeRuntimeError> {
        let planning_permit = self.admit_foreground_bounded()?;
        if self.search_format == SearchFormat::InlineStateV1 {
            let snapshot = self.snapshot_unadmitted(0)?;
            let visible_csn = snapshot
                .visible_csn()
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            let hits = snapshot.match_text(index, query, limit)?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_lexical_receipt(visible_csn, hits, execution));
        }
        let snapshot = self.coordinator.snapshot(0)?;
        self.match_btree_text_profiled(
            &snapshot,
            index,
            query,
            limit,
            model::Bm25ScoreParameters::default(),
            planning_permit,
        )
    }

    // Keep the ordered fail-closed validation, bounded visitor, accounting,
    // and retained-state construction visible as one auditable hydration.
    #[allow(clippy::too_many_lines)]
    pub(crate) fn open_lexical_read_state(
        &self,
        snapshot: &Snapshot,
        request: &NativeLexicalReadViewOpenRequest<'_>,
        retained_permit: &OwnedGovernorPermit,
        planned_terms: usize,
    ) -> Result<NativeLexicalReadState, NativeRuntimeError> {
        let NativeLexicalReadViewOpenRequest {
            index,
            query,
            limit,
            maximum_retained_postings,
            maximum_retained_bytes,
        } = *request;
        if limit == 0
            || maximum_retained_postings == 0
            || maximum_retained_bytes == 0
            || query.len() > MAX_LOCAL_SEARCH_QUERY_BYTES
        {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        if retained_permit.class() != WorkloadClass::ForegroundBounded
            || retained_permit.request().memory_bytes < maximum_retained_bytes
        {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        let snapshot_csn = snapshot
            .visible_csn
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let roots = snapshot.roots();
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        if !matches!(
            self.catalog_object_at_root(catalog_root, index)?,
            Some(CatalogObject::Search(_))
        ) {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        let root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let format = physical_search_format(&self.pages, tree)?;
        let format_identity = match format {
            PhysicalSearchFormat::V1 => b"v1".as_slice(),
            PhysicalSearchFormat::V2 => b"v2".as_slice(),
            PhysicalSearchFormat::V3 => b"v3".as_slice(),
        };
        let mut lexical_identity = blake3::Hasher::new();
        lexical_identity.update(native_hybrid::NATIVE_LEXICAL_INDEX_IDENTITY_ALGORITHM.as_bytes());
        lexical_identity.update(&root.get().to_le_bytes());
        lexical_identity.update(&index.get().to_le_bytes());
        lexical_identity.update(format_identity);
        let lexical_index_identity = *lexical_identity.finalize().as_bytes();
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &search_index_meta_key(index),
            )?
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let (document_count, total_document_terms) =
            decode_search_index_metadata(metadata.bytes())?;
        let index_metadata_key = search_index_meta_key(index);
        let query_tokens: BTreeSet<String> = analyze(query).into_iter().collect();
        let mut terms = Vec::with_capacity(planned_terms);
        let mut retained_postings = 0_usize;
        let mut retained_memory_bytes = 0_u64;
        let mut observed_physical_entries = 1_usize;
        let mut observed_physical_bytes = u64::try_from(index_metadata_key.len())
            .ok()
            .and_then(|bytes| bytes.checked_add(u64::try_from(metadata.bytes().len()).ok()?))
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        for term in query_tokens {
            let term_key = search_term_meta_key(index, term.as_bytes())?;
            let Some(term_metadata) =
                tree.get_cached_pinned(&self.pages, &self.buffer_pool, &term_key)?
            else {
                continue;
            };
            let Some(document_frequency) =
                decode_live_search_term_metadata(term_metadata.bytes(), format)?
            else {
                continue;
            };
            if document_frequency == 0 || document_frequency > document_count {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            observed_physical_entries = observed_physical_entries
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            observed_physical_bytes = observed_physical_bytes
                .checked_add(u64::try_from(term_key.len()).unwrap_or(u64::MAX))
                .and_then(|bytes| {
                    bytes
                        .checked_add(u64::try_from(term_metadata.bytes().len()).unwrap_or(u64::MAX))
                })
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            let required = retained_postings
                .checked_add(
                    usize::try_from(document_frequency)
                        .map_err(|_| NativeRuntimeError::InvalidSearchTree)?,
                )
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            if required > maximum_retained_postings {
                return Err(NativeRuntimeError::Model(format!(
                    "lexical-read-view-retention-postings required={required} maximum={maximum_retained_postings}"
                )));
            }
            let posting_prefix = search_posting_prefix(index, term.as_bytes())?;
            let expected = usize::try_from(document_frequency)
                .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
            let mut retained = Vec::with_capacity(expected);
            let mut visit_error = None;
            let _visit = tree.visit_prefix_cached(
                &self.pages,
                &self.buffer_pool,
                &posting_prefix,
                None,
                |key, encoded_frequency| {
                    if retained.len() >= expected {
                        visit_error = Some(NativeRuntimeError::InvalidSearchTree);
                        return ControlFlow::Break(());
                    }
                    let next = (|| -> Result<NativeLexicalReadPostingBytes, NativeRuntimeError> {
                        let document_id = key
                            .strip_prefix(posting_prefix.as_slice())
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?
                            .to_vec();
                        decode_live_search_posting(encoded_frequency, format)?
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        let document = tree
                            .get_cached_pinned(
                                &self.pages,
                                &self.buffer_pool,
                                &search_document_key(index, &document_id)?,
                            )?
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        if is_search_document_tombstone(document.bytes()) {
                            return Err(NativeRuntimeError::InvalidSearchTree);
                        }
                        let encoded_document_header: [u8; SEARCH_DOCUMENT_HEADER_SIZE] = document
                            .bytes()
                            .get(..SEARCH_DOCUMENT_HEADER_SIZE)
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?
                            .try_into()
                            .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
                        decode_search_document_header(&encoded_document_header)?;
                        let document_key = search_document_key(index, &document_id)?;
                        let posting_physical_bytes = u64::try_from(key.len())
                            .ok()
                            .and_then(|bytes| {
                                bytes.checked_add(u64::try_from(encoded_frequency.len()).ok()?)
                            })
                            .and_then(|bytes| {
                                bytes.checked_add(
                                    u64::try_from(document_key.len()).ok()?,
                                )
                            })
                            .and_then(|bytes| {
                                bytes.checked_add(u64::try_from(document.bytes().len()).ok()?)
                            })
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        observed_physical_entries = observed_physical_entries
                            .checked_add(2)
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        observed_physical_bytes = observed_physical_bytes
                            .checked_add(posting_physical_bytes)
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        let retained_encoded_bytes = u64::try_from(document_id.len())
                            .ok()
                            .and_then(|bytes| {
                                bytes.checked_add(u64::try_from(encoded_frequency.len()).ok()?)
                            })
                            .and_then(|bytes| {
                                bytes.checked_add(
                                    u64::try_from(SEARCH_DOCUMENT_HEADER_SIZE).ok()?,
                                )
                            })
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        retained_memory_bytes = retained_memory_bytes
                            .checked_add(retained_encoded_bytes)
                            .and_then(|bytes| {
                                bytes.checked_add(
                                    u64::try_from(std::mem::size_of::<
                                        NativeLexicalReadPostingBytes,
                                    >())
                                    .unwrap_or(u64::MAX),
                                )
                            })
                            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                        if retained_memory_bytes > maximum_retained_bytes {
                            return Err(NativeRuntimeError::Model(format!(
                                "lexical-read-view-retention-bytes required={retained_memory_bytes} maximum={maximum_retained_bytes}"
                            )));
                        }
                        Ok(NativeLexicalReadPostingBytes {
                            document_id,
                            encoded_frequency: encoded_frequency.to_vec(),
                            encoded_document_header,
                        })
                    })();
                    match next {
                        Ok(posting) => {
                            retained.push(posting);
                            ControlFlow::Continue(())
                        }
                        Err(error) => {
                            visit_error = Some(error);
                            ControlFlow::Break(())
                        }
                    }
                },
            )?;
            if let Some(error) = visit_error {
                return Err(error);
            }
            if u64::try_from(retained.len()).map_err(|_| NativeRuntimeError::InvalidSearchTree)?
                != document_frequency
            {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            retained_postings = required;
            retained_memory_bytes = retained_memory_bytes
                .checked_add(
                    u64::try_from(std::mem::size_of::<NativeLexicalReadTerm>()).unwrap_or(u64::MAX),
                )
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            if retained_memory_bytes > maximum_retained_bytes {
                return Err(NativeRuntimeError::Model(format!(
                    "lexical-read-view-retention-bytes required={retained_memory_bytes} maximum={maximum_retained_bytes}"
                )));
            }
            terms.push(NativeLexicalReadTerm {
                document_frequency,
                postings: retained,
            });
        }
        if terms.len() != planned_terms {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        let retained_memory_bytes = lexical_retained_allocation_bytes(&terms, terms.capacity())?;
        if retained_memory_bytes > maximum_retained_bytes {
            return Err(NativeRuntimeError::Model(format!(
                "lexical-read-view-retention-bytes required={retained_memory_bytes} maximum={maximum_retained_bytes}"
            )));
        }
        Ok(NativeLexicalReadState {
            root_identity: roots.digest(),
            lexical_index_identity,
            snapshot_csn,
            catalog_version: roots.catalog_version(),
            index,
            limit,
            format,
            document_count,
            total_document_terms,
            terms,
            retained_postings,
            observed_physical_entries,
            observed_physical_bytes,
            retained_memory_bytes,
        })
    }

    // The preplan deliberately mirrors every hydration accounting term so a
    // review can compare the conservative bound with the observed receipt.
    #[allow(clippy::too_many_lines)]
    pub(crate) fn plan_lexical_read_state(
        &self,
        snapshot: &Snapshot,
        request: &NativeLexicalReadViewOpenRequest<'_>,
    ) -> Result<NativeLexicalReadPlan, NativeRuntimeError> {
        let NativeLexicalReadViewOpenRequest {
            index,
            query,
            limit,
            maximum_retained_postings,
            maximum_retained_bytes,
        } = *request;
        if limit == 0
            || maximum_retained_postings == 0
            || maximum_retained_bytes == 0
            || query.len() > MAX_LOCAL_SEARCH_QUERY_BYTES
        {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        let roots = snapshot.roots();
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        if !matches!(
            self.catalog_object_at_root(catalog_root, index)?,
            Some(CatalogObject::Search(_))
        ) {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        let root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let format = physical_search_format(&self.pages, tree)?;
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &search_index_meta_key(index),
            )?
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let (document_count, _) = decode_search_index_metadata(metadata.bytes())?;
        let mut planned_physical_entries = 1_usize;
        let index_metadata_key = search_index_meta_key(index);
        let mut planned_physical_bytes = u64::try_from(index_metadata_key.len())
            .ok()
            .and_then(|bytes| bytes.checked_add(u64::try_from(SEARCH_INDEX_META_SIZE).ok()?))
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let mut retained_memory_bytes = 0_u64;
        let mut retained_postings = 0_usize;
        let mut retained_terms = 0_usize;
        let query_tokens = analyze(query).into_iter().collect::<BTreeSet<_>>();
        let query_token_bytes = query_tokens.iter().try_fold(0_u64, |total, term| {
            total.checked_add(u64::try_from(term.len()).unwrap_or(u64::MAX))
        });
        let query_working_bytes = query_token_bytes
            .and_then(|bytes| {
                bytes.checked_add(
                    u64::try_from(query_tokens.len())
                        .unwrap_or(u64::MAX)
                        .checked_mul(256)?,
                )
            })
            .and_then(|bytes| bytes.checked_add(4_096))
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        for term in query_tokens {
            let term_key = search_term_meta_key(index, term.as_bytes())?;
            let Some(term_metadata) =
                tree.get_cached_pinned(&self.pages, &self.buffer_pool, &term_key)?
            else {
                continue;
            };
            let Some(document_frequency) =
                decode_live_search_term_metadata(term_metadata.bytes(), format)?
            else {
                continue;
            };
            if document_frequency == 0 || document_frequency > document_count {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            let count = usize::try_from(document_frequency)
                .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
            retained_postings = retained_postings
                .checked_add(count)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            if retained_postings > maximum_retained_postings {
                return Err(NativeRuntimeError::Model(format!(
                    "lexical-read-view-retention-postings required={retained_postings} maximum={maximum_retained_postings}"
                )));
            }
            retained_terms = retained_terms
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            planned_physical_entries = planned_physical_entries
                .checked_add(1)
                .and_then(|entries| entries.checked_add(count.checked_mul(2)?))
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            let per_posting_physical = BTREE_MAX_KEY_SIZE
                .checked_add(SEARCH_POSTING_SIZE)
                .and_then(|bytes| bytes.checked_add(BTREE_MAX_KEY_SIZE))
                .and_then(|bytes| {
                    bytes.checked_add(SEARCH_DOCUMENT_HEADER_SIZE + SEARCH_INLINE_VALUE_LIMIT)
                })
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            planned_physical_bytes = planned_physical_bytes
                .checked_add(u64::try_from(term_key.len()).unwrap_or(u64::MAX))
                .and_then(|bytes| {
                    bytes.checked_add(u64::try_from(SEARCH_TERM_META_SIZE).unwrap_or(u64::MAX))
                })
                .and_then(|bytes| {
                    bytes.checked_add(
                        u64::try_from(count)
                            .unwrap_or(u64::MAX)
                            .checked_mul(u64::try_from(per_posting_physical).unwrap_or(u64::MAX))?,
                    )
                })
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            let per_posting_memory = per_posting_physical
                .checked_add(std::mem::size_of::<NativeLexicalReadPostingBytes>())
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            retained_memory_bytes = retained_memory_bytes
                .checked_add(
                    u64::try_from(count)
                        .unwrap_or(u64::MAX)
                        .checked_mul(u64::try_from(per_posting_memory).unwrap_or(u64::MAX))
                        .ok_or(NativeRuntimeError::InvalidSearchTree)?,
                )
                .and_then(|bytes| {
                    bytes.checked_add(
                        u64::try_from(std::mem::size_of::<NativeLexicalReadTerm>())
                            .unwrap_or(u64::MAX),
                    )
                })
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        }
        let retained_memory_bytes = retained_memory_bytes.max(1);
        if retained_memory_bytes > maximum_retained_bytes {
            return Err(NativeRuntimeError::Model(format!(
                "lexical-read-view-retention-bytes required={retained_memory_bytes} maximum={maximum_retained_bytes}"
            )));
        }
        Ok(NativeLexicalReadPlan {
            physical_entries: planned_physical_entries,
            physical_bytes: planned_physical_bytes,
            retained_terms,
            retained_memory_bytes,
            hydration_memory_bytes: retained_memory_bytes
                .checked_add(query_working_bytes)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?,
        })
    }

    pub(crate) fn plan_structure_filter_state(
        lexical: &NativeLexicalReadState,
        request: &NativeStructureScalarFilter<'_>,
    ) -> Result<NativeStructureFilterPlan, NativeRuntimeError> {
        if request.key_prefix.is_empty()
            || request.expected_inline_value.len() > STRUCTURE_INLINE_VALUE_LIMIT
            || lexical
                .terms
                .iter()
                .flat_map(|term| &term.postings)
                .any(|posting| {
                    request
                        .key_prefix
                        .len()
                        .checked_add(posting.document_id.len())
                        .and_then(|bytes| bytes.checked_add(1))
                        .is_none_or(|bytes| bytes > BTREE_MAX_KEY_SIZE)
                })
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let maximum_records = lexical.retained_postings;
        let per_record_physical = BTREE_MAX_KEY_SIZE
            .checked_add(STRUCTURE_VALUE_HEADER_SIZE + STRUCTURE_INLINE_VALUE_LIMIT)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let per_record_memory = per_record_physical
            .checked_add(std::mem::size_of::<NativeStructureFilterRecord>())
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let physical_bytes = u64::try_from(maximum_records)
            .unwrap_or(u64::MAX)
            .checked_mul(u64::try_from(per_record_physical).unwrap_or(u64::MAX))
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let retained_memory_bytes = u64::try_from(maximum_records)
            .unwrap_or(u64::MAX)
            .checked_mul(u64::try_from(per_record_memory).unwrap_or(u64::MAX))
            .and_then(|bytes| {
                bytes.checked_add(
                    u64::try_from(request.expected_inline_value.len()).unwrap_or(u64::MAX),
                )
            })
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
            .max(1);
        Ok(NativeStructureFilterPlan {
            maximum_records,
            physical_entries: maximum_records,
            physical_bytes,
            retained_memory_bytes,
            hydration_memory_bytes: retained_memory_bytes
                .checked_add(64 * 1_024)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?,
        })
    }

    #[allow(clippy::too_many_lines)]
    pub(crate) fn open_structure_filter_state(
        &self,
        snapshot: &Snapshot,
        lexical: &NativeLexicalReadState,
        request: &NativeStructureScalarFilter<'_>,
        retained_permit: &OwnedGovernorPermit,
        plan: NativeStructureFilterPlan,
    ) -> Result<NativeStructureFilterState, NativeRuntimeError> {
        if retained_permit.class() != WorkloadClass::ForegroundBounded
            || retained_permit.request().memory_bytes < plan.retained_memory_bytes
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let roots = snapshot.roots();
        if roots.digest() != lexical.root_identity
            || snapshot.visible_csn != Some(lexical.snapshot_csn)
            || roots.catalog_version() != lexical.catalog_version
        {
            return Err(NativeRuntimeError::InvalidCommittedRoot);
        }
        let structure_root = roots
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(structure_root);
        let mut identities = BTreeSet::new();
        for term in &lexical.terms {
            for posting in &term.postings {
                identities.insert(posting.document_id.clone());
            }
        }
        if identities.len() > plan.maximum_records {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let mut records = Vec::with_capacity(identities.len());
        let mut observed_physical_bytes = 0_u64;
        let mut observed_physical_entries = 0_usize;
        for document_id in identities {
            let mut logical_key = Vec::with_capacity(
                request
                    .key_prefix
                    .len()
                    .checked_add(document_id.len())
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?,
            );
            logical_key.extend_from_slice(request.key_prefix);
            logical_key.extend_from_slice(&document_id);
            let encoded_key = structure_key(&logical_key);
            if encoded_key.len() > BTREE_MAX_KEY_SIZE {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            let encoded = tree
                .get_cached_pinned(&self.pages, &self.buffer_pool, &encoded_key)?
                .map(|value| value.bytes().to_vec());
            validate_retained_structure_filter_record(encoded.as_deref())?;
            if let Some(encoded) = &encoded {
                observed_physical_entries = observed_physical_entries
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                observed_physical_bytes = observed_physical_bytes
                    .checked_add(u64::try_from(encoded_key.len()).unwrap_or(u64::MAX))
                    .and_then(|bytes| {
                        bytes.checked_add(u64::try_from(encoded.len()).unwrap_or(u64::MAX))
                    })
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            }
            records.push(NativeStructureFilterRecord {
                document_id,
                encoded,
            });
        }
        let mut retained_memory_bytes = u64::try_from(records.capacity())
            .unwrap_or(u64::MAX)
            .checked_mul(
                u64::try_from(std::mem::size_of::<NativeStructureFilterRecord>())
                    .unwrap_or(u64::MAX),
            )
            .and_then(|bytes| {
                bytes.checked_add(
                    u64::try_from(request.expected_inline_value.len()).unwrap_or(u64::MAX),
                )
            })
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        for record in &records {
            retained_memory_bytes = retained_memory_bytes
                .checked_add(u64::try_from(record.document_id.capacity()).unwrap_or(u64::MAX))
                .and_then(|bytes| {
                    bytes.checked_add(record.encoded.as_ref().map_or(0, |encoded| {
                        u64::try_from(encoded.capacity()).unwrap_or(u64::MAX)
                    }))
                })
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        }
        let mut retained_memory_bytes = retained_memory_bytes.max(1);
        let expected_inline_value = request.expected_inline_value.to_vec();
        retained_memory_bytes = retained_memory_bytes
            .checked_sub(u64::try_from(request.expected_inline_value.len()).unwrap_or(u64::MAX))
            .and_then(|bytes| {
                bytes.checked_add(
                    u64::try_from(expected_inline_value.capacity()).unwrap_or(u64::MAX),
                )
            })
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if records.len() > plan.physical_entries
            || observed_physical_bytes > plan.physical_bytes
            || retained_memory_bytes > plan.retained_memory_bytes
        {
            return Err(NativeRuntimeError::Model(
                "structure-filter-read-view-plan-underflow".to_owned(),
            ));
        }
        let mut identity = blake3::Hasher::new();
        identity.update(native_hybrid::NATIVE_STRUCTURE_FILTER_IDENTITY_ALGORITHM.as_bytes());
        identity.update(&structure_root.get().to_le_bytes());
        identity.update(request.key_prefix);
        identity.update(request.expected_inline_value);
        identity.update(&request.logical_time_micros.to_le_bytes());
        Ok(NativeStructureFilterState {
            structure_identity: *identity.finalize().as_bytes(),
            expected_inline_value,
            logical_time_micros: request.logical_time_micros,
            records,
            observed_physical_entries,
            observed_physical_bytes,
            retained_memory_bytes,
        })
    }

    /// Scores one analyzed free-text query from the durable BM25 postings at
    /// the supplied retained snapshot's roots, bit-identical to the model.
    ///
    /// # Errors
    ///
    /// Fails closed when the snapshot carries no visible commit, its page
    /// generation was reclaimed by vacuum, the index is not a catalogued
    /// search object at that root, or the physical tree is invalid. The
    /// inline state format is answered by the retained model instead.
    pub fn match_text_at_snapshot(
        &self,
        snapshot: &NativeSnapshot,
        index: ObjectId,
        query: &str,
        limit: usize,
        parameters: model::Bm25ScoreParameters,
    ) -> Result<Vec<MatchHit>, NativeRuntimeError> {
        if self.search_format == SearchFormat::InlineStateV1 {
            return snapshot.match_text_with_parameters(index, query, limit, parameters);
        }
        let planning_permit = self.admit_foreground_bounded()?;
        let current = self.coordinator.snapshot(0)?;
        if snapshot.metadata.roots().page_generation() != current.roots().page_generation() {
            return Err(NativeRuntimeError::InvalidCommittedRoot);
        }
        let catalog_root = snapshot
            .metadata
            .roots()
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        match self.catalog_object_at_root(catalog_root, index)? {
            Some(CatalogObject::Search(_)) => {}
            _ => return Err(ModelError::UnknownObject.into()),
        }
        let receipt = self.match_btree_text_profiled(
            &snapshot.metadata,
            index,
            query,
            limit,
            parameters,
            planning_permit,
        )?;
        Ok(receipt.hits)
    }

    fn match_btree_text_profiled(
        &self,
        snapshot: &hyphae_native_mvcc::Snapshot,
        index: ObjectId,
        query: &str,
        limit: usize,
        parameters: model::Bm25ScoreParameters,
        planning_permit: Option<DatabaseGovernorPermit>,
    ) -> Result<NativeLexicalSearchExecutionReceipt, NativeRuntimeError> {
        let visible_csn = snapshot
            .visible_csn
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let root = snapshot
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let tree = BTree::from_root(root);
        let format = physical_search_format(&self.pages, tree)?;
        let metadata = tree
            .get_cached_pinned(
                &self.pages,
                &self.buffer_pool,
                &search_index_meta_key(index),
            )?
            .ok_or(ModelError::UnknownObject)?;
        let (document_count, total_document_terms) =
            decode_search_index_metadata(metadata.bytes())?;
        let query_tokens: BTreeSet<String> = analyze(query).into_iter().collect();
        if query_tokens.is_empty() || limit == 0 || document_count == 0 {
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_lexical_receipt(visible_csn, Vec::new(), execution));
        }
        let document_count_f64 = search_count_f64(document_count)?;
        let average_length = search_count_f64(total_document_terms)? / document_count_f64;
        if document_count <= SEARCH_SEGMENT_SCAN_THRESHOLD {
            let hits = self.match_text_in_tree_direct(
                tree,
                format,
                index,
                query_tokens,
                document_count,
                document_count_f64,
                average_length,
                parameters,
                limit,
            )?;
            let execution = planning_permit.map(DatabaseGovernorPermit::finish);
            return Ok(direct_lexical_receipt(visible_csn, hits, execution));
        }
        let term_plans = self.plan_lexical_term_segments(
            tree,
            format,
            index,
            query_tokens,
            document_count,
            document_count_f64,
        )?;
        let planned_terms = term_plans.len();
        let planned_segments = term_plans.iter().try_fold(0_usize, |total, plan| {
            total
                .checked_add(plan.segments.len())
                .ok_or(NativeRuntimeError::InvalidSearchTree)
        })?;
        let planned_physical_entries = term_plans.iter().try_fold(0_usize, |total, plan| {
            total
                .checked_add(plan.physical_entries)
                .ok_or(NativeRuntimeError::InvalidSearchTree)
        })?;
        let expected_document_frequencies = term_plans
            .iter()
            .map(|plan| plan.document_frequency)
            .collect::<Vec<_>>();
        let work = lexical_segment_work(term_plans);
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        self.execute_lexical_plan(
            LexicalExecutionPlan {
                parameters,
                snapshot_csn: visible_csn,
                tree,
                format,
                index,
                average_length,
                planned_terms,
                planned_segments,
                planned_physical_entries,
                expected_document_frequencies,
                work,
                planning,
            },
            limit,
        )
    }

    fn execute_lexical_plan(
        &self,
        plan: LexicalExecutionPlan,
        limit: usize,
    ) -> Result<NativeLexicalSearchExecutionReceipt, NativeRuntimeError> {
        if plan.work.is_empty() {
            return Ok(empty_segmented_lexical_receipt(&plan));
        }
        let planned_memory_bytes = segmented_result_memory_bytes(plan.planned_physical_entries);
        let permit =
            self.admit_parallel_foreground_bounded_io(planned_memory_bytes, plan.work.len())?;
        let planned_workers = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let (batches, worker_batches) = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit)) if planned_workers > 1 => self
                .scan_lexical_segments_parallel(
                    plan.tree,
                    plan.format,
                    plan.index,
                    plan.average_length,
                    plan.parameters,
                    plan.work,
                    execution_pool,
                    permit.permit(),
                )?,
            _ => (
                self.scan_lexical_segments_serial(
                    plan.tree,
                    plan.format,
                    plan.index,
                    plan.average_length,
                    plan.parameters,
                    &plan.work,
                )?,
                0,
            ),
        };
        let hits = finalize_lexical_batches(batches, &plan.expected_document_frequencies, limit)?;
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeLexicalSearchExecutionReceipt {
            snapshot_csn: Some(plan.snapshot_csn),
            hits,
            planned_terms: plan.planned_terms,
            planned_segments: plan.planned_segments,
            planned_physical_entries: plan.planned_physical_entries,
            planning: plan.planning,
            execution,
            planned_workers,
            worker_batches,
        })
    }

    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::too_many_arguments)]
    fn match_text_in_tree_direct(
        &self,
        tree: BTree,
        format: PhysicalSearchFormat,
        index: ObjectId,
        query_tokens: BTreeSet<String>,
        document_count: u64,
        document_count_f64: f64,
        average_length: f64,
        parameters: model::Bm25ScoreParameters,
        limit: usize,
    ) -> Result<Vec<MatchHit>, NativeRuntimeError> {
        let mut scores = BTreeMap::<Vec<u8>, f64>::new();
        let mut document_lengths = BTreeMap::<Vec<u8>, u64>::new();
        for term in query_tokens {
            let term_key = search_term_meta_key(index, term.as_bytes())?;
            let Some(term_metadata) =
                tree.get_cached_pinned(&self.pages, &self.buffer_pool, &term_key)?
            else {
                continue;
            };
            let Some(document_frequency) =
                decode_live_search_term_metadata(term_metadata.bytes(), format)?
            else {
                continue;
            };
            if document_frequency == 0 || document_frequency > document_count {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            let idf = bm25_idf(document_count_f64, search_count_f64(document_frequency)?);
            let posting_prefix = search_posting_prefix(index, term.as_bytes())?;
            let postings =
                tree.scan_prefix_cached(&self.pages, &self.buffer_pool, &posting_prefix)?;
            let mut live_postings = 0_u64;
            for (key, encoded_frequency) in postings {
                let document_id = key
                    .strip_prefix(posting_prefix.as_slice())
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?
                    .to_vec();
                let Some(term_frequency) = decode_live_search_posting(&encoded_frequency, format)?
                else {
                    continue;
                };
                live_postings = live_postings
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                let document_length = if let Some(length) = document_lengths.get(&document_id) {
                    *length
                } else {
                    let document = tree
                        .get_cached_pinned(
                            &self.pages,
                            &self.buffer_pool,
                            &search_document_key(index, &document_id)?,
                        )?
                        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                    if is_search_document_tombstone(document.bytes()) {
                        return Err(NativeRuntimeError::InvalidSearchTree);
                    }
                    let (length, _, _) = decode_search_document_header(document.bytes())?;
                    document_lengths.insert(document_id.clone(), length);
                    length
                };
                *scores.entry(document_id).or_default() += bm25_term_score(
                    idf,
                    f64::from(term_frequency),
                    search_count_f64(document_length)?,
                    average_length,
                    parameters,
                );
            }
            if live_postings != document_frequency {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
        }
        Ok(rank_match_hits(scores, limit))
    }

    fn plan_lexical_term_segments(
        &self,
        tree: BTree,
        format: PhysicalSearchFormat,
        index: ObjectId,
        query_tokens: BTreeSet<String>,
        document_count: u64,
        document_count_f64: f64,
    ) -> Result<Vec<LexicalTermSegmentPlan>, NativeRuntimeError> {
        let mut plans = Vec::with_capacity(query_tokens.len());
        for term in query_tokens {
            let term_key = search_term_meta_key(index, term.as_bytes())?;
            let Some(term_metadata) =
                tree.get_cached_pinned(&self.pages, &self.buffer_pool, &term_key)?
            else {
                continue;
            };
            let Some(document_frequency) =
                decode_live_search_term_metadata(term_metadata.bytes(), format)?
            else {
                continue;
            };
            if document_frequency == 0 || document_frequency > document_count {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            let posting_prefix = search_posting_prefix(index, term.as_bytes())?;
            let segment_plan = self.plan_btree_segments(
                tree,
                posting_prefix.clone(),
                Bound::Unbounded,
                Bound::Unbounded,
                NativeRuntimeError::InvalidSearchTree,
            )?;
            if segment_plan.segments.is_empty() {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            plans.push(LexicalTermSegmentPlan {
                posting_prefix,
                document_frequency,
                idf: bm25_idf(document_count_f64, search_count_f64(document_frequency)?),
                segments: segment_plan.segments,
                physical_entries: segment_plan.physical_entries,
            });
        }
        Ok(plans)
    }

    fn scan_lexical_segments_serial(
        &self,
        tree: BTree,
        format: PhysicalSearchFormat,
        index: ObjectId,
        average_length: f64,
        parameters: model::Bm25ScoreParameters,
        work: &[LexicalSegmentWork],
    ) -> Result<Vec<LexicalPostingBatch>, NativeRuntimeError> {
        work.iter()
            .map(|work| {
                decode_lexical_segment(
                    tree,
                    &self.pages,
                    &self.buffer_pool,
                    format,
                    index,
                    average_length,
                    parameters,
                    work,
                )
            })
            .collect()
    }

    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::too_many_arguments)]
    fn scan_lexical_segments_parallel(
        &self,
        tree: BTree,
        format: PhysicalSearchFormat,
        index: ObjectId,
        average_length: f64,
        parameters: model::Bm25ScoreParameters,
        work: Vec<LexicalSegmentWork>,
        execution_pool: &NativeExecutionPool,
        permit: &OwnedGovernorPermit,
    ) -> Result<(Vec<LexicalPostingBatch>, usize), NativeRuntimeError> {
        let pages = Arc::new(self.pages.read_handle()?);
        let pool = Arc::clone(&self.buffer_pool);
        let (batches, worker_batches) = execution_pool
            .execute_ordered_profiled_with_child_request(
                permit,
                work,
                GovernorRequest {
                    compute_threads: 1,
                    io_slots: 1,
                    memory_bytes: 0,
                },
                move |work| {
                    decode_lexical_segment(
                        tree,
                        &pages,
                        &pool,
                        format,
                        index,
                        average_length,
                        parameters,
                        &work,
                    )
                },
            )?;
        Ok((
            batches
                .into_iter()
                .collect::<Result<Vec<_>, NativeRuntimeError>>()?,
            worker_batches,
        ))
    }

    /// Executes approximate vector search against the current committed
    /// all-engine root set.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown ANN index, invalid query, malformed
    /// catalog/root state, or query breadth outside the catalog definition.
    pub fn search_ann_latest(
        &self,
        index: ObjectId,
        query: &Vector,
        options: AnnSearchOptions,
    ) -> Result<AnnSearchReceipt, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        let state = load_state(&self.pages, &self.blobs, snapshot.roots())?;
        let result = state.ann.search(index, query, options)?;
        Ok(ann_search_receipt(index, snapshot.visible_csn, result))
    }

    /// Hydrates one exact current-root ANN index into an owned reusable view.
    ///
    /// # Errors
    ///
    /// Returns an error without a partial view when execution authority is
    /// absent, admission is rejected, cancellation is observed, or the target
    /// catalog/search authority is invalid.
    pub fn open_ann_read_view(
        &self,
        index: ObjectId,
    ) -> Result<(NativeAnnReadView, NativeAnnReadViewOpenReceipt), NativeRuntimeError> {
        self.open_ann_read_view_with_optional_cancellation(index, None)
    }

    /// Hydrates one exact current-root ANN index with cooperative cancellation.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::open_ann_read_view`] and a
    /// cancelled queue error when cancellation is observed.
    pub fn open_ann_read_view_with_cancellation(
        &self,
        index: ObjectId,
        cancellation: &GovernorCancellation,
    ) -> Result<(NativeAnnReadView, NativeAnnReadViewOpenReceipt), NativeRuntimeError> {
        self.open_ann_read_view_with_optional_cancellation(index, Some(cancellation))
    }

    fn open_ann_read_view_with_optional_cancellation(
        &self,
        index: ObjectId,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<(NativeAnnReadView, NativeAnnReadViewOpenReceipt), NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        self.open_ann_read_view_at_snapshot(index, &snapshot, cancellation)
    }

    fn open_ann_read_view_at_snapshot(
        &self,
        index: ObjectId,
        snapshot: &Snapshot,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<(NativeAnnReadView, NativeAnnReadViewOpenReceipt), NativeRuntimeError> {
        let (governor, execution_pool) = self
            .resource_governor
            .as_ref()
            .zip(self.execution_pool.as_ref())
            .ok_or(NativeRuntimeError::AnnReadViewExecutionAuthorityRequired)?;
        if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
            return Err(GovernorQueueError::Cancelled.into());
        }
        let planning = self
            .admit_foreground_bounded_with_cancellation(cancellation)?
            .ok_or(NativeRuntimeError::AnnReadViewExecutionAuthorityRequired)?;
        let roots = snapshot.roots();
        let catalog_root = roots
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::UnknownVectorIndex { index })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, index)?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex { index });
        };
        let definition = ann_store::definition_from_search(&search_definition)?;
        let search_root = roots
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidAnnTree)?;
        let load_plan = ann_store::plan_index_load_with_cancellation(
            &self.pages,
            &self.buffer_pool,
            search_root,
            index,
            definition,
            cancellation,
        )?;
        let _planning_evidence = planning.finish();
        let retained_memory_bytes = load_plan.hydration_memory_bytes().max(1);
        let planned_peak_memory_bytes =
            FOREGROUND_BOUNDED_MEMORY_BYTES.saturating_add(load_plan.hydration_memory_bytes());
        let hydration = self
            .admit_parallel_foreground_bounded_with_cancellation(
                planned_peak_memory_bytes,
                cancellation,
            )?
            .ok_or(NativeRuntimeError::AnnReadViewExecutionAuthorityRequired)?;
        let reads_before = self.pages.physical_read_count();
        let restores_before = ann_store::process_index_scoped_restore_count();
        let (state, observation) = ann_store::hydrate_owned_read_state(
            &self.pages,
            &self.buffer_pool,
            &load_plan,
            cancellation,
        )?;
        let reads_after = self.pages.physical_read_count();
        let restores_after = ann_store::process_index_scoped_restore_count();
        let hydration_evidence = hydration.evidence();
        let memory_permit = hydration.retain_memory(retained_memory_bytes)?.into_owned();
        let authority = state.authority();
        let policy_identity = governor_policy_identity(governor.policy())?;
        let receipt = self.ann_read_view_open_receipt(&NativeAnnReadViewOpenContext {
            index,
            snapshot_csn: snapshot.visible_csn,
            roots,
            catalog_root,
            search_root,
            load_plan: &load_plan,
            authority,
            observation,
            planned_peak_memory_bytes,
            retained_memory_bytes,
            process_physical_page_read_delta: reads_after.saturating_sub(reads_before),
            hydration_restore_count: restores_after.saturating_sub(restores_before),
            policy_identity,
            hydration: hydration_evidence,
        });
        self.ann_read_views.fetch_add(1, Ordering::AcqRel);
        let view = NativeAnnReadView {
            inner: Arc::new(NativeAnnReadViewInner {
                index,
                snapshot_csn: snapshot.visible_csn,
                root_identity: roots.digest(),
                dimension: authority.dimension,
                state,
                governor: Arc::clone(governor),
                execution_pool: Arc::clone(execution_pool),
                resource_queue_wait: self.resource_queue_wait,
                governor_policy_identity: policy_identity,
                governor_generation: self.governor_generation,
                _memory_permit: memory_permit,
                live_views: Arc::clone(&self.ann_read_views),
                database_live: Arc::clone(&self.database_live),
                open_receipt: receipt.clone(),
            }),
        };
        Ok((view, receipt))
    }

    /// Routes an approximate vector query against the current root to an
    /// explicit durable partition bound.
    ///
    /// # Errors
    ///
    /// Returns an error for a zero partition bound, unknown ANN index, invalid
    /// query, malformed state, or query breadth outside the catalog
    /// definition.
    pub fn search_ann_selected_latest(
        &self,
        index: ObjectId,
        query: &Vector,
        options: AnnSearchOptions,
        maximum_partitions: usize,
    ) -> Result<AnnSelectedSearchReceipt, NativeRuntimeError> {
        self.search_ann_selected_latest_inner(index, query, options, maximum_partitions, None)
    }

    /// Routes one current-root ANN query with cooperative admission and
    /// partition-wave cancellation.
    ///
    /// # Errors
    ///
    /// Returns the same validation failures as [`Self::search_ann_selected_latest`]
    /// and `GovernorQueueError::Cancelled` when cancellation is observed
    /// during physical hydration, restore validation, or child execution.
    pub fn search_ann_selected_latest_with_cancellation(
        &self,
        index: ObjectId,
        query: &Vector,
        options: AnnSearchOptions,
        maximum_partitions: usize,
        cancellation: &GovernorCancellation,
    ) -> Result<AnnSelectedSearchReceipt, NativeRuntimeError> {
        self.search_ann_selected_latest_inner(
            index,
            query,
            options,
            maximum_partitions,
            Some(cancellation),
        )
    }

    fn search_ann_selected_latest_inner(
        &self,
        index: ObjectId,
        query: &Vector,
        options: AnnSearchOptions,
        maximum_partitions: usize,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<AnnSelectedSearchReceipt, NativeRuntimeError> {
        validate_ann_partition_bound(maximum_partitions)?;
        if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
            return Err(GovernorQueueError::Cancelled.into());
        }
        let planning_permit = self.admit_foreground_bounded_with_cancellation(cancellation)?;
        let snapshot = self.coordinator.snapshot(0)?;
        let catalog_root = snapshot
            .roots()
            .root(SLOT_CATALOG)
            .ok_or(NativeRuntimeError::UnknownVectorIndex { index })?;
        let Some(CatalogObject::Search(search_definition)) =
            self.catalog_object_at_root(catalog_root, index)?
        else {
            return Err(NativeRuntimeError::UnknownVectorIndex { index });
        };
        let definition = ann_store::definition_from_search(&search_definition)?;
        let search_root = snapshot
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidAnnTree)?;
        let plan = ann_store::plan_index_load(
            &self.pages,
            &self.buffer_pool,
            search_root,
            index,
            definition,
        )?;
        drop(planning_permit);
        let planned_memory_bytes =
            FOREGROUND_BOUNDED_MEMORY_BYTES.saturating_add(plan.hydration_memory_bytes());
        let execution_permit = self.admit_parallel_foreground_bounded_with_cancellation(
            planned_memory_bytes,
            cancellation,
        )?;
        let execution = if let (Some(execution_pool), Some(execution_permit)) =
            (self.execution_pool.as_deref(), execution_permit.as_ref())
        {
            ann_store::search_selected_planned_parallel(
                &self.pages,
                &self.buffer_pool,
                &plan,
                query,
                options,
                maximum_partitions,
                ann_store::AnnParallelSearchExecution {
                    pool: execution_pool,
                    permit: execution_permit.permit(),
                    cancellation,
                },
            )?
        } else {
            if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
                return Err(GovernorQueueError::Cancelled.into());
            }
            ann_store::search_selected_planned_with_cancellation(
                &self.pages,
                &self.buffer_pool,
                &plan,
                query,
                options,
                maximum_partitions,
                cancellation,
            )?
        };
        Ok(ann_selected_search_receipt(
            index,
            snapshot.visible_csn,
            maximum_partitions,
            execution,
        ))
    }

    /// Executes filter-aware ANN traversal or adaptive exact filtering
    /// against the current committed root set.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown index, invalid query, malformed state,
    /// or invalid query breadth.
    pub fn search_ann_filtered_latest(
        &self,
        index: ObjectId,
        query: &Vector,
        options: AnnSearchOptions,
        allowlist: &BTreeSet<ObjectId>,
    ) -> Result<AnnSearchReceipt, NativeRuntimeError> {
        let _permit = self.admit_foreground_bounded()?;
        let snapshot = self.coordinator.snapshot(0)?;
        let state = load_state(&self.pages, &self.blobs, snapshot.roots())?;
        let result = state
            .ann
            .search_filtered(index, query, options, allowlist)?;
        Ok(ann_search_receipt(index, snapshot.visible_csn, result))
    }

    /// Executes the complete exact vector-ranking oracle against the current
    /// committed all-engine root set.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown ANN index, invalid query, or malformed
    /// catalog/root state.
    pub fn search_vector_exact_latest(
        &self,
        index: ObjectId,
        query: &Vector,
        k: usize,
    ) -> Result<Vec<VectorHit>, NativeRuntimeError> {
        Ok(self
            .search_vector_exact_latest_profiled(index, query, k)?
            .hits)
    }

    /// Executes the exact vector oracle and returns explicit governor and
    /// persistent-worker evidence for the completed query.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown ANN index, invalid query, malformed
    /// catalog/root state, or rejected resource admission.
    pub fn search_vector_exact_latest_profiled(
        &self,
        index: ObjectId,
        query: &Vector,
        k: usize,
    ) -> Result<NativeExactAnnExecutionReceipt, NativeRuntimeError> {
        self.search_vector_exact_profiled(index, query, k, None)
    }

    /// Executes the complete exact vector oracle over a stable-ID allowlist
    /// against the current committed root set.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown index, invalid query, or malformed
    /// catalog/root state.
    pub fn search_vector_exact_filtered_latest(
        &self,
        index: ObjectId,
        query: &Vector,
        k: usize,
        allowlist: &BTreeSet<ObjectId>,
    ) -> Result<Vec<VectorHit>, NativeRuntimeError> {
        Ok(self
            .search_vector_exact_filtered_latest_profiled(index, query, k, allowlist)?
            .hits)
    }

    /// Executes the allowlist-filtered exact vector oracle and returns
    /// explicit governor and persistent-worker evidence.
    ///
    /// # Errors
    ///
    /// Returns an error for an unknown ANN index, invalid query, malformed
    /// catalog/root state, or rejected resource admission.
    pub fn search_vector_exact_filtered_latest_profiled(
        &self,
        index: ObjectId,
        query: &Vector,
        k: usize,
        allowlist: &BTreeSet<ObjectId>,
    ) -> Result<NativeExactAnnExecutionReceipt, NativeRuntimeError> {
        self.search_vector_exact_profiled(index, query, k, Some(allowlist))
    }

    /// Captures an empty native vector index and builds its complete initial
    /// generation without holding writer admission.
    ///
    /// # Errors
    ///
    /// Returns an error unless the index has an empty base, no deltas, and no
    /// retained generation. Invalid vectors, rejected bulk admission, worker
    /// failure, or noncanonical child output also fail before publication.
    pub fn plan_initial_ann_bulk(
        &self,
        index: ObjectId,
        vectors: Vec<(ObjectId, Vector)>,
        requested_partitions: usize,
    ) -> Result<InitialAnnBulkPlan, NativeRuntimeError> {
        self.plan_initial_ann_bulk_with_control(index, vectors, requested_partitions, None, None)
    }

    /// Builds one publication-ready initial ANN generation and reports
    /// planning plus per-child completion without holding writer admission.
    ///
    /// The callback may run on persistent execution-pool workers and must not
    /// perform unbounded or fallible work.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::plan_initial_ann_bulk`].
    pub fn plan_initial_ann_bulk_with_progress(
        &self,
        index: ObjectId,
        vectors: Vec<(ObjectId, Vector)>,
        requested_partitions: usize,
        progress: impl Fn(InitialAnnBulkProgress) + Send + Sync + 'static,
    ) -> Result<InitialAnnBulkPlan, NativeRuntimeError> {
        self.plan_initial_ann_bulk_with_control(
            index,
            vectors,
            requested_partitions,
            None,
            Some(Arc::new(progress)),
        )
    }

    /// Builds one publication-ready initial ANN generation with cooperative
    /// cancellation while no writer admission is held.
    ///
    /// # Errors
    ///
    /// Returns the same failures as [`Self::plan_initial_ann_bulk`], plus
    /// [`hyphae_native_ann::AnnError::BuildCancelled`] when cancellation is
    /// observed before the complete candidate is validated.
    pub fn plan_initial_ann_bulk_with_cancellation(
        &self,
        index: ObjectId,
        vectors: Vec<(ObjectId, Vector)>,
        requested_partitions: usize,
        cancellation: &GovernorCancellation,
    ) -> Result<InitialAnnBulkPlan, NativeRuntimeError> {
        self.plan_initial_ann_bulk_with_control(
            index,
            vectors,
            requested_partitions,
            Some(cancellation),
            None,
        )
    }

    fn plan_initial_ann_bulk_with_control(
        &self,
        index: ObjectId,
        vectors: Vec<(ObjectId, Vector)>,
        requested_partitions: usize,
        cancellation: Option<&GovernorCancellation>,
        progress: Option<Arc<dyn Fn(InitialAnnBulkProgress) + Send + Sync>>,
    ) -> Result<InitialAnnBulkPlan, NativeRuntimeError> {
        if vectors.is_empty() || requested_partitions == 0 {
            return Err(hyphae_native_ann::AnnError::InvalidPartitionCount.into());
        }
        let effective_partitions = requested_partitions.min(vectors.len());
        let snapshot = self.coordinator.snapshot(0)?;
        let root = snapshot
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let catalog = load_catalog_state(&self.pages, &self.blobs, snapshot.roots())?;
        let authority =
            ann_store::capture_initial_bulk_authority(&self.pages, root, &catalog, index)?;
        let maximum_partitions =
            ann_store::maximum_initial_ann_bulk_partitions(authority.lifecycle.retain_generations);
        if effective_partitions > maximum_partitions {
            return Err(NativeRuntimeError::InitialAnnBulkPartitionLimit {
                requested: effective_partitions,
                maximum: maximum_partitions,
            });
        }
        let candidate_csn = snapshot
            .visible_csn
            .and_then(Csn::checked_next)
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let records = vectors
            .into_iter()
            .map(|(object_id, vector)| VectorRecord {
                object_id,
                creating_csn: candidate_csn,
                vector,
            })
            .collect();
        let candidate_result = self.build_partitioned_hnsw_candidate(
            authority.definition,
            records,
            requested_partitions,
            cancellation,
            progress,
            true,
        )?;
        let receipt = candidate_result.receipt;
        let evidence = InitialAnnBulkBuildEvidence {
            builder: InitialAnnBulkBuilder::PartitionedHnswV1,
            input_identity: receipt.index.input_identity(),
            build_identity: receipt.index.build_identity(),
            planned_vectors: receipt.planned_vectors,
            planned_partitions: receipt.planned_partitions,
            planned_compute_threads: receipt.planned_compute_threads,
            planned_memory_bytes: receipt.planned_memory_bytes,
            worker_batches: receipt.worker_batches,
            execution: receipt.execution,
            total_time: receipt.total_time,
        };
        Ok(InitialAnnBulkPlan {
            index_id: index,
            expected_roots: snapshot.roots().clone(),
            expected_base_identity: authority.base_identity,
            expected_view_identity: authority.view_identity,
            candidate_csn,
            candidate: receipt.index,
            build: evidence,
            resource_permit: candidate_result.resource_permit,
        })
    }

    /// Builds one process-local deterministic partitioned HNSW candidate
    /// under the shared bulk governor and persistent worker pool.
    ///
    /// This is a P4 bakeoff surface. It deliberately does not modify the data
    /// directory or publish the candidate as the current ANN generation.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid vectors or partition count, rejected
    /// bulk admission, worker failure, or noncanonical child output.
    pub fn build_partitioned_hnsw_experimental(
        &self,
        definition: VectorIndexDefinition,
        records: Vec<VectorRecord>,
        requested_partitions: usize,
    ) -> Result<NativePartitionedHnswBuildReceipt, NativeRuntimeError> {
        self.build_partitioned_hnsw_candidate(
            definition,
            records,
            requested_partitions,
            None,
            None,
            false,
        )
        .map(|built| built.receipt)
    }

    fn build_partitioned_hnsw_candidate(
        &self,
        definition: VectorIndexDefinition,
        records: Vec<VectorRecord>,
        requested_partitions: usize,
        cancellation: Option<&GovernorCancellation>,
        progress: Option<Arc<dyn Fn(InitialAnnBulkProgress) + Send + Sync>>,
        retain_resources: bool,
    ) -> Result<BuiltPartitionedHnswCandidate, NativeRuntimeError> {
        if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
            return Err(hyphae_native_ann::AnnError::BuildCancelled.into());
        }
        let total_started = Instant::now();
        let planned_vectors = records.len();
        let effective_partitions = requested_partitions.min(planned_vectors).max(1);
        let planned_memory_bytes = partitioned_hnsw_build_memory_bytes(planned_vectors, definition);
        let permit =
            self.admit_parallel_bulk(planned_memory_bytes, effective_partitions, cancellation)?;
        let planned_compute_threads = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        report_initial_ann_bulk_progress(
            progress.as_deref(),
            InitialAnnBulkProgressStage::Planning,
            0,
            1,
        );
        let plan = HnswPartitionPlan::build_cancellable(
            definition,
            records,
            requested_partitions,
            || {
                if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
                    ControlFlow::Break(())
                } else {
                    ControlFlow::Continue(())
                }
            },
        )?;
        let input_identity = plan.input_identity();
        let planned_partitions = plan.partition_count();
        report_initial_ann_bulk_progress(
            progress.as_deref(),
            InitialAnnBulkProgressStage::Planning,
            1,
            1,
        );
        report_initial_ann_bulk_progress(
            progress.as_deref(),
            InitialAnnBulkProgressStage::Building,
            0,
            planned_partitions,
        );
        let partition_records = plan.into_partitions();
        let (children, worker_batches) = execute_initial_ann_bulk_children(
            self.execution_pool.as_deref(),
            permit.as_ref(),
            partition_records,
            planned_compute_threads,
            InitialAnnBulkChildControl {
                definition,
                cancellation: cancellation.cloned(),
                progress,
                completed: Arc::new(Mutex::new(0)),
                total: planned_partitions,
            },
        )?;
        let index = PartitionedHnswIndex::from_governed_partitions_cancellable(
            definition,
            input_identity,
            children,
            || {
                if cancellation.is_some_and(GovernorCancellation::is_cancelled) {
                    ControlFlow::Break(())
                } else {
                    ControlFlow::Continue(())
                }
            },
        )?;
        let (execution, resource_permit) = match (retain_resources, permit) {
            (true, Some(permit)) => {
                let evidence = permit.evidence();
                let retained = permit.retain_memory(planned_memory_bytes)?;
                (Some(evidence), Some(retained))
            }
            (false, Some(permit)) => (Some(permit.finish()), None),
            (_, None) => (None, None),
        };
        Ok(BuiltPartitionedHnswCandidate {
            receipt: NativePartitionedHnswBuildReceipt {
                index,
                planned_vectors,
                planned_partitions,
                planned_compute_threads,
                planned_memory_bytes,
                worker_batches,
                execution,
                total_time: total_started.elapsed(),
            },
            resource_permit,
        })
    }

    /// Atomically selects one previously built initial ANN generation.
    ///
    /// Writer admission is held only while the captured empty authority is
    /// revalidated and the completed candidate is persisted. Any intervening
    /// commit makes the plan stale; the candidate is never silently rebased.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::InitialAnnBulkStale`] when roots, selected
    /// ANN identities, or the candidate CSN changed after planning. It also
    /// returns storage, WAL, MVCC, or candidate-validation failures.
    pub fn publish_initial_ann_bulk(
        &mut self,
        plan: InitialAnnBulkPlan,
        durability: DurabilityClass,
    ) -> Result<InitialAnnBulkPublishReceipt, NativeRuntimeError> {
        self.publish_initial_ann_bulk_at(plan, durability, None)
    }

    /// Publishes an initial ANN bulk plan with one deterministic ordinary
    /// commit interruption.
    ///
    /// # Errors
    ///
    /// Returns [`NativeRuntimeError::InjectedCrash`] at the requested boundary,
    /// or the same failures as [`Self::publish_initial_ann_bulk`].
    pub fn publish_initial_ann_bulk_with_interruption(
        &mut self,
        plan: InitialAnnBulkPlan,
        durability: DurabilityClass,
        boundary: CommitBoundary,
    ) -> Result<InitialAnnBulkPublishReceipt, NativeRuntimeError> {
        self.publish_initial_ann_bulk_at(plan, durability, Some(boundary))
    }

    fn publish_initial_ann_bulk_at(
        &mut self,
        plan: InitialAnnBulkPlan,
        durability: DurabilityClass,
        interruption: Option<CommitBoundary>,
    ) -> Result<InitialAnnBulkPublishReceipt, NativeRuntimeError> {
        let publication_permit =
            self.admit_initial_ann_publication(FOREGROUND_BOUNDED_MEMORY_BYTES)?;
        if self.search_format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::InvalidAnnTree);
        }
        let InitialAnnBulkPlan {
            index_id,
            expected_roots,
            expected_base_identity,
            expected_view_identity,
            candidate_csn,
            candidate,
            build,
            resource_permit,
        } = plan;
        let _resource_permit = resource_permit;
        let _publication_permit = publication_permit;
        let snapshot = self.coordinator.snapshot(0)?;
        if snapshot.roots() != &expected_roots {
            return Err(NativeRuntimeError::InitialAnnBulkStale);
        }
        let root = snapshot
            .roots()
            .root(SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let catalog = load_catalog_state(&self.pages, &self.blobs, snapshot.roots())?;
        let authority =
            ann_store::capture_initial_bulk_authority(&self.pages, root, &catalog, index_id)?;
        validate_initial_ann_bulk_plan(
            authority,
            expected_base_identity,
            expected_view_identity,
            &candidate,
            build,
        )?;
        let transaction_id = TransactionId::new(self.next_transaction_id)
            .map_err(|_| NativeRuntimeError::TransactionIdExhausted)?;
        let publication = InitialAnnBulkPublication {
            index: index_id,
            expected_base_identity,
            expected_view_identity,
            candidate_csn,
            candidate: candidate.into_snapshot(),
        };
        let mutation_value = ann_store::encode_initial_bulk_publication(&publication)?;
        let root_transaction = self.coordinator.begin_write()?;
        validate_initial_ann_bulk_commit_authority(
            &root_transaction,
            &expected_roots,
            candidate_csn,
        )?;
        let directory_identity = self.directory_identity().clone();
        let transaction = NativeTransaction {
            pages: &mut self.pages,
            buffer_pool: self.buffer_pool.clone(),
            blobs: &mut self.blobs,
            wal: &mut self.wal,
            conflicts: &mut self.conflicts,
            relational_format: self.relational_format,
            structure_format: self.structure_format,
            search_format: self.search_format,
            root_transaction,
            conflict_read_csn: snapshot.visible_csn,
            transaction_id,
            next_transaction_id: &mut self.next_transaction_id,
            transaction_resolutions: &mut self.transaction_resolutions,
            transaction_receipts: &mut self.transaction_receipts,
            resolution: None,
            batch: NativeWriteBatch {
                lineage: None,
                directory_identity,
                snapshot,
                state: MaterializedState {
                    catalog,
                    ..MaterializedState::default()
                },
                mutations: vec![Mutation {
                    engine: EngineKind::Search,
                    opcode: Opcode::PublishInitialAnnBulk,
                    target: Some(index_id),
                    key: Vec::new(),
                    value: mutation_value,
                    expires_at_micros: None,
                }],
                dirty: [false, false, false, true],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalInitialAnnBulkPublication,
                delta_stage_active: false,
                delta: None,
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: Some(publication),
                resource_permit: None,
            },
        };
        let commit = commit_transaction_at(transaction, interruption)?;
        self.finish_initial_ann_bulk_publication(index_id, build, commit)
    }

    fn finish_initial_ann_bulk_publication(
        &self,
        index_id: ObjectId,
        build: InitialAnnBulkBuildEvidence,
        commit: CommitReceipt,
    ) -> Result<InitialAnnBulkPublishReceipt, NativeRuntimeError> {
        validate_published_initial_ann(self.observe_ann_index_unadmitted(index_id)?, build)?;
        Ok(InitialAnnBulkPublishReceipt {
            index_id,
            build,
            commit,
        })
    }

    fn search_vector_exact_profiled(
        &self,
        index: ObjectId,
        query: &Vector,
        k: usize,
        allowlist: Option<&BTreeSet<ObjectId>>,
    ) -> Result<NativeExactAnnExecutionReceipt, NativeRuntimeError> {
        let total_started = Instant::now();
        let planning_permit = self.admit_foreground_bounded()?;
        let observation = self.observe_ann_index_unadmitted(index)?;
        let planning = planning_permit.map(DatabaseGovernorPermit::finish);
        let eligible_count = allowlist.map_or(observation.effective_vector_count, |allowlist| {
            observation.effective_vector_count.min(allowlist.len())
        });
        let planned_memory_bytes = exact_ann_memory_bytes(eligible_count, query.dimension());
        let permit = self.admit_parallel_foreground_bounded(planned_memory_bytes)?;
        let planned_compute_threads = permit
            .as_ref()
            .map_or(1, |permit| permit.permit().request().compute_threads);
        let snapshot = self.coordinator.snapshot(0)?;
        let state = load_state(&self.pages, &self.blobs, snapshot.roots())?;
        let exact = match (self.execution_pool.as_deref(), permit.as_ref()) {
            (Some(execution_pool), Some(permit))
                if permit.permit().request().compute_threads > 1 =>
            {
                state.ann.search_exact_parallel(
                    index,
                    query,
                    k,
                    allowlist,
                    execution_pool,
                    permit.permit(),
                )?
            }
            _ => state
                .ann
                .search_exact_profiled(index, query, k, allowlist)?,
        };
        let execution = permit.map(DatabaseGovernorPermit::finish);
        Ok(NativeExactAnnExecutionReceipt {
            snapshot_csn: snapshot.visible_csn,
            hits: exact.hits,
            planned_vectors: exact.planned_vectors,
            planned_batches: exact.planned_batches,
            planning,
            execution,
            planned_compute_threads,
            planned_memory_bytes,
            worker_batches: exact.worker_batches,
            total_time: total_started.elapsed(),
        })
    }

    /// Verifies the current relational B+tree and returns its node height.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot coordination, a missing committed root,
    /// or any reachable B+tree/page corruption.
    pub fn latest_relational_tree_height(&self) -> Result<usize, NativeRuntimeError> {
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_RELATIONAL) else {
            return Ok(0);
        };
        Ok(BTree::from_root(root).height(&self.pages)?)
    }

    /// Verifies the current structure B+tree and returns its node height.
    ///
    /// Legacy inline-state roots report zero because they are not a B+tree.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot, page, or B+tree corruption.
    pub fn latest_structure_tree_height(&self) -> Result<usize, NativeRuntimeError> {
        if self.structure_format == StructureFormat::InlineStateV1 {
            return Ok(0);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_STRUCTURE) else {
            return Ok(0);
        };
        Ok(BTree::from_root(root).height(&self.pages)?)
    }

    /// Verifies the current inverted-index B+tree and returns its node height.
    ///
    /// Legacy inline search roots report zero.
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot, page, or B+tree corruption.
    pub fn latest_search_tree_height(&self) -> Result<usize, NativeRuntimeError> {
        if self.search_format == SearchFormat::InlineStateV1 {
            return Ok(0);
        }
        let snapshot = self.coordinator.snapshot(0)?;
        let Some(root) = snapshot.roots().root(SLOT_SEARCH) else {
            return Ok(0);
        };
        Ok(BTree::from_root(root).height(&self.pages)?)
    }

    /// Returns monotonic physical counters for bounded delta evidence.
    ///
    /// Subtract two observations from the same open handle to isolate page
    /// reads, page appends, WAL growth, and complete-state loads for a route.
    ///
    /// # Errors
    ///
    /// Returns an error when WAL file metadata cannot be read.
    pub fn physical_observation(&self) -> Result<NativePhysicalObservation, NativeRuntimeError> {
        Ok(NativePhysicalObservation {
            page_count: self.pages.page_count(),
            physical_page_reads: self.pages.physical_read_count(),
            wal_bytes: fs::metadata(self.data_directory.join(WAL_FILE))?.len(),
            process_full_state_loads: FULL_STATE_LOADS.load(Ordering::Relaxed),
            process_full_catalog_loads: FULL_CATALOG_STATE_LOADS.load(Ordering::Relaxed),
        })
    }

    /// Returns process-wide materialization counters without touching durable
    /// state. Subtract two observations around a measured interval.
    pub fn process_materialization_observation() -> NativeMaterializationObservation {
        NativeMaterializationObservation {
            full_state_loads: FULL_STATE_LOADS.load(Ordering::Relaxed),
            full_catalog_loads: FULL_CATALOG_STATE_LOADS.load(Ordering::Relaxed),
        }
    }

    /// Returns the process-wide count of completed index-scoped ANN restores.
    ///
    /// Subtract observations around a query interval to verify that an owned
    /// ANN read view did not cross its one-time hydration boundary.
    pub fn process_ann_index_restore_count() -> u64 {
        ann_store::process_index_scoped_restore_count()
    }

    /// Prepares one detached optimistic write transaction.
    ///
    /// Preparation captures and materializes an immutable snapshot without
    /// acquiring the serialized writer guard. Multiple callers may therefore
    /// prepare private write sets concurrently. Publication remains a short,
    /// explicitly serialized operation through [`Self::commit_optimistic`].
    ///
    /// # Errors
    ///
    /// Returns an error for snapshot, page, root, blob, or state corruption.
    pub fn begin_optimistic(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
    ) -> Result<NativeWriteBatch, NativeRuntimeError> {
        self.begin_optimistic_with_admission(
            logical_time_micros,
            durability,
            self.resource_queue_wait,
            None,
        )
    }

    fn begin_optimistic_scheduled(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<NativeWriteBatch, NativeRuntimeError> {
        self.begin_optimistic_with_admission(
            logical_time_micros,
            durability,
            maximum_wait,
            cancellation,
        )
    }

    fn begin_optimistic_with_admission(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<NativeWriteBatch, NativeRuntimeError> {
        let resource_permit = self.admit_mutation_owned_with_wait(maximum_wait, cancellation)?;
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        let state = load_state(&self.pages, &self.blobs, snapshot.roots())?;
        Ok(NativeWriteBatch {
            lineage: Some(self.acquire_write_batch_lease()),
            directory_identity: self.directory_identity().clone(),
            snapshot,
            state,
            mutations: Vec::new(),
            dirty: [false; 4],
            durability,
            structure_format: self.structure_format,
            search_format: self.search_format,
            mode: NativeWriteBatchMode::Materialized,
            delta_stage_active: false,
            delta: None,
            ann_consolidation: None,
            ann_consolidation_structure: None,
            ann_initial_bulk: None,
            resource_permit,
        })
    }

    /// Clones one legacy materialized private write set into a temporary
    /// rollback candidate.
    ///
    /// This is the rollback-candidate seam for legacy product transactions.
    /// The deep copy shares the source's primary mutation authority and holds
    /// a separate memory-only reservation until the caller immediately
    /// replaces the source. This compatibility seam does not claim plan-sized
    /// accounting. Point-resolved delta, maintenance, and ANN publication
    /// batches remain deliberately linear and cannot be cloned.
    ///
    /// # Errors
    ///
    /// Returns an error when the batch is not a materialized write set from
    /// this exact data directory and physical format, or when a second
    /// memory reservation is unavailable.
    pub fn clone_legacy_materialized_write_batch(
        &self,
        batch: &NativeWriteBatch,
    ) -> Result<LegacyMaterializedWriteBatchCandidate, NativeRuntimeError> {
        if batch.mode != NativeWriteBatchMode::Materialized
            || batch.directory_identity != *self.directory_identity()
            || !self.owns_detached_batch(batch)
        {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let root_formats = formats_for_latest_root(
            &self.pages,
            (!root_set_is_pristine(batch.snapshot.roots())).then_some(batch.snapshot.roots()),
        )?;
        if root_formats
            != (
                self.relational_format,
                self.structure_format,
                self.search_format,
            )
            || batch.structure_format != self.structure_format
            || batch.search_format != self.search_format
        {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let copy_memory_permit = self.admit_database_work(
            WorkloadClass::Mutation,
            GovernorRequest {
                compute_threads: 0,
                io_slots: 0,
                memory_bytes: MUTATION_MEMORY_BYTES,
            },
        )?;
        Ok(LegacyMaterializedWriteBatchCandidate {
            batch: batch.clone_with_resource_permit(batch.resource_permit.clone()),
            copy_memory_permit: copy_memory_permit.map(DatabaseGovernorPermit::into_owned),
        })
    }

    /// Prepares one detached point-resolved all-engine write transaction.
    ///
    /// The batch captures the immutable root-set snapshot without materializing
    /// engine or catalog state. Required definitions, rows, scalar keys, and
    /// document identities are resolved by the corresponding `stage_delta_*`
    /// operation.
    ///
    /// Materialized reads are deliberately absent from the returned delta
    /// authority. Using the default private state as a read surface would
    /// report false absence for durable values that have not been hydrated.
    ///
    /// ```compile_fail
    /// use hyphae_native_runtime::NativeDatabase;
    /// use hyphae_native_types::DurabilityClass;
    ///
    /// fn false_absence(database: &NativeDatabase) {
    ///     let delta = database
    ///         .begin_optimistic_delta(0, DurabilityClass::Memory)
    ///         .unwrap();
    ///     let _ = delta.get(b"durable-key");
    /// }
    /// ```
    ///
    /// Direct materialized mutation is also absent. Delta mutation must pass
    /// through a `NativeDatabase::stage_delta_*` entrypoint so point hydration,
    /// retained-memory admission, and rollback remain one operation.
    ///
    /// ```compile_fail
    /// use hyphae_native_runtime::NativeDatabase;
    /// use hyphae_native_types::DurabilityClass;
    ///
    /// fn bypass_staging(database: &NativeDatabase) {
    ///     let mut delta = database
    ///         .begin_optimistic_delta(0, DurabilityClass::Memory)
    ///         .unwrap();
    ///     delta.set(b"key".to_vec(), b"value".to_vec(), None).unwrap();
    /// }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns an error for unsupported legacy physical formats, snapshot,
    /// catalog, relational-index metadata, page, blob, or model corruption.
    pub fn begin_optimistic_delta(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
    ) -> Result<NativeDeltaWriteBatch, NativeRuntimeError> {
        self.begin_optimistic_delta_with_admission(
            logical_time_micros,
            durability,
            self.resource_queue_wait,
            None,
        )
    }

    fn begin_optimistic_delta_scheduled(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<NativeDeltaWriteBatch, NativeRuntimeError> {
        self.begin_optimistic_delta_with_admission(
            logical_time_micros,
            durability,
            maximum_wait,
            cancellation,
        )
    }

    fn begin_optimistic_delta_with_admission(
        &self,
        logical_time_micros: i64,
        durability: DurabilityClass,
        maximum_wait: Duration,
        cancellation: Option<&GovernorCancellation>,
    ) -> Result<NativeDeltaWriteBatch, NativeRuntimeError> {
        let resource_permit = self.admit_mutation_owned_with_wait(maximum_wait, cancellation)?;
        if self.relational_format != RelationalFormat::VersionChainV2
            || !matches!(
                self.structure_format,
                StructureFormat::BTreeV2 | StructureFormat::BTreeV3
            )
            || self.search_format != SearchFormat::InvertedBTreeV1
        {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let snapshot = self.coordinator.snapshot(logical_time_micros)?;
        Ok(NativeDeltaWriteBatch {
            inner: NativeWriteBatch {
                lineage: Some(self.acquire_write_batch_lease()),
                directory_identity: self.directory_identity().clone(),
                snapshot,
                state: MaterializedState::default(),
                mutations: Vec::new(),
                dirty: [false; 4],
                durability,
                structure_format: self.structure_format,
                search_format: self.search_format,
                mode: NativeWriteBatchMode::PhysicalAllEngineDelta,
                delta_stage_active: false,
                delta: Some(DeltaOverlay::default()),
                ann_consolidation: None,
                ann_consolidation_structure: None,
                ann_initial_bulk: None,
                resource_permit,
            },
        })
    }

    /// Stages one exact-primary-key SQL DML statement in a delta batch.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta batch, unsupported SQL, binding,
    /// point-read corruption, or native relational semantics.
    pub fn stage_delta_sql_dml(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        statement: &str,
        parameters: &[SqlValue],
    ) -> Result<SqlResult, SqlError> {
        let batch = &mut batch.inner;
        self.require_delta_batch(batch).map_err(SqlError::from)?;
        let input_bytes = parameters.iter().fold(0_u64, |bytes, parameter| {
            bytes.saturating_add(retained_scalar_value_capacity(parameter))
        });
        Self::ensure_delta_memory_growth(
            batch,
            input_bytes
                .saturating_mul(2)
                .saturating_add(DELTA_ENGINE_CONTAINER_OVERHEAD),
        )
        .map_err(SqlError::from)?;
        let dml = sql::TransactionDml::parse(statement)?;
        let relation_rollback = self
            .hydrate_delta_relation(batch, dml.relation_name()?)
            .map_err(SqlError::from)?;
        let mut row_rollback = None;
        let mut row_identity = None;
        let staged = (|| {
            let (table, primary_key) = dml.primary_key(batch, parameters)?;
            let catalog_root = batch
                .snapshot
                .roots()
                .root(SLOT_CATALOG)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            self.require_delta_relation_without_foreign_keys(batch, catalog_root, table)
                .map_err(SqlError::from)?;
            row_rollback = self
                .hydrate_delta_relational_row(batch, table, &primary_key)
                .map_err(SqlError::from)?;
            row_identity = Some((table, primary_key.clone()));
            Self::refresh_delta_memory_ledger(batch).map_err(SqlError::from)?;
            let candidate = dml.candidate_row(batch, parameters)?;
            let candidate_charge = delta_sql_candidate_charge(
                batch,
                table,
                primary_key.capacity(),
                candidate.as_ref().map_or(0, Vec::capacity),
            );
            Self::ensure_delta_memory_growth(batch, candidate_charge).map_err(SqlError::from)?;
            let unique_probes = candidate
                .as_deref()
                .map(|row| self.validate_delta_unique_projections(batch, table, &primary_key, row))
                .transpose()
                .map_err(sql::map_runtime_error)?
                .unwrap_or_default();
            let result = batch.with_delta_stage(|batch| dml.execute(batch, parameters))?;
            batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
                .unique_probes
                .extend(unique_probes);
            Self::refresh_delta_memory_ledger(batch).map_err(SqlError::from)?;
            Ok(result)
        })();
        if staged.is_err() {
            if let Some(previous) = row_rollback {
                batch.state.relational = previous;
                if let Some(identity) = row_identity {
                    batch
                        .delta
                        .as_mut()
                        .ok_or(NativeRuntimeError::InvalidPreparedMutation)
                        .map_err(SqlError::from)?
                        .relational_rows
                        .remove(&identity);
                }
            }
            if let Some(previous) = relation_rollback {
                let delta = batch
                    .delta
                    .as_mut()
                    .ok_or(NativeRuntimeError::InvalidPreparedMutation)
                    .map_err(SqlError::from)?;
                for id in previous.catalog_object_ids {
                    delta.catalog_object_memory_bytes.remove(&id);
                }
                batch.state.catalog = previous.catalog;
                batch.state.relational = previous.relational;
            }
            let retained = replay_delta_retained_memory_bytes(batch);
            batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)
                .map_err(SqlError::from)?
                .retained_memory_bytes = retained;
        }
        staged
    }

    /// Stages one scalar `SET` in a delta batch.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta batch, physical corruption, a
    /// collection-owned key, or invalid structure identity.
    pub fn stage_delta_set(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: Vec<u8>,
        value: Vec<u8>,
        expires_at_micros: Option<i64>,
    ) -> Result<(), NativeRuntimeError> {
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        let candidate_charge =
            delta_payload_retained_charge(key.capacity(), value.capacity(), 3, 2)
                .saturating_add(delta_mutation_vector_growth(batch));
        Self::ensure_delta_memory_growth(batch, candidate_charge)?;
        let was_loaded = batch
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_scalars
            .contains(&key);
        let mutation_count = batch.mutations.len();
        let dirty = batch.dirty;
        self.hydrate_delta_scalar(batch, &key)?;
        let hydration_key = key.clone();
        let staged = (|| {
            Self::refresh_delta_memory_ledger(batch)?;
            let reuse_charge = Self::delta_expired_collection_reuse_charge(batch, &key);
            let staged_mutations = 1 + usize::from(reuse_charge != 0);
            let complete_candidate_charge =
                delta_payload_retained_charge(key.capacity(), value.capacity(), 3, 2)
                    .saturating_add(reuse_charge)
                    .saturating_add(delta_mutation_vector_growth_for(batch, staged_mutations));
            Self::ensure_delta_memory_growth(batch, complete_candidate_charge)?;
            batch.with_delta_stage(|batch| batch.set(key, value, expires_at_micros))?;
            Self::refresh_delta_memory_ledger(batch)
        })();
        if staged.is_err() {
            batch.mutations.truncate(mutation_count);
            batch.dirty = dirty;
            if !was_loaded {
                Self::restore_delta_scalar_hydration(batch, &hydration_key)?;
            }
        }
        staged
    }

    /// Stages one exact-field `HSET` without materializing the hash.
    ///
    /// The existing field payload remains unresolved: only its physical
    /// envelope and TTL authority are inspected to distinguish `Added` from
    /// `Updated`. Hash-delta identities, overlay envelopes, and mutations are
    /// charged to an aggregate 8 MiB sub-budget inside the fixed mutation
    /// allocation.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta or non-V3 batch, invalid identities,
    /// another structure kind, a missing or expired hash, or corruption.
    pub fn stage_delta_hset(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: impl Into<Vec<u8>>,
        field: impl Into<Vec<u8>>,
        value: Vec<u8>,
    ) -> Result<HashSetOutcome, NativeRuntimeError> {
        let key = key.into().into_boxed_slice().into_vec();
        let field = field.into().into_boxed_slice().into_vec();
        let value = value.into_boxed_slice().into_vec();
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        let identity_capacity = key.capacity().saturating_add(field.capacity());
        let candidate_charge =
            delta_payload_retained_charge(identity_capacity, value.capacity(), 3, 1)
                .saturating_add(delta_mutation_vector_growth(batch));
        Self::ensure_delta_memory_growth(batch, candidate_charge)?;
        let identity = (key.clone(), field.clone());
        let rollback = Self::capture_delta_hash_stage_rollback(batch, &identity)?;
        let staged = (|| {
            self.hydrate_delta_hash_field(batch, &key, &field)?;
            Self::refresh_delta_memory_ledger(batch)?;
            Self::ensure_delta_memory_growth(batch, candidate_charge)?;
            let added = matches!(
                batch
                    .delta
                    .as_ref()
                    .and_then(|delta| delta.structure_hash_fields.get(&identity)),
                Some(DeltaHashFieldOverlay::Missing | DeltaHashFieldOverlay::Deleted(_))
            );
            let mutation_index = batch.mutations.len();
            let mutation = Mutation {
                engine: EngineKind::Structure,
                opcode: Opcode::SetHashField,
                target: None,
                key: hash_field_identity(&key, &field)?,
                value,
                expires_at_micros: None,
            };
            let overlay = DeltaHashFieldOverlay::Staged(mutation_index);
            let accounted_bytes = Self::delta_hash_accounting_after_replacement(
                batch,
                &identity,
                &overlay,
                Some(&mutation),
            )?;
            batch.mutations.push(mutation);
            let delta = batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
            delta
                .structure_hash_fields
                .insert(identity.clone(), overlay);
            delta.structure_hash_memory_bytes = accounted_bytes;
            batch.dirty[2] = true;
            Self::refresh_delta_memory_ledger(batch)?;
            Ok(if added {
                HashSetOutcome::Added
            } else {
                HashSetOutcome::Updated
            })
        })();
        if staged.is_err() {
            Self::restore_delta_hash_stage_rollback(batch, &identity, rollback)?;
        }
        staged
    }

    /// Stages one exact-field `HDEL` without reading the old field payload.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta or non-V3 batch, invalid identities,
    /// another structure kind, a missing or expired hash, or corruption.
    pub fn stage_delta_hdelete(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: impl Into<Vec<u8>>,
        field: impl Into<Vec<u8>>,
    ) -> Result<bool, NativeRuntimeError> {
        let key = key.into().into_boxed_slice().into_vec();
        let field = field.into().into_boxed_slice().into_vec();
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        let identity_capacity = key.capacity().saturating_add(field.capacity());
        let candidate_charge = delta_payload_retained_charge(identity_capacity, 0, 3, 0)
            .saturating_add(delta_mutation_vector_growth(batch));
        Self::ensure_delta_memory_growth(batch, candidate_charge)?;
        let identity = (key.clone(), field.clone());
        let rollback = Self::capture_delta_hash_stage_rollback(batch, &identity)?;
        let staged = (|| {
            self.hydrate_delta_hash_field(batch, &key, &field)?;
            Self::refresh_delta_memory_ledger(batch)?;
            Self::ensure_delta_memory_growth(batch, candidate_charge)?;
            match batch
                .delta
                .as_ref()
                .and_then(|delta| delta.structure_hash_fields.get(&identity))
            {
                Some(DeltaHashFieldOverlay::Missing) => {
                    let removed = batch
                        .delta
                        .as_mut()
                        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
                        .structure_hash_fields
                        .remove(&identity)
                        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
                    let released = Self::delta_hash_overlay_charge(&identity, &removed)?;
                    let delta = batch
                        .delta
                        .as_mut()
                        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
                    delta.structure_hash_memory_bytes = delta
                        .structure_hash_memory_bytes
                        .checked_sub(released)
                        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
                    Self::refresh_delta_memory_ledger(batch)?;
                    return Ok(false);
                }
                Some(DeltaHashFieldOverlay::Deleted(_)) => return Ok(false),
                Some(DeltaHashFieldOverlay::Durable(_) | DeltaHashFieldOverlay::Staged(_)) => {}
                None => return Err(NativeRuntimeError::InvalidPreparedMutation),
            }
            let mutation_index = batch.mutations.len();
            let mutation = Mutation {
                engine: EngineKind::Structure,
                opcode: Opcode::DeleteHashField,
                target: None,
                key: hash_field_identity(&key, &field)?,
                value: Vec::new(),
                expires_at_micros: None,
            };
            let overlay = DeltaHashFieldOverlay::Deleted(mutation_index);
            let accounted_bytes = Self::delta_hash_accounting_after_replacement(
                batch,
                &identity,
                &overlay,
                Some(&mutation),
            )?;
            batch.mutations.push(mutation);
            let delta = batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
            delta
                .structure_hash_fields
                .insert(identity.clone(), overlay);
            delta.structure_hash_memory_bytes = accounted_bytes;
            batch.dirty[2] = true;
            Self::refresh_delta_memory_ledger(batch)?;
            Ok(true)
        })();
        if staged.is_err() {
            Self::restore_delta_hash_stage_rollback(batch, &identity, rollback)?;
        }
        staged
    }

    /// Stages one exact-field signed `HINCRBY` without materializing the hash.
    ///
    /// A durable blob payload is admitted from its verified logical length
    /// before it is read. Retained hash-delta values plus that transient read
    /// must fit the 8 MiB hash-delta budget. Missing or expired fields start at
    /// zero.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta or non-V3 batch, invalid identities,
    /// another structure kind, a missing or expired hash, resource rejection,
    /// noncanonical integer bytes, signed overflow, or corruption.
    pub fn stage_delta_hincrement(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: impl Into<Vec<u8>>,
        field: impl Into<Vec<u8>>,
        increment: i64,
    ) -> Result<i64, NativeRuntimeError> {
        let key = key.into().into_boxed_slice().into_vec();
        let field = field.into().into_boxed_slice().into_vec();
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        let identity_capacity = key.capacity().saturating_add(field.capacity());
        let candidate_charge = delta_payload_retained_charge(identity_capacity, 32, 3, 1)
            .saturating_add(delta_mutation_vector_growth(batch));
        Self::ensure_delta_memory_growth(batch, candidate_charge)?;
        let identity = (key.clone(), field.clone());
        let previous_overlay = batch
            .delta
            .as_ref()
            .and_then(|delta| delta.structure_hash_fields.get(&identity))
            .cloned();
        let previous_hash_memory = batch
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_hash_memory_bytes;
        let previous_retained_memory = batch
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .retained_memory_bytes;
        let mutation_count = batch.mutations.len();
        let dirty = batch.dirty;
        let staged = (|| {
            self.hydrate_delta_hash_field(batch, &key, &field)?;
            Self::refresh_delta_memory_ledger(batch)?;
            Self::ensure_delta_memory_growth(batch, candidate_charge)?;
            let base = self.delta_hash_field_integer(batch, &identity)?;
            let value = base
                .checked_add(increment)
                .ok_or(NativeRuntimeError::StructureIntegerOverflow)?;
            let mutation_index = batch.mutations.len();
            let mutation = Mutation {
                engine: EngineKind::Structure,
                opcode: Opcode::SetHashField,
                target: None,
                key: hash_field_identity(&key, &field)?,
                value: value.to_string().into_bytes(),
                expires_at_micros: None,
            };
            let overlay = DeltaHashFieldOverlay::Staged(mutation_index);
            let accounted_bytes = Self::delta_hash_accounting_after_replacement(
                batch,
                &identity,
                &overlay,
                Some(&mutation),
            )?;
            batch.mutations.push(mutation);
            let delta = batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
            delta
                .structure_hash_fields
                .insert(identity.clone(), overlay);
            delta.structure_hash_memory_bytes = accounted_bytes;
            batch.dirty[2] = true;
            Self::refresh_delta_memory_ledger(batch)?;
            Ok(value)
        })();
        if staged.is_err() {
            batch.mutations.truncate(mutation_count);
            batch.dirty = dirty;
            let delta = batch
                .delta
                .as_mut()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
            if let Some(previous) = previous_overlay {
                delta.structure_hash_fields.insert(identity, previous);
            } else {
                delta.structure_hash_fields.remove(&identity);
            }
            delta.structure_hash_memory_bytes = previous_hash_memory;
            delta.retained_memory_bytes = previous_retained_memory;
        }
        staged
    }

    /// Reads one exact hash field through a point-resolved delta overlay.
    ///
    /// This is the only hash read-your-writes surface for delta batches;
    /// aggregate length and scan operations intentionally remain unsupported.
    ///
    /// # Errors
    ///
    /// Returns an error for the same identity, shape, resource, blob, and
    /// corruption failures as the corresponding staged mutation.
    pub fn delta_hget(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: &[u8],
        field: &[u8],
    ) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
        let batch = &mut batch.inner;
        self.hydrate_delta_hash_field(batch, key, field)?;
        Self::refresh_delta_memory_ledger(batch)?;
        self.delta_hash_field_value(batch, &(key.to_vec(), field.to_vec()))
    }

    /// Returns one exact hash family's TTL from V3 point metadata.
    ///
    /// Field writes do not change the whole-hash expiry, so staged `HSET` and
    /// `HINCRBY` operations preserve the TTL returned by this method. No
    /// partial materialized hash map is constructed.
    ///
    /// # Errors
    ///
    /// Returns an error for a foreign, stale, non-delta, or non-V3 batch,
    /// another structure kind, an invalid physical identity, or corruption.
    pub fn delta_ttl_hash(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: &[u8],
    ) -> Result<Ttl, NativeRuntimeError> {
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        if self.structure_format != StructureFormat::BTreeV3 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let root = batch
            .snapshot
            .roots()
            .root(SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        structure_v3::delta_hash_ttl_latest_at_v3(
            &self.pages,
            &self.buffer_pool,
            BTree::from_root(root),
            key,
            batch.snapshot.logical_time_micros,
        )
    }

    /// Returns one exact hash field's TTL through a point-resolved delta
    /// overlay.
    ///
    /// `HSET` and `HINCRBY` clear a field TTL; `HDEL`, missing, and due fields
    /// return [`Ttl::Missing`].
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta or non-V3 batch, invalid identity,
    /// another structure kind, a missing or expired hash, or corruption.
    pub fn delta_ttl_hash_field(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        key: &[u8],
        field: &[u8],
    ) -> Result<Ttl, NativeRuntimeError> {
        let batch = &mut batch.inner;
        self.hydrate_delta_hash_field(batch, key, field)?;
        Self::refresh_delta_memory_ledger(batch)?;
        let overlay = batch
            .delta
            .as_ref()
            .and_then(|delta| {
                delta
                    .structure_hash_fields
                    .get(&(key.to_vec(), field.to_vec()))
            })
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        Ok(match overlay {
            DeltaHashFieldOverlay::Missing | DeltaHashFieldOverlay::Deleted(_) => Ttl::Missing,
            DeltaHashFieldOverlay::Staged(_) => Ttl::Persistent,
            DeltaHashFieldOverlay::Durable(field) => match field.expires_at_micros {
                None => Ttl::Persistent,
                Some(expiry) => Ttl::RemainingMicros(
                    expiry
                        .checked_sub(batch.snapshot.logical_time_micros)
                        .ok_or(NativeRuntimeError::InvalidStructureTree)?,
                ),
            },
        })
    }

    /// Stages one immutable lexical document in a delta batch.
    ///
    /// # Errors
    ///
    /// Returns an error for a non-delta batch, unknown index, duplicate
    /// document identity, invalid identity bounds, or physical corruption.
    pub fn stage_delta_index_document(
        &self,
        batch: &mut NativeDeltaWriteBatch,
        index: ObjectId,
        document_id: Vec<u8>,
        text: String,
    ) -> Result<(), NativeRuntimeError> {
        let batch = &mut batch.inner;
        self.require_delta_batch(batch)?;
        let candidate_charge =
            delta_payload_retained_charge(document_id.capacity(), text.capacity(), 3, 2)
                .saturating_add(delta_mutation_vector_growth(batch));
        Self::ensure_delta_memory_growth(batch, candidate_charge)?;
        let mutation_count = batch.mutations.len();
        let dirty = batch.dirty;
        let rollback = self.hydrate_delta_search_document(batch, index, &document_id)?;
        let staged = (|| {
            Self::refresh_delta_memory_ledger(batch)?;
            Self::ensure_delta_memory_growth(batch, candidate_charge)?;
            batch.with_delta_stage(|batch| batch.index_document(index, document_id, text))?;
            Self::refresh_delta_memory_ledger(batch)
        })();
        if staged.is_err() {
            batch.mutations.truncate(mutation_count);
            batch.dirty = dirty;
            if let Some(rollback) = rollback {
                Self::restore_delta_search_hydration(batch, rollback)?;
            }
        }
        staged
    }

