struct CheckpointValidation {
    last_checkpoint_lsn: Option<Lsn>,
    latest_visible_csn: Option<Csn>,
    latest_generation: Option<ManifestGeneration>,
    latest_digest: Option<[u8; 32]>,
    unanchored_manifest_suffix: usize,
}

fn manifest_by_generation(
    manifests: &[RootManifest],
    generation: ManifestGeneration,
) -> Option<&RootManifest> {
    manifests
        .binary_search_by_key(&generation.get(), |manifest| manifest.generation().get())
        .ok()
        .and_then(|index| manifests.get(index))
}

fn validate_snapshot_pins(
    data_directory: &Path,
    pins: &SnapshotPinStore,
    manifests: &[RootManifest],
    recovered: &RecoveredWal,
    retention_anchor: Option<&WalRetentionAnchor>,
    blobs: &BlobStore,
) -> Result<(), NativeRuntimeError> {
    for pin in pins.iter() {
        let manifest = manifest_by_generation(manifests, pin.manifest_generation())
            .ok_or(NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        if !pin.matches_manifest(manifest)
            || !snapshot_pin_has_checkpoint_authority(pin, recovered, retention_anchor)
            || pin.blob_generation() > blobs.generation()?
        {
            return Err(NativeRuntimeError::InvalidSnapshotPinAuthority);
        }
        let roots = manifest.to_root_set()?;
        let pages = PageStore::open_generation(
            page_generation_path(data_directory, pin.page_generation()),
            pin.page_generation(),
        )
        .map_err(|_| NativeRuntimeError::InvalidSnapshotPinAuthority)?;
        validate_roots(&pages, blobs, &roots, pin.visible_csn())
            .map_err(|_| NativeRuntimeError::InvalidSnapshotPinAuthority)?;
    }
    Ok(())
}

fn recover_snapshot_pin_files(
    data_directory: &Path,
    pins: &mut SnapshotPinStore,
    manifests: &[RootManifest],
    recovered: &RecoveredWal,
    retention_anchor: Option<&WalRetentionAnchor>,
    blobs: &BlobStore,
    active_page_generation: PageGeneration,
) -> Result<usize, NativeRuntimeError> {
    validate_snapshot_pins(
        data_directory,
        pins,
        manifests,
        recovered,
        retention_anchor,
        blobs,
    )?;
    pins.cleanup_temporaries()?;
    let pinned_generations = pins.pinned_generations();
    Ok(
        collect_page_generation_files(data_directory, active_page_generation, &pinned_generations)?
            .removed_files,
    )
}

fn validate_open_snapshots(
    data_directory: &Path,
    pins: &mut SnapshotPinStore,
    wal: &WalOpenState,
    committed_roots: &BTreeMap<Csn, RootSet>,
    retention_anchor: Option<&WalRetentionAnchor>,
    blobs: &BlobStore,
    active_page_generation: PageGeneration,
) -> Result<(CheckpointValidation, usize), NativeRuntimeError> {
    let checkpoint_validation = validate_checkpoints(
        &wal.recovered_wal,
        &wal.manifest_recovery.manifests,
        committed_roots,
        retention_anchor,
    )?;
    let recovered_page_generation_files = recover_snapshot_pin_files(
        data_directory,
        pins,
        &wal.manifest_recovery.manifests,
        &wal.recovered_wal,
        retention_anchor,
        blobs,
        active_page_generation,
    )?;
    Ok((checkpoint_validation, recovered_page_generation_files))
}

fn finish_open_recovery(
    data_directory: &Path,
    pins: &mut SnapshotPinStore,
    wal: &mut WalOpenState,
    committed_roots: &BTreeMap<Csn, RootSet>,
    retention_anchor: Option<WalRetentionAnchor>,
    blobs: &BlobStore,
    active_page_generation: PageGeneration,
) -> Result<OpenRecoveryState, NativeRuntimeError> {
    let (checkpoint_validation, recovered_page_generation_files) = validate_open_snapshots(
        data_directory,
        pins,
        wal,
        committed_roots,
        retention_anchor.as_ref(),
        blobs,
        active_page_generation,
    )?;
    let transaction_resolutions = recover_transaction_resolutions(&wal.recovered_wal)?;
    let recovered_outcome_updates = transaction_resolutions
        .values()
        .filter(|resolution| {
            wal.recovered_wal.outcomes.iter().any(|outcome| {
                outcome.resolution_id == resolution.resolution_id
                    && outcome.state == 3
                    && !matches!(
                        resolution.outcome,
                        DurableTransactionOutcome::OutcomeUnknown { .. }
                    )
            })
        })
        .copied()
        .collect::<Vec<_>>();
    persist_recovered_outcome_updates(&mut wal.opened_wal.wal, &recovered_outcome_updates)?;
    let transaction_receipts =
        recover_transaction_receipts(&wal.recovered_wal, &wal.opened_wal.recovery)?;
    let (manifest_prune, manifest_pruning_time) =
        prune_recovered_manifest_prefix(&mut wal.manifests, retention_anchor)?;
    cleanup_stale_wal_anchors(&mut wal.wal_retention, retention_anchor)?;
    Ok(OpenRecoveryState {
        transaction_resolutions,
        transaction_receipts,
        checkpoint_validation,
        recovered_page_generation_files,
        manifest_prune,
        manifest_pruning_time,
    })
}

fn snapshot_pin_has_checkpoint_authority(
    pin: &SnapshotPin,
    recovered: &RecoveredWal,
    retention_anchor: Option<&WalRetentionAnchor>,
) -> bool {
    let recovered_checkpoint = recovered.checkpoints.iter().any(|checkpoint| {
        checkpoint.visible_csn == pin.visible_csn()
            && checkpoint.manifest_generation == pin.manifest_generation()
            && checkpoint.manifest_digest == pin.manifest_digest()
    });
    let retained_checkpoint = retention_anchor.is_some_and(|anchor| {
        let fields = anchor.fields();
        fields.base_visible_csn == pin.visible_csn()
            && fields.manifest_generation == pin.manifest_generation()
            && fields.manifest_digest == pin.manifest_digest()
            && fields.root_commit_lsn == pin.wal_lsn()
            && fields.root_commit_block_digest == pin.wal_digest()
    });
    recovered_checkpoint || retained_checkpoint
}

fn validate_retention_anchor(
    anchor: &WalRetentionAnchor,
    manifests: &[RootManifest],
) -> Result<RootSet, NativeRuntimeError> {
    let fields = anchor.fields();
    let manifest = manifest_by_generation(manifests, fields.manifest_generation)
        .ok_or(NativeRuntimeError::InvalidCheckpoint)?;
    let root = manifest.to_root_set()?;
    if manifest.generation() != fields.manifest_generation
        || manifest.generation().get() != fields.checkpoint_count
        || manifest.lineage() != anchor.lineage()
        || manifest.digest() != fields.manifest_digest
        || manifest.visible_csn() != fields.base_visible_csn
        || manifest.retention_floor_csn() != fields.base_visible_csn
        || manifest.wal_anchor().lsn != fields.root_commit_lsn
        || manifest.wal_anchor().digest != fields.root_commit_block_digest
        || root.visible_csn() != Some(fields.base_visible_csn)
        || root.retention_floor_csn() != Some(fields.base_visible_csn)
    {
        return Err(NativeRuntimeError::InvalidCheckpoint);
    }
    Ok(root)
}

fn validate_checkpoints(
    recovered: &RecoveredWal,
    manifests: &[RootManifest],
    committed_roots: &BTreeMap<Csn, RootSet>,
    base_anchor: Option<&WalRetentionAnchor>,
) -> Result<CheckpointValidation, NativeRuntimeError> {
    for checkpoint in &recovered.checkpoints {
        let manifest = manifest_by_generation(manifests, checkpoint.manifest_generation)
            .ok_or(NativeRuntimeError::InvalidCheckpoint)?;
        let committed_root = committed_roots
            .get(&checkpoint.visible_csn)
            .ok_or(NativeRuntimeError::InvalidCheckpoint)?;
        if manifest.generation() != checkpoint.manifest_generation
            || manifest.visible_csn() != checkpoint.visible_csn
            || manifest.digest() != checkpoint.manifest_digest
            || manifest.to_root_set()? != *committed_root
        {
            return Err(NativeRuntimeError::InvalidCheckpoint);
        }
    }
    let latest = recovered.checkpoints.last();
    let anchored_generation = latest
        .map(|checkpoint| checkpoint.manifest_generation)
        .or_else(|| base_anchor.map(|anchor| anchor.fields().manifest_generation));
    let unanchored_manifest_suffix = anchored_generation.map_or(manifests.len(), |generation| {
        manifests
            .iter()
            .filter(|manifest| manifest.generation() > generation)
            .count()
    });
    Ok(CheckpointValidation {
        last_checkpoint_lsn: latest
            .map(|checkpoint| checkpoint.checkpoint_lsn)
            .or_else(|| base_anchor.map(|anchor| anchor.fields().retired_checkpoint_lsn)),
        latest_visible_csn: latest
            .map(|checkpoint| checkpoint.visible_csn)
            .or_else(|| base_anchor.map(|anchor| anchor.fields().base_visible_csn)),
        latest_generation: latest
            .map(|checkpoint| checkpoint.manifest_generation)
            .or_else(|| base_anchor.map(|anchor| anchor.fields().manifest_generation)),
        latest_digest: latest
            .map(|checkpoint| checkpoint.manifest_digest)
            .or_else(|| base_anchor.map(|anchor| anchor.fields().manifest_digest)),
        unanchored_manifest_suffix,
    })
}

fn commit_transaction_at(
    transaction: NativeTransaction<'_>,
    interruption: Option<CommitBoundary>,
) -> Result<CommitReceipt, NativeRuntimeError> {
    match interruption {
        Some(boundary) => transaction.commit_with_interruption(boundary),
        None => transaction.commit(),
    }
}

fn validate_initial_ann_bulk_plan(
    authority: ann_store::InitialBulkAuthority,
    expected_base_identity: [u8; 32],
    expected_view_identity: [u8; 32],
    candidate: &PartitionedHnswIndex,
    build: InitialAnnBulkBuildEvidence,
) -> Result<(), NativeRuntimeError> {
    if authority.base_identity == expected_base_identity
        && authority.view_identity == expected_view_identity
        && candidate.input_identity() == build.input_identity
        && candidate.build_identity() == build.build_identity
        && candidate.len() == build.planned_vectors
        && candidate.partition_count() == build.planned_partitions
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InitialAnnBulkStale)
    }
}

fn validate_initial_ann_bulk_commit_authority(
    transaction: &RootTransaction<'_>,
    expected_roots: &RootSet,
    candidate_csn: Csn,
) -> Result<(), NativeRuntimeError> {
    if transaction.base_roots() == expected_roots && transaction.commit_csn()? == candidate_csn {
        Ok(())
    } else {
        Err(NativeRuntimeError::InitialAnnBulkStale)
    }
}

fn validate_published_initial_ann(
    observed: AnnIndexObservation,
    build: InitialAnnBulkBuildEvidence,
) -> Result<(), NativeRuntimeError> {
    if observed.base_identity == build.build_identity
        && observed.base_vector_count == build.planned_vectors
        && observed.delta_records == 0
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidAnnTree)
    }
}

#[allow(clippy::too_many_arguments)]
fn commit_engine_roots(
    pages: &mut PageStore,
    buffer_pool: &BufferPool,
    blobs: &BlobStore,
    mut roots: [Option<PageId>; 4],
    relational_format: RelationalFormat,
    structure_format: StructureFormat,
    search_format: SearchFormat,
    transaction_id: TransactionId,
    commit_csn: Csn,
    batch: &NativeWriteBatch,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<[Option<PageId>; 4], NativeRuntimeError> {
    validate_write_batch_shape(batch, &roots, structure_format, search_format)?;
    if batch.dirty[0] || roots[0].is_none() {
        roots[0] = catalog_root_after_mutations(
            pages,
            blobs,
            roots[0],
            commit_csn,
            &batch.state.catalog,
            &batch.mutations,
            blob_references,
        )?;
    }
    if batch.dirty[1] || roots[1].is_none() {
        roots[1] = relational_tree_after_mutations(
            pages,
            blobs,
            roots[1],
            relational_format,
            commit_csn,
            &batch.state.catalog,
            &batch.state.relational,
            &batch.mutations,
            blob_references,
        )?
        .root();
    }
    if batch.dirty[2] || roots[2].is_none() {
        roots[2] = structure_root_after_mutations(
            pages,
            roots[2],
            commit_csn,
            &StructureMutationContext {
                blobs,
                buffer_pool,
                format: structure_format,
                mode: batch.mode,
                transaction_id,
                logical_time_micros: batch.snapshot.logical_time_micros,
                state: &batch.state.structures,
                mutations: &batch.mutations,
                blob_references,
            },
        )?;
    }
    if batch.dirty[3] || roots[3].is_none() {
        roots[3] = search_root_after_mutations(
            pages,
            roots[3],
            commit_csn,
            &SearchMutationContext {
                format: search_format,
                mode: batch.mode,
                blobs,
                buffer_pool,
                catalog: &batch.state.catalog,
                state: &batch.state.search,
                mutations: &batch.mutations,
                blob_references,
                ann_consolidation: batch.ann_consolidation.as_ref(),
                ann_consolidation_structure: batch.ann_consolidation_structure.as_ref(),
                ann_initial_bulk: batch.ann_initial_bulk.as_ref(),
            },
        )?;
    }
    Ok(roots)
}

fn catalog_requires_full_rebuild(
    pages: &PageStore,
    root: Option<PageId>,
) -> Result<bool, NativeRuntimeError> {
    let Some(root) = root else {
        return Ok(true);
    };
    let page = pages.read(root)?;
    match page.kind() {
        PageKind::CatalogRoot => Ok(true),
        PageKind::BTreeLeaf | PageKind::BTreeInternal => {
            let marker = BTree::from_root(root)
                .get(pages, CATALOG_FORMAT_KEY)?
                .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
            match marker.as_slice() {
                CATALOG_FORMAT_VALUE_V7 => Ok(false),
                CATALOG_FORMAT_VALUE_V3
                | CATALOG_FORMAT_VALUE_V4
                | CATALOG_FORMAT_VALUE_V5
                | CATALOG_FORMAT_VALUE_V6 => Ok(true),
                _ => Err(NativeRuntimeError::InvalidCatalogTree),
            }
        }
        _ => Err(NativeRuntimeError::InvalidCatalogTree),
    }
}

#[allow(clippy::too_many_lines)]
fn catalog_root_after_mutations(
    pages: &mut PageStore,
    blobs: &BlobStore,
    root: Option<PageId>,
    commit_csn: Csn,
    catalog: &CatalogState,
    mutations: &[Mutation],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Option<PageId>, NativeRuntimeError> {
    let rebuild = catalog_requires_full_rebuild(pages, root)?
        || mutations.iter().any(|mutation| {
            matches!(
                mutation.opcode,
                Opcode::DropSecondaryIndex
                    | Opcode::DropTable
                    | Opcode::RenameTable
                    | Opcode::MigrateCatalogV7
            )
        });
    let tree = if rebuild {
        let secondary_indexes = catalog
            .objects
            .values()
            .filter(|object| matches!(object, CatalogObject::SecondaryIndex(_)))
            .count();
        let dependency_entries = catalog
            .objects
            .values()
            .map(CatalogObject::dependencies)
            .chain(
                catalog
                    .logical_objects
                    .values()
                    .map(LogicalCatalogObject::dependencies),
            )
            .try_fold(0_usize, |count, dependencies| {
                count
                    .checked_add(dependencies.len().saturating_mul(2))
                    .ok_or(NativeRuntimeError::InvalidCatalogTree)
            })?;
        let mut entries = Vec::with_capacity(
            catalog
                .objects
                .len()
                .checked_mul(2)
                .and_then(|count| count.checked_add(secondary_indexes))
                .and_then(|count| {
                    count.checked_add(catalog.logical_objects.len().saturating_mul(2))
                })
                .and_then(|count| count.checked_add(dependency_entries))
                .and_then(|count| count.checked_add(2))
                .ok_or(NativeRuntimeError::InvalidCatalogTree)?,
        );
        entries.push((
            CATALOG_FORMAT_KEY.to_vec(),
            CATALOG_FORMAT_VALUE_V7.to_vec(),
        ));
        entries.push((
            CATALOG_ID_AUTHORITY_KEY.to_vec(),
            catalog
                .next_object_id_raw()
                .unwrap_or(0)
                .to_be_bytes()
                .to_vec(),
        ));
        for object in catalog.objects.values() {
            append_catalog_object_entries(&mut entries, object, blob_references)?;
            append_catalog_ancestor_entries(&mut entries, catalog, object.header().id)?;
        }
        for object in catalog.logical_objects.values() {
            append_logical_catalog_object_entries(&mut entries, object, blob_references)?;
            append_catalog_ancestor_entries(&mut entries, catalog, object.id())?;
        }
        entries.sort_by(|left, right| left.0.cmp(&right.0));
        BTree::empty()
            .upsert_sorted_batch(pages, commit_csn, entries)?
            .tree
    } else {
        let root = root.ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        let existing = BTree::from_root(root);
        let mut entries = Vec::new();
        entries.push((
            CATALOG_ID_AUTHORITY_KEY.to_vec(),
            catalog
                .next_object_id_raw()
                .unwrap_or(0)
                .to_be_bytes()
                .to_vec(),
        ));
        for mutation in mutations
            .iter()
            .filter(|mutation| is_catalog_creation(mutation.opcode))
        {
            let object = catalog_object_from_creation_mutation(mutation)?;
            let object_key = catalog_object_key(object.id());
            let name_key = catalog_name_key_from_qualified(object.name())?;
            if existing.get(pages, &object_key)?.is_some()
                || existing.get(pages, &name_key)?.is_some()
            {
                return Err(NativeRuntimeError::InvalidCatalogTree);
            }
            append_any_catalog_object_entries(&mut entries, &object, blob_references)?;
            append_catalog_ancestor_entries(&mut entries, catalog, object.id())?;
        }
        entries.sort_by(|left, right| left.0.cmp(&right.0));
        existing
            .upsert_sorted_batch(pages, commit_csn, entries)?
            .tree
    };
    let root = tree.root().ok_or(NativeRuntimeError::InvalidCatalogTree)?;
    if load_catalog_state_root(pages, blobs, root)? != *catalog {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    Ok(Some(root))
}

fn append_catalog_object_entries(
    entries: &mut Vec<(Vec<u8>, Vec<u8>)>,
    object: &CatalogObject,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<(), NativeRuntimeError> {
    let definition = object.encode_definition()?;
    entries.push((
        catalog_object_key(object.header().id),
        catalog_definition_storage_value(&definition, blob_references)?,
    ));
    entries.push((
        catalog_name_key(object.header())?,
        object.header().id.get().to_be_bytes().to_vec(),
    ));
    if let CatalogObject::SecondaryIndex(definition) = object {
        entries.push((
            catalog_relation_index_key(definition.relation, definition.header.id),
            Vec::new(),
        ));
    }
    for edge in object.dependencies() {
        entries.push((
            catalog_dependency_key(edge, DependencyDirection::Outgoing),
            Vec::new(),
        ));
        entries.push((
            catalog_dependency_key(edge, DependencyDirection::Incoming),
            Vec::new(),
        ));
    }
    Ok(())
}

fn append_logical_catalog_object_entries(
    entries: &mut Vec<(Vec<u8>, Vec<u8>)>,
    object: &LogicalCatalogObject,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<(), NativeRuntimeError> {
    let definition = object.encode_definition_v2()?;
    entries.push((
        catalog_object_key(object.id()),
        catalog_definition_storage_value(&definition, blob_references)?,
    ));
    entries.push((
        catalog_name_key_from_qualified(object.name())?,
        object.id().get().to_be_bytes().to_vec(),
    ));
    for edge in object.dependencies() {
        entries.push((
            catalog_dependency_key(edge, DependencyDirection::Outgoing),
            Vec::new(),
        ));
        entries.push((
            catalog_dependency_key(edge, DependencyDirection::Incoming),
            Vec::new(),
        ));
    }
    Ok(())
}

enum PersistedCatalogObject {
    Legacy(CatalogObject),
    Logical(LogicalCatalogObject),
}

impl PersistedCatalogObject {
    const fn id(&self) -> ObjectId {
        match self {
            Self::Legacy(object) => object.header().id,
            Self::Logical(object) => object.id(),
        }
    }

    const fn name(&self) -> &QualifiedName {
        match self {
            Self::Legacy(object) => &object.header().name,
            Self::Logical(object) => object.name(),
        }
    }
}

fn append_any_catalog_object_entries(
    entries: &mut Vec<(Vec<u8>, Vec<u8>)>,
    object: &PersistedCatalogObject,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<(), NativeRuntimeError> {
    match object {
        PersistedCatalogObject::Legacy(object) => {
            append_catalog_object_entries(entries, object, blob_references)
        }
        PersistedCatalogObject::Logical(object) => {
            append_logical_catalog_object_entries(entries, object, blob_references)
        }
    }
}

fn append_catalog_ancestor_entries(
    entries: &mut Vec<(Vec<u8>, Vec<u8>)>,
    catalog: &CatalogState,
    descendant: ObjectId,
) -> Result<(), NativeRuntimeError> {
    let mut ancestor = Some(descendant);
    let mut visited = BTreeSet::new();
    while let Some(current) = ancestor {
        if !visited.insert(current) {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        entries.push((
            catalog_ancestor_descendant_key(current, descendant),
            Vec::new(),
        ));
        ancestor = catalog.parent(current);
    }
    Ok(())
}

fn catalog_definition_storage_value(
    definition: &[u8],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Vec<u8>, NativeRuntimeError> {
    let uses_blob = definition.len() > CATALOG_INLINE_VALUE_LIMIT;
    let payload_length = if uses_blob {
        hyphae_native_records::BLOB_REFERENCE_SIZE
    } else {
        definition.len()
    };
    let mut encoded = Vec::with_capacity(CATALOG_VALUE_HEADER_SIZE + payload_length);
    encoded.extend_from_slice(CATALOG_VALUE_MAGIC);
    encoded.push(if uses_blob {
        CATALOG_VALUE_BLOB
    } else {
        CATALOG_VALUE_INLINE
    });
    encoded.extend_from_slice(&[0; 7]);
    if uses_blob {
        let digest = *blake3::hash(definition).as_bytes();
        let reference = blob_references
            .get(&digest)
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?;
        encoded.extend_from_slice(&reference.encode());
    } else {
        encoded.extend_from_slice(definition);
    }
    Ok(encoded)
}

fn catalog_object_key(id: ObjectId) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(CATALOG_OBJECT_PREFIX);
    key.extend_from_slice(&id.get().to_be_bytes());
    key
}

fn decode_catalog_object_key(key: &[u8]) -> Result<ObjectId, NativeRuntimeError> {
    if key.len() != 17 || key.first() != Some(&CATALOG_OBJECT_PREFIX) {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    ObjectId::new(u128::from_be_bytes(
        key[1..]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)
}

fn catalog_ancestor_descendant_prefix(ancestor: ObjectId) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(CATALOG_ANCESTOR_DESCENDANT_PREFIX);
    key.extend_from_slice(&ancestor.get().to_be_bytes());
    key
}

fn catalog_ancestor_descendant_key(ancestor: ObjectId, descendant: ObjectId) -> Vec<u8> {
    let mut key = catalog_ancestor_descendant_prefix(ancestor);
    key.extend_from_slice(&descendant.get().to_be_bytes());
    key
}

fn decode_catalog_ancestor_descendant_entry(
    key: &[u8],
    value: &[u8],
) -> Result<(ObjectId, ObjectId), NativeRuntimeError> {
    if key.len() != 33
        || key.first() != Some(&CATALOG_ANCESTOR_DESCENDANT_PREFIX)
        || !value.is_empty()
    {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let ancestor = ObjectId::new(u128::from_be_bytes(
        key[1..17]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    let descendant = ObjectId::new(u128::from_be_bytes(
        key[17..]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    Ok((ancestor, descendant))
}

fn decode_catalog_name_value(value: &[u8]) -> Result<ObjectId, NativeRuntimeError> {
    if value.len() != 16 {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    ObjectId::new(u128::from_be_bytes(
        value
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)
}

fn catalog_dependency_prefix(object: ObjectId, direction: DependencyDirection) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(match direction {
        DependencyDirection::Outgoing => CATALOG_DEPENDENCY_OUTGOING_PREFIX,
        DependencyDirection::Incoming => CATALOG_DEPENDENCY_INCOMING_PREFIX,
    });
    key.extend_from_slice(&object.get().to_be_bytes());
    key
}

fn catalog_dependency_cursor_key(
    object: ObjectId,
    direction: DependencyDirection,
    adjacent: ObjectId,
) -> Vec<u8> {
    let mut key = catalog_dependency_prefix(object, direction);
    key.extend_from_slice(&adjacent.get().to_be_bytes());
    key.push(u8::MAX);
    key
}

fn catalog_dependency_key(edge: DependencyEdge, direction: DependencyDirection) -> Vec<u8> {
    let (object, adjacent) = match direction {
        DependencyDirection::Outgoing => (edge.dependent, edge.prerequisite),
        DependencyDirection::Incoming => (edge.prerequisite, edge.dependent),
    };
    let mut key = catalog_dependency_prefix(object, direction);
    key.extend_from_slice(&adjacent.get().to_be_bytes());
    key.push(edge.kind as u8);
    key
}

fn decode_catalog_dependency_entry(
    key: &[u8],
    value: &[u8],
    direction: DependencyDirection,
) -> Result<(DependencyEdge, ObjectId), NativeRuntimeError> {
    let expected_prefix = match direction {
        DependencyDirection::Outgoing => CATALOG_DEPENDENCY_OUTGOING_PREFIX,
        DependencyDirection::Incoming => CATALOG_DEPENDENCY_INCOMING_PREFIX,
    };
    if key.len() != 34 || key.first() != Some(&expected_prefix) || !value.is_empty() {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let object = ObjectId::new(u128::from_be_bytes(
        key[1..17]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    let adjacent = ObjectId::new(u128::from_be_bytes(
        key[17..33]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    let kind = match key[33] {
        1 => DependencyKind::Parent,
        2 => DependencyKind::SecondaryIndexRelation,
        3 => DependencyKind::ForeignKey,
        4 => DependencyKind::Analyzer,
        5 => DependencyKind::LinkEndpoint,
        6 => DependencyKind::RelationSchema,
        _ => return Err(NativeRuntimeError::InvalidCatalogTree),
    };
    let edge = match direction {
        DependencyDirection::Outgoing => DependencyEdge::new(object, adjacent, kind),
        DependencyDirection::Incoming => DependencyEdge::new(adjacent, object, kind),
    };
    Ok((edge, adjacent))
}

fn decode_logical_catalog_definition(
    definition: &[u8],
    id: ObjectId,
) -> Result<LogicalCatalogObject, NativeRuntimeError> {
    if !definition.starts_with(b"HYCOBJ02") {
        let object = CatalogObject::decode_definition(definition)?;
        if object.header().id != id {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        return Ok(LogicalCatalogObject::from_legacy(object));
    }
    let object = LogicalCatalogObject::decode_definition_v2(definition)?;
    if object.id() != id {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    Ok(object)
}

fn logical_catalog_summary(object: &LogicalCatalogObject) -> CatalogObjectSummary {
    CatalogObjectSummary {
        id: object.id(),
        kind: object.kind(),
        owner: object.owner(),
        name: object.name().clone(),
        parent: object.parent(),
    }
}

fn catalog_summary_bytes(summary: &CatalogObjectSummary) -> Result<usize, NativeRuntimeError> {
    [
        summary.name.database.display(),
        summary.name.database.lookup(),
        summary.name.schema.display(),
        summary.name.schema.lookup(),
        summary.name.object.display(),
        summary.name.object.lookup(),
    ]
    .into_iter()
    .try_fold(
        43_usize + usize::from(summary.parent.is_some()) * 16,
        |total, value| {
            total
                .checked_add(value.len())
                .ok_or(NativeRuntimeError::InvalidCatalogTree)
        },
    )
}

fn validate_catalog_read_limits(
    item_limit: usize,
    visit_limit: usize,
    byte_limit: usize,
) -> Result<(), NativeRuntimeError> {
    if !(1..=MAX_CATALOG_READ_ITEMS).contains(&item_limit)
        || !(1..=MAX_CATALOG_READ_VISITS).contains(&visit_limit)
        || !(1..=MAX_CATALOG_READ_BYTES).contains(&byte_limit)
    {
        return Err(NativeRuntimeError::InvalidCatalogReadLimit);
    }
    Ok(())
}

fn catalog_relation_index_prefix(relation: ObjectId) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(CATALOG_RELATION_INDEX_PREFIX);
    key.extend_from_slice(&relation.get().to_be_bytes());
    key
}

fn catalog_relation_index_key(relation: ObjectId, index: ObjectId) -> Vec<u8> {
    let mut key = catalog_relation_index_prefix(relation);
    key.reserve(16);
    key.extend_from_slice(&index.get().to_be_bytes());
    key
}

fn catalog_name_key(header: &ObjectHeader) -> Result<Vec<u8>, NativeRuntimeError> {
    catalog_name_key_from_qualified(&header.name)
}

fn catalog_name_key_from_qualified(name: &QualifiedName) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = catalog_name_identity_from_qualified(name)?;
    let mut key = Vec::with_capacity(
        identity
            .len()
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidCatalogTree)?,
    );
    key.push(CATALOG_NAME_PREFIX);
    key.extend_from_slice(&identity);
    if key.len() > BTREE_MAX_KEY_SIZE {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    Ok(key)
}

const fn is_catalog_creation(opcode: Opcode) -> bool {
    matches!(
        opcode,
        Opcode::CreateTable
            | Opcode::CreateSecondaryIndex
            | Opcode::CreateIndex
            | Opcode::CreateAnnIndex
            | Opcode::CreateCatalogObjectV2
    )
}

fn catalog_object_from_creation_mutation(
    mutation: &Mutation,
) -> Result<PersistedCatalogObject, NativeRuntimeError> {
    let id = mutation
        .target
        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
    match (mutation.engine, mutation.opcode) {
        (EngineKind::Relational, Opcode::CreateTable) => {
            decode_relation_creation(id, mutation).map(PersistedCatalogObject::Legacy)
        }
        (EngineKind::Relational, Opcode::CreateSecondaryIndex) => {
            decode_secondary_index_creation(id, mutation).map(PersistedCatalogObject::Legacy)
        }
        (EngineKind::Search, Opcode::CreateIndex) => {
            decode_search_creation(id, mutation).map(PersistedCatalogObject::Legacy)
        }
        (EngineKind::Search, Opcode::CreateAnnIndex) => decode_ann_creation(id, mutation)
            .map(|(object, _)| PersistedCatalogObject::Legacy(object)),
        (EngineKind::Kernel, Opcode::CreateCatalogObjectV2) => {
            let object = LogicalCatalogObject::decode_definition_v2(&mutation.value)?;
            if object.id() != id
                || mutation.key != catalog_name_identity_from_qualified(object.name())?
                || mutation.expires_at_micros.is_some()
            {
                return Err(NativeRuntimeError::InvalidPreparedMutation);
            }
            Ok(PersistedCatalogObject::Logical(object))
        }
        _ => Err(NativeRuntimeError::InvalidPreparedMutation),
    }
}

struct PageGenerationBuildContext<'database> {
    data_directory: &'database Path,
    source: &'database PageStore,
    blobs: &'database BlobStore,
    base_roots: &'database RootSet,
    formats: (RelationalFormat, StructureFormat, SearchFormat),
    generation: PageGeneration,
    vacuum_csn: Csn,
}

struct BuiltPageGeneration {
    temporary_path: PathBuf,
    final_path: PathBuf,
    roots: [PageId; 4],
    page_count: u64,
}

struct VacuumWalContext {
    transaction_id: TransactionId,
    read_csn: Option<Csn>,
    catalog_version: CatalogVersion,
    commit_csn: Csn,
    roots: [PageId; 4],
    blob_generation: u64,
    page_generation: PageGeneration,
}

struct VacuumWalReceipt {
    lsn: Lsn,
    digest: [u8; 32],
    append_time: Duration,
    synchronization_time: Duration,
}

fn append_vacuum_wal(
    wal: &mut WalFile,
    context: &VacuumWalContext,
    interruption: Option<VacuumBoundary>,
) -> Result<VacuumWalReceipt, NativeRuntimeError> {
    let mutations = [Mutation {
        engine: EngineKind::Kernel,
        opcode: Opcode::VacuumPageGeneration,
        target: None,
        key: Vec::new(),
        value: Vec::new(),
        expires_at_micros: None,
    }];
    let mut pending = encode_transaction(&TransactionPlan {
        transaction_id: context.transaction_id,
        read_csn: context.read_csn,
        catalog_version: context.catalog_version,
        logical_time_micros: 0,
        durability: DurabilityClass::Strict,
        mutations: &mutations,
        commit_csn: context.commit_csn,
        roots: context.roots,
        blob_generation: context.blob_generation,
        page_generation: context.page_generation,
        retention_floor_csn: context.commit_csn,
    })?;
    let commit_record = pending.pop().ok_or(WalError::EmptyBlock)?;
    let append_started = Instant::now();
    wal.append_records(pending, false)?;
    interrupt_vacuum(interruption, VacuumBoundary::WalAppended)?;
    let receipts = wal.append_records(vec![commit_record], false)?;
    let append_time = append_started.elapsed();
    let synchronization_started = Instant::now();
    wal.sync_data()?;
    let synchronization_time = synchronization_started.elapsed();
    interrupt_vacuum(interruption, VacuumBoundary::WalSynchronized)?;
    let block = receipts.last().ok_or(WalError::EmptyBlock)?;
    Ok(VacuumWalReceipt {
        lsn: block.last_lsn,
        digest: block.digest,
        append_time,
        synchronization_time,
    })
}

fn vacuum_write_key() -> WriteKey {
    WriteKey::new(EngineKind::Kernel, None, vec![u8::MAX])
}

fn build_page_generation_candidate(
    context: &PageGenerationBuildContext<'_>,
    interruption: Option<VacuumBoundary>,
) -> Result<BuiltPageGeneration, NativeRuntimeError> {
    let temporary_path = page_generation_temporary_path(context.data_directory, context.generation);
    let final_path = page_generation_path(context.data_directory, context.generation);
    let mut candidate = PageStore::create_generation(&temporary_path, context.generation)?;
    let roots = match rebuild_page_generation(
        context.source,
        &mut candidate,
        context.blobs,
        context.base_roots,
        context.formats,
        context.vacuum_csn,
    ) {
        Ok(roots) => roots,
        Err(source) => {
            drop(candidate);
            fs::remove_file(&temporary_path)?;
            return Err(source);
        }
    };
    if let Err(source) = candidate.sync_data() {
        drop(candidate);
        fs::remove_file(&temporary_path)?;
        return Err(source.into());
    }
    interrupt_vacuum(interruption, VacuumBoundary::CandidateSynchronized)?;
    let page_count = candidate.page_count();
    drop(candidate);
    Ok(BuiltPageGeneration {
        temporary_path,
        final_path,
        roots,
        page_count,
    })
}

fn page_vacuum_noop(generation: PageGeneration, page_count: u64) -> PageVacuumReceipt {
    PageVacuumReceipt {
        applied: false,
        previous_generation: generation,
        active_generation: generation,
        previous_page_count: page_count,
        active_page_count: page_count,
        reclaimed_pages: 0,
        commit: None,
    }
}

fn rebuild_page_generation(
    source: &PageStore,
    candidate: &mut PageStore,
    blobs: &BlobStore,
    base_roots: &RootSet,
    formats: (RelationalFormat, StructureFormat, SearchFormat),
    vacuum_csn: Csn,
) -> Result<[PageId; 4], NativeRuntimeError> {
    let source_state = load_state(source, blobs, base_roots)?;
    let source_roots = require_roots(roots_from_snapshot(base_roots))?;
    let catalog = match source.read(source_roots[0])?.kind() {
        PageKind::CatalogRoot => copy_root_page(
            source,
            candidate,
            source_roots[0],
            PageKind::CatalogRoot,
            vacuum_csn,
        )?,
        PageKind::BTreeLeaf | PageKind::BTreeInternal => {
            rebuild_btree_root(source, candidate, source_roots[0], vacuum_csn)?
        }
        _ => return Err(NativeRuntimeError::InvalidCatalogTree),
    };
    let relational =
        rebuild_relational_root(source, candidate, source_roots[1], formats.0, vacuum_csn)?;
    let structures = match formats.1 {
        StructureFormat::InlineStateV1 => copy_root_page(
            source,
            candidate,
            source_roots[2],
            PageKind::StructureNode,
            vacuum_csn,
        )?,
        StructureFormat::BTreeV1 | StructureFormat::BTreeV2 | StructureFormat::BTreeV3 => {
            rebuild_btree_root(source, candidate, source_roots[2], vacuum_csn)?
        }
    };
    let search = match formats.2 {
        SearchFormat::InlineStateV1 => copy_root_page(
            source,
            candidate,
            source_roots[3],
            PageKind::SearchDelta,
            vacuum_csn,
        )?,
        SearchFormat::InvertedBTreeV1 => {
            rebuild_btree_root(source, candidate, source_roots[3], vacuum_csn)?
        }
    };
    let roots = [catalog, relational, structures, search];
    let candidate_roots = RootSet::committed_with_storage(
        vacuum_csn,
        base_roots.catalog_version(),
        base_roots
            .wal_anchor()
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?,
        root_map(roots),
        base_roots.blob_generation(),
        candidate.generation(),
        vacuum_csn,
    )?;
    validate_roots(candidate, blobs, &candidate_roots, vacuum_csn)?;
    if load_state(candidate, blobs, &candidate_roots)? != source_state {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    Ok(roots)
}

fn copy_root_page(
    source: &PageStore,
    candidate: &mut PageStore,
    source_root: PageId,
    expected_kind: PageKind,
    vacuum_csn: Csn,
) -> Result<PageId, NativeRuntimeError> {
    let page = source.read(source_root)?;
    if page.kind() != expected_kind || page.next().is_some() {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    Ok(candidate.append(
        expected_kind,
        Some(vacuum_csn),
        None,
        page.payload().to_vec(),
    )?)
}

fn rebuild_btree_root(
    source: &PageStore,
    candidate: &mut PageStore,
    source_root: PageId,
    vacuum_csn: Csn,
) -> Result<PageId, NativeRuntimeError> {
    let entries = BTree::from_root(source_root).scan(source)?;
    BTree::empty()
        .upsert_sorted_batch(candidate, vacuum_csn, entries)?
        .tree
        .root()
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)
}

fn rebuild_relational_root(
    source: &PageStore,
    candidate: &mut PageStore,
    source_root: PageId,
    format: RelationalFormat,
    vacuum_csn: Csn,
) -> Result<PageId, NativeRuntimeError> {
    let mut entries = BTree::from_root(source_root).scan(source)?;
    if format == RelationalFormat::VersionChainV2 {
        for (key, value) in &mut entries {
            if key.first() != Some(&RELATIONAL_ROW_PREFIX) {
                continue;
            }
            let pointer = RowVersionPointer::decode(value)?;
            let head = source.read(pointer.page_id)?;
            if head.kind() != PageKind::VersionChain {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
            let row = RowRecord::decode(head.payload())?;
            if row.end_csn().is_some() {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
            let page_id = candidate.append(
                PageKind::VersionChain,
                Some(row.begin_csn()),
                None,
                head.payload().to_vec(),
            )?;
            *value = RowVersionPointer { page_id }.encode().to_vec();
        }
    }
    BTree::empty()
        .upsert_sorted_batch(candidate, vacuum_csn, entries)?
        .tree
        .root()
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)
}

fn validate_write_batch_shape(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    reject_unsupported_v3_structure_mutations(structure_format, batch)?;
    match batch.mode {
        NativeWriteBatchMode::Materialized => Ok(()),
        NativeWriteBatchMode::PhysicalAllEngineDelta => {
            validate_delta_write_batch_shape(batch, roots, structure_format, search_format)
        }
        NativeWriteBatchMode::PhysicalStructureExpiry => {
            validate_physical_structure_expiry(batch, roots, structure_format, search_format)
        }
        NativeWriteBatchMode::PhysicalStructureCompaction => validate_physical_compaction(
            batch,
            roots,
            structure_format,
            search_format,
            EngineKind::Structure,
            Opcode::CompactStructure,
        ),
        NativeWriteBatchMode::PhysicalStructureMigrationV3 => {
            validate_physical_structure_v3_migration(batch, roots, structure_format, search_format)
        }
        NativeWriteBatchMode::PhysicalStructureRetirementV3 => {
            validate_physical_structure_v3_retirement(batch, roots, structure_format, search_format)
        }
        NativeWriteBatchMode::PhysicalSearchCompaction => validate_physical_compaction(
            batch,
            roots,
            structure_format,
            search_format,
            EngineKind::Search,
            Opcode::CompactSearch,
        ),
        NativeWriteBatchMode::PhysicalAnnConsolidation => {
            validate_physical_ann_consolidation(batch, roots, structure_format, search_format)
        }
        NativeWriteBatchMode::PhysicalInitialAnnBulkPublication => {
            validate_physical_initial_ann_bulk(batch, roots, structure_format, search_format)
        }
    }
}

fn validate_physical_structure_v3_migration(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_mutation = matches!(batch.mutations.as_slice(), [mutation]
        if mutation.engine == EngineKind::Structure
            && mutation.opcode == Opcode::MigrateStructureV3
            && mutation.target.is_none()
            && mutation.key.is_empty()
            && mutation.value.is_empty()
            && mutation.expires_at_micros.is_none());
    if roots.iter().all(Option::is_some)
        && matches!(
            structure_format,
            StructureFormat::BTreeV2 | StructureFormat::BTreeV3
        )
        && batch.structure_format == structure_format
        && batch.search_format == search_format
        && batch.state == MaterializedState::default()
        && batch.dirty == [false, false, true, false]
        && batch.delta.is_none()
        && batch.ann_consolidation.is_none()
        && batch.ann_initial_bulk.is_none()
        && valid_mutation
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_physical_structure_v3_retirement(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_mutation = matches!(batch.mutations.as_slice(), [mutation]
        if validate_maintenance_mutation(mutation).is_ok()
            && mutation.opcode == Opcode::CleanupStructureRetirementV3);
    if roots.iter().all(Option::is_some)
        && structure_format == StructureFormat::BTreeV3
        && batch.structure_format == StructureFormat::BTreeV3
        && batch.search_format == search_format
        && batch.state == MaterializedState::default()
        && batch.dirty == [false, false, true, false]
        && batch.delta.is_none()
        && batch.ann_consolidation.is_none()
        && batch.ann_initial_bulk.is_none()
        && valid_mutation
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn reject_unsupported_v3_structure_mutations(
    structure_format: StructureFormat,
    batch: &NativeWriteBatch,
) -> Result<(), NativeRuntimeError> {
    if structure_format == StructureFormat::BTreeV3
        && batch.mode != NativeWriteBatchMode::PhysicalStructureCompaction
        && batch.mode != NativeWriteBatchMode::PhysicalStructureExpiry
        && batch.mode != NativeWriteBatchMode::PhysicalStructureRetirementV3
        && !is_materialized_v3_structure_write_batch(batch)
        && !is_delta_v3_structure_write_batch(batch)
        && (batch.dirty[2]
            || batch
                .mutations
                .iter()
                .any(|mutation| mutation.engine == EngineKind::Structure))
    {
        Err(NativeRuntimeError::StructureV3MutationUnsupported)
    } else {
        Ok(())
    }
}

fn is_delta_v3_structure_write_batch(batch: &NativeWriteBatch) -> bool {
    batch.mode == NativeWriteBatchMode::PhysicalAllEngineDelta
        && batch.structure_format == StructureFormat::BTreeV3
        && batch
            .mutations
            .iter()
            .filter(|mutation| mutation.engine == EngineKind::Structure)
            .all(is_supported_v3_structure_mutation)
}

fn is_materialized_v3_structure_write_batch(batch: &NativeWriteBatch) -> bool {
    batch.mode == NativeWriteBatchMode::Materialized
        && batch.dirty[2]
        && batch
            .mutations
            .iter()
            .any(|mutation| mutation.engine == EngineKind::Structure)
        && batch
            .mutations
            .iter()
            .filter(|mutation| mutation.engine == EngineKind::Structure)
            .all(is_supported_v3_structure_mutation)
}

fn is_supported_v3_structure_mutation(mutation: &Mutation) -> bool {
    if mutation.target.is_some() {
        return false;
    }
    match mutation.opcode {
        Opcode::SetValue => return true,
        Opcode::ExpireValue => return mutation.expires_at_micros.is_some(),
        Opcode::DeleteValue => {
            return mutation.value.is_empty() && mutation.expires_at_micros.is_none();
        }
        _ => {}
    }
    if matches!(
        mutation.opcode,
        Opcode::ExpireHash
            | Opcode::ExpireHashField
            | Opcode::ExpireSet
            | Opcode::ExpireList
            | Opcode::ExpireStream
            | Opcode::ExpireSortedSet
    ) {
        return mutation.value.is_empty() && mutation.expires_at_micros.is_some();
    }
    if mutation.expires_at_micros.is_some() {
        return false;
    }
    match mutation.opcode {
        Opcode::CreateHash
        | Opcode::DeleteHash
        | Opcode::CreateSet
        | Opcode::DeleteSet
        | Opcode::CreateList
        | Opcode::DeleteList
        | Opcode::CreateStream
        | Opcode::DeleteStream
        | Opcode::CreateSortedSet
        | Opcode::DeleteSortedSet
        | Opcode::AddSetMember
        | Opcode::DeleteHashField
        | Opcode::DeleteSetMember
        | Opcode::DeleteSortedSetMember => mutation.value.is_empty(),
        Opcode::SetHashField
        | Opcode::PushListHead
        | Opcode::PushListTail
        | Opcode::PopListHead
        | Opcode::PopListTail => true,
        Opcode::AppendStreamEntry => decode_stream_wal_entry(&mutation.value).is_ok(),
        Opcode::UpsertSortedSetMember => decode_sorted_set_wal_score(&mutation.value).is_ok(),
        _ => false,
    }
}

fn validate_physical_structure_expiry(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_mutations = !batch.mutations.is_empty()
        && batch.mutations.iter().all(|mutation| {
            mutation.engine == EngineKind::Structure
                && matches!(
                    mutation.opcode,
                    Opcode::DeleteValue
                        | Opcode::DeleteHash
                        | Opcode::DeleteSet
                        | Opcode::DeleteList
                        | Opcode::DeleteStream
                        | Opcode::DeleteSortedSet
                        | Opcode::DeleteHashField
                )
                && mutation.target.is_none()
                && mutation.value.is_empty()
                && mutation.expires_at_micros.is_none()
        });
    if roots.iter().all(Option::is_some)
        && matches!(
            structure_format,
            StructureFormat::BTreeV2 | StructureFormat::BTreeV3
        )
        && batch.structure_format == structure_format
        && batch.search_format == search_format
        && batch.state == MaterializedState::default()
        && batch.dirty == [false, false, true, false]
        && valid_mutations
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_physical_compaction(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
    engine: EngineKind,
    opcode: Opcode,
) -> Result<(), NativeRuntimeError> {
    let valid_formats = if engine == EngineKind::Structure {
        matches!(
            structure_format,
            StructureFormat::BTreeV2 | StructureFormat::BTreeV3
        ) && batch.structure_format == structure_format
            && batch.search_format == search_format
    } else {
        search_format == SearchFormat::InvertedBTreeV1
            && batch.search_format == SearchFormat::InvertedBTreeV1
            && batch.structure_format == structure_format
    };
    let dirty = if engine == EngineKind::Structure {
        [false, false, true, false]
    } else {
        [false, false, false, true]
    };
    let valid_mutation = matches!(batch.mutations.as_slice(), [mutation]
        if mutation.engine == engine
            && mutation.opcode == opcode
            && mutation.target.is_none()
            && mutation.key.is_empty()
            && mutation.value.is_empty()
            && mutation.expires_at_micros.is_none());
    if roots.iter().all(Option::is_some)
        && valid_formats
        && batch.state == MaterializedState::default()
        && batch.dirty == dirty
        && valid_mutation
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_physical_ann_consolidation(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_plan = batch.ann_consolidation.as_ref().is_some_and(|plan| {
        matches!(batch.mutations.as_slice(), [mutation]
            if mutation.engine == EngineKind::Search
                && mutation.opcode == Opcode::ConsolidateAnn
                && mutation.target == Some(plan.index())
                && mutation.key.is_empty()
                && mutation.value == ann_store::encode_consolidation_mutation(plan)
                && mutation.expires_at_micros.is_none())
    });
    if roots.iter().all(Option::is_some)
        && search_format == SearchFormat::InvertedBTreeV1
        && batch.search_format == SearchFormat::InvertedBTreeV1
        && batch.structure_format == structure_format
        && batch.state.relational == RelationState::default()
        && batch.state.structures == StructureState::default()
        && batch.state.search == SearchState::default()
        && batch.state.ann == ann_store::AnnState::default()
        && batch.dirty == [false, false, false, true]
        && batch.delta.is_none()
        && batch.ann_initial_bulk.is_none()
        && valid_plan
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_physical_initial_ann_bulk(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_plan = batch.ann_initial_bulk.as_ref().is_some_and(|plan| {
        matches!(batch.mutations.as_slice(), [mutation]
            if mutation.engine == EngineKind::Search
                && mutation.opcode == Opcode::PublishInitialAnnBulk
                && mutation.target == Some(plan.index)
                && mutation.key.is_empty()
                && mutation.expires_at_micros.is_none()
                && ann_store::encode_initial_bulk_publication(plan)
                    .is_ok_and(|encoded| mutation.value == encoded))
    });
    if roots.iter().all(Option::is_some)
        && search_format == SearchFormat::InvertedBTreeV1
        && batch.search_format == SearchFormat::InvertedBTreeV1
        && batch.structure_format == structure_format
        && batch.state.relational == RelationState::default()
        && batch.state.structures == StructureState::default()
        && batch.state.search == SearchState::default()
        && batch.state.ann == ann_store::AnnState::default()
        && batch.dirty == [false, false, false, true]
        && batch.delta.is_none()
        && batch.ann_consolidation.is_none()
        && valid_plan
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_delta_write_batch_shape(
    batch: &NativeWriteBatch,
    roots: &[Option<PageId>; 4],
    structure_format: StructureFormat,
    search_format: SearchFormat,
) -> Result<(), NativeRuntimeError> {
    let valid_roots = roots.iter().all(Option::is_some)
        || (batch.snapshot.visible_csn.is_none() && roots.iter().all(Option::is_none));
    let valid_formats = matches!(
        structure_format,
        StructureFormat::BTreeV2 | StructureFormat::BTreeV3
    ) && batch.structure_format == structure_format
        && search_format == SearchFormat::InvertedBTreeV1
        && batch.search_format == SearchFormat::InvertedBTreeV1;
    let valid_stage_boundary = !batch.delta_stage_active;
    let Some(delta) = batch.delta.as_ref() else {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    };
    let mut expected_dirty = [false; 4];
    let valid_mutations = !batch.mutations.is_empty()
        && batch
            .mutations
            .iter()
            .all(|mutation| match mutation.engine {
                EngineKind::Relational => {
                    expected_dirty[1] = true;
                    mutation.target.is_some_and(|table| {
                        delta
                            .relational_rows
                            .contains(&(table, mutation.key.clone()))
                    }) && matches!(
                        mutation.opcode,
                        Opcode::InsertRow | Opcode::UpdateRow | Opcode::DeleteRow
                    ) && mutation.expires_at_micros.is_none()
                }
                EngineKind::Structure => {
                    expected_dirty[2] = true;
                    let scalar_shape = delta.structure_scalars.contains(&mutation.key)
                        && match mutation.opcode {
                            Opcode::SetValue => true,
                            Opcode::DeleteHash
                            | Opcode::DeleteSet
                            | Opcode::DeleteList
                            | Opcode::DeleteStream
                            | Opcode::DeleteSortedSet => {
                                mutation.value.is_empty() && mutation.expires_at_micros.is_none()
                            }
                            _ => false,
                        };
                    let hash_field_shape =
                        matches!(
                            mutation.opcode,
                            Opcode::SetHashField | Opcode::DeleteHashField
                        ) && decode_hash_field_identity(&mutation.key).is_ok_and(|(key, field)| {
                            delta
                                .structure_hash_fields
                                .contains_key(&(key.to_vec(), field.to_vec()))
                        }) && mutation.expires_at_micros.is_none()
                            && (mutation.opcode != Opcode::DeleteHashField
                                || mutation.value.is_empty());
                    mutation.target.is_none() && (scalar_shape || hash_field_shape)
                }
                EngineKind::Search => {
                    expected_dirty[3] = true;
                    mutation.target.is_some_and(|index| {
                        delta
                            .search_documents
                            .contains(&(index, mutation.key.clone()))
                    }) && matches!(
                        mutation.opcode,
                        Opcode::IndexDocument | Opcode::ReplaceDocument | Opcode::DeleteDocument
                    ) && mutation.expires_at_micros.is_none()
                        && (mutation.opcode != Opcode::DeleteDocument || mutation.value.is_empty())
                }
                EngineKind::Kernel => false,
            });
    let valid_unique_probes = delta.unique_probes.iter().all(|probe| {
        !probe.key.is_empty()
            && matches!(
                batch.state.catalog.object(probe.index),
                Some(CatalogObject::SecondaryIndex(definition)) if definition.unique
            )
    });
    let valid_hash_overlay = validate_delta_hash_overlay_shape(batch, delta)?;
    let replayed_memory_bytes = replay_delta_retained_memory_bytes(batch);
    let valid_memory_ledger = replayed_memory_bytes == delta.retained_memory_bytes
        && replayed_memory_bytes <= NativeDatabase::delta_memory_capacity(batch);
    if valid_roots
        && valid_formats
        && valid_stage_boundary
        && valid_mutations
        && valid_unique_probes
        && valid_hash_overlay
        && valid_memory_ledger
        && batch.dirty == expected_dirty
        && !batch.dirty[0]
        && batch.state.ann == ann_store::AnnState::default()
        && batch.ann_consolidation.is_none()
        && batch.ann_initial_bulk.is_none()
    {
        Ok(())
    } else {
        Err(NativeRuntimeError::InvalidPreparedMutation)
    }
}

fn validate_delta_hash_overlay_shape(
    batch: &NativeWriteBatch,
    delta: &DeltaOverlay,
) -> Result<bool, NativeRuntimeError> {
    let mut latest_mutations = BTreeMap::new();
    let mut accounted_bytes = 0_u64;
    for (mutation_index, mutation) in batch.mutations.iter().enumerate() {
        if mutation.engine != EngineKind::Structure
            || !matches!(
                mutation.opcode,
                Opcode::SetHashField | Opcode::DeleteHashField
            )
        {
            continue;
        }
        let (key, field) = decode_hash_field_identity(&mutation.key)?;
        let identity = (key.to_vec(), field.to_vec());
        latest_mutations.insert(identity, mutation_index);
        accounted_bytes = accounted_bytes
            .checked_add(NativeDatabase::delta_hash_mutation_charge(mutation)?)
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
    }

    for (identity, overlay) in &delta.structure_hash_fields {
        accounted_bytes = accounted_bytes
            .checked_add(NativeDatabase::delta_hash_overlay_charge(
                identity, overlay,
            )?)
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let expected = match overlay {
            DeltaHashFieldOverlay::Missing | DeltaHashFieldOverlay::Durable(_) => None,
            DeltaHashFieldOverlay::Staged(index) => Some((*index, Opcode::SetHashField)),
            DeltaHashFieldOverlay::Deleted(index) => Some((*index, Opcode::DeleteHashField)),
        };
        match expected {
            None if latest_mutations.contains_key(identity) => return Ok(false),
            None => {}
            Some((index, opcode)) => {
                let Some(mutation) = batch.mutations.get(index) else {
                    return Ok(false);
                };
                let identity_matches =
                    decode_hash_field_identity(&mutation.key).is_ok_and(|(key, field)| {
                        key == identity.0.as_slice() && field == identity.1.as_slice()
                    });
                if mutation.engine != EngineKind::Structure
                    || mutation.opcode != opcode
                    || !identity_matches
                    || latest_mutations.get(identity) != Some(&index)
                {
                    return Ok(false);
                }
            }
        }
    }

    Ok(latest_mutations
        .keys()
        .all(|identity| delta.structure_hash_fields.contains_key(identity))
        && accounted_bytes == delta.structure_hash_memory_bytes
        && accounted_bytes <= NativeDatabase::delta_hash_memory_capacity(batch))
}

fn stage_large_values(
    blobs: &BlobStore,
    batch: &NativeWriteBatch,
    rebuild_catalog: bool,
    synchronize: bool,
) -> Result<BTreeMap<[u8; 32], StagedBlob>, NativeRuntimeError> {
    let mut staged = BTreeMap::new();
    if batch.dirty[0] {
        if rebuild_catalog {
            for object in batch.state.catalog.objects.values() {
                let definition = object.encode_definition()?;
                if definition.len() > CATALOG_INLINE_VALUE_LIMIT {
                    stage_blob_value(blobs, &mut staged, &definition, synchronize)?;
                }
            }
            for object in batch.state.catalog.logical_objects.values() {
                let definition = object.encode_definition_v2()?;
                if definition.len() > CATALOG_INLINE_VALUE_LIMIT {
                    stage_blob_value(blobs, &mut staged, &definition, synchronize)?;
                }
            }
        } else {
            for mutation in batch
                .mutations
                .iter()
                .filter(|mutation| is_catalog_creation(mutation.opcode))
            {
                let definition = match catalog_object_from_creation_mutation(mutation)? {
                    PersistedCatalogObject::Legacy(object) => object.encode_definition()?,
                    PersistedCatalogObject::Logical(object) => object.encode_definition_v2()?,
                };
                if definition.len() > CATALOG_INLINE_VALUE_LIMIT {
                    stage_blob_value(blobs, &mut staged, &definition, synchronize)?;
                }
            }
        }
    }
    for mutation in &batch.mutations {
        let large = (mutation.engine == EngineKind::Relational
            && matches!(mutation.opcode, Opcode::InsertRow | Opcode::UpdateRow)
            && mutation.value.len() > RELATIONAL_INLINE_VALUE_LIMIT)
            || (mutation.engine == EngineKind::Structure
                && matches!(
                    mutation.opcode,
                    Opcode::SetValue
                        | Opcode::ExpireValue
                        | Opcode::SetHashField
                        | Opcode::PushListHead
                        | Opcode::PushListTail
                        | Opcode::PopListHead
                        | Opcode::PopListTail
                )
                && mutation.value.len() > STRUCTURE_INLINE_VALUE_LIMIT)
            || (mutation.engine == EngineKind::Search
                && matches!(
                    mutation.opcode,
                    Opcode::IndexDocument | Opcode::ReplaceDocument
                )
                && mutation.value.len() > SEARCH_INLINE_VALUE_LIMIT);
        if large {
            stage_blob_value(blobs, &mut staged, &mutation.value, synchronize)?;
        }
    }
    Ok(staged)
}

fn stage_blob_value(
    blobs: &BlobStore,
    staged: &mut BTreeMap<[u8; 32], StagedBlob>,
    value: &[u8],
    synchronize: bool,
) -> Result<(), NativeRuntimeError> {
    let digest = *blake3::hash(value).as_bytes();
    if let std::collections::btree_map::Entry::Vacant(entry) = staged.entry(digest) {
        entry.insert(blobs.stage(value, synchronize)?);
    }
    Ok(())
}

fn publish_staged_blobs(
    blobs: &mut BlobStore,
    staged: BTreeMap<[u8; 32], StagedBlob>,
    synchronize: bool,
) -> Result<BTreeMap<[u8; 32], BlobReference>, NativeRuntimeError> {
    staged
        .into_iter()
        .map(|(digest, staged)| Ok((digest, blobs.publish(staged, synchronize)?)))
        .collect()
}

fn relational_storage_value(
    value: &[u8],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Vec<u8>, NativeRuntimeError> {
    if value.len() <= RELATIONAL_INLINE_VALUE_LIMIT {
        let mut encoded = Vec::with_capacity(value.len() + 1);
        encoded.push(RELATIONAL_VALUE_INLINE);
        encoded.extend_from_slice(value);
        return Ok(encoded);
    }
    let digest = *blake3::hash(value).as_bytes();
    let reference = blob_references
        .get(&digest)
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    let mut encoded = Vec::with_capacity(1 + hyphae_native_records::BLOB_REFERENCE_SIZE);
    encoded.push(RELATIONAL_VALUE_BLOB);
    encoded.extend_from_slice(&reference.encode());
    Ok(encoded)
}

fn structure_storage_value(
    value: &[u8],
    expires_at_micros: Option<i64>,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Vec<u8>, NativeRuntimeError> {
    let uses_blob = value.len() > STRUCTURE_INLINE_VALUE_LIMIT;
    let payload_length = if uses_blob {
        hyphae_native_records::BLOB_REFERENCE_SIZE
    } else {
        value.len()
    };
    let mut encoded = Vec::with_capacity(STRUCTURE_VALUE_HEADER_SIZE + payload_length);
    encoded.extend_from_slice(STRUCTURE_VALUE_MAGIC);
    encoded.push(u8::from(expires_at_micros.is_some()) * STRUCTURE_VALUE_HAS_EXPIRY);
    encoded.push(if uses_blob {
        STRUCTURE_VALUE_BLOB
    } else {
        STRUCTURE_VALUE_INLINE
    });
    encoded.extend_from_slice(&[0; 6]);
    encoded.extend_from_slice(&expires_at_micros.unwrap_or(0).to_le_bytes());
    if uses_blob {
        let digest = *blake3::hash(value).as_bytes();
        let reference = blob_references
            .get(&digest)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        encoded.extend_from_slice(&reference.encode());
    } else {
        encoded.extend_from_slice(value);
    }
    Ok(encoded)
}

fn search_document_storage_value(
    text: &[u8],
    token_count: u64,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Vec<u8>, NativeRuntimeError> {
    let uses_blob = text.len() > SEARCH_INLINE_VALUE_LIMIT;
    let payload_length = if uses_blob {
        hyphae_native_records::BLOB_REFERENCE_SIZE
    } else {
        text.len()
    };
    let mut encoded = Vec::with_capacity(SEARCH_DOCUMENT_HEADER_SIZE + payload_length);
    encoded.extend_from_slice(SEARCH_DOCUMENT_MAGIC);
    encoded.push(if uses_blob {
        SEARCH_DOCUMENT_BLOB
    } else {
        SEARCH_DOCUMENT_INLINE
    });
    encoded.extend_from_slice(&[0; 7]);
    encoded.extend_from_slice(&token_count.to_le_bytes());
    if uses_blob {
        let digest = *blake3::hash(text).as_bytes();
        let reference = blob_references
            .get(&digest)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        encoded.extend_from_slice(&reference.encode());
    } else {
        encoded.extend_from_slice(text);
    }
    Ok(encoded)
}

fn structure_tombstone_value() -> Vec<u8> {
    let mut encoded = Vec::with_capacity(STRUCTURE_VALUE_HEADER_SIZE);
    encoded.extend_from_slice(STRUCTURE_VALUE_MAGIC);
    encoded.push(STRUCTURE_VALUE_TOMBSTONE);
    encoded.push(STRUCTURE_VALUE_INLINE);
    encoded.extend_from_slice(&[0; 6]);
    encoded.extend_from_slice(&0_i64.to_le_bytes());
    encoded
}

fn is_structure_tombstone(encoded: &[u8]) -> bool {
    encoded.len() == STRUCTURE_VALUE_HEADER_SIZE
        && encoded.get(..8) == Some(STRUCTURE_VALUE_MAGIC.as_slice())
        && encoded[8] == STRUCTURE_VALUE_TOMBSTONE
        && encoded[9] == STRUCTURE_VALUE_INLINE
        && encoded[10..24].iter().all(|byte| *byte == 0)
}

struct StructureCompactionPlan {
    state: StructureState,
    scanned_entries: usize,
    retained_entries: Vec<(Vec<u8>, Vec<u8>)>,
    dropped_tombstones: usize,
}

struct StructureCompactionObservation {
    scanned_entries: usize,
    retained_entries: usize,
    dropped_tombstones: usize,
}

fn plan_structure_compaction(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
) -> Result<StructureCompactionPlan, NativeRuntimeError> {
    let state = load_structure_state_root(pages, blobs, root)?;
    let entries = BTree::from_root(root).scan(pages)?;
    let scanned_entries = entries.len();
    let mut retained_entries = Vec::with_capacity(scanned_entries);
    let mut dropped_tombstones = 0_usize;
    for (key, value) in entries {
        if compactable_structure_tombstone(&key, &value)? {
            dropped_tombstones = dropped_tombstones
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        } else {
            retained_entries.push((key, value));
        }
    }
    Ok(StructureCompactionPlan {
        state,
        scanned_entries,
        retained_entries,
        dropped_tombstones,
    })
}

fn observe_structure_compaction(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
    format: StructureFormat,
) -> Result<StructureCompactionObservation, NativeRuntimeError> {
    match format {
        StructureFormat::BTreeV2 => {
            let plan = plan_structure_compaction(pages, blobs, root)?;
            Ok(StructureCompactionObservation {
                scanned_entries: plan.scanned_entries,
                retained_entries: plan.retained_entries.len(),
                dropped_tombstones: plan.dropped_tombstones,
            })
        }
        StructureFormat::BTreeV3 => {
            let plan =
                structure_v3::plan_structure_v3_compaction(pages, blobs, BTree::from_root(root))?;
            Ok(StructureCompactionObservation {
                scanned_entries: plan.scanned_entries,
                retained_entries: plan.retained_entries,
                dropped_tombstones: plan.dropped_tombstones,
            })
        }
        StructureFormat::InlineStateV1 | StructureFormat::BTreeV1 => {
            Err(NativeRuntimeError::StructureCompactionUnsupported)
        }
    }
}

fn compactable_structure_tombstone(key: &[u8], value: &[u8]) -> Result<bool, NativeRuntimeError> {
    if key == STRUCTURE_FORMAT_KEY {
        return Ok(false);
    }
    match key.first().copied() {
        Some(
            STRUCTURE_ENTRY_PREFIX
            | STRUCTURE_HASH_FIELD_PREFIX
            | STRUCTURE_SET_MEMBER_PREFIX
            | STRUCTURE_LIST_CHUNK_PREFIX
            | STRUCTURE_SORTED_SET_MEMBER_PREFIX
            | STRUCTURE_SORTED_SET_ORDER_PREFIX
            | STRUCTURE_STREAM_ENTRY_PREFIX,
        ) => Ok(is_structure_tombstone(value)),
        Some(STRUCTURE_EXPIRY_PREFIX) => match value {
            [STRUCTURE_EXPIRY_TOMBSTONE] => Ok(true),
            [
                STRUCTURE_EXPIRY_LIVE
                | STRUCTURE_HASH_EXPIRY_LIVE
                | STRUCTURE_SET_EXPIRY_LIVE
                | STRUCTURE_LIST_EXPIRY_LIVE
                | STRUCTURE_STREAM_EXPIRY_LIVE
                | STRUCTURE_SORTED_SET_EXPIRY_LIVE,
            ] => Ok(false),
            _ => Err(NativeRuntimeError::InvalidStructureTree),
        },
        Some(STRUCTURE_HASH_FIELD_EXPIRY_PREFIX) => match value {
            [STRUCTURE_EXPIRY_TOMBSTONE] => Ok(true),
            [STRUCTURE_HASH_FIELD_EXPIRY_LIVE] => Ok(false),
            _ => Err(NativeRuntimeError::InvalidStructureTree),
        },
        Some(STRUCTURE_LIST_META_PREFIX) => {
            if is_structure_tombstone(value) {
                Ok(true)
            } else {
                decode_list_metadata(value).map(|_| false)
            }
        }
        Some(STRUCTURE_SORTED_SET_META_PREFIX) => Ok(false),
        Some(STRUCTURE_HASH_META_PREFIX) => {
            if is_structure_tombstone(value) {
                Ok(true)
            } else {
                decode_hash_metadata(value).map(|_| false)
            }
        }
        Some(STRUCTURE_SET_META_PREFIX) => {
            if is_structure_tombstone(value) {
                Ok(true)
            } else {
                decode_set_metadata_state(value).map(|_| false)
            }
        }
        Some(STRUCTURE_STREAM_META_PREFIX) => {
            if is_structure_tombstone(value) {
                Ok(true)
            } else {
                decode_stream_metadata(value).map(|_| false)
            }
        }
        _ => Err(NativeRuntimeError::InvalidStructureTree),
    }
}

fn decode_structure_value(
    encoded: &[u8],
    blobs: &BlobStore,
) -> Result<Option<StructureEntry>, NativeRuntimeError> {
    if encoded.len() < STRUCTURE_VALUE_HEADER_SIZE
        || encoded.get(..8) != Some(STRUCTURE_VALUE_MAGIC.as_slice())
        || !matches!(
            encoded[8],
            0 | STRUCTURE_VALUE_HAS_EXPIRY | STRUCTURE_VALUE_TOMBSTONE
        )
        || encoded[10..16] != [0; 6]
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut expiry_bytes = [0_u8; 8];
    expiry_bytes.copy_from_slice(&encoded[16..24]);
    let raw_expiry = i64::from_le_bytes(expiry_bytes);
    let payload = &encoded[STRUCTURE_VALUE_HEADER_SIZE..];
    if encoded[8] == STRUCTURE_VALUE_TOMBSTONE {
        if !is_structure_tombstone(encoded) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        return Ok(None);
    }
    let expires_at_micros = if encoded[8] == STRUCTURE_VALUE_HAS_EXPIRY {
        Some(raw_expiry)
    } else if raw_expiry == 0 {
        None
    } else {
        return Err(NativeRuntimeError::InvalidStructureTree);
    };
    let value = match encoded[9] {
        STRUCTURE_VALUE_INLINE if payload.len() <= STRUCTURE_INLINE_VALUE_LIMIT => payload.to_vec(),
        STRUCTURE_VALUE_BLOB if payload.len() == hyphae_native_records::BLOB_REFERENCE_SIZE => {
            let reference = BlobReference::decode(payload)?;
            if reference.logical_length <= STRUCTURE_INLINE_VALUE_LIMIT as u64 {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            blobs.read(reference)?
        }
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    };
    Ok(Some(StructureEntry {
        value,
        expires_at_micros,
    }))
}

#[derive(Clone, Copy)]
enum DeltaCollectionMarkerV2 {
    Hash(Option<i64>),
    Set(Option<i64>),
    List(Option<i64>),
    SortedSet(Option<i64>),
    Stream(Option<i64>),
}

fn decode_delta_structure_value(encoded: &[u8]) -> Result<Option<()>, NativeRuntimeError> {
    if encoded.len() < STRUCTURE_VALUE_HEADER_SIZE
        || encoded.get(..8) != Some(STRUCTURE_VALUE_MAGIC.as_slice())
        || !matches!(
            encoded[8],
            0 | STRUCTURE_VALUE_HAS_EXPIRY | STRUCTURE_VALUE_TOMBSTONE
        )
        || encoded[10..16] != [0; 6]
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if encoded[8] == STRUCTURE_VALUE_TOMBSTONE {
        return is_structure_tombstone(encoded)
            .then_some(None)
            .ok_or(NativeRuntimeError::InvalidStructureTree);
    }
    let mut expiry_bytes = [0_u8; 8];
    expiry_bytes.copy_from_slice(&encoded[16..24]);
    let raw_expiry = i64::from_le_bytes(expiry_bytes);
    if encoded[8] == STRUCTURE_VALUE_HAS_EXPIRY {
        let _ = raw_expiry;
    } else if raw_expiry == 0 {
    } else {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let payload = &encoded[STRUCTURE_VALUE_HEADER_SIZE..];
    match encoded[9] {
        STRUCTURE_VALUE_INLINE if payload.len() <= STRUCTURE_INLINE_VALUE_LIMIT => {}
        STRUCTURE_VALUE_BLOB if payload.len() == hyphae_native_records::BLOB_REFERENCE_SIZE => {
            let reference = BlobReference::decode(payload)?;
            if reference.logical_length <= STRUCTURE_INLINE_VALUE_LIMIT as u64 {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        }
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    }
    Ok(Some(()))
}

fn wal_mutations(
    mutations: &[Mutation],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<Vec<Mutation>, NativeRuntimeError> {
    mutations
        .iter()
        .cloned()
        .map(|mut mutation| {
            if mutation.engine == EngineKind::Relational
                && matches!(mutation.opcode, Opcode::InsertRow | Opcode::UpdateRow)
            {
                mutation.value = relational_storage_value(&mutation.value, blob_references)?;
            } else if mutation.engine == EngineKind::Structure
                && matches!(
                    mutation.opcode,
                    Opcode::SetValue
                        | Opcode::ExpireValue
                        | Opcode::SetHashField
                        | Opcode::PushListHead
                        | Opcode::PushListTail
                        | Opcode::PopListHead
                        | Opcode::PopListTail
                )
            {
                mutation.value = structure_storage_value(
                    &mutation.value,
                    mutation.expires_at_micros,
                    blob_references,
                )?;
            } else if mutation.engine == EngineKind::Search
                && matches!(
                    mutation.opcode,
                    Opcode::IndexDocument | Opcode::ReplaceDocument
                )
            {
                let text = std::str::from_utf8(&mutation.value)
                    .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
                mutation.value = search_document_storage_value(
                    &mutation.value,
                    u64::try_from(analyze(text).len())
                        .map_err(|_| NativeRuntimeError::InvalidSearchTree)?,
                    blob_references,
                )?;
            }
            Ok(mutation)
        })
        .collect()
}

fn structure_key(key: &[u8]) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(key.len().saturating_add(1));
    encoded.push(STRUCTURE_ENTRY_PREFIX);
    encoded.extend_from_slice(key);
    encoded
}

fn structure_expiry_key(expires_at_micros: i64, key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    if key
        .len()
        .checked_add(9)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    let sortable = expires_at_micros.cast_unsigned() ^ (1_u64 << 63);
    let mut encoded = Vec::with_capacity(key.len().saturating_add(9));
    encoded.push(STRUCTURE_EXPIRY_PREFIX);
    encoded.extend_from_slice(&sortable.to_be_bytes());
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn decode_structure_expiry_identity(identity: &[u8]) -> Result<(i64, &[u8]), NativeRuntimeError> {
    let timestamp = identity
        .get(..8)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut sortable = [0_u8; 8];
    sortable.copy_from_slice(timestamp);
    let expires_at_micros = (u64::from_be_bytes(sortable) ^ (1_u64 << 63)).cast_signed();
    Ok((expires_at_micros, &identity[8..]))
}

fn structure_hash_field_expiry_key(
    expires_at_micros: i64,
    key: &[u8],
    field: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = collection_member_identity(key, field)?;
    if identity
        .len()
        .checked_add(9)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    let sortable = expires_at_micros.cast_unsigned() ^ (1_u64 << 63);
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(9));
    encoded.push(STRUCTURE_HASH_FIELD_EXPIRY_PREFIX);
    encoded.extend_from_slice(&sortable.to_be_bytes());
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn decode_structure_hash_field_expiry_identity(
    identity: &[u8],
) -> Result<(i64, &[u8], &[u8]), NativeRuntimeError> {
    let timestamp = identity
        .get(..8)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut sortable = [0_u8; 8];
    sortable.copy_from_slice(timestamp);
    let expires_at_micros = (u64::from_be_bytes(sortable) ^ (1_u64 << 63)).cast_signed();
    let (key, field) = decode_hash_field_identity(&identity[8..])
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    Ok((expires_at_micros, key, field))
}

fn structure_value_expiry(encoded: &[u8]) -> Result<Option<i64>, NativeRuntimeError> {
    if encoded.len() < STRUCTURE_VALUE_HEADER_SIZE
        || encoded.get(..8) != Some(STRUCTURE_VALUE_MAGIC.as_slice())
        || !matches!(
            encoded[8],
            0 | STRUCTURE_VALUE_HAS_EXPIRY | STRUCTURE_VALUE_TOMBSTONE
        )
        || encoded[10..16] != [0; 6]
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if encoded[8] == STRUCTURE_VALUE_TOMBSTONE {
        return is_structure_tombstone(encoded)
            .then_some(None)
            .ok_or(NativeRuntimeError::InvalidStructureTree);
    }
    let payload = &encoded[STRUCTURE_VALUE_HEADER_SIZE..];
    if !matches!(
        (encoded[9], payload.len()),
        (STRUCTURE_VALUE_INLINE, 0..=STRUCTURE_INLINE_VALUE_LIMIT)
            | (
                STRUCTURE_VALUE_BLOB,
                hyphae_native_records::BLOB_REFERENCE_SIZE
            )
    ) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut expiry = [0_u8; 8];
    expiry.copy_from_slice(&encoded[16..24]);
    let expiry = i64::from_le_bytes(expiry);
    match encoded[8] {
        STRUCTURE_VALUE_HAS_EXPIRY => Ok(Some(expiry)),
        0 if expiry == 0 => Ok(None),
        _ => Err(NativeRuntimeError::InvalidStructureTree),
    }
}

fn replace_structure_value_expiry(
    encoded: &[u8],
    expires_at_micros: Option<i64>,
) -> Result<Vec<u8>, NativeRuntimeError> {
    if is_structure_tombstone(encoded) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    structure_value_expiry(encoded)?;
    let mut updated = encoded.to_vec();
    updated[8] = if expires_at_micros.is_some() {
        STRUCTURE_VALUE_HAS_EXPIRY
    } else {
        0
    };
    updated[16..24].copy_from_slice(&expires_at_micros.unwrap_or(0).to_le_bytes());
    Ok(updated)
}

fn structure_hash_meta_key(key: &[u8]) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(key.len().saturating_add(1));
    encoded.push(STRUCTURE_HASH_META_PREFIX);
    encoded.extend_from_slice(key);
    encoded
}

fn structure_set_meta_key(key: &[u8]) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(key.len().saturating_add(1));
    encoded.push(STRUCTURE_SET_META_PREFIX);
    encoded.extend_from_slice(key);
    encoded
}

fn structure_list_meta_key(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    if key
        .len()
        .checked_add(13)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    let mut encoded = Vec::with_capacity(key.len().saturating_add(1));
    encoded.push(STRUCTURE_LIST_META_PREFIX);
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn canonical_sorted_set_score(score: f64) -> Result<SortedSetScore, NativeRuntimeError> {
    SortedSetScore::new(score).ok_or(NativeRuntimeError::StructureScoreNotCanonical)
}

fn canonical_sorted_set_score_bound(
    bound: Bound<f64>,
) -> Result<Bound<SortedSetScore>, NativeRuntimeError> {
    match bound {
        Bound::Included(score) => Ok(Bound::Included(canonical_sorted_set_score(score)?)),
        Bound::Excluded(score) => Ok(Bound::Excluded(canonical_sorted_set_score(score)?)),
        Bound::Unbounded => Ok(Bound::Unbounded),
    }
}

fn canonical_sorted_set_score_bounds(
    lower: Bound<f64>,
    upper: Bound<f64>,
) -> Result<(Bound<SortedSetScore>, Bound<SortedSetScore>), NativeRuntimeError> {
    Ok((
        canonical_sorted_set_score_bound(lower)?,
        canonical_sorted_set_score_bound(upper)?,
    ))
}

fn sorted_set_score_physical_bounds(
    key: &[u8],
    lower: Bound<SortedSetScore>,
    upper: Bound<SortedSetScore>,
) -> Result<NativePhysicalKeyRange, NativeRuntimeError> {
    let prefix = structure_sorted_set_order_prefix(key)?;
    let lower = match lower {
        Bound::Included(score) => Bound::Included(structure_sorted_set_score_prefix(key, score)?),
        Bound::Excluded(score) => Bound::Included(
            byte_prefix_successor(&structure_sorted_set_score_prefix(key, score)?)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?,
        ),
        Bound::Unbounded => Bound::Unbounded,
    };
    let upper = match upper {
        Bound::Included(score) => Bound::Excluded(
            byte_prefix_successor(&structure_sorted_set_score_prefix(key, score)?)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?,
        ),
        Bound::Excluded(score) => Bound::Excluded(structure_sorted_set_score_prefix(key, score)?),
        Bound::Unbounded => Bound::Unbounded,
    };
    Ok(NativePhysicalKeyRange {
        prefix,
        lower,
        upper,
    })
}

fn sorted_set_rank_range_from_state(
    structures: &StructureState,
    key: &[u8],
    start: i64,
    stop: i64,
    direction: SortedSetDirection,
) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
    if structures.entries.contains_key(key)
        || structures.hashes.contains_key(key)
        || structures.sets.contains_key(key)
        || structures.lists.contains_key(key)
    {
        return Err(NativeRuntimeError::StructureKindMismatch);
    }
    let entries = match direction {
        SortedSetDirection::Ascending => structures.zrange(key, start, stop),
        SortedSetDirection::Descending => structures.zrevrange(key, start, stop),
    }
    .ok_or(NativeRuntimeError::UnknownStructureSortedSet)?;
    Ok(entries
        .into_iter()
        .map(|(member, score)| SortedSetEntry { member, score })
        .collect())
}

fn sorted_set_score_range_from_state(
    structures: &StructureState,
    key: &[u8],
    lower: Bound<f64>,
    upper: Bound<f64>,
    offset: usize,
    limit: usize,
    direction: SortedSetDirection,
) -> Result<Vec<SortedSetEntry>, NativeRuntimeError> {
    let (lower, upper) = canonical_sorted_set_score_bounds(lower, upper)?;
    if structures.entries.contains_key(key)
        || structures.hashes.contains_key(key)
        || structures.sets.contains_key(key)
        || structures.lists.contains_key(key)
    {
        return Err(NativeRuntimeError::StructureKindMismatch);
    }
    let entries = match direction {
        SortedSetDirection::Ascending => {
            structures.zrange_by_score(key, lower, upper, offset, limit)
        }
        SortedSetDirection::Descending => {
            structures.zrevrange_by_score(key, lower, upper, offset, limit)
        }
    }
    .ok_or(NativeRuntimeError::UnknownStructureSortedSet)?;
    Ok(entries
        .into_iter()
        .map(|(member, score)| SortedSetEntry { member, score })
        .collect())
}

fn sorted_set_rank_from_state(
    structures: &StructureState,
    key: &[u8],
    member: &[u8],
    reverse: bool,
) -> Result<Option<usize>, NativeRuntimeError> {
    if structures.entries.contains_key(key)
        || structures.hashes.contains_key(key)
        || structures.sets.contains_key(key)
        || structures.lists.contains_key(key)
    {
        return Err(NativeRuntimeError::StructureKindMismatch);
    }
    match structures.sorted_set_ranks(key, member) {
        SortedSetRankState::MissingSet => Err(NativeRuntimeError::UnknownStructureSortedSet),
        SortedSetRankState::MissingMember => Ok(None),
        SortedSetRankState::Present {
            forward,
            reverse: reverse_rank,
        } => Ok(Some(if reverse { reverse_rank } else { forward })),
    }
}

fn structure_sorted_set_meta_key(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    if key
        .len()
        .checked_add(13)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    let mut encoded = Vec::with_capacity(key.len().saturating_add(1));
    encoded.push(STRUCTURE_SORTED_SET_META_PREFIX);
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn list_chunk_identity(key: &[u8], chunk_id: i64) -> Result<Vec<u8>, NativeRuntimeError> {
    let key_length =
        u32::try_from(key.len()).map_err(|_| NativeRuntimeError::StructureIdentityTooLarge)?;
    let mut encoded = Vec::with_capacity(12_usize.saturating_add(key.len()));
    encoded.extend_from_slice(&key_length.to_be_bytes());
    encoded.extend_from_slice(key);
    encoded.extend_from_slice(&(chunk_id.cast_unsigned() ^ (1_u64 << 63)).to_be_bytes());
    if encoded
        .len()
        .checked_add(1)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    Ok(encoded)
}

fn decode_list_chunk_identity(encoded: &[u8]) -> Result<(&[u8], i64), NativeRuntimeError> {
    let key_length_bytes = encoded
        .get(..4)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut key_length = [0_u8; 4];
    key_length.copy_from_slice(key_length_bytes);
    let key_length = usize::try_from(u32::from_be_bytes(key_length))
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    let chunk_start = 4_usize
        .checked_add(key_length)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if encoded.len() != chunk_start.saturating_add(8) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut chunk_id = [0_u8; 8];
    chunk_id.copy_from_slice(&encoded[chunk_start..]);
    let chunk_id = (u64::from_be_bytes(chunk_id) ^ (1_u64 << 63)).cast_signed();
    Ok((&encoded[4..chunk_start], chunk_id))
}

fn structure_list_chunk_key(key: &[u8], chunk_id: i64) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = list_chunk_identity(key, chunk_id)?;
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(1));
    encoded.push(STRUCTURE_LIST_CHUNK_PREFIX);
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn structure_list_chunk_prefix(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    structure_list_meta_key(key)?;
    let key_length =
        u32::try_from(key.len()).map_err(|_| NativeRuntimeError::StructureIdentityTooLarge)?;
    let mut encoded = Vec::with_capacity(key.len().saturating_add(5));
    encoded.push(STRUCTURE_LIST_CHUNK_PREFIX);
    encoded.extend_from_slice(&key_length.to_be_bytes());
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn collection_member_identity(key: &[u8], member: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let key_length =
        u32::try_from(key.len()).map_err(|_| NativeRuntimeError::StructureIdentityTooLarge)?;
    let mut encoded = Vec::with_capacity(
        4_usize
            .saturating_add(key.len())
            .saturating_add(member.len()),
    );
    encoded.extend_from_slice(&key_length.to_be_bytes());
    encoded.extend_from_slice(key);
    encoded.extend_from_slice(member);
    Ok(encoded)
}

fn decode_collection_member_identity(encoded: &[u8]) -> Result<(&[u8], &[u8]), NativeRuntimeError> {
    let length_bytes = encoded
        .get(..4)
        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
    let mut length = [0_u8; 4];
    length.copy_from_slice(length_bytes);
    let key_length = usize::try_from(u32::from_be_bytes(length))
        .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?;
    let member_start = 4_usize
        .checked_add(key_length)
        .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
    if member_start > encoded.len() {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    Ok((&encoded[4..member_start], &encoded[member_start..]))
}

fn hash_field_identity(key: &[u8], field: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = collection_member_identity(key, field)?;
    if identity
        .len()
        .checked_add(1)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    Ok(identity)
}

fn decode_hash_field_identity(encoded: &[u8]) -> Result<(&[u8], &[u8]), NativeRuntimeError> {
    decode_collection_member_identity(encoded)
}

fn validate_hash_field_batch_size(requested: usize) -> Result<(), NativeRuntimeError> {
    if requested > MAX_HASH_FIELD_BATCH_SIZE {
        return Err(NativeRuntimeError::HashFieldBatchTooLarge { requested });
    }
    Ok(())
}

fn validate_hash_field_identity(key: &[u8], field: &[u8]) -> Result<(), NativeRuntimeError> {
    hash_field_identity(key, field).map(drop)
}

fn validate_hash_pattern_identity(
    key: &[u8],
    request: &HashPatternScanRequest,
) -> Result<(), NativeRuntimeError> {
    validate_hash_field_identity(key, request.compiled().leading_literal_prefix())?;
    if let Some(cursor) = request.start_after() {
        validate_hash_field_identity(key, cursor)?;
    }
    Ok(())
}

fn validate_set_algebra_keys(request: &SetAlgebraRequest) -> Result<(), NativeRuntimeError> {
    for key in request.keys() {
        let metadata_key = structure_set_meta_key(key);
        let member_prefix = structure_set_member_key(key, &[])?;
        if metadata_key.len() > BTREE_MAX_KEY_SIZE || member_prefix.len() > BTREE_MAX_KEY_SIZE {
            return Err(NativeRuntimeError::StructureIdentityTooLarge);
        }
    }
    Ok(())
}

fn validate_hash_field_positions(key: &[u8], fields: &[Vec<u8>]) -> Result<(), NativeRuntimeError> {
    validate_hash_field_batch_size(fields.len())?;
    for field in fields {
        validate_hash_field_identity(key, field)?;
    }
    Ok(())
}

fn prepare_hash_mutation_fields(
    key: &[u8],
    mut fields: Vec<Vec<u8>>,
) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
    validate_hash_field_positions(key, &fields)?;
    fields.sort_unstable();
    if fields.windows(2).any(|pair| pair[0] == pair[1]) {
        return Err(NativeRuntimeError::DuplicateHashField);
    }
    Ok(fields)
}

fn prepare_hash_field_updates(
    key: &[u8],
    mut updates: Vec<HashFieldUpdate>,
) -> Result<Vec<HashFieldUpdate>, NativeRuntimeError> {
    validate_hash_field_batch_size(updates.len())?;
    for (field, _) in &updates {
        validate_hash_field_identity(key, field)?;
    }
    updates.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if updates.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(NativeRuntimeError::DuplicateHashField);
    }
    Ok(updates)
}

fn set_member_identity(key: &[u8], member: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = collection_member_identity(key, member)?;
    if identity
        .len()
        .checked_add(1)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    Ok(identity)
}

fn decode_set_member_identity(encoded: &[u8]) -> Result<(&[u8], &[u8]), NativeRuntimeError> {
    decode_collection_member_identity(encoded)
}

fn validate_set_member_batch_size(requested: usize) -> Result<(), NativeRuntimeError> {
    if requested > MAX_SET_MEMBER_BATCH_SIZE {
        return Err(NativeRuntimeError::SetMemberBatchTooLarge { requested });
    }
    Ok(())
}

fn validate_set_member_identity(key: &[u8], member: &[u8]) -> Result<(), NativeRuntimeError> {
    structure_set_member_key(key, member).map(drop)
}

fn validate_set_member_positions(
    key: &[u8],
    members: &[Vec<u8>],
) -> Result<(), NativeRuntimeError> {
    validate_set_member_batch_size(members.len())?;
    for member in members {
        validate_set_member_identity(key, member)?;
    }
    Ok(())
}

fn prepare_set_mutation_members(
    key: &[u8],
    mut members: Vec<Vec<u8>>,
) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
    validate_set_member_positions(key, &members)?;
    members.sort_unstable();
    if members.windows(2).any(|pair| pair[0] == pair[1]) {
        return Err(NativeRuntimeError::DuplicateSetMember);
    }
    Ok(members)
}

fn validate_set_scan_identity(
    key: &[u8],
    start_after: Option<&[u8]>,
) -> Result<(), NativeRuntimeError> {
    let metadata = structure_set_meta_key(key);
    if metadata.len() > BTREE_MAX_KEY_SIZE {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    validate_set_member_identity(key, &[])?;
    if let Some(cursor) = start_after {
        validate_set_member_identity(key, cursor)?;
    }
    Ok(())
}

fn decode_set_scan_member_identity<'key>(
    physical_key: &'key [u8],
    expected_set: &[u8],
) -> Result<&'key [u8], NativeRuntimeError> {
    if physical_key.first() != Some(&STRUCTURE_SET_MEMBER_PREFIX) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (set, member) = decode_set_member_identity(&physical_key[1..])
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    if set != expected_set {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(member)
}

fn sorted_set_member_identity(key: &[u8], member: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = collection_member_identity(key, member)?;
    if identity
        .len()
        .checked_add(1)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    Ok(identity)
}

fn decode_sorted_set_member_identity(encoded: &[u8]) -> Result<(&[u8], &[u8]), NativeRuntimeError> {
    decode_collection_member_identity(encoded)
}

fn structure_hash_field_key(key: &[u8], field: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = hash_field_identity(key, field)?;
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(1));
    encoded.push(STRUCTURE_HASH_FIELD_PREFIX);
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn structure_set_member_key(key: &[u8], member: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = set_member_identity(key, member)?;
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(1));
    encoded.push(STRUCTURE_SET_MEMBER_PREFIX);
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn structure_sorted_set_member_key(
    key: &[u8],
    member: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = sorted_set_member_identity(key, member)?;
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(1));
    encoded.push(STRUCTURE_SORTED_SET_MEMBER_PREFIX);
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn sorted_set_order_identity(
    key: &[u8],
    score: SortedSetScore,
    member: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let key_length =
        u32::try_from(key.len()).map_err(|_| NativeRuntimeError::StructureIdentityTooLarge)?;
    let mut encoded = Vec::with_capacity(
        12_usize
            .saturating_add(key.len())
            .saturating_add(member.len()),
    );
    encoded.extend_from_slice(&key_length.to_be_bytes());
    encoded.extend_from_slice(key);
    encoded.extend_from_slice(&score.sortable_bits().to_be_bytes());
    encoded.extend_from_slice(member);
    if encoded
        .len()
        .checked_add(1)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    Ok(encoded)
}

fn decode_sorted_set_order_identity(
    encoded: &[u8],
) -> Result<(&[u8], SortedSetScore, &[u8]), NativeRuntimeError> {
    let length_bytes = encoded
        .get(..4)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut length = [0_u8; 4];
    length.copy_from_slice(length_bytes);
    let key_length = usize::try_from(u32::from_be_bytes(length))
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    let score_start = 4_usize
        .checked_add(key_length)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let member_start = score_start
        .checked_add(8)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if member_start > encoded.len() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut sortable = [0_u8; 8];
    sortable.copy_from_slice(&encoded[score_start..member_start]);
    let score = SortedSetScore::from_sortable_bits(u64::from_be_bytes(sortable))
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    Ok((&encoded[4..score_start], score, &encoded[member_start..]))
}

fn structure_sorted_set_order_key(
    key: &[u8],
    score: SortedSetScore,
    member: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let identity = sorted_set_order_identity(key, score, member)?;
    let mut encoded = Vec::with_capacity(identity.len().saturating_add(1));
    encoded.push(STRUCTURE_SORTED_SET_ORDER_PREFIX);
    encoded.extend_from_slice(&identity);
    Ok(encoded)
}

fn structure_sorted_set_order_prefix(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    structure_sorted_set_meta_key(key)?;
    let key_length =
        u32::try_from(key.len()).map_err(|_| NativeRuntimeError::StructureIdentityTooLarge)?;
    let mut encoded = Vec::with_capacity(key.len().saturating_add(5));
    encoded.push(STRUCTURE_SORTED_SET_ORDER_PREFIX);
    encoded.extend_from_slice(&key_length.to_be_bytes());
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn structure_sorted_set_score_prefix(
    key: &[u8],
    score: SortedSetScore,
) -> Result<Vec<u8>, NativeRuntimeError> {
    let mut encoded = structure_sorted_set_order_prefix(key)?;
    if encoded
        .len()
        .checked_add(8)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    encoded.extend_from_slice(&score.sortable_bits().to_be_bytes());
    Ok(encoded)
}

fn encode_hash_metadata(field_count: u64) -> Vec<u8> {
    encode_hash_metadata_state(HashMetadata {
        field_count,
        expires_at_micros: None,
    })
}

fn decode_hash_metadata(encoded: &[u8]) -> Result<u64, NativeRuntimeError> {
    Ok(decode_hash_metadata_state(encoded)?.field_count)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct HashMetadata {
    field_count: u64,
    expires_at_micros: Option<i64>,
}

impl HashMetadata {
    fn is_visible_at(self, logical_time_micros: i64) -> bool {
        self.expires_at_micros
            .is_none_or(|expiry| expiry > logical_time_micros)
    }
}

fn encode_hash_metadata_state(metadata: HashMetadata) -> Vec<u8> {
    match metadata.expires_at_micros {
        None => {
            let mut encoded = Vec::with_capacity(STRUCTURE_HASH_META_SIZE);
            encoded.extend_from_slice(STRUCTURE_HASH_META_MAGIC);
            encoded.extend_from_slice(&metadata.field_count.to_le_bytes());
            encoded
        }
        Some(expiry) => {
            let mut encoded = Vec::with_capacity(STRUCTURE_HASH_EXPIRING_META_SIZE);
            encoded.extend_from_slice(STRUCTURE_HASH_EXPIRING_META_MAGIC);
            encoded.extend_from_slice(&metadata.field_count.to_le_bytes());
            encoded.extend_from_slice(&expiry.to_le_bytes());
            encoded
        }
    }
}

fn decode_hash_metadata_state(encoded: &[u8]) -> Result<HashMetadata, NativeRuntimeError> {
    let expires_at_micros = if encoded.len() == STRUCTURE_HASH_META_SIZE
        && encoded.get(..8) == Some(STRUCTURE_HASH_META_MAGIC.as_slice())
    {
        None
    } else if encoded.len() == STRUCTURE_HASH_EXPIRING_META_SIZE
        && encoded.get(..8) == Some(STRUCTURE_HASH_EXPIRING_META_MAGIC.as_slice())
    {
        let mut expiry = [0_u8; 8];
        expiry.copy_from_slice(&encoded[16..24]);
        Some(i64::from_le_bytes(expiry))
    } else {
        return Err(NativeRuntimeError::InvalidStructureTree);
    };
    let mut count = [0_u8; 8];
    count.copy_from_slice(&encoded[8..16]);
    Ok(HashMetadata {
        field_count: u64::from_le_bytes(count),
        expires_at_micros,
    })
}

fn decode_live_hash_metadata(encoded: &[u8]) -> Result<Option<HashMetadata>, NativeRuntimeError> {
    if is_structure_tombstone(encoded) {
        Ok(None)
    } else {
        decode_hash_metadata_state(encoded).map(Some)
    }
}

fn decode_hash_field_entry(
    encoded: &[u8],
    blobs: &BlobStore,
) -> Result<Option<StructureEntry>, NativeRuntimeError> {
    decode_structure_value(encoded, blobs)
}

#[cfg(test)]
fn decode_hash_field_value(
    encoded: &[u8],
    blobs: &BlobStore,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    decode_hash_field_entry(encoded, blobs).map(|entry| entry.map(|entry| entry.value))
}

fn decode_hash_field_value_at(
    encoded: &[u8],
    blobs: &BlobStore,
    logical_time_micros: i64,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    match decode_structure_value(encoded, blobs)? {
        Some(entry)
            if entry
                .expires_at_micros
                .is_none_or(|expiry| expiry > logical_time_micros) =>
        {
            Ok(Some(entry.value))
        }
        Some(_) | None => Ok(None),
    }
}

fn decode_hash_scan_entry(
    physical_key: &[u8],
    encoded: &[u8],
    expected_hash: &[u8],
    blobs: &BlobStore,
    logical_time_micros: i64,
) -> Result<(bool, Option<HashFieldEntry>), NativeRuntimeError> {
    let field = decode_hash_scan_field_identity(physical_key, expected_hash)?;
    let Some(entry) = decode_hash_field_entry(encoded, blobs)? else {
        return Ok((false, None));
    };
    let visible = entry
        .expires_at_micros
        .is_none_or(|expiry| expiry > logical_time_micros);
    Ok((
        true,
        visible.then(|| HashFieldEntry::new(field.to_vec(), entry.value)),
    ))
}

fn decode_hash_segment(
    physical_entries: Vec<(Vec<u8>, Vec<u8>)>,
    expected_hash: &[u8],
    blobs: &BlobStore,
    logical_time_micros: i64,
) -> Result<HashSegmentBatch, NativeRuntimeError> {
    let mut physical_live = 0_usize;
    let mut entries = Vec::new();
    for (physical_key, encoded) in physical_entries {
        let (live, entry) = decode_hash_scan_entry(
            &physical_key,
            &encoded,
            expected_hash,
            blobs,
            logical_time_micros,
        )?;
        physical_live = physical_live
            .checked_add(usize::from(live))
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if let Some(entry) = entry {
            entries.push(entry);
        }
    }
    Ok(HashSegmentBatch {
        physical_live,
        entries,
    })
}

fn finalize_hash_segment_batches(
    batches: Vec<HashSegmentBatch>,
    declared_field_count: usize,
    verify_complete: bool,
    limit: usize,
) -> Result<Vec<HashFieldEntry>, NativeRuntimeError> {
    let physical_live = batches.iter().try_fold(0_usize, |total, batch| {
        total
            .checked_add(batch.physical_live)
            .ok_or(NativeRuntimeError::InvalidStructureTree)
    })?;
    if physical_live > declared_field_count
        || (verify_complete && physical_live != declared_field_count)
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut entries = batches
        .into_iter()
        .flat_map(|batch| batch.entries)
        .collect::<Vec<_>>();
    entries.truncate(limit);
    Ok(entries)
}

fn decode_set_segment(
    physical_entries: Vec<(Vec<u8>, Vec<u8>)>,
    expected_set: &[u8],
) -> Result<SetSegmentBatch, NativeRuntimeError> {
    let mut physical_live = 0_usize;
    let mut members = Vec::new();
    for (physical_key, encoded) in physical_entries {
        let member = decode_set_scan_member_identity(&physical_key, expected_set)?;
        if decode_set_member_value(&encoded)? {
            physical_live = physical_live
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            members.push(member.to_vec());
        }
    }
    Ok(SetSegmentBatch {
        physical_live,
        members,
    })
}

fn finalize_set_segment_batches(
    batches: Vec<SetSegmentBatch>,
    declared_member_count: usize,
    verify_complete: bool,
    limit: usize,
) -> Result<Vec<Vec<u8>>, NativeRuntimeError> {
    let physical_live = batches.iter().try_fold(0_usize, |total, batch| {
        total
            .checked_add(batch.physical_live)
            .ok_or(NativeRuntimeError::InvalidStructureTree)
    })?;
    if physical_live > declared_member_count
        || (verify_complete && physical_live != declared_member_count)
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut members = batches
        .into_iter()
        .flat_map(|batch| batch.members)
        .collect::<Vec<_>>();
    members.truncate(limit);
    Ok(members)
}

fn decode_stream_segment(
    physical_entries: Vec<(Vec<u8>, Vec<u8>)>,
    expected_stream: &[u8],
) -> Result<Vec<NativeStreamEntry>, NativeRuntimeError> {
    let prefix = structure_stream_entry_prefix(expected_stream)?;
    let expected_key_length = prefix
        .len()
        .checked_add(8)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut entries = Vec::new();
    for (physical_key, encoded) in physical_entries {
        if physical_key.len() != expected_key_length || !physical_key.starts_with(&prefix) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if is_structure_tombstone(&encoded) {
            continue;
        }
        let id = u64::from_be_bytes(
            physical_key[prefix.len()..]
                .try_into()
                .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
        );
        let (payload_id, fields) = decode_stream_wal_entry(&encoded)?;
        if payload_id != id {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((id, fields));
    }
    Ok(entries)
}

fn decode_hash_scan_field_identity<'key>(
    physical_key: &'key [u8],
    expected_hash: &[u8],
) -> Result<&'key [u8], NativeRuntimeError> {
    if physical_key.first().copied() != Some(STRUCTURE_HASH_FIELD_PREFIX) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let identity = physical_key
        .get(1..)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (hash, field) = decode_hash_field_identity(identity)
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    if hash != expected_hash {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(field)
}

