fn set_hash_field_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    if mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, field) = decode_hash_field_identity(&mutation.key)?;
    let metadata_key = structure_hash_meta_key(key);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_hash_metadata_state(&metadata)?;
    let field_key = structure_hash_field_key(key, field)?;
    let existing = tree.get(pages, &field_key)?;
    let added = existing
        .as_ref()
        .is_none_or(|value| is_structure_tombstone(value));
    let prior_expiry = existing
        .as_deref()
        .map(structure_value_expiry)
        .transpose()?
        .flatten();
    let value = structure_storage_value(&mutation.value, None, blob_references)?;
    if prior_expiry.is_none() {
        tree = tree.upsert(pages, creating_csn, field_key, value)?.tree;
        if added {
            metadata.field_count = metadata
                .field_count
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            tree = tree
                .upsert(
                    pages,
                    creating_csn,
                    metadata_key,
                    encode_hash_metadata_state(metadata),
                )?
                .tree;
        }
        return Ok(tree);
    }
    let mut entries = Vec::with_capacity(3);
    entries.push((field_key, value));
    if let Some(expiry) = prior_expiry {
        let expiry_key = structure_hash_field_expiry_key(expiry, key, field)?;
        if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_HASH_FIELD_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    }
    debug_assert!(!added);
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if entries.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn expire_hash_field_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let Some(expires_at_micros) = mutation.expires_at_micros else {
        return Err(NativeRuntimeError::InvalidStructureTree);
    };
    if !mutation.value.is_empty() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, field) = decode_hash_field_identity(&mutation.key)?;
    let metadata = tree
        .get(pages, &structure_hash_meta_key(key))?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    decode_live_hash_metadata(&metadata)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let field_key = structure_hash_field_key(key, field)?;
    let encoded = tree
        .get(pages, &field_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if is_structure_tombstone(&encoded) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let previous_expiry = structure_value_expiry(&encoded)?;
    let new_expiry_key = structure_hash_field_expiry_key(expires_at_micros, key, field)?;
    let mut entries = Vec::with_capacity(3);
    if let Some(previous_expiry) = previous_expiry
        && previous_expiry != expires_at_micros
    {
        let previous_expiry_key = structure_hash_field_expiry_key(previous_expiry, key, field)?;
        if tree.get(pages, &previous_expiry_key)?.as_deref()
            != Some(&[STRUCTURE_HASH_FIELD_EXPIRY_LIVE])
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((previous_expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    }
    entries.push((
        field_key,
        replace_structure_value_expiry(&encoded, Some(expires_at_micros))?,
    ));
    entries.push((new_expiry_key, vec![STRUCTURE_HASH_FIELD_EXPIRY_LIVE]));
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if entries.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn delete_hash_field_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, field) = decode_hash_field_identity(&mutation.key)?;
    let metadata_key = structure_hash_meta_key(key);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_hash_metadata_state(&metadata)?;
    let field_key = structure_hash_field_key(key, field)?;
    let field_value = tree
        .get(pages, &field_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if is_structure_tombstone(&field_value) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let prior_expiry = structure_value_expiry(&field_value)?;
    metadata.field_count = metadata
        .field_count
        .checked_sub(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut entries = vec![
        (field_key, structure_tombstone_value()),
        (metadata_key, encode_hash_metadata_state(metadata)),
    ];
    if let Some(expiry) = prior_expiry {
        let expiry_key = structure_hash_field_expiry_key(expiry, key, field)?;
        if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_HASH_FIELD_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    }
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if entries.windows(2).any(|pair| pair[0].0 == pair[1].0) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn add_set_member_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, member) = decode_set_member_identity(&mutation.key)?;
    let metadata_key = structure_set_meta_key(key);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_set_metadata_state(&metadata)?;
    let member_key = structure_set_member_key(key, member)?;
    if let Some(existing) = tree.get(pages, &member_key)?
        && decode_set_member_value(&existing)?
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    tree = tree
        .upsert(pages, creating_csn, member_key, set_member_live_value())?
        .tree;
    metadata.member_count = metadata
        .member_count
        .checked_add(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_set_metadata_state(metadata),
        )?
        .tree)
}

fn delete_set_member_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, member) = decode_set_member_identity(&mutation.key)?;
    let metadata_key = structure_set_meta_key(key);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_set_metadata_state(&metadata)?;
    let member_key = structure_set_member_key(key, member)?;
    let member_value = tree
        .get(pages, &member_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if !decode_set_member_value(&member_value)? {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    tree = tree
        .upsert(pages, creating_csn, member_key, structure_tombstone_value())?
        .tree;
    metadata.member_count = metadata
        .member_count
        .checked_sub(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_set_metadata_state(metadata),
        )?
        .tree)
}

fn create_list_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_list_meta_key(&mutation.key)?;
    if tree
        .get(pages, &metadata_key)?
        .map(|value| decode_live_list_metadata(&value))
        .transpose()?
        .flatten()
        .is_some()
        || tree
            .get(pages, &structure_hash_meta_key(&mutation.key))?
            .map(|value| decode_live_hash_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_set_meta_key(&mutation.key))?
            .map(|value| decode_live_set_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_sorted_set_meta_key(&mutation.key)?)?
            .is_some()
        || tree
            .get(pages, &structure_key(&mutation.key))?
            .is_some_and(|value| !is_structure_tombstone(&value))
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_list_metadata(ListMetadata::empty()),
        )?
        .tree)
}

fn delete_list_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut entries = list_retirement_entries(pages, tree, mutation, None)?;
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn list_retirement_entries(
    pages: &PageStore,
    tree: BTree,
    mutation: &Mutation,
    due_at_micros: Option<i64>,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let metadata_key = structure_list_meta_key(&mutation.key)?;
    let encoded = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let metadata =
        decode_live_list_metadata(&encoded)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if let Some(logical_time_micros) = due_at_micros
        && metadata
            .expires_at_micros
            .is_none_or(|expiry| expiry > logical_time_micros)
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let chunk_prefix = structure_list_chunk_prefix(&mutation.key)?;
    let physical_chunks = tree.scan_prefix(pages, &chunk_prefix)?;
    let capacity = physical_chunks
        .len()
        .checked_add(2)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut entries = Vec::with_capacity(capacity);
    let mut live_chunks = BTreeSet::new();
    let mut element_count = 0_u64;
    for (physical_key, value) in physical_chunks {
        let identity = physical_key
            .get(1..)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let (list, chunk_id) = decode_list_chunk_identity(identity)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if list != mutation.key {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if let Some(elements) = decode_list_chunk_storage(&value)? {
            let chunk_length = u64::try_from(elements.len())
                .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
            if chunk_length == 0 || !live_chunks.insert(chunk_id) {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            element_count = element_count
                .checked_add(chunk_length)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            entries.push((physical_key, structure_tombstone_value()));
        }
    }
    if element_count != metadata.length {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if metadata.length == 0 {
        if !live_chunks.is_empty() {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    } else {
        let mut expected = metadata.head_chunk;
        loop {
            if !live_chunks.contains(&expected) {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            if expected == metadata.tail_chunk {
                break;
            }
            expected = expected
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        }
        let expected_chunks = metadata
            .tail_chunk
            .checked_sub(metadata.head_chunk)
            .and_then(|distance| distance.checked_add(1))
            .and_then(|count| usize::try_from(count).ok())
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if live_chunks.len() != expected_chunks {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    entries.push((metadata_key, structure_tombstone_value()));
    if let Some(expiry) = metadata.expires_at_micros {
        let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
        if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_LIST_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    }
    Ok(entries)
}

fn expire_list_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let expires_at_micros = mutation
        .expires_at_micros
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if !mutation.value.is_empty() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_list_meta_key(&mutation.key)?;
    let encoded = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata =
        decode_live_list_metadata(&encoded)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let previous_expiry = metadata.expires_at_micros;
    if let Some(previous) = previous_expiry {
        let previous_key = structure_expiry_key(previous, &mutation.key)?;
        if tree.get(pages, &previous_key)?.as_deref() != Some(&[STRUCTURE_LIST_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if previous == expires_at_micros {
            metadata.expires_at_micros = Some(expires_at_micros);
            return Ok(tree
                .upsert(
                    pages,
                    creating_csn,
                    metadata_key,
                    encode_list_metadata(metadata),
                )?
                .tree);
        }
    }
    let expiry_key = structure_expiry_key(expires_at_micros, &mutation.key)?;
    if let Some(marker) = tree.get(pages, &expiry_key)?
        && marker.as_slice() != [STRUCTURE_EXPIRY_TOMBSTONE]
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    metadata.expires_at_micros = Some(expires_at_micros);
    let mut entries = vec![
        (metadata_key, encode_list_metadata(metadata)),
        (expiry_key, vec![STRUCTURE_LIST_EXPIRY_LIVE]),
    ];
    if let Some(previous) = previous_expiry {
        entries.push((
            structure_expiry_key(previous, &mutation.key)?,
            vec![STRUCTURE_EXPIRY_TOMBSTONE],
        ));
    }
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn structure_stream_meta_key(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    if key
        .len()
        .checked_add(9)
        .is_none_or(|length| length > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::StructureIdentityTooLarge);
    }
    let mut encoded = Vec::with_capacity(key.len() + 1);
    encoded.push(STRUCTURE_STREAM_META_PREFIX);
    encoded.extend_from_slice(key);
    Ok(encoded)
}

fn structure_stream_entry_key(key: &[u8], id: u64) -> Result<Vec<u8>, NativeRuntimeError> {
    let mut encoded = structure_stream_entry_prefix(key)?;
    encoded.extend_from_slice(&id.to_be_bytes());
    Ok(encoded)
}

fn structure_stream_entry_prefix(key: &[u8]) -> Result<Vec<u8>, NativeRuntimeError> {
    let mut encoded = structure_stream_meta_key(key)?;
    encoded[0] = STRUCTURE_STREAM_ENTRY_PREFIX;
    Ok(encoded)
}

fn create_stream_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let key = structure_stream_meta_key(&mutation.key)?;
    if tree.get(pages, &key)?.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree
        .upsert(pages, creating_csn, key, 0_u64.to_be_bytes().to_vec())?
        .tree)
}

fn append_stream_entry_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let (id, _) = decode_stream_wal_entry(&mutation.value)?;
    let metadata_key = structure_stream_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let last = u64::from_be_bytes(
        metadata
            .get(..8)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
    );
    if id <= last {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let entry_key = structure_stream_entry_key(&mutation.key, id)?;
    if tree.get(pages, &entry_key)?.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    tree = tree
        .upsert(pages, creating_csn, entry_key, mutation.value.clone())?
        .tree;
    let mut next_metadata = id.to_be_bytes().to_vec();
    if metadata.len() == 16 {
        next_metadata.extend_from_slice(&metadata[8..16]);
    } else if metadata.len() != 8 {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree
        .upsert(pages, creating_csn, metadata_key, next_metadata)?
        .tree)
}

fn expire_stream_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let expiry = mutation
        .expires_at_micros
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let key = structure_stream_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (last, previous_expiry) = match metadata.len() {
        8 => (
            u64::from_be_bytes(
                metadata[..8]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            ),
            None,
        ),
        16 => (
            u64::from_be_bytes(
                metadata[..8]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            ),
            Some(i64::from_be_bytes(
                metadata[8..16]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            )),
        ),
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    };
    let mut updated = last.to_be_bytes().to_vec();
    updated.extend_from_slice(&expiry.to_be_bytes());
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    let mut entries = vec![
        (key, updated),
        (expiry_key, vec![STRUCTURE_STREAM_EXPIRY_LIVE]),
    ];
    if let Some(previous) = previous_expiry
        && previous != expiry
    {
        let previous_key = structure_expiry_key(previous, &mutation.key)?;
        if tree.get(pages, &previous_key)?.as_deref() != Some(&[STRUCTURE_STREAM_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        entries.push((previous_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    }
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn delete_stream_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let metadata_key = structure_stream_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let last = u64::from_be_bytes(
        metadata
            .get(..8)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
    );
    let expiry = match metadata.len() {
        8 => None,
        16 => Some(i64::from_be_bytes(
            metadata[8..16]
                .try_into()
                .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
        )),
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    };
    for id in 1..=last {
        let entry_key = structure_stream_entry_key(&mutation.key, id)?;
        if tree.get(pages, &entry_key)?.is_some() {
            tree = tree
                .upsert(pages, creating_csn, entry_key, structure_tombstone_value())?
                .tree;
        }
    }
    if let Some(expiry) = expiry {
        let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
        if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_STREAM_EXPIRY_LIVE]) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        tree = tree
            .upsert(
                pages,
                creating_csn,
                expiry_key,
                vec![STRUCTURE_EXPIRY_TOMBSTONE],
            )?
            .tree;
    }
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            structure_tombstone_value(),
        )?
        .tree)
}

fn expire_sorted_set_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    let expiry = mutation
        .expires_at_micros
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let metadata_key = structure_sorted_set_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (count, previous) = decode_sorted_set_metadata_state(&metadata)?;
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    let mut entries = vec![
        (
            metadata_key,
            encode_sorted_set_metadata_state(count, Some(expiry)),
        ),
        (expiry_key, vec![STRUCTURE_SORTED_SET_EXPIRY_LIVE]),
    ];
    if let Some(previous) = previous
        && previous != expiry
    {
        entries.push((
            structure_expiry_key(previous, &mutation.key)?,
            vec![STRUCTURE_EXPIRY_TOMBSTONE],
        ));
    }
    entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    Ok(tree.upsert_sorted_batch(pages, creating_csn, entries)?.tree)
}

fn delete_sorted_set_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_sorted_set_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (count, expiry) = decode_sorted_set_metadata_state(&metadata)?;
    let expiry_key = expiry
        .map(|expiry| structure_expiry_key(expiry, &mutation.key))
        .transpose()?;
    if let Some(expiry_key) = expiry_key.as_ref()
        && tree.get(pages, expiry_key)?.as_deref() != Some(&[STRUCTURE_SORTED_SET_EXPIRY_LIVE])
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let prefix = structure_sorted_set_member_key(&mutation.key, &[])?;
    let members = tree.scan_prefix(pages, &prefix)?;
    let mut live = 0_u64;
    for (member_key, encoded) in members {
        let Some(score) = decode_sorted_set_score(&encoded)? else {
            continue;
        };
        let (key, member) = decode_sorted_set_member_identity(&member_key[1..])?;
        if key != mutation.key {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        live = live
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let order_key = structure_sorted_set_order_key(key, score, member)?;
        if tree.get(pages, &order_key)?.as_deref() != Some(&set_member_live_value()) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        tree = tree
            .upsert(pages, creating_csn, member_key, structure_tombstone_value())?
            .tree;
        tree = tree
            .upsert(pages, creating_csn, order_key, structure_tombstone_value())?
            .tree;
    }
    if live != count {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if let Some(expiry_key) = expiry_key {
        tree = tree
            .upsert(
                pages,
                creating_csn,
                expiry_key,
                vec![STRUCTURE_EXPIRY_TOMBSTONE],
            )?
            .tree;
    }
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            structure_tombstone_value(),
        )?
        .tree)
}

fn create_sorted_set_in_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_sorted_set_meta_key(&mutation.key)?;
    if tree.get(pages, &metadata_key)?.is_some()
        || tree
            .get(pages, &structure_hash_meta_key(&mutation.key))?
            .map(|value| decode_live_hash_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_set_meta_key(&mutation.key))?
            .map(|value| decode_live_set_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_list_meta_key(&mutation.key)?)?
            .map(|value| decode_live_list_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_key(&mutation.key))?
            .is_some_and(|value| !is_structure_tombstone(&value))
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(tree
        .insert_unique(
            pages,
            creating_csn,
            metadata_key,
            encode_sorted_set_metadata(0),
        )?
        .tree)
}

fn upsert_sorted_set_member_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, member) = decode_sorted_set_member_identity(&mutation.key)?;
    let score = decode_sorted_set_wal_score(&mutation.value)
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
    let metadata_key = structure_sorted_set_meta_key(key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (mut count, expiry) = decode_sorted_set_metadata_state(&metadata)?;
    let member_key = structure_sorted_set_member_key(key, member)?;
    let previous = tree
        .get(pages, &member_key)?
        .map(|encoded| decode_sorted_set_score(&encoded))
        .transpose()?
        .flatten();
    if previous == Some(score) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if let Some(previous) = previous {
        let old_order_key = structure_sorted_set_order_key(key, previous, member)?;
        let old_marker = tree
            .get(pages, &old_order_key)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if !decode_set_member_value(&old_marker)? {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        tree = tree
            .upsert(
                pages,
                creating_csn,
                old_order_key,
                structure_tombstone_value(),
            )?
            .tree;
    } else {
        count = count
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        tree = tree
            .upsert(
                pages,
                creating_csn,
                metadata_key.clone(),
                encode_sorted_set_metadata_state(count, expiry),
            )?
            .tree;
    }
    let new_order_key = structure_sorted_set_order_key(key, score, member)?;
    if tree
        .get(pages, &new_order_key)?
        .is_some_and(|encoded| decode_set_member_value(&encoded).unwrap_or(true))
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    tree = tree
        .upsert(
            pages,
            creating_csn,
            member_key,
            encode_sorted_set_score(score),
        )?
        .tree;
    Ok(tree
        .upsert(pages, creating_csn, new_order_key, set_member_live_value())?
        .tree)
}

fn delete_sorted_set_member_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
) -> Result<BTree, NativeRuntimeError> {
    if !mutation.value.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let (key, member) = decode_sorted_set_member_identity(&mutation.key)?;
    let metadata_key = structure_sorted_set_meta_key(key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (count, expiry) = decode_sorted_set_metadata_state(&metadata)?;
    let member_key = structure_sorted_set_member_key(key, member)?;
    let score = tree
        .get(pages, &member_key)?
        .map(|encoded| decode_sorted_set_score(&encoded))
        .transpose()?
        .flatten()
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let order_key = structure_sorted_set_order_key(key, score, member)?;
    let order_marker = tree
        .get(pages, &order_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if !decode_set_member_value(&order_marker)? {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    tree = tree
        .upsert(pages, creating_csn, member_key, structure_tombstone_value())?
        .tree;
    tree = tree
        .upsert(pages, creating_csn, order_key, structure_tombstone_value())?
        .tree;
    let count = count
        .checked_sub(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_sorted_set_metadata_state(count, expiry),
        )?
        .tree)
}

fn push_list_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
    at_head: bool,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    if mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_list_meta_key(&mutation.key)?;
    let encoded_metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_list_metadata(&encoded_metadata)?;
    let element = structure_storage_value(&mutation.value, None, blob_references)?;
    if metadata.length == 0 {
        let chunk_key = structure_list_chunk_key(&mutation.key, 0)?;
        if tree
            .get(pages, &chunk_key)?
            .is_some_and(|encoded| !is_structure_tombstone(&encoded))
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        tree = tree
            .upsert(
                pages,
                creating_csn,
                chunk_key,
                encode_list_chunk_storage(&[element])?,
            )?
            .tree;
        metadata = ListMetadata {
            length: 1,
            value_bytes: Some(
                u64::try_from(mutation.value.len())
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
            ),
            head_chunk: 0,
            tail_chunk: 0,
            expires_at_micros: metadata.expires_at_micros,
        };
    } else {
        let boundary = if at_head {
            metadata.head_chunk
        } else {
            metadata.tail_chunk
        };
        let chunk_key = structure_list_chunk_key(&mutation.key, boundary)?;
        let elements = tree
            .get(pages, &chunk_key)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let elements = decode_list_chunk_storage(&elements)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if let Some(encoded) = list_chunk_with_push(elements, element.clone(), at_head)? {
            tree = tree.upsert(pages, creating_csn, chunk_key, encoded)?.tree;
        } else {
            let next = if at_head {
                boundary
                    .checked_sub(1)
                    .ok_or(NativeRuntimeError::StructureListIndexExhausted)?
            } else {
                boundary
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::StructureListIndexExhausted)?
            };
            let next_key = structure_list_chunk_key(&mutation.key, next)?;
            if tree
                .get(pages, &next_key)?
                .is_some_and(|encoded| !is_structure_tombstone(&encoded))
            {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            tree = tree
                .upsert(
                    pages,
                    creating_csn,
                    next_key,
                    encode_list_chunk_storage(&[element])?,
                )?
                .tree;
            if at_head {
                metadata.head_chunk = next;
            } else {
                metadata.tail_chunk = next;
            }
        }
        metadata.length = metadata
            .length
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        add_list_value_bytes(&mut metadata, mutation.value.len())?;
    }
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_list_metadata(metadata),
        )?
        .tree)
}

fn pop_list_in_tree(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
    at_head: bool,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    if mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let metadata_key = structure_list_meta_key(&mutation.key)?;
    let encoded_metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut metadata = decode_list_metadata(&encoded_metadata)?;
    if metadata.length == 0 {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let boundary = if at_head {
        metadata.head_chunk
    } else {
        metadata.tail_chunk
    };
    let chunk_key = structure_list_chunk_key(&mutation.key, boundary)?;
    let encoded_chunk = tree
        .get(pages, &chunk_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut elements = decode_list_chunk_storage(&encoded_chunk)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let removed = if at_head {
        elements.remove(0)
    } else {
        elements
            .pop()
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
    };
    let expected = structure_storage_value(&mutation.value, None, blob_references)?;
    if removed != expected {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    metadata.length = metadata
        .length
        .checked_sub(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    remove_list_value_bytes(&mut metadata, mutation.value.len())?;
    if elements.is_empty() {
        tree = tree
            .upsert(pages, creating_csn, chunk_key, structure_tombstone_value())?
            .tree;
        if metadata.length == 0 {
            metadata = ListMetadata::empty();
        } else if at_head {
            metadata.head_chunk = metadata
                .head_chunk
                .checked_add(1)
                .ok_or(NativeRuntimeError::StructureListIndexExhausted)?;
        } else {
            metadata.tail_chunk = metadata
                .tail_chunk
                .checked_sub(1)
                .ok_or(NativeRuntimeError::StructureListIndexExhausted)?;
        }
    } else {
        if metadata.length == 0 {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        tree = tree
            .upsert(
                pages,
                creating_csn,
                chunk_key,
                encode_list_chunk_storage(&elements)?,
            )?
            .tree;
    }
    Ok(tree
        .upsert(
            pages,
            creating_csn,
            metadata_key,
            encode_list_metadata(metadata),
        )?
        .tree)
}

fn structure_tree_after_mutations(
    pages: &mut PageStore,
    root: Option<PageId>,
    format: StructureFormat,
    creating_csn: Csn,
    mutations: &[Mutation],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let marker = format
        .marker()
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut tree = root.map_or_else(BTree::empty, BTree::from_root);
    if tree.root().is_none() {
        tree = tree
            .insert_unique(
                pages,
                creating_csn,
                STRUCTURE_FORMAT_KEY.to_vec(),
                marker.to_vec(),
            )?
            .tree;
    }
    for mutation in mutations
        .iter()
        .filter(|mutation| mutation.engine == EngineKind::Structure)
    {
        tree = apply_structure_tree_mutation(
            pages,
            tree,
            format,
            creating_csn,
            mutation,
            blob_references,
        )?;
    }
    Ok(tree)
}

fn apply_structure_tree_mutation(
    pages: &mut PageStore,
    tree: BTree,
    format: StructureFormat,
    creating_csn: Csn,
    mutation: &Mutation,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    if mutation.target.is_some() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    match mutation.opcode {
        Opcode::CreateHash => create_hash_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteHash => delete_hash_in_tree(pages, tree, creating_csn, mutation),
        Opcode::ExpireHash => expire_hash_in_tree(pages, tree, creating_csn, mutation),
        Opcode::ExpireHashField => expire_hash_field_in_tree(pages, tree, creating_csn, mutation),
        Opcode::SetHashField => {
            set_hash_field_in_tree(pages, tree, creating_csn, mutation, blob_references)
        }
        Opcode::DeleteHashField => delete_hash_field_in_tree(pages, tree, creating_csn, mutation),
        Opcode::CreateSet => create_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::ExpireSet => expire_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteSet => delete_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::AddSetMember => add_set_member_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteSetMember => delete_set_member_in_tree(pages, tree, creating_csn, mutation),
        Opcode::CreateStream => create_stream_in_tree(pages, tree, creating_csn, mutation),
        Opcode::AppendStreamEntry => {
            append_stream_entry_in_tree(pages, tree, creating_csn, mutation)
        }
        Opcode::ExpireStream => expire_stream_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteStream => delete_stream_in_tree(pages, tree, creating_csn, mutation),
        Opcode::CreateSortedSet => create_sorted_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteSortedSet => delete_sorted_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::ExpireSortedSet => expire_sorted_set_in_tree(pages, tree, creating_csn, mutation),
        Opcode::UpsertSortedSetMember => {
            upsert_sorted_set_member_in_tree(pages, tree, creating_csn, mutation)
        }
        Opcode::DeleteSortedSetMember => {
            delete_sorted_set_member_in_tree(pages, tree, creating_csn, mutation)
        }
        Opcode::CreateList => create_list_in_tree(pages, tree, creating_csn, mutation),
        Opcode::DeleteList => delete_list_in_tree(pages, tree, creating_csn, mutation),
        Opcode::ExpireList => expire_list_in_tree(pages, tree, creating_csn, mutation),
        Opcode::PushListHead | Opcode::PushListTail => push_list_in_tree(
            pages,
            tree,
            creating_csn,
            mutation,
            mutation.opcode == Opcode::PushListHead,
            blob_references,
        ),
        Opcode::PopListHead | Opcode::PopListTail => pop_list_in_tree(
            pages,
            tree,
            creating_csn,
            mutation,
            mutation.opcode == Opcode::PopListHead,
            blob_references,
        ),
        Opcode::SetValue | Opcode::ExpireValue | Opcode::DeleteValue => {
            upsert_scalar_structure_mutation(
                pages,
                tree,
                format.uses_ordered_expiry_index(),
                creating_csn,
                mutation,
                blob_references,
            )
        }
        _ => Err(NativeRuntimeError::InvalidStructureTree),
    }
}

fn upsert_scalar_structure_mutation(
    pages: &mut PageStore,
    mut tree: BTree,
    maintain_expiry_index: bool,
    creating_csn: Csn,
    mutation: &Mutation,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let value = match mutation.opcode {
        Opcode::SetValue => {
            structure_storage_value(&mutation.value, mutation.expires_at_micros, blob_references)?
        }
        Opcode::ExpireValue if mutation.expires_at_micros.is_some() => {
            structure_storage_value(&mutation.value, mutation.expires_at_micros, blob_references)?
        }
        Opcode::DeleteValue
            if mutation.value.is_empty() && mutation.expires_at_micros.is_none() =>
        {
            structure_tombstone_value()
        }
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    };
    if tree
        .get(pages, &structure_hash_meta_key(&mutation.key))?
        .map(|value| decode_live_hash_metadata(&value))
        .transpose()?
        .flatten()
        .is_some()
        || tree
            .get(pages, &structure_set_meta_key(&mutation.key))?
            .map(|value| decode_live_set_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_list_meta_key(&mutation.key)?)?
            .map(|value| decode_live_list_metadata(&value))
            .transpose()?
            .flatten()
            .is_some()
        || tree
            .get(pages, &structure_stream_meta_key(&mutation.key)?)?
            .as_deref()
            .filter(|value| !is_structure_tombstone(value))
            .map(decode_stream_metadata)
            .transpose()?
            .is_some()
        || tree
            .get(pages, &structure_sorted_set_meta_key(&mutation.key)?)?
            .as_deref()
            .filter(|value| !is_structure_tombstone(value))
            .map(decode_sorted_set_metadata_state)
            .transpose()?
            .is_some()
    {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if maintain_expiry_index {
        let prior_expiry = tree
            .get(pages, &structure_key(&mutation.key))?
            .map(|encoded| structure_value_expiry(&encoded))
            .transpose()?
            .flatten();
        let new_expiry = mutation.expires_at_micros;
        if prior_expiry != new_expiry {
            if let Some(expiry) = prior_expiry {
                tree = tree
                    .upsert(
                        pages,
                        creating_csn,
                        structure_expiry_key(expiry, &mutation.key)?,
                        vec![STRUCTURE_EXPIRY_TOMBSTONE],
                    )?
                    .tree;
            }
            if let Some(expiry) = new_expiry {
                tree = tree
                    .upsert(
                        pages,
                        creating_csn,
                        structure_expiry_key(expiry, &mutation.key)?,
                        vec![STRUCTURE_EXPIRY_LIVE],
                    )?
                    .tree;
            }
        }
    }
    Ok(tree
        .upsert(pages, creating_csn, structure_key(&mutation.key), value)?
        .tree)
}

struct StructureMutationContext<'a> {
    blobs: &'a BlobStore,
    buffer_pool: &'a BufferPool,
    format: StructureFormat,
    mode: NativeWriteBatchMode,
    transaction_id: TransactionId,
    logical_time_micros: i64,
    state: &'a StructureState,
    mutations: &'a [Mutation],
    blob_references: &'a BTreeMap<[u8; 32], BlobReference>,
}

fn structure_root_after_mutations(
    pages: &mut PageStore,
    root: Option<PageId>,
    creating_csn: Csn,
    context: &StructureMutationContext<'_>,
) -> Result<Option<PageId>, NativeRuntimeError> {
    if context.mode == NativeWriteBatchMode::PhysicalStructureExpiry {
        return structure_expiry_root_after_mutations(pages, root, creating_csn, context);
    }
    if context.mode == NativeWriteBatchMode::PhysicalStructureCompaction {
        let source = BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?);
        return match context.format {
            StructureFormat::BTreeV2 => {
                Ok(compact_structure_tree(pages, context.blobs, root, creating_csn)?.root())
            }
            StructureFormat::BTreeV3 => Ok(structure_v3::compact_structure_v3_tree(
                pages,
                context.blobs,
                source,
                creating_csn,
            )?
            .0
            .root()),
            StructureFormat::InlineStateV1 | StructureFormat::BTreeV1 => {
                Err(NativeRuntimeError::InvalidPreparedMutation)
            }
        };
    }
    if context.mode == NativeWriteBatchMode::PhysicalStructureMigrationV3 {
        if context.format != StructureFormat::BTreeV2 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let source = BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?);
        return Ok(structure_v3::migrate_v2_structure_tree_to_v3(
            pages,
            context.blobs,
            source,
            creating_csn,
            context.transaction_id,
        )?
        .root());
    }
    if context.mode == NativeWriteBatchMode::PhysicalStructureRetirementV3 {
        if context.format != StructureFormat::BTreeV3 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let [mutation] = context.mutations else {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        };
        validate_maintenance_mutation(mutation)?;
        let entry_budget = usize::try_from(u32::from_le_bytes(
            mutation
                .value
                .as_slice()
                .try_into()
                .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?,
        ))
        .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?;
        return Ok(structure_v3::cleanup_structure_retirement_v3_step(
            pages,
            context.buffer_pool,
            BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?),
            creating_csn,
            &mutation.key,
            entry_budget,
        )?
        .root());
    }
    match context.format {
        StructureFormat::InlineStateV1 => Ok(Some(pages.append(
            PageKind::StructureNode,
            Some(creating_csn),
            None,
            context.state.encode()?,
        )?)),
        StructureFormat::BTreeV1 | StructureFormat::BTreeV2 => Ok(structure_tree_after_mutations(
            pages,
            root,
            context.format,
            creating_csn,
            context.mutations,
            context.blob_references,
        )?
        .root()),
        StructureFormat::BTreeV3 => Ok(structure_v3::apply_structure_mutations_v3(
            pages,
            BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?),
            creating_csn,
            context.transaction_id,
            context.mutations,
            context.blob_references,
        )?
        .root()),
    }
}

fn structure_expiry_root_after_mutations(
    pages: &mut PageStore,
    root: Option<PageId>,
    creating_csn: Csn,
    context: &StructureMutationContext<'_>,
) -> Result<Option<PageId>, NativeRuntimeError> {
    match context.format {
        StructureFormat::BTreeV2 => Ok(physical_expiry_tree_after_mutations(
            pages,
            root,
            creating_csn,
            context.logical_time_micros,
            context.mutations,
        )?
        .root()),
        StructureFormat::BTreeV3 => Ok(structure_v3::expire_due_structure_mutations_v3(
            pages,
            BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?),
            creating_csn,
            context.logical_time_micros,
            context.mutations,
        )?
        .root()),
        StructureFormat::InlineStateV1 | StructureFormat::BTreeV1 => {
            Err(NativeRuntimeError::InvalidPreparedMutation)
        }
    }
}

fn physical_expiry_tree_after_mutations(
    pages: &mut PageStore,
    root: Option<PageId>,
    creating_csn: Csn,
    logical_time_micros: i64,
    mutations: &[Mutation],
) -> Result<BTree, NativeRuntimeError> {
    let tree = BTree::from_root(root.ok_or(NativeRuntimeError::InvalidStructureTree)?);
    let mut physical_entries = Vec::new();
    let mut hash_field_decrements = BTreeMap::<Vec<u8>, u64>::new();
    for mutation in mutations {
        if mutation.engine != EngineKind::Structure
            || mutation.target.is_some()
            || !mutation.value.is_empty()
            || mutation.expires_at_micros.is_some()
        {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let entries = match mutation.opcode {
            Opcode::DeleteValue => {
                physical_scalar_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteHash => {
                physical_hash_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteSet => {
                physical_set_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteList => {
                physical_list_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteStream => {
                physical_stream_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteSortedSet => {
                physical_sorted_set_expiry_entries(pages, tree, logical_time_micros, mutation)?
            }
            Opcode::DeleteHashField => physical_hash_field_expiry_entries(
                pages,
                tree,
                logical_time_micros,
                mutation,
                &mut hash_field_decrements,
            )?,
            _ => return Err(NativeRuntimeError::InvalidPreparedMutation),
        };
        physical_entries.extend(entries);
    }
    physical_entries.extend(hash_field_expiry_metadata_entries(
        pages,
        tree,
        hash_field_decrements,
    )?);
    physical_entries.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if physical_entries
        .windows(2)
        .any(|pair| pair[0].0 == pair[1].0)
    {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    Ok(tree
        .upsert_sorted_batch(pages, creating_csn, physical_entries)?
        .tree)
}

fn physical_scalar_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let scalar_key = structure_key(&mutation.key);
    let scalar = tree
        .get(pages, &scalar_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry = structure_value_expiry(&scalar)?
        .filter(|expiry| *expiry <= logical_time_micros)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(vec![
        (scalar_key, structure_tombstone_value()),
        (expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]),
    ])
}

fn physical_hash_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let metadata_key = structure_hash_meta_key(&mutation.key);
    let encoded = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let metadata =
        decode_live_hash_metadata(&encoded)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry = metadata
        .expires_at_micros
        .filter(|expiry| *expiry <= logical_time_micros)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_HASH_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let field_prefix = structure_hash_field_key(&mutation.key, &[])?;
    let mut live_count = 0_u64;
    let mut entries = Vec::new();
    for (field_key, value) in tree.scan_prefix(pages, &field_prefix)? {
        let (hash_key, field) = decode_hash_field_identity(
            field_key
                .get(1..)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?,
        )
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if hash_key != mutation.key {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if is_structure_tombstone(&value) {
            continue;
        }
        if let Some(field_expiry) = structure_value_expiry(&value)? {
            let field_expiry_key = structure_hash_field_expiry_key(field_expiry, hash_key, field)?;
            if tree.get(pages, &field_expiry_key)?.as_deref()
                != Some(&[STRUCTURE_HASH_FIELD_EXPIRY_LIVE])
            {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            entries.push((field_expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
        }
        live_count = live_count
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        entries.push((field_key, structure_tombstone_value()));
    }
    if live_count != metadata.field_count {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    entries.push((metadata_key, structure_tombstone_value()));
    entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    Ok(entries)
}

fn physical_set_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let metadata_key = structure_set_meta_key(&mutation.key);
    let encoded = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let metadata =
        decode_live_set_metadata(&encoded)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry = metadata
        .expires_at_micros
        .filter(|expiry| *expiry <= logical_time_micros)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_SET_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let member_prefix = structure_set_member_key(&mutation.key, &[])?;
    let mut live_count = 0_u64;
    let mut entries = Vec::new();
    for (member_key, value) in tree.scan_prefix(pages, &member_prefix)? {
        let (set, _) = decode_set_member_identity(
            member_key
                .get(1..)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?,
        )
        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if set != mutation.key {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if decode_set_member_value(&value)? {
            live_count = live_count
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            entries.push((member_key, structure_tombstone_value()));
        }
    }
    if live_count != metadata.member_count {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    entries.push((metadata_key, structure_tombstone_value()));
    entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    Ok(entries)
}

fn physical_list_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    list_retirement_entries(pages, tree, mutation, Some(logical_time_micros))
}

fn physical_sorted_set_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let metadata_key = structure_sorted_set_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let (count, expiry) = decode_sorted_set_metadata_state(&metadata)?;
    let expiry = expiry
        .filter(|expiry| *expiry <= logical_time_micros)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_SORTED_SET_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let mut entries = vec![
        (metadata_key, structure_tombstone_value()),
        (expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]),
    ];
    let prefix = structure_sorted_set_member_key(&mutation.key, &[])?;
    let mut live = 0_u64;
    for (member_key, encoded) in tree.scan_prefix(pages, &prefix)? {
        let Some(score) = decode_sorted_set_score(&encoded)? else {
            continue;
        };
        let (key, member) = decode_sorted_set_member_identity(&member_key[1..])?;
        let order_key = structure_sorted_set_order_key(key, score, member)?;
        live += 1;
        entries.push((member_key, structure_tombstone_value()));
        entries.push((order_key, structure_tombstone_value()));
    }
    if live != count {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(entries)
}

fn physical_stream_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let metadata_key = structure_stream_meta_key(&mutation.key)?;
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    if metadata.len() != 16 {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let last = u64::from_be_bytes(
        metadata[..8]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
    );
    let expiry = i64::from_be_bytes(
        metadata[8..16]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
    );
    if expiry > logical_time_micros {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let expiry_key = structure_expiry_key(expiry, &mutation.key)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_STREAM_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let capacity = usize::try_from(last)
        .ok()
        .and_then(|last| last.checked_add(2))
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let mut entries = Vec::with_capacity(capacity);
    entries.push((metadata_key, structure_tombstone_value()));
    entries.push((expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]));
    for id in 1..=last {
        let key = structure_stream_entry_key(&mutation.key, id)?;
        if tree.get(pages, &key)?.is_some() {
            entries.push((key, structure_tombstone_value()));
        }
    }
    Ok(entries)
}

fn physical_hash_field_expiry_entries(
    pages: &PageStore,
    tree: BTree,
    logical_time_micros: i64,
    mutation: &Mutation,
    decrements: &mut BTreeMap<Vec<u8>, u64>,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let (hash_key, field) = decode_hash_field_identity(&mutation.key)?;
    let metadata = tree
        .get(pages, &structure_hash_meta_key(hash_key))?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    decode_live_hash_metadata(&metadata)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let field_key = structure_hash_field_key(hash_key, field)?;
    let field_value = tree
        .get(pages, &field_key)?
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry = structure_value_expiry(&field_value)?
        .filter(|expiry| *expiry <= logical_time_micros)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let expiry_key = structure_hash_field_expiry_key(expiry, hash_key, field)?;
    if tree.get(pages, &expiry_key)?.as_deref() != Some(&[STRUCTURE_HASH_FIELD_EXPIRY_LIVE]) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let decrement = decrements.entry(hash_key.to_vec()).or_default();
    *decrement = decrement
        .checked_add(1)
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    Ok(vec![
        (field_key, structure_tombstone_value()),
        (expiry_key, vec![STRUCTURE_EXPIRY_TOMBSTONE]),
    ])
}

fn hash_field_expiry_metadata_entries(
    pages: &PageStore,
    tree: BTree,
    decrements: BTreeMap<Vec<u8>, u64>,
) -> Result<PhysicalStructureEntries, NativeRuntimeError> {
    let mut entries = Vec::with_capacity(decrements.len());
    for (hash_key, decrement) in decrements {
        let metadata_key = structure_hash_meta_key(&hash_key);
        let encoded = tree
            .get(pages, &metadata_key)?
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let mut metadata =
            decode_live_hash_metadata(&encoded)?.ok_or(NativeRuntimeError::InvalidStructureTree)?;
        metadata.field_count = metadata
            .field_count
            .checked_sub(decrement)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        entries.push((metadata_key, encode_hash_metadata_state(metadata)));
    }
    Ok(entries)
}

fn compact_structure_tree(
    pages: &mut PageStore,
    blobs: &BlobStore,
    root: Option<PageId>,
    creating_csn: Csn,
) -> Result<BTree, NativeRuntimeError> {
    let root = root.ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let plan = plan_structure_compaction(pages, blobs, root)?;
    if plan.dropped_tombstones == 0 {
        return Ok(BTree::from_root(root));
    }
    let compacted = BTree::empty()
        .upsert_sorted_batch(pages, creating_csn, plan.retained_entries)?
        .tree;
    let compacted_root = compacted
        .root()
        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
    let compacted_state = load_structure_state_root(pages, blobs, compacted_root)?;
    if compacted_state != plan.state {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(compacted)
}

struct SearchCompactionPlan {
    state: SearchState,
    scanned_entries: usize,
    retained_entries: Vec<(Vec<u8>, Vec<u8>)>,
    dropped_tombstones: usize,
}

fn plan_search_compaction(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
) -> Result<SearchCompactionPlan, NativeRuntimeError> {
    let state = load_search_state_root(pages, blobs, root)?;
    let tree = BTree::from_root(root);
    let format = physical_search_format(pages, tree)?;
    let entries = tree.scan(pages)?;
    let scanned_entries = entries.len();
    let mut retained_entries = Vec::with_capacity(scanned_entries);
    let mut dropped_tombstones = 0_usize;
    for (key, value) in entries {
        if compactable_search_tombstone(format, &key, &value) {
            dropped_tombstones = dropped_tombstones
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        } else {
            retained_entries.push((key, value));
        }
    }
    Ok(SearchCompactionPlan {
        state,
        scanned_entries,
        retained_entries,
        dropped_tombstones,
    })
}

fn compactable_search_tombstone(format: PhysicalSearchFormat, key: &[u8], value: &[u8]) -> bool {
    if !format.admits_tombstones() {
        return false;
    }
    match key.first().copied() {
        Some(SEARCH_DOCUMENT_PREFIX) => is_search_document_tombstone(value),
        Some(SEARCH_TERM_META_PREFIX) => is_search_term_metadata_tombstone(value),
        Some(SEARCH_POSTING_PREFIX) => is_search_posting_tombstone(value),
        _ => false,
    }
}

fn compact_search_tree(
    pages: &mut PageStore,
    blobs: &BlobStore,
    root: Option<PageId>,
    creating_csn: Csn,
) -> Result<BTree, NativeRuntimeError> {
    let root = root.ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let plan = plan_search_compaction(pages, blobs, root)?;
    if plan.dropped_tombstones == 0 {
        return Ok(BTree::from_root(root));
    }
    let compacted = BTree::empty()
        .upsert_sorted_batch(pages, creating_csn, plan.retained_entries)?
        .tree;
    let compacted_root = compacted
        .root()
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let compacted_state = load_search_state_root(pages, blobs, compacted_root)?;
    if compacted_state != plan.state {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    Ok(compacted)
}

fn search_tree_after_mutations(
    pages: &mut PageStore,
    blobs: &BlobStore,
    root: Option<PageId>,
    creating_csn: Csn,
    catalog: &CatalogState,
    mutations: &[Mutation],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let mut tree = root.map_or_else(BTree::empty, BTree::from_root);
    if tree.root().is_none() {
        tree = tree
            .insert_unique(
                pages,
                creating_csn,
                SEARCH_FORMAT_KEY.to_vec(),
                SEARCH_FORMAT_VALUE_V1.to_vec(),
            )?
            .tree;
    }
    for mutation in mutations.iter().filter(|mutation| {
        mutation.engine == EngineKind::Search
            && matches!(
                mutation.opcode,
                Opcode::CreateIndex
                    | Opcode::IndexDocument
                    | Opcode::ReplaceDocument
                    | Opcode::DeleteDocument
            )
    }) {
        tree = apply_search_tree_mutation(
            pages,
            blobs,
            tree,
            creating_csn,
            mutation,
            blob_references,
        )?;
    }
    ann_store::apply_tree_mutations(pages, tree, creating_csn, catalog, mutations)
}

fn apply_search_tree_mutation(
    pages: &mut PageStore,
    blobs: &BlobStore,
    tree: BTree,
    creating_csn: Csn,
    mutation: &Mutation,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let index = mutation
        .target
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    match mutation.opcode {
        Opcode::CreateIndex => {
            if mutation.expires_at_micros.is_some()
                || decode_search_creation(index, mutation).is_err()
            {
                return Err(NativeRuntimeError::InvalidSearchTree);
            }
            Ok(tree
                .insert_unique(
                    pages,
                    creating_csn,
                    search_index_meta_key(index),
                    encode_search_index_metadata(0, 0),
                )?
                .tree)
        }
        Opcode::IndexDocument if mutation.expires_at_micros.is_none() => {
            index_document_in_search_tree(
                pages,
                tree,
                creating_csn,
                index,
                mutation,
                blob_references,
            )
        }
        Opcode::ReplaceDocument if mutation.expires_at_micros.is_none() => {
            lifecycle_document_in_search_tree(
                pages,
                blobs,
                tree,
                creating_csn,
                index,
                mutation,
                Some(&mutation.value),
                blob_references,
            )
        }
        Opcode::DeleteDocument
            if mutation.expires_at_micros.is_none() && mutation.value.is_empty() =>
        {
            lifecycle_document_in_search_tree(
                pages,
                blobs,
                tree,
                creating_csn,
                index,
                mutation,
                None,
                blob_references,
            )
        }
        _ => Err(NativeRuntimeError::InvalidSearchTree),
    }
}

fn index_document_in_search_tree(
    pages: &mut PageStore,
    tree: BTree,
    creating_csn: Csn,
    index: ObjectId,
    mutation: &Mutation,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let text =
        std::str::from_utf8(&mutation.value).map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
    validate_search_document_identity(&mutation.key, text)?;
    let metadata_key = search_index_meta_key(index);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let (document_count, total_document_terms) = decode_search_index_metadata(&metadata)?;
    let format = physical_search_format(pages, tree)?;
    let document_key = search_document_key(index, &mutation.key)?;
    if let Some(existing) = tree.get(pages, &document_key)?
        && (!format.admits_tombstones() || !is_search_document_tombstone(&existing))
    {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    let (token_count, frequencies) = search_term_frequencies(text)?;
    let mut entries = BTreeMap::new();
    entries.insert(
        document_key,
        search_document_storage_value(&mutation.value, token_count, blob_references)?,
    );
    for (term, term_frequency) in frequencies {
        let term_key = search_term_meta_key(index, &term)?;
        let document_frequency = tree
            .get(pages, &term_key)?
            .map(|encoded| decode_live_search_term_metadata(&encoded, format))
            .transpose()?
            .flatten()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let posting_key = search_posting_key(index, &term, &mutation.key)?;
        if let Some(encoded) = tree.get(pages, &posting_key)?
            && decode_live_search_posting(&encoded, format)?.is_some()
        {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
        entries.insert(term_key, encode_search_term_metadata(document_frequency));
        entries.insert(posting_key, encode_search_posting(term_frequency));
    }
    entries.insert(
        metadata_key,
        encode_search_index_metadata(
            document_count
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?,
            total_document_terms
                .checked_add(token_count)
                .ok_or(NativeRuntimeError::InvalidSearchTree)?,
        ),
    );
    Ok(tree
        .upsert_sorted_batch(pages, creating_csn, entries.into_iter().collect())?
        .tree)
}

#[allow(clippy::too_many_arguments)]
fn lifecycle_document_in_search_tree(
    pages: &mut PageStore,
    blobs: &BlobStore,
    tree: BTree,
    creating_csn: Csn,
    index: ObjectId,
    mutation: &Mutation,
    replacement: Option<&[u8]>,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let format = physical_search_format(pages, tree)?;
    let document_key = search_document_key(index, &mutation.key)?;
    let encoded_document = tree
        .get(pages, &document_key)?
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let (old_text, old_token_count) =
        decode_live_search_document(&encoded_document, blobs, format)?
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let (verified_old_count, old_frequencies) = search_term_frequencies(&old_text)?;
    if verified_old_count != old_token_count {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    let (new_token_count, new_frequencies) = if let Some(replacement) = replacement {
        let replacement =
            std::str::from_utf8(replacement).map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
        validate_search_document_identity(&mutation.key, replacement)?;
        search_term_frequencies(replacement)?
    } else {
        (0, BTreeMap::new())
    };
    let metadata_key = search_index_meta_key(index);
    let metadata = tree
        .get(pages, &metadata_key)?
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    let (document_count, total_document_terms) = decode_search_index_metadata(&metadata)?;
    let next_document_count = if replacement.is_some() {
        document_count
    } else {
        document_count
            .checked_sub(1)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?
    };
    let next_total_document_terms = total_document_terms
        .checked_sub(old_token_count)
        .and_then(|total| total.checked_add(new_token_count))
        .ok_or(NativeRuntimeError::InvalidSearchTree)?;

    let mut entries = BTreeMap::new();
    entries.insert(SEARCH_FORMAT_KEY.to_vec(), SEARCH_FORMAT_VALUE_V2.to_vec());
    entries.insert(
        document_key,
        if let Some(replacement) = replacement {
            search_document_storage_value(replacement, new_token_count, blob_references)?
        } else {
            SEARCH_DOCUMENT_TOMBSTONE.to_vec()
        },
    );
    entries.insert(
        metadata_key,
        encode_search_index_metadata(next_document_count, next_total_document_terms),
    );
    append_search_lifecycle_term_entries(
        pages,
        tree,
        format,
        index,
        &mutation.key,
        (&old_frequencies, &new_frequencies),
        &mut entries,
    )?;
    Ok(tree
        .upsert_sorted_batch(pages, creating_csn, entries.into_iter().collect())?
        .tree)
}

fn append_search_lifecycle_term_entries(
    pages: &PageStore,
    tree: BTree,
    format: PhysicalSearchFormat,
    index: ObjectId,
    document_id: &[u8],
    frequencies: (&SearchTermFrequencies, &SearchTermFrequencies),
    entries: &mut BTreeMap<Vec<u8>, Vec<u8>>,
) -> Result<(), NativeRuntimeError> {
    let (old_frequencies, new_frequencies) = frequencies;
    let terms = old_frequencies
        .keys()
        .chain(new_frequencies.keys())
        .cloned()
        .collect::<BTreeSet<_>>();
    for term in terms {
        let old_frequency = old_frequencies.get(&term).copied();
        let new_frequency = new_frequencies.get(&term).copied();
        let term_key = search_term_meta_key(index, &term)?;
        let current_document_frequency = tree
            .get(pages, &term_key)?
            .map(|encoded| decode_live_search_term_metadata(&encoded, format))
            .transpose()?
            .flatten();
        let posting_key = search_posting_key(index, &term, document_id)?;
        let current_term_frequency = tree
            .get(pages, &posting_key)?
            .map(|encoded| decode_live_search_posting(&encoded, format))
            .transpose()?
            .flatten();
        let next_document_frequency = match (old_frequency, new_frequency) {
            (Some(old), Some(new)) => {
                if current_term_frequency != Some(old) {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
                entries.insert(posting_key, encode_search_posting(new));
                current_document_frequency.ok_or(NativeRuntimeError::InvalidSearchTree)?
            }
            (Some(old), None) => {
                if current_term_frequency != Some(old) {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
                entries.insert(posting_key, SEARCH_POSTING_TOMBSTONE.to_vec());
                current_document_frequency
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?
                    .checked_sub(1)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?
            }
            (None, Some(new)) => {
                if current_term_frequency.is_some() {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
                entries.insert(posting_key, encode_search_posting(new));
                current_document_frequency
                    .unwrap_or(0)
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?
            }
            (None, None) => return Err(NativeRuntimeError::InvalidSearchTree),
        };
        entries.insert(
            term_key,
            if next_document_frequency == 0 {
                SEARCH_TERM_META_TOMBSTONE.to_vec()
            } else {
                encode_search_term_metadata(next_document_frequency)
            },
        );
    }
    Ok(())
}

fn search_term_frequencies(text: &str) -> Result<(u64, SearchTermFrequencies), NativeRuntimeError> {
    let tokens = analyze(text);
    let token_count =
        u64::try_from(tokens.len()).map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
    let mut frequencies = BTreeMap::new();
    for token in tokens {
        let frequency = frequencies.entry(token.into_bytes()).or_insert(0_u32);
        *frequency = frequency
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
    }
    Ok((token_count, frequencies))
}

struct SearchMutationContext<'a> {
    format: SearchFormat,
    mode: NativeWriteBatchMode,
    blobs: &'a BlobStore,
    buffer_pool: &'a BufferPool,
    catalog: &'a CatalogState,
    state: &'a SearchState,
    mutations: &'a [Mutation],
    blob_references: &'a BTreeMap<[u8; 32], BlobReference>,
    ann_consolidation: Option<&'a ann_store::ConsolidationPlan>,
    ann_consolidation_structure: Option<&'a PrefixReplacementStructuralPlan>,
    ann_initial_bulk: Option<&'a InitialAnnBulkPublication>,
}

fn search_root_after_mutations(
    pages: &mut PageStore,
    root: Option<PageId>,
    creating_csn: Csn,
    context: &SearchMutationContext<'_>,
) -> Result<Option<PageId>, NativeRuntimeError> {
    if context.mode == NativeWriteBatchMode::PhysicalInitialAnnBulkPublication {
        if context.format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let publication = context
            .ann_initial_bulk
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let replacement = ann_store::publish_initial_bulk_tree(
            pages,
            root,
            creating_csn,
            context.catalog,
            publication,
        )?;
        let replacement_root = replacement
            .root()
            .ok_or(NativeRuntimeError::InvalidAnnTree)?;
        load_search_state_root(pages, context.blobs, replacement_root)?;
        return Ok(Some(replacement_root));
    }
    if context.mode == NativeWriteBatchMode::PhysicalAnnConsolidation {
        if context.format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let plan = context
            .ann_consolidation
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let structural_plan = context
            .ann_consolidation_structure
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let replacement = ann_store::consolidate_tree(
            pages,
            context.buffer_pool,
            root,
            creating_csn,
            plan,
            structural_plan,
        )?;
        let replacement_root = replacement
            .root()
            .ok_or(NativeRuntimeError::InvalidAnnTree)?;
        return Ok(Some(replacement_root));
    }
    if context.mode == NativeWriteBatchMode::PhysicalSearchCompaction {
        if context.format != SearchFormat::InvertedBTreeV1 {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        return Ok(compact_search_tree(pages, context.blobs, root, creating_csn)?.root());
    }
    match context.format {
        SearchFormat::InlineStateV1 => {
            if context.mutations.iter().any(|mutation| {
                matches!(
                    mutation.opcode,
                    Opcode::CreateAnnIndex | Opcode::UpsertVector | Opcode::DeleteVector
                )
            }) {
                return Err(NativeRuntimeError::InvalidAnnTree);
            }
            Ok(Some(pages.append(
                PageKind::SearchDelta,
                Some(creating_csn),
                None,
                context.state.encode()?,
            )?))
        }
        SearchFormat::InvertedBTreeV1 => Ok(search_tree_after_mutations(
            pages,
            context.blobs,
            root,
            creating_csn,
            context.catalog,
            context.mutations,
            context.blob_references,
        )?
        .root()),
    }
}

#[allow(clippy::too_many_arguments)]
fn relational_tree_from_state(
    pages: &mut PageStore,
    format: RelationalFormat,
    creating_csn: Csn,
    catalog: &CatalogState,
    relational: &RelationState,
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let mut entries = vec![(RELATIONAL_FORMAT_KEY.to_vec(), format.marker().to_vec())];
    for (table, rows) in &relational.tables {
        entries.push((relational_table_key(*table), Vec::new()));
        for (primary_key, stored) in rows {
            let row = RowRecord::new(
                relational_row_id(*table, primary_key)?,
                creating_csn,
                None,
                vec![
                    Some(primary_key.clone()),
                    Some(relational_storage_value(stored, blob_references)?),
                ],
            )?;
            let value = match format {
                RelationalFormat::InlineRowV1 => row.encode()?,
                RelationalFormat::VersionChainV2 => {
                    append_row_version(pages, None, &row, creating_csn)?
                }
            };
            entries.push((relational_row_key(*table, primary_key), value));
        }
    }
    for (index, state) in &relational.indexes {
        let Some(CatalogObject::SecondaryIndex(definition)) = catalog.object(*index) else {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        };
        entries.push((
            relational_secondary_index_key(*index),
            encode_secondary_index_metadata(definition, state.layout).to_vec(),
        ));
        for (index_key, primary_keys) in &state.entries {
            for primary_key in primary_keys {
                let identity =
                    secondary_index_entry_identity(state.layout, index_key, primary_key)?;
                entries.push((
                    relational_secondary_entry_key(*index, &identity)?,
                    vec![RELATIONAL_SECONDARY_ENTRY_LIVE],
                ));
            }
        }
    }
    entries.sort_by(|left, right| left.0.cmp(&right.0));
    Ok(BTree::empty()
        .upsert_sorted_batch(pages, creating_csn, entries)?
        .tree)
}

#[allow(clippy::too_many_arguments, clippy::too_many_lines)]
fn relational_tree_after_mutations(
    pages: &mut PageStore,
    blobs: &BlobStore,
    root: Option<PageId>,
    format: RelationalFormat,
    creating_csn: Csn,
    catalog: &CatalogState,
    relational: &RelationState,
    mutations: &[Mutation],
    blob_references: &BTreeMap<[u8; 32], BlobReference>,
) -> Result<BTree, NativeRuntimeError> {
    let rebuild_for_drop = mutations.iter().any(|mutation| {
        matches!(
            mutation.opcode,
            Opcode::DropSecondaryIndex | Opcode::DropTable | Opcode::RenameTable
        )
    });
    let mut tree = if rebuild_for_drop {
        relational_tree_from_state(
            pages,
            format,
            creating_csn,
            catalog,
            relational,
            blob_references,
        )?
    } else {
        root.map_or_else(BTree::empty, BTree::from_root)
    };
    if tree.root().is_none() {
        tree = tree
            .insert_unique(
                pages,
                creating_csn,
                RELATIONAL_FORMAT_KEY.to_vec(),
                format.marker().to_vec(),
            )?
            .tree;
    }
    for mutation in mutations
        .iter()
        .filter(|mutation| mutation.engine == EngineKind::Relational)
    {
        let target = mutation
            .target
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        if mutation.opcode == Opcode::RenameTable {
            continue;
        }
        if matches!(
            mutation.opcode,
            Opcode::DropSecondaryIndex | Opcode::DropTable
        ) {
            if !mutation.key.is_empty() || !mutation.value.is_empty() {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
            continue;
        }
        let key = match mutation.opcode {
            Opcode::CreateTable => {
                tree = tree
                    .insert_unique(
                        pages,
                        creating_csn,
                        relational_table_key(target),
                        Vec::new(),
                    )?
                    .tree;
                continue;
            }
            Opcode::CreateSecondaryIndex => {
                let object = decode_secondary_index_creation(target, mutation)
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
                let CatalogObject::SecondaryIndex(definition) = object else {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                };
                let index_state = relational
                    .indexes
                    .get(&target)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                tree = tree
                    .insert_unique(
                        pages,
                        creating_csn,
                        relational_secondary_index_key(target),
                        encode_secondary_index_metadata(&definition, index_state.layout).to_vec(),
                    )?
                    .tree;
                for (index_key, primary_keys) in &index_state.entries {
                    for primary_key in primary_keys {
                        let identity = secondary_index_entry_identity(
                            index_state.layout,
                            index_key,
                            primary_key,
                        )?;
                        tree = tree
                            .upsert(
                                pages,
                                creating_csn,
                                relational_secondary_entry_key(target, &identity)?,
                                vec![RELATIONAL_SECONDARY_ENTRY_LIVE],
                            )?
                            .tree;
                    }
                }
                continue;
            }
            Opcode::InsertRow | Opcode::UpdateRow | Opcode::DeleteRow => {
                relational_row_key(target, &mutation.key)
            }
            _ => return Err(NativeRuntimeError::InvalidRelationalTree),
        };
        let old_projections = if mutation.opcode == Opcode::InsertRow {
            Vec::new()
        } else {
            let old_row = relational_tree_latest_row(
                pages,
                blobs,
                tree,
                format,
                target,
                &mutation.key,
                Some(creating_csn),
            )?
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            secondary_index_projections(catalog, target, &old_row)?
        };
        let row = if mutation.opcode == Opcode::DeleteRow {
            RowRecord::tombstone(
                relational_row_id(target, &mutation.key)?,
                creating_csn,
                None,
            )?
        } else {
            RowRecord::new(
                relational_row_id(target, &mutation.key)?,
                creating_csn,
                None,
                vec![
                    Some(mutation.key.clone()),
                    Some(relational_storage_value(&mutation.value, blob_references)?),
                ],
            )?
        };
        let value = match format {
            RelationalFormat::InlineRowV1 => row.encode()?,
            RelationalFormat::VersionChainV2 => {
                let previous = tree.get(pages, &key)?;
                append_row_version(pages, previous.as_deref(), &row, creating_csn)?
            }
        };
        tree = tree.upsert(pages, creating_csn, key, value)?.tree;
        tree = write_secondary_index_projection_markers(
            pages,
            tree,
            creating_csn,
            &old_projections,
            &mutation.key,
            RELATIONAL_SECONDARY_ENTRY_TOMBSTONE,
            relational,
        )?;
        if mutation.opcode != Opcode::DeleteRow {
            validate_relation_checks(catalog, target, &mutation.value)?;
            let new_projections = secondary_index_projections(catalog, target, &mutation.value)?;
            tree = write_secondary_index_projection_markers(
                pages,
                tree,
                creating_csn,
                &new_projections,
                &mutation.key,
                RELATIONAL_SECONDARY_ENTRY_LIVE,
                relational,
            )?;
        }
    }
    Ok(tree)
}

fn relational_tree_latest_row(
    pages: &PageStore,
    blobs: &BlobStore,
    tree: BTree,
    format: RelationalFormat,
    table: ObjectId,
    primary_key: &[u8],
    visible_csn: Option<Csn>,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    let Some(encoded) = tree.get(pages, &relational_row_key(table, primary_key))? else {
        return Ok(None);
    };
    match format {
        RelationalFormat::InlineRowV1 => {
            decode_relational_row(table, primary_key, &encoded, visible_csn, blobs)
        }
        RelationalFormat::VersionChainV2 => {
            decode_relational_chain_head(pages, table, primary_key, &encoded, visible_csn, blobs)
        }
    }
}

fn decode_relational_chain_head(
    pages: &PageStore,
    table: ObjectId,
    primary_key: &[u8],
    encoded: &[u8],
    visible_csn: Option<Csn>,
    blobs: &BlobStore,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    let page_id = RowVersionPointer::decode(encoded)?.page_id;
    let page = pages.read(page_id)?;
    #[cfg(test)]
    DELTA_LATEST_VERSION_PAGE_READS.set(
        DELTA_LATEST_VERSION_PAGE_READS
            .get()
            .checked_add(1)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?,
    );
    if page.kind() != PageKind::VersionChain {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let row = RowRecordView::decode(page.payload())?;
    validate_version_page(&page, row, table, primary_key, visible_csn, None)?;
    if !row.is_visible_at(visible_csn) {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    decode_relational_row_value(row, primary_key, blobs)
}

fn write_secondary_index_projection_markers(
    pages: &mut PageStore,
    mut tree: BTree,
    creating_csn: Csn,
    projections: &[SecondaryIndexProjection],
    primary_key: &[u8],
    marker: u8,
    relational: &RelationState,
) -> Result<BTree, NativeRuntimeError> {
    if !matches!(
        marker,
        RELATIONAL_SECONDARY_ENTRY_TOMBSTONE | RELATIONAL_SECONDARY_ENTRY_LIVE
    ) {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    for projection in projections {
        let layout = relational
            .indexes
            .get(&projection.index)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?
            .layout;
        let identity = secondary_index_entry_identity(layout, &projection.key, primary_key)?;
        tree = tree
            .upsert(
                pages,
                creating_csn,
                relational_secondary_entry_key(projection.index, &identity)?,
                vec![marker],
            )?
            .tree;
    }
    Ok(tree)
}

fn append_row_version(
    pages: &mut PageStore,
    previous_pointer: Option<&[u8]>,
    row: &RowRecord,
    creating_csn: Csn,
) -> Result<Vec<u8>, NativeRuntimeError> {
    if row.begin_csn() != creating_csn || row.end_csn().is_some() {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let next = if let Some(previous_pointer) = previous_pointer {
        let pointer = RowVersionPointer::decode(previous_pointer)?;
        let previous_page = pages.read(pointer.page_id)?;
        if previous_page.kind() != PageKind::VersionChain
            || previous_page
                .creating_csn()
                .is_none_or(|created| created > creating_csn)
        {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        let previous = RowRecord::decode(previous_page.payload())?;
        if previous.row_id() != row.row_id() || previous.end_csn().is_some() {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        if previous.begin_csn() == creating_csn {
            previous_page.next()
        } else {
            Some(pages.append(
                PageKind::VersionChain,
                Some(creating_csn),
                previous_page.next(),
                previous.close_at(creating_csn)?.encode()?,
            )?)
        }
    } else {
        None
    };
    let latest = pages.append(
        PageKind::VersionChain,
        Some(creating_csn),
        next,
        row.encode()?,
    )?;
    Ok(RowVersionPointer { page_id: latest }.encode().to_vec())
}

fn relational_table_key(table: ObjectId) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(RELATIONAL_TABLE_PREFIX);
    key.extend_from_slice(&table.get().to_be_bytes());
    key
}

fn relational_row_key(table: ObjectId, primary_key: &[u8]) -> Vec<u8> {
    let mut key = Vec::with_capacity(17 + primary_key.len());
    key.push(RELATIONAL_ROW_PREFIX);
    key.extend_from_slice(&table.get().to_be_bytes());
    key.extend_from_slice(primary_key);
    key
}

fn map_primary_key_bound(table: ObjectId, bound: Bound<&[u8]>) -> Bound<Vec<u8>> {
    match bound {
        Bound::Included(primary_key) => Bound::Included(relational_row_key(table, primary_key)),
        Bound::Excluded(primary_key) => Bound::Excluded(relational_row_key(table, primary_key)),
        Bound::Unbounded => Bound::Unbounded,
    }
}

fn bound_as_slice(bound: &Bound<Vec<u8>>) -> Bound<&[u8]> {
    match bound {
        Bound::Included(key) => Bound::Included(key.as_slice()),
        Bound::Excluded(key) => Bound::Excluded(key.as_slice()),
        Bound::Unbounded => Bound::Unbounded,
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SecondaryIndexProjection {
    index: ObjectId,
    key: Vec<u8>,
    contains_null: bool,
}

fn insert_secondary_index_projections(
    relational: &mut RelationState,
    projections: &[SecondaryIndexProjection],
    primary_key: &[u8],
) -> Result<(), NativeRuntimeError> {
    insert_secondary_index_projections_with_checkpoint(
        relational,
        projections,
        primary_key,
        &mut || true,
    )
}

fn insert_secondary_index_projections_with_checkpoint(
    relational: &mut RelationState,
    projections: &[SecondaryIndexProjection],
    primary_key: &[u8],
    checkpoint: &mut dyn FnMut() -> bool,
) -> Result<(), NativeRuntimeError> {
    for projection in projections {
        runtime_sql_checkpoint(checkpoint)?;
        relational.insert_secondary_index(
            projection.index,
            projection.key.clone(),
            primary_key.to_vec(),
            projection.contains_null,
        )?;
    }
    Ok(())
}

fn remove_secondary_index_projections(
    relational: &mut RelationState,
    projections: &[SecondaryIndexProjection],
    primary_key: &[u8],
) -> Result<(), NativeRuntimeError> {
    remove_secondary_index_projections_with_checkpoint(
        relational,
        projections,
        primary_key,
        &mut || true,
    )
}

fn remove_secondary_index_projections_with_checkpoint(
    relational: &mut RelationState,
    projections: &[SecondaryIndexProjection],
    primary_key: &[u8],
    checkpoint: &mut dyn FnMut() -> bool,
) -> Result<(), NativeRuntimeError> {
    for projection in projections {
        runtime_sql_checkpoint(checkpoint)?;
        relational.remove_secondary_index(projection.index, &projection.key, primary_key)?;
    }
    Ok(())
}

fn validate_parent_not_referenced_state(
    state: &MaterializedState,
    parent_id: ObjectId,
    parent_key: &[u8],
) -> Result<(), NativeRuntimeError> {
    let Some(CatalogObject::Relation(parent)) = state.catalog.object(parent_id) else {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    };
    for object in state.catalog.objects.values() {
        let CatalogObject::Relation(child) = object else {
            continue;
        };
        for foreign_key in &child.foreign_keys {
            if foreign_key.referenced_relation != parent_id {
                continue;
            }
            let Some(rows) = state.relational.tables.get(&child.header.id) else {
                continue;
            };
            for stored in rows.values() {
                let tuple = RowTupleView::decode(stored)?;
                let mut key = Vec::new();
                let mut contains_null = false;
                for (child_id, parent_column_id) in foreign_key
                    .columns
                    .iter()
                    .zip(&foreign_key.referenced_columns)
                {
                    let child_index = child
                        .columns
                        .iter()
                        .position(|column| column.id == *child_id)
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                    let parent_type = &parent
                        .columns
                        .iter()
                        .find(|column| column.id == *parent_column_id)
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?
                        .logical_type;
                    let value = match tuple
                        .value(child_index)
                        .ok_or(NativeRuntimeError::InvalidRelationalTree)?
                    {
                        ColumnValueRef::Null => {
                            contains_null = true;
                            break;
                        }
                        ColumnValueRef::Bytes(encoded) => {
                            ScalarValue::decode_storage(parent_type, encoded)
                                .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?
                        }
                    };
                    key.extend_from_slice(
                        &value
                            .encode_ordered_component(parent_type)
                            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
                    );
                }
                if !contains_null && key == parent_key {
                    return Err(NativeRuntimeError::ForeignKeyConstraintViolation);
                }
            }
        }
    }
    Ok(())
}

fn validate_relation_foreign_keys(
    state: &MaterializedState,
    relation_id: ObjectId,
    row: &[u8],
) -> Result<(), NativeRuntimeError> {
    let Some(CatalogObject::Relation(relation)) = state.catalog.object(relation_id) else {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    };
    if relation.foreign_keys.is_empty() {
        return Ok(());
    }
    let tuple = RowTupleView::decode(row)?;
    for foreign_key in &relation.foreign_keys {
        let Some(CatalogObject::Relation(parent)) =
            state.catalog.object(foreign_key.referenced_relation)
        else {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        };
        let mut key = Vec::new();
        let mut contains_null = false;
        for (child_id, parent_id) in foreign_key
            .columns
            .iter()
            .zip(&foreign_key.referenced_columns)
        {
            let child_index = relation
                .columns
                .iter()
                .position(|column| column.id == *child_id)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let parent_type = &parent
                .columns
                .iter()
                .find(|column| column.id == *parent_id)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?
                .logical_type;
            let value = match tuple
                .value(child_index)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?
            {
                ColumnValueRef::Null => {
                    contains_null = true;
                    break;
                }
                ColumnValueRef::Bytes(encoded) => ScalarValue::decode_storage(parent_type, encoded)
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
            };
            key.extend_from_slice(
                &value
                    .encode_ordered_component(parent_type)
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
            );
        }
        let parent_exists = if let Some(index) = foreign_key.referenced_index {
            state
                .relational
                .indexes
                .get(&index)
                .and_then(|index| index.entries.get(&key))
                .is_some_and(|entries| !entries.is_empty())
        } else {
            state
                .relational
                .select(foreign_key.referenced_relation, &key)
                .is_some()
        };
        if !contains_null && !parent_exists {
            return Err(NativeRuntimeError::ForeignKeyConstraintViolation);
        }
    }
    Ok(())
}

fn validate_relation_checks(
    catalog: &CatalogState,
    relation_id: ObjectId,
    row: &[u8],
) -> Result<(), NativeRuntimeError> {
    let Some(CatalogObject::Relation(relation)) = catalog.object(relation_id) else {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    };
    if relation.checks.is_empty() {
        return Ok(());
    }
    let tuple = RowTupleView::decode(row)?;
    if tuple.column_count() != relation.columns.len() {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    for (column_id, check) in &relation.checks {
        let index = relation
            .columns
            .iter()
            .position(|column| column.id == *column_id)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        let column = &relation.columns[index];
        let value = match tuple
            .value(index)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?
        {
            ColumnValueRef::Null => continue,
            ColumnValueRef::Bytes(encoded) => {
                ScalarValue::decode_storage(&column.logical_type, encoded)
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?
            }
        };
        let left = value
            .encode_ordered_component(&column.logical_type)
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
        let right = check
            .operand
            .encode_ordered_component(&column.logical_type)
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
        let ordering = left.cmp(&right);
        let passes = match check.operator {
            ColumnCheckOperator::Equal => ordering == ValueOrdering::Equal,
            ColumnCheckOperator::NotEqual => ordering != ValueOrdering::Equal,
            ColumnCheckOperator::Less => ordering == ValueOrdering::Less,
            ColumnCheckOperator::LessOrEqual => ordering != ValueOrdering::Greater,
            ColumnCheckOperator::Greater => ordering == ValueOrdering::Greater,
            ColumnCheckOperator::GreaterOrEqual => ordering != ValueOrdering::Less,
        };
        if !passes {
            return Err(NativeRuntimeError::CheckConstraintViolation);
        }
    }
    Ok(())
}

fn secondary_index_projections(
    catalog: &CatalogState,
    relation: ObjectId,
    row: &[u8],
) -> Result<Vec<SecondaryIndexProjection>, NativeRuntimeError> {
    secondary_index_projections_with_checkpoint(catalog, relation, row, &mut || true)
}

fn secondary_index_projections_with_checkpoint(
    catalog: &CatalogState,
    relation: ObjectId,
    row: &[u8],
    checkpoint: &mut dyn FnMut() -> bool,
) -> Result<Vec<SecondaryIndexProjection>, NativeRuntimeError> {
    let mut projections = Vec::new();
    for object in catalog.objects.values() {
        runtime_sql_checkpoint(checkpoint)?;
        if let CatalogObject::SecondaryIndex(definition) = object
            && definition.relation == relation
        {
            projections.push(secondary_index_projection(catalog, definition, row)?);
        }
    }
    Ok(projections)
}

fn secondary_index_projection(
    catalog: &CatalogState,
    definition: &SecondaryIndexDefinition,
    row: &[u8],
) -> Result<SecondaryIndexProjection, NativeRuntimeError> {
    let Some(CatalogObject::Relation(relation)) = catalog.object(definition.relation) else {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    };
    let tuple = RowTupleView::decode(row)?;
    if tuple.column_count() != relation.columns.len() {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut key = Vec::new();
    let mut contains_null = false;
    for column_id in &definition.columns {
        let index = relation
            .columns
            .iter()
            .position(|column| column.id == *column_id)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        let column = &relation.columns[index];
        let value = match tuple
            .value(index)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?
        {
            ColumnValueRef::Null => {
                contains_null = true;
                ScalarValue::Null
            }
            ColumnValueRef::Bytes(encoded) => {
                ScalarValue::decode_storage(&column.logical_type, encoded)
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?
            }
        };
        key.extend_from_slice(
            &value
                .encode_ordered_component(&column.logical_type)
                .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
        );
    }
    Ok(SecondaryIndexProjection {
        index: definition.header.id,
        key,
        contains_null,
    })
}

fn runtime_sql_checkpoint(checkpoint: &mut dyn FnMut() -> bool) -> Result<(), NativeRuntimeError> {
    if checkpoint() {
        Ok(())
    } else {
        Err(GovernorQueueError::Cancelled.into())
    }
}

fn secondary_index_entry_identity(
    layout: SecondaryIndexLayout,
    index_key: &[u8],
    primary_key: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let recorded_length = match layout {
        SecondaryIndexLayout::LegacyLengthFirstV1 => index_key.len(),
        SecondaryIndexLayout::OrderedV2 => primary_key.len(),
    };
    let recorded_length =
        u32::try_from(recorded_length).map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
    let capacity = index_key
        .len()
        .checked_add(primary_key.len())
        .and_then(|length| length.checked_add(4))
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    if capacity
        .checked_add(17)
        .is_none_or(|physical| physical > BTREE_MAX_KEY_SIZE)
    {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut encoded = Vec::with_capacity(capacity);
    match layout {
        SecondaryIndexLayout::LegacyLengthFirstV1 => {
            encoded.extend_from_slice(&recorded_length.to_be_bytes());
            encoded.extend_from_slice(index_key);
            encoded.extend_from_slice(primary_key);
        }
        SecondaryIndexLayout::OrderedV2 => {
            encoded.extend_from_slice(index_key);
            encoded.extend_from_slice(primary_key);
            encoded.extend_from_slice(&recorded_length.to_be_bytes());
        }
    }
    Ok(encoded)
}

fn decode_secondary_index_entry_identity(
    layout: SecondaryIndexLayout,
    encoded: &[u8],
) -> Result<(&[u8], &[u8]), NativeRuntimeError> {
    let (index_key, primary_key) = match layout {
        SecondaryIndexLayout::LegacyLengthFirstV1 => {
            let length = encoded
                .get(..4)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let index_length = usize::try_from(u32::from_be_bytes(
                length
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
            ))
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
            let index_end = 4_usize
                .checked_add(index_length)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let index_key = encoded
                .get(4..index_end)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let primary_key = encoded
                .get(index_end..)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            (index_key, primary_key)
        }
        SecondaryIndexLayout::OrderedV2 => {
            let suffix_offset = encoded
                .len()
                .checked_sub(4)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            let primary_length = usize::try_from(u32::from_be_bytes(
                encoded[suffix_offset..]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
            ))
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
            let primary_offset = suffix_offset
                .checked_sub(primary_length)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            (
                &encoded[..primary_offset],
                &encoded[primary_offset..suffix_offset],
            )
        }
    };
    if index_key.is_empty() || primary_key.is_empty() {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    Ok((index_key, primary_key))
}

fn relational_secondary_index_key(index: ObjectId) -> Vec<u8> {
    let mut key = Vec::with_capacity(17);
    key.push(RELATIONAL_SECONDARY_INDEX_PREFIX);
    key.extend_from_slice(&index.get().to_be_bytes());
    key
}

fn relational_secondary_entry_namespace(index: ObjectId) -> Vec<u8> {
    let mut prefix = Vec::with_capacity(17);
    prefix.push(RELATIONAL_SECONDARY_ENTRY_PREFIX);
    prefix.extend_from_slice(&index.get().to_be_bytes());
    prefix
}

fn relational_secondary_entry_key(
    index: ObjectId,
    identity: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let capacity = 17_usize
        .checked_add(identity.len())
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    if capacity > BTREE_MAX_KEY_SIZE {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut key = Vec::with_capacity(capacity);
    key.push(RELATIONAL_SECONDARY_ENTRY_PREFIX);
    key.extend_from_slice(&index.get().to_be_bytes());
    key.extend_from_slice(identity);
    Ok(key)
}

fn secondary_index_physical_bounds(
    namespace: &[u8],
    lower: Bound<&[u8]>,
    upper: Bound<&[u8]>,
) -> Result<PhysicalKeyBounds, NativeRuntimeError> {
    let namespace_upper =
        byte_prefix_successor(namespace).ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    let lower = match lower {
        Bound::Unbounded => Bound::Included(namespace.to_vec()),
        Bound::Included(index_key) => {
            Bound::Included(secondary_index_bound_key(namespace, index_key)?)
        }
        Bound::Excluded(index_key) => Bound::Included(
            byte_prefix_successor(&secondary_index_bound_key(namespace, index_key)?)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?,
        ),
    };
    let upper = match upper {
        Bound::Unbounded => Bound::Excluded(namespace_upper),
        Bound::Excluded(index_key) => {
            Bound::Excluded(secondary_index_bound_key(namespace, index_key)?)
        }
        Bound::Included(index_key) => Bound::Excluded(
            byte_prefix_successor(&secondary_index_bound_key(namespace, index_key)?)
                .ok_or(NativeRuntimeError::InvalidRelationalTree)?,
        ),
    };
    Ok((lower, upper))
}

fn secondary_index_bound_key(
    namespace: &[u8],
    index_key: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let capacity = namespace
        .len()
        .checked_add(index_key.len())
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    if capacity > BTREE_MAX_KEY_SIZE {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut key = Vec::with_capacity(capacity);
    key.extend_from_slice(namespace);
    key.extend_from_slice(index_key);
    Ok(key)
}

fn byte_prefix_successor(prefix: &[u8]) -> Option<Vec<u8>> {
    let mut successor = prefix.to_vec();
    let offset = successor.iter().rposition(|byte| *byte != u8::MAX)?;
    successor[offset] += 1;
    successor.truncate(offset + 1);
    Some(successor)
}

fn hash_pattern_lower_bound<'key>(
    literal_prefix: Option<&'key [u8]>,
    cursor: Option<&'key [u8]>,
) -> Bound<&'key [u8]> {
    match (literal_prefix, cursor) {
        (None, None) => Bound::Unbounded,
        (None, Some(cursor)) => Bound::Excluded(cursor),
        (Some(prefix), Some(cursor)) if cursor >= prefix => Bound::Excluded(cursor),
        (Some(prefix), None | Some(_)) => Bound::Included(prefix),
    }
}

fn bytes_within_bounds(value: &[u8], lower: &Bound<&[u8]>, upper: &Bound<&[u8]>) -> bool {
    let above_lower = match lower {
        Bound::Included(lower) => value >= *lower,
        Bound::Excluded(lower) => value > *lower,
        Bound::Unbounded => true,
    };
    let below_upper = match upper {
        Bound::Included(upper) => value <= *upper,
        Bound::Excluded(upper) => value < *upper,
        Bound::Unbounded => true,
    };
    above_lower && below_upper
}

fn relational_secondary_entry_prefix(
    index: ObjectId,
    layout: SecondaryIndexLayout,
    index_key: &[u8],
) -> Result<Vec<u8>, NativeRuntimeError> {
    let layout_bytes = match layout {
        SecondaryIndexLayout::LegacyLengthFirstV1 => 4,
        SecondaryIndexLayout::OrderedV2 => 0,
    };
    let capacity = 17_usize
        .checked_add(layout_bytes)
        .and_then(|length| length.checked_add(index_key.len()))
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    if capacity >= BTREE_MAX_KEY_SIZE {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut prefix = Vec::with_capacity(capacity);
    prefix.push(RELATIONAL_SECONDARY_ENTRY_PREFIX);
    prefix.extend_from_slice(&index.get().to_be_bytes());
    if layout == SecondaryIndexLayout::LegacyLengthFirstV1 {
        let index_length = u32::try_from(index_key.len())
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
        prefix.extend_from_slice(&index_length.to_be_bytes());
    }
    prefix.extend_from_slice(index_key);
    Ok(prefix)
}

fn encode_secondary_index_metadata(
    definition: &SecondaryIndexDefinition,
    layout: SecondaryIndexLayout,
) -> [u8; RELATIONAL_SECONDARY_INDEX_META_SIZE] {
    let mut encoded = [0_u8; RELATIONAL_SECONDARY_INDEX_META_SIZE];
    encoded[..8].copy_from_slice(match layout {
        SecondaryIndexLayout::LegacyLengthFirstV1 => RELATIONAL_SECONDARY_INDEX_MAGIC_V1,
        SecondaryIndexLayout::OrderedV2 => RELATIONAL_SECONDARY_INDEX_MAGIC_V2,
    });
    encoded[8..24].copy_from_slice(&definition.relation.get().to_be_bytes());
    encoded[24] = u8::from(definition.unique);
    encoded[25] = u8::from(definition.nulls_distinct);
    encoded
}

fn decode_secondary_index_metadata(
    encoded: &[u8],
) -> Result<(ObjectId, bool, bool, SecondaryIndexLayout), NativeRuntimeError> {
    if encoded.len() != RELATIONAL_SECONDARY_INDEX_META_SIZE
        || !matches!(encoded[24], 0 | 1)
        || !matches!(encoded[25], 0 | 1)
        || encoded[26..].iter().any(|byte| *byte != 0)
    {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let relation = ObjectId::new(u128::from_be_bytes(
        encoded[8..24]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?;
    let layout = match encoded.get(..8) {
        Some(magic) if magic == RELATIONAL_SECONDARY_INDEX_MAGIC_V1 => {
            SecondaryIndexLayout::LegacyLengthFirstV1
        }
        Some(magic) if magic == RELATIONAL_SECONDARY_INDEX_MAGIC_V2 => {
            SecondaryIndexLayout::OrderedV2
        }
        _ => return Err(NativeRuntimeError::InvalidRelationalTree),
    };
    Ok((relation, encoded[24] == 1, encoded[25] == 1, layout))
}

fn relational_row_id(table: ObjectId, primary_key: &[u8]) -> Result<RowId, NativeRuntimeError> {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"hyphae-relational-row-id-v1");
    hasher.update(&table.get().to_be_bytes());
    hasher.update(
        &u64::try_from(primary_key.len())
            .map_err(|_| NativeRuntimeError::InvalidRelationalTree)?
            .to_be_bytes(),
    );
    hasher.update(primary_key);
    let digest = hasher.finalize();
    let mut encoded = [0_u8; 16];
    encoded.copy_from_slice(&digest.as_bytes()[..16]);
    let mut value = u128::from_be_bytes(encoded);
    if value == 0 {
        value = 1;
    }
    RowId::new(value).map_err(|_| NativeRuntimeError::InvalidRelationalTree)
}

fn decode_relational_row(
    table: ObjectId,
    primary_key: &[u8],
    encoded: &[u8],
    visible_csn: Option<Csn>,
    blobs: &BlobStore,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    let row = RowRecordView::decode(encoded)?;
    if row.row_id() != relational_row_id(table, primary_key)? {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    if !row.is_visible_at(visible_csn) {
        return Ok(None);
    }
    decode_relational_row_value(row, primary_key, blobs)
}

fn decode_relational_row_value(
    row: RowRecordView<'_>,
    primary_key: &[u8],
    blobs: &BlobStore,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    if row.is_tombstone() {
        return Ok(None);
    }
    if row.column_count() != 2 {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    match (row.value(0), row.value(1)) {
        (
            Some(ColumnValueRef::Bytes(encoded_primary_key)),
            Some(ColumnValueRef::Bytes(stored_value)),
        ) if encoded_primary_key == primary_key => {
            let Some((&storage, value)) = stored_value.split_first() else {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            };
            match storage {
                RELATIONAL_VALUE_INLINE => Ok(Some(value.to_vec())),
                RELATIONAL_VALUE_BLOB => {
                    let reference = BlobReference::decode(value)?;
                    Ok(Some(blobs.read(reference)?))
                }
                _ => Err(NativeRuntimeError::InvalidRelationalTree),
            }
        }
        _ => Err(NativeRuntimeError::InvalidRelationalTree),
    }
}

enum DeltaRelationalValue {
    Inline(Vec<u8>),
    Blob(BlobReference),
}

enum DeltaCatalogDefinition<'definition> {
    Inline(&'definition [u8]),
    Blob(BlobReference),
}

impl DeltaCatalogDefinition<'_> {
    fn logical_bytes(&self) -> u64 {
        match self {
            Self::Inline(value) => u64::try_from(value.len()).unwrap_or(u64::MAX),
            Self::Blob(reference) => reference.logical_length,
        }
    }

    fn materialize(self, blobs: &BlobStore) -> Result<Vec<u8>, NativeRuntimeError> {
        match self {
            Self::Inline(value) => Ok(value.to_vec()),
            Self::Blob(reference) => Ok(blobs.read(reference)?),
        }
    }
}

impl DeltaRelationalValue {
    fn logical_bytes(&self) -> u64 {
        match self {
            Self::Inline(value) => u64::try_from(value.len()).unwrap_or(u64::MAX),
            Self::Blob(reference) => reference.logical_length,
        }
    }

    fn materialize(self, blobs: &BlobStore) -> Result<Vec<u8>, NativeRuntimeError> {
        match self {
            Self::Inline(value) => Ok(value),
            Self::Blob(reference) => Ok(blobs.read(reference)?),
        }
    }
}

fn decode_delta_relational_row_value(
    row: RowRecordView<'_>,
    primary_key: &[u8],
) -> Result<Option<DeltaRelationalValue>, NativeRuntimeError> {
    if row.is_tombstone() {
        return Ok(None);
    }
    if row.column_count() != 2 {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    match (row.value(0), row.value(1)) {
        (
            Some(ColumnValueRef::Bytes(encoded_primary_key)),
            Some(ColumnValueRef::Bytes(stored_value)),
        ) if encoded_primary_key == primary_key => {
            let Some((&storage, value)) = stored_value.split_first() else {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            };
            match storage {
                RELATIONAL_VALUE_INLINE if value.len() <= RELATIONAL_INLINE_VALUE_LIMIT => {
                    Ok(Some(DeltaRelationalValue::Inline(value.to_vec())))
                }
                RELATIONAL_VALUE_BLOB
                    if value.len() == hyphae_native_records::BLOB_REFERENCE_SIZE =>
                {
                    let reference = BlobReference::decode(value)?;
                    if reference.logical_length <= RELATIONAL_INLINE_VALUE_LIMIT as u64 {
                        return Err(NativeRuntimeError::InvalidRelationalTree);
                    }
                    Ok(Some(DeltaRelationalValue::Blob(reference)))
                }
                _ => Err(NativeRuntimeError::InvalidRelationalTree),
            }
        }
        _ => Err(NativeRuntimeError::InvalidRelationalTree),
    }
}

struct RelationalReadContext<'a> {
    pages: &'a PageStore,
    pool: &'a BufferPool,
    blobs: &'a BlobStore,
    format: RelationalFormat,
    visible_csn: Option<Csn>,
}

fn decode_relational_value_cached(
    context: &RelationalReadContext<'_>,
    table: ObjectId,
    primary_key: &[u8],
    encoded: &[u8],
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    match context.format {
        RelationalFormat::InlineRowV1 => decode_relational_row(
            table,
            primary_key,
            encoded,
            context.visible_csn,
            context.blobs,
        ),
        RelationalFormat::VersionChainV2 => {
            let mut page_id = RowVersionPointer::decode(encoded)?.page_id;
            let mut stack_visited = [0_u64; 64];
            let mut overflow_visited = None;
            let mut depth = 0_usize;
            let mut newer_begin = None;
            loop {
                track_version_page(page_id, depth, &mut stack_visited, &mut overflow_visited)?;
                let frame = context.pool.get_or_load(context.pages, page_id)?;
                let page = frame.page();
                if page.kind() != PageKind::VersionChain {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
                let row = RowRecordView::decode(page.payload())?;
                validate_version_page(
                    page,
                    row,
                    table,
                    primary_key,
                    context.visible_csn,
                    newer_begin,
                )?;
                if row.is_visible_at(context.visible_csn) {
                    return decode_relational_row_value(row, primary_key, context.blobs);
                }
                newer_begin = Some(row.begin_csn());
                page_id = page
                    .next()
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                depth = depth
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
            }
        }
    }
}

fn track_version_page(
    page_id: PageId,
    depth: usize,
    stack_visited: &mut [u64; 64],
    overflow_visited: &mut Option<BTreeSet<u64>>,
) -> Result<(), NativeRuntimeError> {
    if depth < stack_visited.len() {
        if stack_visited[..depth].contains(&page_id.get()) {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        stack_visited[depth] = page_id.get();
        return Ok(());
    }
    let visited = overflow_visited.get_or_insert_with(|| stack_visited.iter().copied().collect());
    if !visited.insert(page_id.get()) {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    Ok(())
}

fn validate_version_page(
    page: &hyphae_native_pages::Page,
    row: RowRecordView<'_>,
    table: ObjectId,
    primary_key: &[u8],
    visible_csn: Option<Csn>,
    newer_begin: Option<Csn>,
) -> Result<(), NativeRuntimeError> {
    let created = page
        .creating_csn()
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    if visible_csn.is_none_or(|visible| created > visible)
        || row.row_id() != relational_row_id(table, primary_key)?
    {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    match newer_begin {
        None if row.end_csn().is_some() || created != row.begin_csn() => {
            Err(NativeRuntimeError::InvalidRelationalTree)
        }
        Some(newer) if row.end_csn() != Some(newer) || created != newer => {
            Err(NativeRuntimeError::InvalidRelationalTree)
        }
        _ => Ok(()),
    }
}

fn decode_relational_chain(
    pages: &PageStore,
    table: ObjectId,
    primary_key: &[u8],
    encoded: &[u8],
    visible_csn: Option<Csn>,
    blobs: &BlobStore,
) -> Result<Option<Vec<u8>>, NativeRuntimeError> {
    let mut page_id = RowVersionPointer::decode(encoded)?.page_id;
    let mut visited = BTreeSet::new();
    let mut newer_begin = None;
    let mut selected = None;
    loop {
        if !visited.insert(page_id) {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        let page = pages.read(page_id)?;
        if page.kind() != PageKind::VersionChain {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        let row = RowRecordView::decode(page.payload())?;
        validate_version_page(&page, row, table, primary_key, visible_csn, newer_begin)?;
        let value = decode_relational_row_value(row, primary_key, blobs)?;
        if selected.is_none() && row.is_visible_at(visible_csn) {
            selected = Some(value);
        }
        newer_begin = Some(row.begin_csn());
        let Some(next) = page.next() else {
            break;
        };
        page_id = next;
    }
    selected.ok_or(NativeRuntimeError::InvalidRelationalTree)
}

fn decode_relational_table(key: &[u8], prefix: u8) -> Result<ObjectId, NativeRuntimeError> {
    if key.len() < 17 || key[0] != prefix {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let mut encoded = [0_u8; 16];
    encoded.copy_from_slice(&key[1..17]);
    ObjectId::new(u128::from_be_bytes(encoded))
        .map_err(|_| NativeRuntimeError::InvalidRelationalTree)
}

fn roots_from_snapshot(root_set: &RootSet) -> [Option<PageId>; 4] {
    ROOT_SLOTS.map(|slot| root_set.root(slot))
}

fn root_set_is_pristine(root_set: &RootSet) -> bool {
    root_set.visible_csn().is_none()
        && ROOT_SLOTS
            .into_iter()
            .all(|slot| root_set.root(slot).is_none())
}

fn require_roots(roots: [Option<PageId>; 4]) -> Result<[PageId; 4], NativeRuntimeError> {
    let [
        Some(catalog),
        Some(relational),
        Some(structures),
        Some(search),
    ] = roots
    else {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    };
    Ok([catalog, relational, structures, search])
}

fn root_map(roots: [PageId; 4]) -> BTreeMap<RootSlot, PageId> {
    ROOT_SLOTS.into_iter().zip(roots).collect()
}

fn page_generation_path(data_directory: &Path, generation: PageGeneration) -> PathBuf {
    if generation == PageGeneration::FIRST {
        data_directory.join(PAGE_FILE)
    } else {
        data_directory.join(format!("pages-{:020}.hydb", generation.get()))
    }
}

fn page_generation_temporary_path(data_directory: &Path, generation: PageGeneration) -> PathBuf {
    let final_path = page_generation_path(data_directory, generation);
    let mut temporary = final_path.into_os_string();
    temporary.push(".tmp");
    PathBuf::from(temporary)
}

#[cfg(unix)]
fn sync_page_generation_directory(data_directory: &Path) -> Result<(), std::io::Error> {
    std::fs::File::open(data_directory)?.sync_all()
}

/// Creates a native data directory restricted to its owning user.
///
/// The directory holds raw WAL, page, blob, and security-catalog bytes plus
/// the default local-protocol endpoint, so group/other filesystem access
/// would bypass durable RBAC on a shared host. Unix applies `0o700` in the
/// `mkdir` call itself, so no window exists in which another local user can
/// enter the directory or retain a handle to it. Windows relies on the
/// profile-directory ACL inherited from the parent.
#[cfg(unix)]
fn create_restricted_data_directory(path: &Path) -> Result<(), NativeRuntimeError> {
    use std::os::unix::fs::DirBuilderExt as _;

    fs::DirBuilder::new().mode(0o700).create(path)?;
    Ok(())
}

#[cfg(windows)]
fn create_restricted_data_directory(path: &Path) -> Result<(), NativeRuntimeError> {
    fs::create_dir(path)?;
    Ok(())
}

#[cfg(windows)]
fn sync_page_generation_directory(data_directory: &Path) -> Result<(), std::io::Error> {
    fs::metadata(data_directory).map(|_| ())
}

fn collect_page_generation_files(
    data_directory: &Path,
    active_generation: PageGeneration,
    pinned_generations: &BTreeSet<PageGeneration>,
) -> Result<PageGenerationCollectionReceipt, NativeRuntimeError> {
    let mut removed_files = 0_usize;
    let mut removed_bytes = 0_u64;
    let mut retained_files = 0_usize;
    let mut retained_bytes = 0_u64;
    for entry in fs::read_dir(data_directory)? {
        let entry = entry?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        let page_generation_like = name == PAGE_FILE || name.starts_with("pages-");
        if page_generation_like && !entry.file_type()?.is_file() {
            return Err(NativeRuntimeError::UnexpectedPageGenerationEntry);
        }
        let (generation, temporary) = if name == PAGE_FILE {
            (Some(PageGeneration::FIRST), false)
        } else if let Some(generation) = parse_page_generation_filename(name, ".hydb") {
            (Some(generation), false)
        } else if parse_page_generation_filename(name, ".hydb.tmp").is_some() {
            (None, true)
        } else if name.starts_with("pages-") {
            return Err(NativeRuntimeError::UnexpectedPageGenerationEntry);
        } else {
            continue;
        };
        let retain = generation.is_some_and(|generation| {
            generation == active_generation || pinned_generations.contains(&generation)
        });
        let bytes = entry.metadata()?.len();
        if temporary || !retain {
            fs::remove_file(entry.path())?;
            removed_files = removed_files
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            removed_bytes = removed_bytes
                .checked_add(bytes)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        } else {
            retained_files = retained_files
                .checked_add(1)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
            retained_bytes = retained_bytes
                .checked_add(bytes)
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        }
    }
    if removed_files != 0 {
        sync_page_generation_directory(data_directory)?;
    }
    Ok(PageGenerationCollectionReceipt {
        removed_files,
        removed_bytes,
        retained_files,
        retained_bytes,
        parent_directory_sync_supported: cfg!(unix),
    })
}

fn parse_page_generation_filename(name: &str, suffix: &str) -> Option<PageGeneration> {
    let value = name.strip_prefix("pages-")?.strip_suffix(suffix)?;
    if value.len() != 20 || !value.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    value
        .parse::<u64>()
        .ok()
        .and_then(|generation| PageGeneration::new(generation).ok())
}

struct WalOpenState {
    manifests: RootManifestStore,
    manifest_recovery: hyphae_native_manifest::ManifestRecovery,
    wal_retention: WalRetentionStore,
    recovered_temporary_wal_anchors: usize,
    retention_anchor: Option<WalRetentionAnchor>,
    base_root: Option<RootSet>,
    opened_wal: hyphae_native_wal::OpenedWal,
    recovered_wal: RecoveredWal,
    active_page_generation: PageGeneration,
    retention_floor_csn: Csn,
    manifest_verification_time: Duration,
    wal_physical_verification_time: Duration,
    wal_semantic_replay_time: Duration,
}

fn open_wal_state(
    path: &Path,
    expected_lineage: LineageIdentity,
) -> Result<WalOpenState, NativeRuntimeError> {
    let mut wal_retention = WalRetentionStore::open(path)?;
    wal_retention.validate_lineage(expected_lineage)?;
    let retention_recovery = wal_retention.recovery();
    let recovery_anchor = retention_recovery
        .candidate
        .or_else(|| wal_retention.current().copied());
    let manifest_verification_started = Instant::now();
    let manifests = recovery_anchor.map_or_else(
        || RootManifestStore::open(path),
        |anchor| {
            RootManifestStore::open_after(
                path,
                anchor.fields().manifest_generation,
                anchor.fields().manifest_digest,
            )
        },
    )?;
    manifests.validate_lineage(expected_lineage)?;
    let manifest_verification_time = manifest_verification_started.elapsed();
    let manifest_recovery = manifests.recovery();
    if let Some(candidate) = retention_recovery.candidate {
        complete_pending_wal_retention(
            path,
            &mut wal_retention,
            candidate,
            &manifest_recovery.manifests,
        )?;
    }
    let retention_anchor = wal_retention.current().copied();
    let base_root = retention_anchor
        .as_ref()
        .map(|anchor| validate_retention_anchor(anchor, &manifest_recovery.manifests))
        .transpose()?;
    let physical_recovery_started = Instant::now();
    let mut opened_wal = open_retained_wal(path, retention_anchor)?;
    let wal_physical_verification_time = physical_recovery_started.elapsed();
    let semantic_base = retention_anchor.map(|anchor| WalSemanticBase {
        visible_csn: anchor.fields().base_visible_csn,
        checkpoint_lsn: anchor.fields().retired_checkpoint_lsn,
        manifest_generation: anchor.fields().manifest_generation,
    });
    let semantic_replay_started = Instant::now();
    let recovered_wal = recover_wal_and_close_dangling(&mut opened_wal, semantic_base)?;
    let wal_semantic_replay_time = semantic_replay_started.elapsed();
    validate_commit_sequence_after(&recovered_wal.commits, base_root.as_ref())?;
    let active_page_generation = recovered_wal.commits.last().map_or_else(
        || {
            base_root
                .as_ref()
                .map_or(PageGeneration::FIRST, RootSet::page_generation)
        },
        |commit| commit.manifest.page_generation,
    );
    let retention_floor_csn = recovered_wal.commits.last().map_or_else(
        || {
            base_root
                .as_ref()
                .and_then(RootSet::retention_floor_csn)
                .unwrap_or(Csn::FIRST)
        },
        |commit| commit.manifest.retention_floor_csn,
    );
    Ok(WalOpenState {
        manifests,
        manifest_recovery,
        wal_retention,
        recovered_temporary_wal_anchors: retention_recovery.ignored_temporary_files,
        retention_anchor,
        base_root,
        opened_wal,
        recovered_wal,
        active_page_generation,
        retention_floor_csn,
        manifest_verification_time,
        wal_physical_verification_time,
        wal_semantic_replay_time,
    })
}

fn complete_pending_wal_retention(
    path: &Path,
    wal_retention: &mut WalRetentionStore,
    candidate: WalRetentionAnchor,
    manifests: &[RootManifest],
) -> Result<(), NativeRuntimeError> {
    validate_retention_anchor(&candidate, manifests)?;
    let file = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(path.join(WAL_FILE))?;
    file.set_len(0)?;
    file.sync_data()?;
    drop(file);
    wal_retention.stabilize_candidate(candidate.fields().epoch, true)?;
    Ok(())
}

fn open_retained_wal(
    path: &Path,
    anchor: Option<WalRetentionAnchor>,
) -> Result<hyphae_native_wal::OpenedWal, WalError> {
    if let Some(anchor) = anchor {
        WalFile::open_after(
            path.join(WAL_FILE),
            anchor.fields().retired_through_sequence,
            anchor.fields().retired_block_digest,
        )
    } else {
        WalFile::open(path.join(WAL_FILE))
    }
}

struct WalRecoveryMetadata {
    next_transaction_id: u128,
    visible_csn: Option<Csn>,
    committed_transactions: usize,
    retained_wal_bytes: u64,
    checkpoint_count: usize,
}

fn wal_recovery_metadata(
    path: &Path,
    anchor: Option<WalRetentionAnchor>,
    physical: &WalRecovery,
    semantic: &RecoveredWal,
) -> Result<WalRecoveryMetadata, NativeRuntimeError> {
    let suffix_next_transaction_id = physical
        .records
        .iter()
        .map(|record| record.transaction_id().get())
        .max()
        .map_or(Ok(1_u128), |transaction_id| {
            transaction_id
                .checked_add(1)
                .ok_or(NativeRuntimeError::TransactionIdExhausted)
        })?;
    let next_transaction_id = anchor.map_or(suffix_next_transaction_id, |anchor| {
        anchor
            .fields()
            .next_transaction_id
            .max(suffix_next_transaction_id)
    });
    let visible_csn = semantic
        .commits
        .last()
        .map(|commit| commit.manifest.commit_csn)
        .or_else(|| anchor.map(|anchor| anchor.fields().base_visible_csn));
    let base_commits = anchor.map_or(0_u64, |anchor| anchor.fields().committed_transaction_count);
    let committed_transactions = checked_recovery_total(base_commits, semantic.commits.len())
        .ok_or(NativeRuntimeError::NoncontiguousCommitSequence)?;
    let base_checkpoints = anchor.map_or(0_u64, |anchor| anchor.fields().checkpoint_count);
    let checkpoint_count = checked_recovery_total(base_checkpoints, semantic.checkpoints.len())
        .ok_or(NativeRuntimeError::InvalidCheckpoint)?;
    Ok(WalRecoveryMetadata {
        next_transaction_id,
        visible_csn,
        committed_transactions,
        retained_wal_bytes: fs::metadata(path.join(WAL_FILE))?.len(),
        checkpoint_count,
    })
}

fn wal_recovery_metadata_for_open(
    path: &Path,
    anchor: Option<WalRetentionAnchor>,
    state: &WalOpenState,
) -> Result<WalRecoveryMetadata, NativeRuntimeError> {
    wal_recovery_metadata(
        path,
        anchor,
        &state.opened_wal.recovery,
        &state.recovered_wal,
    )
}

fn checked_recovery_total(base: u64, suffix: usize) -> Option<usize> {
    base.checked_add(u64::try_from(suffix).ok()?)
        .and_then(|total| usize::try_from(total).ok())
}

fn recover_transaction_resolutions(
    recovered: &RecoveredWal,
) -> Result<BTreeMap<TransactionId, DurableTransactionResolution>, NativeRuntimeError> {
    recovered
        .outcomes
        .iter()
        .map(|outcome| {
            let recovered_commit = recovered
                .commits
                .iter()
                .find(|commit| commit.transaction_id == outcome.runtime_transaction_id);
            let resolved = match (outcome.state, outcome.commit_csn, recovered_commit) {
                (1, Some(commit_csn), _) => DurableTransactionOutcome::Committed {
                    runtime_transaction_id: outcome.runtime_transaction_id,
                    commit_csn,
                },
                (2, None, _) | (3, None, None) => DurableTransactionOutcome::RolledBack {
                    runtime_transaction_id: outcome.runtime_transaction_id,
                },
                (3, None, Some(commit)) => DurableTransactionOutcome::Committed {
                    runtime_transaction_id: outcome.runtime_transaction_id,
                    commit_csn: commit.manifest.commit_csn,
                },
                _ => {
                    return Err(NativeRuntimeError::WalSemantic(
                        "invalid outcome state".into(),
                    ));
                }
            };
            Ok((
                outcome.resolution_id,
                DurableTransactionResolution {
                    resolution_id: outcome.resolution_id,
                    principal_hash: outcome.principal_hash,
                    idempotency_token: outcome.idempotency_token,
                    outcome: resolved,
                },
            ))
        })
        .collect()
}

fn recover_transaction_receipts(
    recovered: &RecoveredWal,
    physical: &WalRecovery,
) -> Result<BTreeMap<TransactionId, CommitReceipt>, NativeRuntimeError> {
    recovered
        .commits
        .iter()
        .map(|commit| {
            Ok((
                commit.transaction_id,
                CommitReceipt {
                    transaction_id: commit.transaction_id,
                    commit_csn: commit.manifest.commit_csn,
                    catalog_version: commit.manifest.catalog_version,
                    commit_lsn: commit.commit_lsn,
                    wal_block_digest: digest_for_lsn(physical, commit.commit_lsn)?,
                    durability: commit.durability,
                    durability_cohort_size: 1,
                    durability_cohort_position: 0,
                    execution_time: Duration::ZERO,
                    wal_append_time: Duration::ZERO,
                    page_synchronization_time: Duration::ZERO,
                    wal_synchronization_time: Duration::ZERO,
                },
            ))
        })
        .collect()
}

fn persist_recovered_outcome_updates(
    wal: &mut WalFile,
    resolutions: &[DurableTransactionResolution],
) -> Result<(), NativeRuntimeError> {
    for resolution in resolutions {
        let (runtime_transaction_id, state, commit_csn) = match resolution.outcome {
            DurableTransactionOutcome::Committed {
                runtime_transaction_id,
                commit_csn,
            } => (runtime_transaction_id, 1, Some(commit_csn)),
            DurableTransactionOutcome::RolledBack {
                runtime_transaction_id,
            } => (runtime_transaction_id, 2, None),
            DurableTransactionOutcome::OutcomeUnknown { .. } => continue,
        };
        wal.append_records(
            vec![encode_outcome(
                resolution.resolution_id,
                runtime_transaction_id,
                resolution.principal_hash,
                resolution.idempotency_token,
                state,
                commit_csn,
            )?],
            true,
        )?;
    }
    Ok(())
}

fn recovered_blob_generation_floor(
    base_root: Option<&RootSet>,
    commits: &[wal_codec::RecoveredCommit],
) -> u64 {
    commits.last().map_or_else(
        || base_root.map_or(0, RootSet::blob_generation),
        |commit| commit.manifest.blob_generation,
    )
}

fn replay_conflicts(
    commits: &[wal_codec::RecoveredCommit],
) -> Result<ConflictTable, NativeRuntimeError> {
    let mut conflicts = ConflictTable::default();
    for recovered in commits {
        let keys = mutation_write_keys(&recovered.mutations);
        let validation_keys = mutation_validation_keys(&recovered.mutations);
        conflicts.validate(recovered.manifest.read_csn, &validation_keys)?;
        conflicts.publish_committed(recovered.manifest.commit_csn, keys);
    }
    Ok(conflicts)
}

fn restore_commit_coordinator(
    latest_root: Option<RootSet>,
) -> Result<CommitCoordinator, NativeRuntimeError> {
    if let Some(root) = latest_root {
        CommitCoordinator::restore(root).map_err(Into::into)
    } else {
        Ok(CommitCoordinator::new(
            CatalogVersion::new(1).map_err(|_| NativeRuntimeError::InvalidCommittedRoot)?,
        ))
    }
}

fn cleanup_stale_wal_anchors(
    store: &mut WalRetentionStore,
    current: Option<WalRetentionAnchor>,
) -> Result<(), NativeRuntimeError> {
    if let Some(anchor) = current
        && store.recovery().anchors.len() > 1
    {
        store.remove_before(anchor.fields().epoch, true)?;
    }
    Ok(())
}

fn prune_recovered_manifest_prefix(
    manifests: &mut RootManifestStore,
    anchor: Option<WalRetentionAnchor>,
) -> Result<(Option<ManifestPruneReceipt>, Duration), NativeRuntimeError> {
    let started = Instant::now();
    let receipt = anchor
        .map(|anchor| {
            manifests.prune_before(
                anchor.fields().manifest_generation,
                anchor.fields().manifest_digest,
                true,
            )
        })
        .transpose()?;
    Ok((receipt, started.elapsed()))
}

struct RetainedPageState<'database> {
    pages: &'database PageStore,
    blobs: &'database BlobStore,
    blob_generation: u64,
    active_generation: PageGeneration,
    retention_floor_csn: Csn,
}

fn recover_wal_and_close_dangling(
    opened: &mut hyphae_native_wal::OpenedWal,
    base: Option<WalSemanticBase>,
) -> Result<RecoveredWal, NativeRuntimeError> {
    let recovered = recover_wal_after(&opened.recovery.records, base)?;
    if let Some(transaction_id) = recovered.dangling_transaction {
        opened
            .wal
            .append_records(vec![encode_abort(transaction_id)?], true)?;
    }
    Ok(recovered)
}

type CommittedRootsRecovery = (BTreeMap<Csn, RootSet>, Option<RootSet>, Duration);

fn recover_committed_roots_timed(
    commits: &[wal_codec::RecoveredCommit],
    wal_recovery: &WalRecovery,
    storage: &RetainedPageState<'_>,
    base_root: Option<RootSet>,
) -> Result<CommittedRootsRecovery, NativeRuntimeError> {
    let started = Instant::now();
    let (committed, latest) = recover_committed_roots(commits, wal_recovery, storage, base_root)?;
    Ok((committed, latest, started.elapsed()))
}

fn recover_committed_roots(
    commits: &[wal_codec::RecoveredCommit],
    wal_recovery: &WalRecovery,
    storage: &RetainedPageState<'_>,
    base_root: Option<RootSet>,
) -> Result<(BTreeMap<Csn, RootSet>, Option<RootSet>), NativeRuntimeError> {
    let mut committed_roots = BTreeMap::new();
    let mut latest_root = base_root;
    if let Some(root) = latest_root.as_ref() {
        let visible_csn = root
            .visible_csn()
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        if root.blob_generation() > storage.blob_generation
            || root.page_generation() != storage.active_generation
            || root.retention_floor_csn() != Some(storage.retention_floor_csn)
        {
            return Err(NativeRuntimeError::InvalidCommittedRoot);
        }
        validate_roots(storage.pages, storage.blobs, root, visible_csn)?;
        committed_roots.insert(visible_csn, root.clone());
    }
    for recovered in commits {
        let anchor_digest = digest_for_lsn(wal_recovery, recovered.commit_lsn)?;
        let root = RootSet::committed_with_storage(
            recovered.manifest.commit_csn,
            recovered.manifest.catalog_version,
            WalAnchor::new(recovered.commit_lsn, anchor_digest)?,
            root_map(recovered.manifest.roots),
            recovered.manifest.blob_generation,
            recovered.manifest.page_generation,
            recovered.manifest.retention_floor_csn,
        )?;
        if root.blob_generation() > storage.blob_generation {
            return Err(NativeRuntimeError::InvalidCommittedRoot);
        }
        if recovered.manifest.commit_csn >= storage.retention_floor_csn {
            if recovered.manifest.page_generation != storage.active_generation {
                return Err(NativeRuntimeError::NoncontiguousCommitSequence);
            }
            validate_roots(
                storage.pages,
                storage.blobs,
                &root,
                recovered.manifest.commit_csn,
            )?;
        }
        committed_roots.insert(recovered.manifest.commit_csn, root.clone());
        latest_root = Some(root);
    }
    Ok((committed_roots, latest_root))
}

#[cfg(test)]
fn validate_commit_sequence(
    commits: &[wal_codec::RecoveredCommit],
) -> Result<(), NativeRuntimeError> {
    validate_commit_sequence_after(commits, None)
}

fn validate_commit_sequence_after(
    commits: &[wal_codec::RecoveredCommit],
    base_root: Option<&RootSet>,
) -> Result<(), NativeRuntimeError> {
    let mut expected = if let Some(root) = base_root {
        root.visible_csn()
            .and_then(|visible| visible.get().checked_add(1))
            .ok_or(NativeRuntimeError::NoncontiguousCommitSequence)?
    } else {
        1
    };
    let mut prior = base_root.and_then(RootSet::visible_csn);
    let mut prior_page_generation = base_root.map(RootSet::page_generation);
    let mut prior_retention_floor = base_root.and_then(RootSet::retention_floor_csn);
    let mut prior_blob_generation = base_root.map_or(0, RootSet::blob_generation);
    for commit in commits {
        let page_generation = commit.manifest.page_generation;
        let retention_floor_csn = commit.manifest.retention_floor_csn;
        let storage_transition_valid = match (prior_page_generation, prior_retention_floor) {
            (None, None) => {
                page_generation == PageGeneration::FIRST && retention_floor_csn == Csn::FIRST
            }
            (Some(prior_generation), Some(prior_floor)) if page_generation == prior_generation => {
                retention_floor_csn == prior_floor
            }
            (Some(prior_generation), Some(_)) => {
                prior_generation.checked_next() == Some(page_generation)
                    && retention_floor_csn == commit.manifest.commit_csn
            }
            _ => false,
        };
        if commit.manifest.commit_csn.get() != expected
            || commit
                .manifest
                .read_csn
                .is_some_and(|read| prior.is_none_or(|published| read > published))
            || commit.manifest.blob_generation < prior_blob_generation
            || !storage_transition_valid
        {
            return Err(NativeRuntimeError::NoncontiguousCommitSequence);
        }
        prior = Some(commit.manifest.commit_csn);
        prior_page_generation = Some(page_generation);
        prior_retention_floor = Some(retention_floor_csn);
        prior_blob_generation = commit.manifest.blob_generation;
        expected = expected
            .checked_add(1)
            .ok_or(NativeRuntimeError::NoncontiguousCommitSequence)?;
    }
    Ok(())
}

fn digest_for_lsn(
    recovery: &WalRecovery,
    lsn: hyphae_native_types::Lsn,
) -> Result<[u8; 32], NativeRuntimeError> {
    recovery
        .blocks
        .iter()
        .find(|block| block.first_lsn <= lsn && lsn <= block.last_lsn)
        .map(|block| block.digest)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)
}

fn validate_roots(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
    visible_csn: Csn,
) -> Result<(), NativeRuntimeError> {
    let catalog_root = roots
        .root(SLOT_CATALOG)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let catalog_page = pages.read(catalog_root)?;
    if !matches!(
        catalog_page.kind(),
        PageKind::CatalogRoot | PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    if catalog_page
        .creating_csn()
        .is_none_or(|creating| creating > visible_csn)
    {
        return Err(NativeRuntimeError::FuturePage);
    }
    if matches!(
        catalog_page.kind(),
        PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        BTree::from_root(catalog_root).validate_visible(pages, visible_csn)?;
    }
    let relational_root = roots
        .root(SLOT_RELATIONAL)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let relational_page = pages.read(relational_root)?;
    if !matches!(
        relational_page.kind(),
        PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    if relational_page
        .creating_csn()
        .is_none_or(|creating| creating > visible_csn)
    {
        return Err(NativeRuntimeError::FuturePage);
    }
    BTree::from_root(relational_root).validate_visible(pages, visible_csn)?;

    let structure_root = roots
        .root(SLOT_STRUCTURE)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let structure_page = pages.read(structure_root)?;
    if !matches!(
        structure_page.kind(),
        PageKind::StructureNode | PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    if structure_page
        .creating_csn()
        .is_none_or(|creating| creating > visible_csn)
    {
        return Err(NativeRuntimeError::FuturePage);
    }
    if matches!(
        structure_page.kind(),
        PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        BTree::from_root(structure_root).validate_visible(pages, visible_csn)?;
    }
    let search_root = roots
        .root(SLOT_SEARCH)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let search_page = pages.read(search_root)?;
    if !matches!(
        search_page.kind(),
        PageKind::SearchDelta | PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        return Err(NativeRuntimeError::InvalidCommittedRoot);
    }
    if search_page
        .creating_csn()
        .is_none_or(|creating| creating > visible_csn)
    {
        return Err(NativeRuntimeError::FuturePage);
    }
    if matches!(
        search_page.kind(),
        PageKind::BTreeLeaf | PageKind::BTreeInternal
    ) {
        BTree::from_root(search_root).validate_visible(pages, visible_csn)?;
    }
    load_state(pages, blobs, roots)?;
    Ok(())
}

fn load_state(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
) -> Result<MaterializedState, NativeRuntimeError> {
    FULL_STATE_LOADS.fetch_add(1, Ordering::Relaxed);
    #[cfg(test)]
    if FAIL_FULL_STATE_LOAD.get() {
        return Err(NativeRuntimeError::UnexpectedFullStateLoad);
    }
    let catalog = load_catalog_state(pages, blobs, roots)?;
    let relational = load_relational_state(pages, blobs, roots, &catalog)?;
    let search = load_search_state(pages, blobs, roots)?;
    let ann = ann_store::load(pages, roots.root(SLOT_SEARCH), &catalog)?;
    Ok(MaterializedState {
        catalog,
        relational,
        structures: load_structure_state(pages, blobs, roots)?,
        search,
        ann,
    })
}

fn load_catalog_state(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
) -> Result<CatalogState, NativeRuntimeError> {
    let Some(root) = roots.root(SLOT_CATALOG) else {
        return Ok(CatalogState::default());
    };
    load_catalog_state_root(pages, blobs, root)
}

#[allow(clippy::too_many_lines)]
fn load_catalog_state_root(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
) -> Result<CatalogState, NativeRuntimeError> {
    FULL_CATALOG_STATE_LOADS.fetch_add(1, Ordering::Relaxed);
    #[cfg(test)]
    reject_full_catalog_state_load_for_test()?;
    let page = pages.read(root)?;
    if page.kind() == PageKind::CatalogRoot {
        return Ok(CatalogState::decode(page.payload())?);
    }
    if !matches!(page.kind(), PageKind::BTreeLeaf | PageKind::BTreeInternal) {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let entries = BTree::from_root(root).scan(pages)?;
    let mut iterator = entries.into_iter();
    let Some((format_key, format_value)) = iterator.next() else {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    };
    if format_key != CATALOG_FORMAT_KEY {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let (
        has_relation_indexes,
        has_id_authority,
        has_logical_dependencies,
        has_ancestor_descendants,
    ) = match format_value.as_slice() {
        CATALOG_FORMAT_VALUE_V3 => (false, false, false, false),
        CATALOG_FORMAT_VALUE_V4 => (true, false, false, false),
        CATALOG_FORMAT_VALUE_V5 => (true, true, false, false),
        CATALOG_FORMAT_VALUE_V6 => (true, true, true, false),
        CATALOG_FORMAT_VALUE_V7 => (true, true, true, true),
        _ => return Err(NativeRuntimeError::InvalidCatalogTree),
    };

    let mut objects = Vec::new();
    let mut logical_objects = Vec::new();
    let mut persisted_next_object_id = None;
    let mut names = BTreeMap::new();
    let mut relation_indexes = BTreeSet::new();
    let mut outgoing_dependencies = BTreeSet::new();
    let mut incoming_dependencies = BTreeSet::new();
    let mut ancestor_descendants = BTreeSet::new();
    for (key, value) in iterator {
        match key.first().copied() {
            Some(0) if has_id_authority && key == CATALOG_ID_AUTHORITY_KEY && value.len() == 16 => {
                let raw = u128::from_be_bytes(
                    value
                        .as_slice()
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
                );
                persisted_next_object_id = Some((raw != 0).then_some(raw));
            }
            Some(CATALOG_OBJECT_PREFIX) if key.len() == 17 => {
                let id = ObjectId::new(u128::from_be_bytes(
                    key[1..]
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
                ))
                .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
                let definition = decode_catalog_definition_storage_value(&value, blobs)?;
                if definition.starts_with(b"HYCOBJ02") {
                    if !has_logical_dependencies {
                        return Err(NativeRuntimeError::InvalidCatalogTree);
                    }
                    let object = LogicalCatalogObject::decode_definition_v2(&definition)?;
                    if object.id() != id {
                        return Err(NativeRuntimeError::InvalidCatalogTree);
                    }
                    logical_objects.push(object);
                } else {
                    let object = CatalogObject::decode_definition(&definition)?;
                    if object.header().id != id {
                        return Err(NativeRuntimeError::InvalidCatalogTree);
                    }
                    objects.push(object);
                }
            }
            Some(CATALOG_NAME_PREFIX) if key.len() > 1 && value.len() == 16 => {
                let id = ObjectId::new(u128::from_be_bytes(
                    value
                        .as_slice()
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
                ))
                .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
                if names.insert(key, id).is_some() {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
            }
            Some(CATALOG_RELATION_INDEX_PREFIX) if has_relation_indexes => {
                let dependency = decode_catalog_relation_index_entry(&key, &value)?;
                if !relation_indexes.insert(dependency) {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
            }
            Some(CATALOG_DEPENDENCY_OUTGOING_PREFIX) if has_logical_dependencies => {
                let (edge, _) =
                    decode_catalog_dependency_entry(&key, &value, DependencyDirection::Outgoing)?;
                if !outgoing_dependencies.insert(edge) {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
            }
            Some(CATALOG_DEPENDENCY_INCOMING_PREFIX) if has_logical_dependencies => {
                let (edge, _) =
                    decode_catalog_dependency_entry(&key, &value, DependencyDirection::Incoming)?;
                if !incoming_dependencies.insert(edge) {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
            }
            Some(CATALOG_ANCESTOR_DESCENDANT_PREFIX) if has_ancestor_descendants => {
                let entry = decode_catalog_ancestor_descendant_entry(&key, &value)?;
                if !ancestor_descendants.insert(entry) {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
            }
            _ => return Err(NativeRuntimeError::InvalidCatalogTree),
        }
    }

    let mut expected_names = BTreeMap::new();
    let mut expected_relation_indexes = BTreeSet::new();
    for object in &objects {
        if expected_names
            .insert(catalog_name_key(object.header())?, object.header().id)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        if let CatalogObject::SecondaryIndex(definition) = object {
            expected_relation_indexes.insert((definition.relation, definition.header.id));
        }
    }
    let mut expected_dependencies = BTreeSet::new();
    if has_logical_dependencies {
        expected_dependencies.extend(objects.iter().flat_map(CatalogObject::dependencies));
    }
    for object in &logical_objects {
        if expected_names
            .insert(catalog_name_key_from_qualified(object.name())?, object.id())
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
        expected_dependencies.extend(object.dependencies());
    }
    if names != expected_names
        || names.len()
            != objects
                .len()
                .checked_add(logical_objects.len())
                .ok_or(NativeRuntimeError::InvalidCatalogTree)?
    {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    if has_relation_indexes && relation_indexes != expected_relation_indexes {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    if has_logical_dependencies
        && (outgoing_dependencies != expected_dependencies
            || incoming_dependencies != expected_dependencies)
    {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    if has_ancestor_descendants {
        let mut expected = BTreeSet::new();
        for object in &objects {
            expected.insert((object.header().id, object.header().id));
        }
        let logical_by_id = logical_objects
            .iter()
            .map(|object| (object.id(), object))
            .collect::<BTreeMap<_, _>>();
        for object in &logical_objects {
            let mut current = Some(object.id());
            let mut visited = BTreeSet::new();
            while let Some(ancestor) = current {
                if !visited.insert(ancestor) {
                    return Err(NativeRuntimeError::InvalidCatalogTree);
                }
                expected.insert((ancestor, object.id()));
                current = logical_by_id
                    .get(&ancestor)
                    .and_then(|definition| definition.parent());
            }
        }
        if ancestor_descendants != expected {
            return Err(NativeRuntimeError::InvalidCatalogTree);
        }
    }
    if has_id_authority && persisted_next_object_id.is_none() {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }

    let mut catalog = CatalogState::default();
    for object in objects.iter().filter(|object| {
        !matches!(
            object,
            CatalogObject::SecondaryIndex(_) | CatalogObject::CrossEngineLink(_)
        )
    }) {
        catalog.create(object.clone())?;
    }
    for object in objects
        .iter()
        .filter(|object| matches!(object, CatalogObject::SecondaryIndex(_)))
    {
        catalog.create(object.clone())?;
    }
    for object in objects
        .into_iter()
        .filter(|object| matches!(object, CatalogObject::CrossEngineLink(_)))
    {
        catalog.create(object)?;
    }
    for object in logical_objects {
        catalog.insert_logical_unchecked(object)?;
    }
    catalog.validate_all_logical_dependencies()?;
    if let Some(authority) = persisted_next_object_id {
        catalog.set_next_object_id_raw(authority)?;
    }
    if catalog.objects.len() + catalog.logical_objects.len() != names.len() {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    Ok(catalog)
}

fn decode_catalog_relation_index_entry(
    key: &[u8],
    value: &[u8],
) -> Result<(ObjectId, ObjectId), NativeRuntimeError> {
    if key.len() != 33 || !value.is_empty() {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let relation = ObjectId::new(u128::from_be_bytes(
        key[1..17]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    let index = ObjectId::new(u128::from_be_bytes(
        key[17..]
            .try_into()
            .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?,
    ))
    .map_err(|_| NativeRuntimeError::InvalidCatalogTree)?;
    Ok((relation, index))
}

fn decode_catalog_definition_storage_value(
    encoded: &[u8],
    blobs: &BlobStore,
) -> Result<Vec<u8>, NativeRuntimeError> {
    if encoded.len() < CATALOG_VALUE_HEADER_SIZE
        || encoded.get(..8) != Some(CATALOG_VALUE_MAGIC.as_slice())
        || encoded[9..CATALOG_VALUE_HEADER_SIZE]
            .iter()
            .any(|byte| *byte != 0)
    {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let payload = &encoded[CATALOG_VALUE_HEADER_SIZE..];
    match encoded[8] {
        CATALOG_VALUE_INLINE if payload.len() <= CATALOG_INLINE_VALUE_LIMIT => Ok(payload.to_vec()),
        CATALOG_VALUE_BLOB if payload.len() == hyphae_native_records::BLOB_REFERENCE_SIZE => {
            let reference = BlobReference::decode(payload)?;
            if reference.logical_length <= CATALOG_INLINE_VALUE_LIMIT as u64 {
                return Err(NativeRuntimeError::InvalidCatalogTree);
            }
            Ok(blobs.read(reference)?)
        }
        _ => Err(NativeRuntimeError::InvalidCatalogTree),
    }
}

fn decode_delta_catalog_definition(
    encoded: &[u8],
) -> Result<DeltaCatalogDefinition<'_>, NativeRuntimeError> {
    if encoded.len() < CATALOG_VALUE_HEADER_SIZE
        || encoded.get(..8) != Some(CATALOG_VALUE_MAGIC.as_slice())
        || encoded[9..CATALOG_VALUE_HEADER_SIZE]
            .iter()
            .any(|byte| *byte != 0)
    {
        return Err(NativeRuntimeError::InvalidCatalogTree);
    }
    let payload = &encoded[CATALOG_VALUE_HEADER_SIZE..];
    match encoded[8] {
        CATALOG_VALUE_INLINE if payload.len() <= CATALOG_INLINE_VALUE_LIMIT => {
            Ok(DeltaCatalogDefinition::Inline(payload))
        }
        CATALOG_VALUE_BLOB if payload.len() == hyphae_native_records::BLOB_REFERENCE_SIZE => {
            let reference = BlobReference::decode(payload)?;
            if reference.logical_length <= CATALOG_INLINE_VALUE_LIMIT as u64 {
                return Err(NativeRuntimeError::InvalidCatalogTree);
            }
            Ok(DeltaCatalogDefinition::Blob(reference))
        }
        _ => Err(NativeRuntimeError::InvalidCatalogTree),
    }
}

#[allow(clippy::too_many_lines)]
fn load_relational_state(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
    catalog: &CatalogState,
) -> Result<RelationState, NativeRuntimeError> {
    let Some(root) = roots.root(SLOT_RELATIONAL) else {
        return Ok(RelationState::default());
    };
    let entries = BTree::from_root(root).scan(pages)?;
    let mut iterator = entries.into_iter();
    let Some((format_key, format_value)) = iterator.next() else {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    };
    if format_key != RELATIONAL_FORMAT_KEY {
        return Err(NativeRuntimeError::InvalidRelationalTree);
    }
    let format = RelationalFormat::decode(&format_value)?;
    let mut tables = BTreeMap::new();
    let mut indexes = BTreeMap::new();
    for (key, value) in iterator {
        match key.first().copied() {
            Some(RELATIONAL_TABLE_PREFIX) if key.len() == 17 && value.is_empty() => {
                let table = decode_relational_table(&key, RELATIONAL_TABLE_PREFIX)?;
                if tables.insert(table, BTreeMap::new()).is_some() {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
            }
            Some(RELATIONAL_ROW_PREFIX) if key.len() >= 17 => {
                let table = decode_relational_table(&key, RELATIONAL_ROW_PREFIX)?;
                let rows = tables
                    .get_mut(&table)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                let primary_key = &key[17..];
                let decoded = match format {
                    RelationalFormat::InlineRowV1 => decode_relational_row(
                        table,
                        primary_key,
                        &value,
                        roots.visible_csn(),
                        blobs,
                    )?,
                    RelationalFormat::VersionChainV2 => decode_relational_chain(
                        pages,
                        table,
                        primary_key,
                        &value,
                        roots.visible_csn(),
                        blobs,
                    )?,
                };
                let Some(value) = decoded else {
                    continue;
                };
                if rows.insert(primary_key.to_vec(), value).is_some() {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
            }
            Some(RELATIONAL_SECONDARY_INDEX_PREFIX) if key.len() == 17 => {
                let index = decode_relational_table(&key, RELATIONAL_SECONDARY_INDEX_PREFIX)?;
                let (relation, unique, nulls_distinct, layout) =
                    decode_secondary_index_metadata(&value)?;
                let Some(CatalogObject::SecondaryIndex(definition)) = catalog.object(index) else {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                };
                if definition.relation != relation
                    || definition.unique != unique
                    || definition.nulls_distinct != nulls_distinct
                    || !tables.contains_key(&relation)
                    || indexes
                        .insert(
                            index,
                            model::SecondaryIndexState {
                                relation,
                                unique,
                                nulls_distinct,
                                layout,
                                entries: BTreeMap::new(),
                            },
                        )
                        .is_some()
                {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
            }
            Some(RELATIONAL_SECONDARY_ENTRY_PREFIX) if key.len() > 21 => {
                let index = decode_relational_table(&key, RELATIONAL_SECONDARY_ENTRY_PREFIX)?;
                let layout = indexes
                    .get(&index)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?
                    .layout;
                let (index_key, primary_key) =
                    decode_secondary_index_entry_identity(layout, &key[17..])?;
                let marker = match value.as_slice() {
                    [RELATIONAL_SECONDARY_ENTRY_TOMBSTONE] => false,
                    [RELATIONAL_SECONDARY_ENTRY_LIVE] => true,
                    _ => return Err(NativeRuntimeError::InvalidRelationalTree),
                };
                let index_state = indexes
                    .get(&index)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                if !marker {
                    continue;
                }
                let row = tables
                    .get(&index_state.relation)
                    .and_then(|rows| rows.get(primary_key))
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                let Some(CatalogObject::SecondaryIndex(definition)) = catalog.object(index) else {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                };
                let projection = secondary_index_projection(catalog, definition, row)?;
                if projection.key != index_key {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
                let index_state = indexes
                    .get_mut(&index)
                    .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
                let existing = index_state
                    .entries
                    .entry(index_key.to_vec())
                    .or_insert_with(BTreeSet::new);
                if !existing.insert(primary_key.to_vec())
                    || (index_state.unique
                        && !(projection.contains_null && index_state.nulls_distinct)
                        && existing.len() != 1)
                {
                    return Err(NativeRuntimeError::InvalidRelationalTree);
                }
            }
            _ => return Err(NativeRuntimeError::InvalidRelationalTree),
        }
    }
    let state = RelationState { tables, indexes };
    validate_secondary_index_projection(catalog, &state)?;
    Ok(state)
}

fn validate_secondary_index_projection(
    catalog: &CatalogState,
    relational: &RelationState,
) -> Result<(), NativeRuntimeError> {
    for object in catalog.objects.values() {
        let CatalogObject::SecondaryIndex(definition) = object else {
            continue;
        };
        let index = relational
            .indexes
            .get(&definition.header.id)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        if index.relation != definition.relation
            || index.unique != definition.unique
            || index.nulls_distinct != definition.nulls_distinct
        {
            return Err(NativeRuntimeError::InvalidRelationalTree);
        }
        let rows = relational
            .tables
            .get(&definition.relation)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        for (primary_key, row) in rows {
            let projection = secondary_index_projection(catalog, definition, row)?;
            if !index
                .entries
                .get(&projection.key)
                .is_some_and(|entries| entries.contains(primary_key))
            {
                return Err(NativeRuntimeError::InvalidRelationalTree);
            }
        }
    }
    Ok(())
}

fn formats_for_latest_root(
    pages: &PageStore,
    root: Option<&RootSet>,
) -> Result<(RelationalFormat, StructureFormat, SearchFormat), NativeRuntimeError> {
    root.map_or(
        Ok((
            RelationalFormat::VersionChainV2,
            StructureFormat::BTreeV2,
            SearchFormat::InvertedBTreeV1,
        )),
        |root| {
            Ok((
                relational_format_for_root(pages, root)?,
                structure_format_for_root(pages, root)?,
                search_format_for_root(pages, root)?,
            ))
        },
    )
}

fn relational_format_for_root(
    pages: &PageStore,
    roots: &RootSet,
) -> Result<RelationalFormat, NativeRuntimeError> {
    let root = roots
        .root(SLOT_RELATIONAL)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let marker = BTree::from_root(root)
        .get(pages, RELATIONAL_FORMAT_KEY)?
        .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
    RelationalFormat::decode(&marker)
}

fn load_structure_state(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
) -> Result<StructureState, NativeRuntimeError> {
    let Some(root) = roots.root(SLOT_STRUCTURE) else {
        return Ok(StructureState::default());
    };
    load_structure_state_root(pages, blobs, root)
}

fn load_structure_state_root(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
) -> Result<StructureState, NativeRuntimeError> {
    #[cfg(test)]
    reject_full_structure_state_load_for_test()?;
    let page = pages.read(root)?;
    if page.kind() == PageKind::StructureNode {
        return Ok(StructureState::decode(page.payload())?);
    }
    if !matches!(page.kind(), PageKind::BTreeLeaf | PageKind::BTreeInternal) {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    let entries = BTree::from_root(root).scan(pages)?;
    let mut iterator = entries.into_iter();
    let Some((format_key, format_value)) = iterator.next() else {
        return Err(NativeRuntimeError::InvalidStructureTree);
    };
    if format_key != STRUCTURE_FORMAT_KEY {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    if format_value.as_slice() == structure_v3::STRUCTURE_FORMAT_VALUE_V3 {
        return structure_v3::load_structure_state_v3(pages, blobs, BTree::from_root(root));
    }
    let require_expiry_index = match format_value.as_slice() {
        STRUCTURE_FORMAT_VALUE_V1 => false,
        STRUCTURE_FORMAT_VALUE_V2 => true,
        _ => return Err(NativeRuntimeError::InvalidStructureTree),
    };
    let mut decoder = StructureTreeDecoder {
        require_expiry_index,
        ..StructureTreeDecoder::default()
    };
    for (key, value) in iterator {
        decoder.consume(&key, &value, blobs)?;
    }
    decoder.finish(blobs)
}

#[derive(Default)]
struct StructureTreeDecoder {
    require_expiry_index: bool,
    entries: BTreeMap<Vec<u8>, StructureEntry>,
    hashes: BTreeMap<Vec<u8>, BTreeMap<Vec<u8>, Vec<u8>>>,
    hash_counts: BTreeMap<Vec<u8>, u64>,
    hash_expiries: BTreeMap<Vec<u8>, i64>,
    hash_field_expiries: BTreeMap<(Vec<u8>, Vec<u8>), i64>,
    retired_hashes: BTreeSet<Vec<u8>>,
    sets: BTreeMap<Vec<u8>, BTreeSet<Vec<u8>>>,
    set_counts: BTreeMap<Vec<u8>, u64>,
    set_expiries: BTreeMap<Vec<u8>, i64>,
    retired_sets: BTreeSet<Vec<u8>>,
    list_metadata: BTreeMap<Vec<u8>, ListMetadata>,
    list_chunks: BTreeMap<Vec<u8>, BTreeMap<i64, Vec<Vec<u8>>>>,
    list_expiries: BTreeMap<Vec<u8>, i64>,
    retired_lists: BTreeSet<Vec<u8>>,
    retired_sorted_sets: BTreeSet<Vec<u8>>,
    sorted_sets: BTreeMap<Vec<u8>, BTreeMap<Vec<u8>, SortedSetScore>>,
    sorted_set_counts: BTreeMap<Vec<u8>, u64>,
    sorted_set_expiries: BTreeMap<Vec<u8>, i64>,
    sorted_set_order: BTreeMap<Vec<u8>, BTreeSet<(SortedSetScore, Vec<u8>)>>,
    streams: BTreeMap<Vec<u8>, model::StreamEntries>,
    stream_last_ids: BTreeMap<Vec<u8>, u64>,
    stream_expiries: BTreeMap<Vec<u8>, i64>,
    retired_streams: BTreeSet<Vec<u8>>,
    expiry_index: BTreeMap<(i64, Vec<u8>), u8>,
    hash_field_expiry_index: BTreeSet<(i64, Vec<u8>, Vec<u8>)>,
}

impl StructureTreeDecoder {
    fn consume(
        &mut self,
        key: &[u8],
        value: &[u8],
        blobs: &BlobStore,
    ) -> Result<(), NativeRuntimeError> {
        match key.first().copied() {
            Some(STRUCTURE_ENTRY_PREFIX) => {
                if let Some(entry) = decode_structure_value(value, blobs)?
                    && self.entries.insert(key[1..].to_vec(), entry).is_some()
                {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
            Some(STRUCTURE_HASH_META_PREFIX) => {
                let hash = key[1..].to_vec();
                match decode_live_hash_metadata(value)? {
                    None => {
                        if !self.retired_hashes.insert(hash) {
                            return Err(NativeRuntimeError::InvalidStructureTree);
                        }
                    }
                    Some(metadata) => {
                        if self.entries.contains_key(&hash)
                            || self.hashes.insert(hash.clone(), BTreeMap::new()).is_some()
                            || self
                                .hash_counts
                                .insert(hash.clone(), metadata.field_count)
                                .is_some()
                            || metadata.expires_at_micros.is_some_and(|expiry| {
                                self.hash_expiries.insert(hash, expiry).is_some()
                            })
                        {
                            return Err(NativeRuntimeError::InvalidStructureTree);
                        }
                    }
                }
            }
            Some(STRUCTURE_HASH_FIELD_PREFIX) => {
                let (hash, field) = decode_hash_field_identity(&key[1..])
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
                if let Some(fields) = self.hashes.get_mut(hash) {
                    if let Some(entry) = decode_hash_field_entry(value, blobs)?
                        && (entry.expires_at_micros.is_some_and(|expiry| {
                            self.hash_field_expiries
                                .insert((hash.to_vec(), field.to_vec()), expiry)
                                .is_some()
                        }) || fields.insert(field.to_vec(), entry.value).is_some())
                    {
                        return Err(NativeRuntimeError::InvalidStructureTree);
                    }
                } else if !self.retired_hashes.contains(hash)
                    || decode_hash_field_entry(value, blobs)?.is_some()
                {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
            Some(STRUCTURE_SET_META_PREFIX) => self.consume_set_metadata(&key[1..], value)?,
            Some(STRUCTURE_SET_MEMBER_PREFIX) => self.consume_set_member(&key[1..], value)?,
            Some(STRUCTURE_LIST_META_PREFIX) => self.consume_list_metadata(&key[1..], value)?,
            Some(STRUCTURE_LIST_CHUNK_PREFIX) => self.consume_list_chunk(&key[1..], value)?,
            Some(STRUCTURE_SORTED_SET_META_PREFIX) => {
                self.consume_sorted_set_metadata(&key[1..], value)?;
            }
            Some(STRUCTURE_SORTED_SET_MEMBER_PREFIX) => {
                self.consume_sorted_set_member(&key[1..], value)?;
            }
            Some(STRUCTURE_SORTED_SET_ORDER_PREFIX) => {
                self.consume_sorted_set_order(&key[1..], value)?;
            }
            Some(STRUCTURE_STREAM_META_PREFIX) => self.consume_stream_metadata(&key[1..], value)?,
            Some(STRUCTURE_STREAM_ENTRY_PREFIX) => self.consume_stream_entry(&key[1..], value)?,
            Some(STRUCTURE_EXPIRY_PREFIX) => {
                let (expiry, structure_key) = decode_structure_expiry_identity(&key[1..])?;
                match value {
                    [STRUCTURE_EXPIRY_TOMBSTONE] => {}
                    [
                        marker @ (STRUCTURE_EXPIRY_LIVE
                        | STRUCTURE_HASH_EXPIRY_LIVE
                        | STRUCTURE_SET_EXPIRY_LIVE
                        | STRUCTURE_LIST_EXPIRY_LIVE
                        | STRUCTURE_STREAM_EXPIRY_LIVE
                        | STRUCTURE_SORTED_SET_EXPIRY_LIVE),
                    ] if self
                        .expiry_index
                        .insert((expiry, structure_key.to_vec()), *marker)
                        .is_none() => {}
                    _ => return Err(NativeRuntimeError::InvalidStructureTree),
                }
            }
            Some(STRUCTURE_HASH_FIELD_EXPIRY_PREFIX) => {
                let (expiry, hash, field) = decode_structure_hash_field_expiry_identity(&key[1..])?;
                match value {
                    [STRUCTURE_EXPIRY_TOMBSTONE] => {}
                    [STRUCTURE_HASH_FIELD_EXPIRY_LIVE]
                        if self.hash_field_expiry_index.insert((
                            expiry,
                            hash.to_vec(),
                            field.to_vec(),
                        )) => {}
                    _ => return Err(NativeRuntimeError::InvalidStructureTree),
                }
            }
            _ => return Err(NativeRuntimeError::InvalidStructureTree),
        }
        Ok(())
    }

    fn consume_stream_metadata(
        &mut self,
        key: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let stream = key.to_vec();
        if is_structure_tombstone(value) {
            if !self.retired_streams.insert(stream) {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            return Ok(());
        }
        let (last, expiry) = match value.len() {
            8 => (
                u64::from_be_bytes(
                    value
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                ),
                None,
            ),
            16 => (
                u64::from_be_bytes(
                    value[..8]
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                ),
                Some(i64::from_be_bytes(
                    value[8..]
                        .try_into()
                        .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                )),
            ),
            _ => return Err(NativeRuntimeError::InvalidStructureTree),
        };
        if self.entries.contains_key(&stream)
            || self.hashes.contains_key(&stream)
            || self.sets.contains_key(&stream)
            || self.list_metadata.contains_key(&stream)
            || self.sorted_sets.contains_key(&stream)
            || self
                .streams
                .insert(stream.clone(), BTreeMap::new())
                .is_some()
            || self.stream_last_ids.insert(stream.clone(), last).is_some()
            || expiry.is_some_and(|expiry| self.stream_expiries.insert(stream, expiry).is_some())
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_stream_entry(
        &mut self,
        identity: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        if identity.len() < 8 {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let split = identity.len() - 8;
        let key = &identity[..split];
        if is_structure_tombstone(value) {
            return Ok(());
        }
        let id = u64::from_be_bytes(
            identity[split..]
                .try_into()
                .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
        );
        let (payload_id, fields) = decode_stream_wal_entry(value)?;
        if id != payload_id {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let entries = self
            .streams
            .get_mut(key)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        if entries.insert(id, fields).is_some() {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_sorted_set_metadata(
        &mut self,
        key: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let sorted_set = key.to_vec();
        if is_structure_tombstone(value) {
            if !self.retired_sorted_sets.insert(sorted_set) {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            return Ok(());
        }
        let (count, expiry) = decode_sorted_set_metadata_state(value)?;
        if self.entries.contains_key(&sorted_set)
            || self.hashes.contains_key(&sorted_set)
            || self.sets.contains_key(&sorted_set)
            || self.list_metadata.contains_key(&sorted_set)
            || self
                .sorted_sets
                .insert(sorted_set.clone(), BTreeMap::new())
                .is_some()
            || self
                .sorted_set_counts
                .insert(sorted_set.clone(), count)
                .is_some()
            || expiry.is_some_and(|expiry| {
                self.sorted_set_expiries
                    .insert(sorted_set.clone(), expiry)
                    .is_some()
            })
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_sorted_set_member(
        &mut self,
        identity: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let (sorted_set, member) = decode_sorted_set_member_identity(identity)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if let Some(members) = self.sorted_sets.get_mut(sorted_set) {
            if let Some(score) = decode_sorted_set_score(value)?
                && members.insert(member.to_vec(), score).is_some()
            {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        } else if !self.retired_sorted_sets.contains(sorted_set)
            || decode_sorted_set_score(value)?.is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_sorted_set_order(
        &mut self,
        identity: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let (sorted_set, score, member) = decode_sorted_set_order_identity(identity)?;
        if self.retired_sorted_sets.contains(sorted_set) {
            if decode_set_member_value(value)? {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
            return Ok(());
        }
        if !self.sorted_sets.contains_key(sorted_set) {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        if decode_set_member_value(value)?
            && !self
                .sorted_set_order
                .entry(sorted_set.to_vec())
                .or_default()
                .insert((score, member.to_vec()))
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_set_metadata(&mut self, key: &[u8], value: &[u8]) -> Result<(), NativeRuntimeError> {
        let set = key.to_vec();
        match decode_live_set_metadata(value)? {
            None => {
                if !self.retired_sets.insert(set) {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
            Some(metadata) => {
                if self.entries.contains_key(&set)
                    || self.hashes.contains_key(&set)
                    || self.sets.insert(set.clone(), BTreeSet::new()).is_some()
                    || self
                        .set_counts
                        .insert(set.clone(), metadata.member_count)
                        .is_some()
                    || metadata
                        .expires_at_micros
                        .is_some_and(|expiry| self.set_expiries.insert(set, expiry).is_some())
                {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
        }
        Ok(())
    }

    fn consume_set_member(
        &mut self,
        identity: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let (set, member) = decode_set_member_identity(identity)
            .map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if let Some(members) = self.sets.get_mut(set) {
            if decode_set_member_value(value)? && !members.insert(member.to_vec()) {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        } else if !self.retired_sets.contains(set) || decode_set_member_value(value)? {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn consume_list_metadata(
        &mut self,
        key: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let list = key.to_vec();
        match decode_live_list_metadata(value)? {
            None => {
                if !self.retired_lists.insert(list) {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
            Some(metadata) => {
                if self.entries.contains_key(&list)
                    || self.hashes.contains_key(&list)
                    || self.sets.contains_key(&list)
                    || self.list_metadata.insert(list.clone(), metadata).is_some()
                    || metadata
                        .expires_at_micros
                        .is_some_and(|expiry| self.list_expiries.insert(list, expiry).is_some())
                {
                    return Err(NativeRuntimeError::InvalidStructureTree);
                }
            }
        }
        Ok(())
    }

    fn consume_list_chunk(
        &mut self,
        identity: &[u8],
        value: &[u8],
    ) -> Result<(), NativeRuntimeError> {
        let (list, chunk_id) = decode_list_chunk_identity(identity)?;
        if self.list_metadata.contains_key(list) {
            if let Some(elements) = decode_list_chunk_storage(value)?
                && self
                    .list_chunks
                    .entry(list.to_vec())
                    .or_default()
                    .insert(chunk_id, elements)
                    .is_some()
            {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        } else if !self.retired_lists.contains(list) || decode_list_chunk_storage(value)?.is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(())
    }

    fn finish(self, blobs: &BlobStore) -> Result<StructureState, NativeRuntimeError> {
        let Self {
            entries,
            hashes,
            hash_counts,
            hash_expiries,
            hash_field_expiries,
            retired_hashes: _,
            sets,
            set_counts,
            set_expiries,
            retired_sets: _,
            list_metadata,
            list_chunks,
            list_expiries,
            retired_lists: _,
            retired_sorted_sets: _,
            sorted_sets,
            sorted_set_counts,
            sorted_set_expiries,
            sorted_set_order,
            streams,
            stream_last_ids,
            stream_expiries,
            retired_streams: _,
            expiry_index,
            hash_field_expiry_index,
            require_expiry_index,
        } = self;
        validate_hash_counts(&hashes, hash_counts)?;
        validate_set_counts(&sets, set_counts)?;
        let lists = materialize_lists(list_metadata, list_chunks, blobs)?;
        validate_sorted_sets(&sorted_sets, &sorted_set_counts, sorted_set_order)?;
        for (key, last) in &stream_last_ids {
            let entries = streams
                .get(key)
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            if entries.last_key_value().map_or(0, |(id, _)| *id) != *last {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        }
        if require_expiry_index {
            validate_expiry_index(
                &entries,
                &hash_expiries,
                &set_expiries,
                &list_expiries,
                &stream_expiries,
                &sorted_set_expiries,
                &expiry_index,
            )?;
            validate_hash_field_expiry_index(&hash_field_expiries, &hash_field_expiry_index)?;
        } else if !expiry_index.is_empty()
            || !set_expiries.is_empty()
            || !list_expiries.is_empty()
            || !stream_expiries.is_empty()
            || !sorted_set_expiries.is_empty()
            || !hash_field_expiries.is_empty()
            || !hash_field_expiry_index.is_empty()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        Ok(StructureState {
            entries,
            hashes,
            hash_expiries,
            hash_field_expiries,
            sets,
            set_expiries,
            lists,
            list_expiries,
            sorted_sets,
            sorted_set_expiries,
            streams,
            stream_expiries,
        })
    }
}

fn materialize_lists(
    metadata: BTreeMap<Vec<u8>, ListMetadata>,
    mut chunks: BTreeMap<Vec<u8>, BTreeMap<i64, Vec<Vec<u8>>>>,
    blobs: &BlobStore,
) -> Result<BTreeMap<Vec<u8>, VecDeque<Vec<u8>>>, NativeRuntimeError> {
    let mut lists = BTreeMap::new();
    for (key, metadata) in metadata {
        let mut values = VecDeque::new();
        let mut value_bytes = 0_u64;
        let mut list_chunks = chunks.remove(&key).unwrap_or_default();
        if metadata.length == 0 {
            if !list_chunks.is_empty() {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        } else {
            let mut chunk_id = metadata.head_chunk;
            loop {
                let elements = list_chunks
                    .remove(&chunk_id)
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                for element in elements {
                    let value = decode_list_element(&element, blobs)?;
                    value_bytes = value_bytes
                        .checked_add(
                            u64::try_from(value.len())
                                .map_err(|_| NativeRuntimeError::InvalidStructureTree)?,
                        )
                        .ok_or(NativeRuntimeError::InvalidStructureTree)?;
                    values.push_back(value);
                }
                if chunk_id == metadata.tail_chunk {
                    break;
                }
                chunk_id = chunk_id
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            }
            if !list_chunks.is_empty()
                || u64::try_from(values.len())
                    .map_err(|_| NativeRuntimeError::InvalidStructureTree)?
                    != metadata.length
                || metadata
                    .value_bytes
                    .is_some_and(|expected| expected != value_bytes)
            {
                return Err(NativeRuntimeError::InvalidStructureTree);
            }
        }
        lists.insert(key, values);
    }
    if !chunks.is_empty() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(lists)
}

fn validate_hash_counts(
    hashes: &BTreeMap<Vec<u8>, BTreeMap<Vec<u8>, Vec<u8>>>,
    expected_counts: BTreeMap<Vec<u8>, u64>,
) -> Result<(), NativeRuntimeError> {
    for (key, expected) in expected_counts {
        let actual = hashes
            .get(&key)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
            .len();
        if u64::try_from(actual).map_err(|_| NativeRuntimeError::InvalidStructureTree)? != expected
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    Ok(())
}

fn validate_set_counts(
    sets: &BTreeMap<Vec<u8>, BTreeSet<Vec<u8>>>,
    expected_counts: BTreeMap<Vec<u8>, u64>,
) -> Result<(), NativeRuntimeError> {
    for (key, expected) in expected_counts {
        let actual = sets
            .get(&key)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?
            .len();
        if u64::try_from(actual).map_err(|_| NativeRuntimeError::InvalidStructureTree)? != expected
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    Ok(())
}

fn validate_sorted_sets(
    sorted_sets: &BTreeMap<Vec<u8>, BTreeMap<Vec<u8>, SortedSetScore>>,
    expected_counts: &BTreeMap<Vec<u8>, u64>,
    mut ordered: BTreeMap<Vec<u8>, BTreeSet<(SortedSetScore, Vec<u8>)>>,
) -> Result<(), NativeRuntimeError> {
    for (key, members) in sorted_sets {
        let expected = expected_counts
            .get(key)
            .ok_or(NativeRuntimeError::InvalidStructureTree)?;
        let actual =
            u64::try_from(members.len()).map_err(|_| NativeRuntimeError::InvalidStructureTree)?;
        if actual != *expected {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
        let expected_order = members
            .iter()
            .map(|(member, score)| (*score, member.clone()))
            .collect::<BTreeSet<_>>();
        if ordered.remove(key).unwrap_or_default() != expected_order {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    if expected_counts.len() != sorted_sets.len() || !ordered.is_empty() {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(())
}

fn validate_expiry_index(
    entries: &BTreeMap<Vec<u8>, StructureEntry>,
    hash_expiries: &BTreeMap<Vec<u8>, i64>,
    set_expiries: &BTreeMap<Vec<u8>, i64>,
    list_expiries: &BTreeMap<Vec<u8>, i64>,
    stream_expiries: &BTreeMap<Vec<u8>, i64>,
    sorted_set_expiries: &BTreeMap<Vec<u8>, i64>,
    actual: &BTreeMap<(i64, Vec<u8>), u8>,
) -> Result<(), NativeRuntimeError> {
    let mut expected = entries
        .iter()
        .filter_map(|(key, entry)| {
            entry
                .expires_at_micros
                .map(|expiry| ((expiry, key.clone()), STRUCTURE_EXPIRY_LIVE))
        })
        .collect::<BTreeMap<_, _>>();
    for (key, expiry) in hash_expiries {
        if expected
            .insert(((*expiry), key.clone()), STRUCTURE_HASH_EXPIRY_LIVE)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    for (key, expiry) in set_expiries {
        if expected
            .insert(((*expiry), key.clone()), STRUCTURE_SET_EXPIRY_LIVE)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    for (key, expiry) in list_expiries {
        if expected
            .insert(((*expiry), key.clone()), STRUCTURE_LIST_EXPIRY_LIVE)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    for (key, expiry) in stream_expiries {
        if expected
            .insert(((*expiry), key.clone()), STRUCTURE_STREAM_EXPIRY_LIVE)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    for (key, expiry) in sorted_set_expiries {
        if expected
            .insert(((*expiry), key.clone()), STRUCTURE_SORTED_SET_EXPIRY_LIVE)
            .is_some()
        {
            return Err(NativeRuntimeError::InvalidStructureTree);
        }
    }
    if *actual != expected {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(())
}

fn validate_hash_field_expiry_index(
    expected: &BTreeMap<(Vec<u8>, Vec<u8>), i64>,
    actual: &BTreeSet<(i64, Vec<u8>, Vec<u8>)>,
) -> Result<(), NativeRuntimeError> {
    let expected = expected
        .iter()
        .map(|((hash, field), expiry)| (*expiry, hash.clone(), field.clone()))
        .collect::<BTreeSet<_>>();
    if *actual != expected {
        return Err(NativeRuntimeError::InvalidStructureTree);
    }
    Ok(())
}

fn load_search_state(
    pages: &PageStore,
    blobs: &BlobStore,
    roots: &RootSet,
) -> Result<SearchState, NativeRuntimeError> {
    let Some(root) = roots.root(SLOT_SEARCH) else {
        return Ok(SearchState::default());
    };
    load_search_state_root(pages, blobs, root)
}

fn load_search_state_root(
    pages: &PageStore,
    blobs: &BlobStore,
    root: PageId,
) -> Result<SearchState, NativeRuntimeError> {
    let page = pages.read(root)?;
    if page.kind() == PageKind::SearchDelta {
        return Ok(SearchState::decode(page.payload())?);
    }
    if !matches!(page.kind(), PageKind::BTreeLeaf | PageKind::BTreeInternal) {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    let entries = BTree::from_root(root).scan(pages)?;
    let mut iterator = entries.into_iter();
    let Some((format_key, format_value)) = iterator.next() else {
        return Err(NativeRuntimeError::InvalidSearchTree);
    };
    if format_key != SEARCH_FORMAT_KEY {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    let format = PhysicalSearchFormat::decode(&format_value)?;
    let mut indexes = BTreeMap::<ObjectId, BTreeMap<Vec<u8>, String>>::new();
    let mut index_metadata = BTreeMap::<ObjectId, (u64, u64)>::new();
    let mut term_metadata = BTreeMap::<(ObjectId, Vec<u8>), u64>::new();
    let mut postings = BTreeMap::<(ObjectId, Vec<u8>, Vec<u8>), u32>::new();
    for (key, value) in iterator {
        match key.first().copied() {
            Some(SEARCH_INDEX_META_PREFIX) if key.len() == 17 => {
                let (index, suffix) = decode_search_object_key(&key, SEARCH_INDEX_META_PREFIX)?;
                if !suffix.is_empty()
                    || indexes.insert(index, BTreeMap::new()).is_some()
                    || index_metadata
                        .insert(index, decode_search_index_metadata(&value)?)
                        .is_some()
                {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
            }
            Some(SEARCH_DOCUMENT_PREFIX) => {
                let (index, document_id) = decode_search_object_key(&key, SEARCH_DOCUMENT_PREFIX)?;
                let documents = indexes
                    .get_mut(&index)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                validate_search_document_identity(document_id, "")
                    .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
                let Some((text, _)) = decode_live_search_document(&value, blobs, format)? else {
                    continue;
                };
                validate_search_document_identity(document_id, &text)
                    .map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
                if documents.insert(document_id.to_vec(), text).is_some() {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
            }
            Some(SEARCH_TERM_META_PREFIX) => {
                let (index, term) = decode_search_object_key(&key, SEARCH_TERM_META_PREFIX)?;
                if !indexes.contains_key(&index) || !is_canonical_search_term(term) {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
                let Some(document_frequency) = decode_live_search_term_metadata(&value, format)?
                else {
                    continue;
                };
                if term_metadata
                    .insert((index, term.to_vec()), document_frequency)
                    .is_some()
                {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
            }
            Some(SEARCH_POSTING_PREFIX) => {
                let (index, term, document_id) = decode_search_posting_key(&key)?;
                if !indexes.contains_key(&index)
                    || !is_canonical_search_term(term)
                    || validate_search_document_identity(document_id, "").is_err()
                {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
                let Some(term_frequency) = decode_live_search_posting(&value, format)? else {
                    continue;
                };
                if !indexes
                    .get(&index)
                    .is_some_and(|documents| documents.contains_key(document_id))
                    || postings
                        .insert((index, term.to_vec(), document_id.to_vec()), term_frequency)
                        .is_some()
                {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
            }
            _ if ann_store::is_ann_physical_key(&key) => {}
            _ => return Err(NativeRuntimeError::InvalidSearchTree),
        }
    }
    validate_search_projection(&indexes, &index_metadata, &term_metadata, &postings)?;
    Ok(SearchState { indexes })
}

fn validate_search_projection(
    indexes: &BTreeMap<ObjectId, BTreeMap<Vec<u8>, String>>,
    index_metadata: &BTreeMap<ObjectId, (u64, u64)>,
    term_metadata: &BTreeMap<(ObjectId, Vec<u8>), u64>,
    postings: &BTreeMap<(ObjectId, Vec<u8>, Vec<u8>), u32>,
) -> Result<(), NativeRuntimeError> {
    let mut expected_terms = BTreeMap::<(ObjectId, Vec<u8>), u64>::new();
    let mut expected_postings = BTreeMap::<(ObjectId, Vec<u8>, Vec<u8>), u32>::new();
    for (index, documents) in indexes {
        let (expected_document_count, expected_total_terms) = index_metadata
            .get(index)
            .ok_or(NativeRuntimeError::InvalidSearchTree)?;
        let actual_document_count =
            u64::try_from(documents.len()).map_err(|_| NativeRuntimeError::InvalidSearchTree)?;
        let mut actual_total_terms = 0_u64;
        for (document_id, text) in documents {
            let tokens = analyze(text);
            actual_total_terms = actual_total_terms
                .checked_add(
                    u64::try_from(tokens.len())
                        .map_err(|_| NativeRuntimeError::InvalidSearchTree)?,
                )
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            let mut frequencies = BTreeMap::<Vec<u8>, u32>::new();
            for token in tokens {
                let frequency = frequencies.entry(token.into_bytes()).or_default();
                *frequency = frequency
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            }
            for (term, frequency) in frequencies {
                let document_frequency = expected_terms.entry((*index, term.clone())).or_default();
                *document_frequency = (*document_frequency)
                    .checked_add(1)
                    .ok_or(NativeRuntimeError::InvalidSearchTree)?;
                if expected_postings
                    .insert((*index, term, document_id.clone()), frequency)
                    .is_some()
                {
                    return Err(NativeRuntimeError::InvalidSearchTree);
                }
            }
        }
        if *expected_document_count != actual_document_count
            || *expected_total_terms != actual_total_terms
        {
            return Err(NativeRuntimeError::InvalidSearchTree);
        }
    }
    if *term_metadata != expected_terms || *postings != expected_postings {
        return Err(NativeRuntimeError::InvalidSearchTree);
    }
    Ok(())
}

fn is_canonical_search_term(term: &[u8]) -> bool {
    std::str::from_utf8(term)
        .ok()
        .is_some_and(|term| analyze(term) == [term])
}

fn structure_format_for_root(
    pages: &PageStore,
    roots: &RootSet,
) -> Result<StructureFormat, NativeRuntimeError> {
    let root = roots
        .root(SLOT_STRUCTURE)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let page = pages.read(root)?;
    match page.kind() {
        PageKind::StructureNode => Ok(StructureFormat::InlineStateV1),
        PageKind::BTreeLeaf | PageKind::BTreeInternal => {
            let marker = BTree::from_root(root)
                .get(pages, STRUCTURE_FORMAT_KEY)?
                .ok_or(NativeRuntimeError::InvalidStructureTree)?;
            if marker == STRUCTURE_FORMAT_VALUE_V1 {
                Ok(StructureFormat::BTreeV1)
            } else if marker == STRUCTURE_FORMAT_VALUE_V2 {
                Ok(StructureFormat::BTreeV2)
            } else if marker == structure_v3::STRUCTURE_FORMAT_VALUE_V3 {
                Ok(StructureFormat::BTreeV3)
            } else {
                Err(NativeRuntimeError::InvalidStructureTree)
            }
        }
        _ => Err(NativeRuntimeError::InvalidStructureTree),
    }
}

fn search_format_for_root(
    pages: &PageStore,
    roots: &RootSet,
) -> Result<SearchFormat, NativeRuntimeError> {
    let root = roots
        .root(SLOT_SEARCH)
        .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
    let page = pages.read(root)?;
    match page.kind() {
        PageKind::SearchDelta => Ok(SearchFormat::InlineStateV1),
        PageKind::BTreeLeaf | PageKind::BTreeInternal => {
            let marker = BTree::from_root(root)
                .get(pages, SEARCH_FORMAT_KEY)?
                .ok_or(NativeRuntimeError::InvalidSearchTree)?;
            if marker == SEARCH_FORMAT_VALUE_V1
                || marker == SEARCH_FORMAT_VALUE_V2
                || marker == SEARCH_FORMAT_VALUE_V3
            {
                Ok(SearchFormat::InvertedBTreeV1)
            } else {
                Err(NativeRuntimeError::InvalidSearchTree)
            }
        }
        _ => Err(NativeRuntimeError::InvalidSearchTree),
    }
}

fn decode_relation_creation(
    id: ObjectId,
    mutation: &Mutation,
) -> Result<CatalogObject, NativeRuntimeError> {
    let encoded_definition = mutation.value.starts_with(b"HYCOBJ01");
    let object = if encoded_definition {
        CatalogObject::decode_definition(&mutation.value)?
    } else {
        if !mutation.key.is_empty() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let name = std::str::from_utf8(&mutation.value)
            .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?;
        CatalogObject::Relation(binary_relation_definition(id, name)?)
    };
    if !matches!(&object, CatalogObject::Relation(_)) || object.header().id != id {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    if encoded_definition && mutation.key.is_empty() {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    validate_catalog_creation_identity(&object, mutation)?;
    Ok(object)
}

fn decode_secondary_index_creation(
    id: ObjectId,
    mutation: &Mutation,
) -> Result<CatalogObject, NativeRuntimeError> {
    if mutation.key.is_empty()
        || mutation.expires_at_micros.is_some()
        || !mutation.value.starts_with(b"HYCOBJ01")
    {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    let object = CatalogObject::decode_definition(&mutation.value)?;
    if !matches!(&object, CatalogObject::SecondaryIndex(_)) || object.header().id != id {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    validate_catalog_creation_identity(&object, mutation)?;
    Ok(object)
}

fn decode_search_creation(
    id: ObjectId,
    mutation: &Mutation,
) -> Result<CatalogObject, NativeRuntimeError> {
    let encoded_definition = mutation.value.starts_with(b"HYCOBJ01");
    let object = if encoded_definition {
        CatalogObject::decode_definition(&mutation.value)?
    } else {
        if !mutation.key.is_empty() {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let name = std::str::from_utf8(&mutation.value)
            .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?;
        CatalogObject::Search(text_search_definition(id, name)?)
    };
    if !matches!(&object, CatalogObject::Search(_)) || object.header().id != id {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    if encoded_definition && mutation.key.is_empty() {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    validate_catalog_creation_identity(&object, mutation)?;
    Ok(object)
}

fn decode_ann_creation(
    id: ObjectId,
    mutation: &Mutation,
) -> Result<(CatalogObject, IncrementalVectorLifecycle), NativeRuntimeError> {
    if mutation.key.is_empty() || mutation.expires_at_micros.is_some() {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    let (definition, lifecycle) = if mutation.value.starts_with(b"HYCOBJ01") {
        (
            mutation.value.as_slice(),
            ann_store::DEFAULT_INCREMENTAL_VECTOR_LIFECYCLE,
        )
    } else {
        if mutation.value.len() < 20
            || mutation.value.get(..8) != Some(ANN_CREATION_MAGIC)
            || mutation.value[16..20]
                != u32::try_from(mutation.value.len() - 20)
                    .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?
                    .to_le_bytes()
        {
            return Err(NativeRuntimeError::InvalidPreparedMutation);
        }
        let lifecycle = IncrementalVectorLifecycle {
            delta_max_entries: u32::from_le_bytes(
                mutation.value[8..12]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?,
            ),
            consolidate_after_deltas: u16::from_le_bytes(
                mutation.value[12..14]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?,
            ),
            retain_generations: u16::from_le_bytes(
                mutation.value[14..16]
                    .try_into()
                    .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?,
            ),
        };
        lifecycle.validate()?;
        (&mutation.value[20..], lifecycle)
    };
    let object = CatalogObject::decode_definition(definition)?;
    let CatalogObject::Search(definition) = &object else {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    };
    if definition.header.id != id || definition.vector.is_none() || definition.ann.is_none() {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    validate_catalog_creation_identity(&object, mutation)?;
    Ok((object, lifecycle))
}

fn encode_ann_creation(
    object: &CatalogObject,
    lifecycle: IncrementalVectorLifecycle,
) -> Result<Vec<u8>, NativeRuntimeError> {
    lifecycle.validate()?;
    let definition = object.encode_definition()?;
    let mut encoded = Vec::with_capacity(20 + definition.len());
    encoded.extend_from_slice(ANN_CREATION_MAGIC);
    encoded.extend_from_slice(&lifecycle.delta_max_entries.to_le_bytes());
    encoded.extend_from_slice(&lifecycle.consolidate_after_deltas.to_le_bytes());
    encoded.extend_from_slice(&lifecycle.retain_generations.to_le_bytes());
    encoded.extend_from_slice(
        &u32::try_from(definition.len())
            .map_err(|_| NativeRuntimeError::InvalidPreparedMutation)?
            .to_le_bytes(),
    );
    encoded.extend_from_slice(&definition);
    Ok(encoded)
}

fn validate_catalog_creation_identity(
    object: &CatalogObject,
    mutation: &Mutation,
) -> Result<(), NativeRuntimeError> {
    if !mutation.key.is_empty() && mutation.key != catalog_name_identity(object.header())? {
        return Err(NativeRuntimeError::InvalidPreparedMutation);
    }
    Ok(())
}

fn catalog_name_identity(header: &ObjectHeader) -> Result<Vec<u8>, CatalogError> {
    catalog_name_identity_from_qualified(&header.name)
}

fn catalog_name_identity_from_qualified(name: &QualifiedName) -> Result<Vec<u8>, CatalogError> {
    let mut encoded = Vec::new();
    for component in [&name.database, &name.schema, &name.object] {
        let lookup = component.lookup().as_bytes();
        let length = u32::try_from(lookup.len()).map_err(|_| CatalogError::NameTooLong)?;
        encoded.extend_from_slice(&length.to_le_bytes());
        encoded.extend_from_slice(lookup);
    }
    Ok(encoded)
}

fn binary_relation_definition(
    id: ObjectId,
    name: &str,
) -> Result<RelationDefinition, CatalogError> {
    let definition = RelationDefinition {
        header: ObjectHeader {
            id,
            owner: EngineKind::Relational,
            name: qualified_name(name)?,
        },
        columns: vec![
            ColumnDefinition {
                id: ColumnId::new(1).map_err(|_| CatalogError::EmptyName)?,
                name: CatalogName::unquoted("primary_key")?,
                logical_type: LogicalType::Binary,
                nullable: false,
            },
            ColumnDefinition {
                id: ColumnId::new(2).map_err(|_| CatalogError::EmptyName)?,
                name: CatalogName::unquoted("row")?,
                logical_type: LogicalType::Binary,
                nullable: false,
            },
        ],
        primary_key: vec![ColumnId::new(1).map_err(|_| CatalogError::EmptyName)?],
        checks: Vec::new(),
        foreign_keys: Vec::new(),
    };
    definition.validate()?;
    Ok(definition)
}

fn text_search_definition(
    id: ObjectId,
    name: &str,
) -> Result<SearchCollectionDefinition, CatalogError> {
    let definition = SearchCollectionDefinition {
        header: ObjectHeader {
            id,
            owner: EngineKind::Search,
            name: qualified_name(name)?,
        },
        fields: vec![SearchFieldDefinition {
            id: FieldId::new(1).map_err(|_| CatalogError::EmptyName)?,
            name: CatalogName::unquoted("text")?,
            logical_type: LogicalType::Text,
            analyzer: None,
            doc_values: false,
        }],
        vector: None,
        ann: None,
    };
    definition.validate()?;
    Ok(definition)
}

fn vector_search_definition(
    id: ObjectId,
    name: &str,
    dimension: u16,
    metric: VectorMetric,
    config: HnswConfig,
) -> Result<SearchCollectionDefinition, CatalogError> {
    let metric = match metric {
        VectorMetric::Cosine => CatalogVectorMetric::Cosine,
        VectorMetric::NegativeDot => CatalogVectorMetric::NegativeDot,
        VectorMetric::SquaredL2 => CatalogVectorMetric::SquaredL2,
    };
    let definition = SearchCollectionDefinition {
        header: ObjectHeader {
            id,
            owner: EngineKind::Search,
            name: qualified_name(name)?,
        },
        fields: Vec::new(),
        vector: Some(VectorType::new(VectorElement::Float32, dimension)?),
        ann: Some(AnnIndexDefinition::new(
            metric,
            config.m(),
            config.ef_construction(),
            config.ef_search_default(),
            config.ef_search_max(),
            config.seed(),
        )?),
    };
    definition.validate()?;
    Ok(definition)
}

fn qualified_name(name: &str) -> Result<QualifiedName, CatalogError> {
    Ok(QualifiedName::new(
        CatalogName::unquoted("main")?,
        CatalogName::unquoted("public")?,
        CatalogName::unquoted(name)?,
    ))
}

