    #[test]
    fn unchanged_roots_reuse_the_decoded_snapshot_state() -> Result<(), Box<dyn std::error::Error>>
    {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let index = ObjectId::new(10)?;
        let mut seed = database.begin(10, DurabilityClass::Memory)?;
        seed.create_search_index(index, "native_search")?;
        seed.index_document(index, b"a".to_vec(), "rust engine".to_owned())?;
        seed.commit()?;

        let first = database.snapshot(11)?;
        // The roots have not changed: the second snapshot must reuse the
        // decoded state without re-materializing the directory.
        super::FAIL_FULL_STATE_LOAD.set(true);
        let second = database.snapshot(12)?;
        super::FAIL_FULL_STATE_LOAD.set(false);
        assert_eq!(first.root_digest(), second.root_digest());
        assert!(Arc::ptr_eq(&first.state, &second.state));
        let pinned = first.match_text(index, "rust", 8)?;
        let reused = second.match_text(index, "rust", 8)?;
        assert_eq!(pinned.len(), reused.len());
        for (left, right) in pinned.iter().zip(&reused) {
            assert_eq!(left.document_id, right.document_id);
            assert_eq!(left.score.to_bits(), right.score.to_bits());
        }

        // A commit changes the roots: the next snapshot misses the cache
        // and decodes the new state fully.
        let mut write = database.begin(13, DurabilityClass::Memory)?;
        write.index_document(index, b"b".to_vec(), "sql engine".to_owned())?;
        write.commit()?;
        let third = database.snapshot(14)?;
        assert_ne!(second.root_digest(), third.root_digest());
        assert!(!Arc::ptr_eq(&second.state, &third.state));
        assert_eq!(third.match_text(index, "sql", 8)?.len(), 1);
        Ok(())
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn native_inverted_index_matches_reference_bm25_across_recovery()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let index = ObjectId::new(10)?;
        let mut seed = database.begin(10, DurabilityClass::Memory)?;
        seed.create_search_index(index, "native_search")?;
        for document in 0..512_u32 {
            let text = if document % 2 == 0 {
                format!("rust engine common document{document}")
            } else {
                format!("sql engine common document{document}")
            };
            seed.index_document(index, document.to_be_bytes().to_vec(), text)?;
        }
        seed.commit()?;
        assert!(database.latest_search_tree_height()? >= 2);

        let historical = database.snapshot(11)?;
        for query in ["rust", "sql engine", "common", "missing"] {
            assert_eq!(
                database.match_latest_text(index, query, 25)?,
                historical.match_text(index, query, 25)?
            );
            // The pinned-snapshot posting scorer must be bit-identical to
            // the retained model at the same roots.
            let pinned = database.match_text_at_snapshot(
                &historical,
                index,
                query,
                25,
                super::Bm25ScoreParameters::default(),
            )?;
            let model = historical.match_text(index, query, 25)?;
            assert_eq!(pinned.len(), model.len());
            for (durable, reference) in pinned.iter().zip(&model) {
                assert_eq!(durable.document_id, reference.document_id);
                assert_eq!(durable.score.to_bits(), reference.score.to_bits());
            }
            // Tuned parameters must stay bit-identical between the pinned
            // posting scorer and the retained model as well.
            let tuned = super::Bm25ScoreParameters {
                k1_micros: 900_000,
                b_micros: 0,
            };
            let pinned_tuned =
                database.match_text_at_snapshot(&historical, index, query, 25, tuned)?;
            let model_tuned = historical.match_text_with_parameters(index, query, 25, tuned)?;
            assert_eq!(pinned_tuned.len(), model_tuned.len());
            for (durable, reference) in pinned_tuned.iter().zip(&model_tuned) {
                assert_eq!(durable.document_id, reference.document_id);
                assert_eq!(durable.score.to_bits(), reference.score.to_bits());
            }
        }

        let serial_segmented =
            database.match_latest_text_profiled(index, "rust engine common", 128)?;
        assert_eq!(
            serial_segmented.hits,
            historical.match_text(index, "rust engine common", 128)?
        );
        assert_eq!(serial_segmented.snapshot_csn, Some(Csn::new(1)?));
        assert_eq!(serial_segmented.planned_terms, 3);
        assert!(serial_segmented.planned_segments > 1);
        assert!(serial_segmented.planned_physical_entries >= 512 * 2);
        assert_eq!(serial_segmented.planned_workers, 1);
        assert_eq!(serial_segmented.worker_batches, 0);

        let policy = parallel_engine_admission_test_policy();
        let profile = portable_execution_profile(&policy);
        let governor = Arc::new(NativeResourceGovernor::new(policy.clone()));
        let execution_pool = Arc::new(NativeExecutionPool::new(&profile, &policy)?);
        database.set_resource_governor_with_execution_pool(
            Arc::clone(&governor),
            execution_pool,
            Duration::ZERO,
        )?;
        let parallel_segmented =
            database.match_latest_text_profiled(index, "rust engine common", 128)?;
        assert_eq!(parallel_segmented.hits, serial_segmented.hits);
        assert_eq!(
            parallel_segmented.planned_segments,
            serial_segmented.planned_segments
        );
        assert!(parallel_segmented.planning.is_some());
        let execution = parallel_segmented
            .execution
            .ok_or_else(|| std::io::Error::other("missing lexical execution admission"))?;
        assert_eq!(
            execution.request.compute_threads,
            parallel_segmented.planned_workers
        );
        assert_eq!(
            execution.request.io_slots,
            parallel_segmented.planned_workers
        );
        assert_eq!(
            u64::try_from(parallel_segmented.worker_batches)?,
            parallel_segmented.planned_workers
        );
        assert_eq!(governor.usage_snapshot().compute_threads, 0);
        assert_eq!(governor.usage_snapshot().io_slots, 0);
        database.clear_resource_governor()?;

        let mut later = database.begin(12, DurabilityClass::Strict)?;
        later.index_document(
            index,
            b"exclusive-document".to_vec(),
            "exclusive exclusive rust",
        )?;
        later.commit()?;
        assert!(historical.match_text(index, "exclusive", 10)?.is_empty());
        assert_eq!(
            database.match_latest_text(index, "exclusive", 10)?[0].document_id,
            b"exclusive-document"
        );
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        assert_eq!(reopened.recovery_report().committed_transactions, 2);
        assert!(reopened.latest_search_tree_height()? >= 2);
        assert_eq!(
            reopened.match_latest_text(index, "exclusive", 10)?[0].document_id,
            b"exclusive-document"
        );
        assert_eq!(
            reopened.match_latest_text(index, "rust engine", 25)?,
            reopened
                .snapshot(13)?
                .match_text(index, "rust engine", 25)?
        );
        Ok(())
    }

    #[test]
    fn search_metadata_mismatch_fails_complete_state_validation()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let index = ObjectId::new(13)?;
        let mut seed = database.begin(10, DurabilityClass::Strict)?;
        seed.create_search_index(index, "corruption_probe")?;
        seed.index_document(index, b"doc".to_vec(), "rust search")?;
        seed.commit()?;

        let root_set = database.coordinator.snapshot(11)?.roots().clone();
        let root = root_set
            .root(super::SLOT_SEARCH)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let bad_tree = hyphae_native_btree::BTree::from_root(root)
            .upsert(
                &mut database.pages,
                Csn::new(1)?,
                super::search_index_meta_key(index),
                super::encode_search_index_metadata(2, 2),
            )?
            .tree;
        let mut roots = root_set
            .iter_roots()
            .collect::<std::collections::BTreeMap<_, _>>();
        roots.insert(
            super::SLOT_SEARCH,
            bad_tree
                .root()
                .ok_or(NativeRuntimeError::InvalidSearchTree)?,
        );
        let forged = hyphae_native_mvcc::RootSet::committed(
            root_set
                .visible_csn()
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?,
            root_set.catalog_version(),
            root_set
                .wal_anchor()
                .ok_or(NativeRuntimeError::InvalidCommittedRoot)?,
            roots,
            root_set.blob_generation(),
        )?;
        assert!(matches!(
            super::load_search_state(&database.pages, &database.blobs, &forged),
            Err(NativeRuntimeError::InvalidSearchTree)
        ));
        Ok(())
    }

