    #[test]
    fn delta_internal_materialized_guards_fail_closed_without_changing_the_batch()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let database = NativeDatabase::create(temporary.path())?;
        let mut delta = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        let initial_state = delta.inner.state.clone();
        let initial_dirty = delta.inner.dirty;
        let initial_retained_memory = delta
            .inner
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .retained_memory_bytes;

        assert!(matches!(
            delta
                .inner
                .execute_sql("CREATE TABLE forbidden (id BIGINT PRIMARY KEY)", &[]),
            Err(SqlError::Runtime(
                NativeRuntimeError::InvalidPreparedMutation
            ))
        ));
        assert!(matches!(
            delta.inner.create_hash(b"forbidden-hash".to_vec()),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.expire_hash(b"forbidden-hash".to_vec(), 100),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.hset(
                b"forbidden-hash".to_vec(),
                b"field".to_vec(),
                b"value".to_vec(),
            ),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta
                .inner
                .create_search_index(ObjectId::new(101)?, "forbidden_search"),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.create_vector_index(
                ObjectId::new(102)?,
                "forbidden_vectors",
                2,
                VectorMetric::SquaredL2,
                ann_config()?,
            ),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.upsert_vector(
                ObjectId::new(102)?,
                ObjectId::new(1)?,
                Vector::new([1.0, 0.0])?,
            ),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta
                .inner
                .delete_vector(ObjectId::new(102)?, ObjectId::new(1)?),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));

        assert_eq!(delta.inner.state, initial_state);
        assert_eq!(delta.inner.dirty, initial_dirty);
        assert_eq!(delta.mutation_count(), 0);
        assert_eq!(
            delta
                .inner
                .delta
                .as_ref()
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
                .retained_memory_bytes,
            initial_retained_memory
        );
        Ok(())
    }

    #[test]
    fn delta_whole_hash_ttl_is_exact_and_survives_field_writes()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"leased".to_vec())?;
        seed.hset(b"leased".to_vec(), b"counter".to_vec(), b"40".to_vec())?;
        assert!(seed.expire_hash(b"leased".to_vec(), 100)?);
        seed.create_hash(b"persistent".to_vec())?;
        seed.create_hash(b"due".to_vec())?;
        assert!(seed.expire_hash(b"due".to_vec(), 10)?);
        seed.set(b"scalar".to_vec(), b"value".to_vec(), None)?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        let _full_load_guard = FullLoadFailureGuard::install();
        let mut delta = database.begin_optimistic_delta(10, DurabilityClass::Memory)?;
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"leased")?,
            super::Ttl::RemainingMicros(90)
        );
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"persistent")?,
            super::Ttl::Persistent
        );
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"due")?,
            super::Ttl::Missing
        );
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"missing")?,
            super::Ttl::Missing
        );
        assert!(matches!(
            database.delta_ttl_hash(&mut delta, b"scalar"),
            Err(NativeRuntimeError::StructureKindMismatch)
        ));
        database.stage_delta_hset(
            &mut delta,
            b"leased".to_vec(),
            b"field".to_vec(),
            b"value".to_vec(),
        )?;
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"leased")?,
            super::Ttl::RemainingMicros(90)
        );
        assert_eq!(
            database.stage_delta_hincrement(
                &mut delta,
                b"leased".to_vec(),
                b"counter".to_vec(),
                2,
            )?,
            42
        );
        assert_eq!(
            database.delta_ttl_hash(&mut delta, b"leased")?,
            super::Ttl::RemainingMicros(90)
        );
        Ok(())
    }

    #[test]
    fn delta_all_engine_hot_path_does_not_materialize_complete_engine_state()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let index = ObjectId::new(100)?;
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.execute_sql(
            "CREATE TABLE events (
                id BIGINT PRIMARY KEY,
                body TEXT NOT NULL
            )",
            &[],
        )?;
        seed.execute_sql("INSERT INTO events (id, body) VALUES (1, 'seed')", &[])?;
        seed.set(b"joint-key".to_vec(), b"seed".to_vec(), None)?;
        seed.create_search_index(index, "documents")?;
        for sequence in 1_000_u128..1_256 {
            seed.create_relation(
                ObjectId::new(sequence)?,
                &format!("unrelated_relation_{sequence}"),
            )?;
        }
        seed.commit()?;

        let physical_before = database.physical_observation()?;
        super::FAIL_FULL_STATE_LOAD.set(true);
        super::FAIL_FULL_CATALOG_STATE_LOAD.set(true);
        let delta_commit = (|| -> Result<_, Box<dyn std::error::Error>> {
            let mut delta = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
            database.stage_delta_sql_dml(
                &mut delta,
                "UPDATE events SET body = ? WHERE id = ?",
                &[SqlValue::Text("delta".to_owned()), SqlValue::Signed(1)],
            )?;
            database.stage_delta_set(&mut delta, b"joint-key".to_vec(), b"delta".to_vec(), None)?;
            database.stage_delta_index_document(
                &mut delta,
                index,
                b"doc-1".to_vec(),
                "delta native".to_owned(),
            )?;
            Ok(database.commit_optimistic(delta)?)
        })();
        super::FAIL_FULL_STATE_LOAD.set(false);
        super::FAIL_FULL_CATALOG_STATE_LOAD.set(false);
        let committed = delta_commit?;
        let physical_after = database.physical_observation()?;

        assert_eq!(
            database.snapshot(2)?.visible_csn(),
            Some(committed.commit_csn)
        );
        assert!(physical_after.physical_page_reads > physical_before.physical_page_reads);
        assert!(physical_after.page_count > physical_before.page_count);
        assert!(physical_after.wal_bytes > physical_before.wal_bytes);
        assert_eq!(
            database.get_latest_structure(b"joint-key", 2)?,
            Some(b"delta".to_vec())
        );
        Ok(())
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn delta_all_engine_v3_reuses_expired_collections_without_materialization()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let index = ObjectId::new(100)?;
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.execute_sql(
            "CREATE TABLE events (
                id BIGINT PRIMARY KEY,
                body TEXT NOT NULL
            )",
            &[],
        )?;
        seed.execute_sql("INSERT INTO events (id, body) VALUES (1, 'seed')", &[])?;
        seed.set(b"existing-scalar".to_vec(), b"seed".to_vec(), None)?;
        seed.create_hash(b"expired-hash".to_vec())?;
        assert!(seed.expire_hash(b"expired-hash".to_vec(), 10)?);
        seed.create_set(b"expired-set".to_vec())?;
        assert!(seed.expire_set(b"expired-set".to_vec(), 10)?);
        seed.create_list(b"expired-list".to_vec())?;
        assert!(seed.expire_list(b"expired-list".to_vec(), 10)?);
        seed.create_stream(b"expired-stream".to_vec())?;
        assert!(seed.expire_stream(b"expired-stream".to_vec(), 10)?);
        seed.create_sorted_set(b"expired-sorted".to_vec())?;
        assert!(seed.expire_sorted_set(b"expired-sorted".to_vec(), 10)?);
        seed.create_hash(b"live-hash".to_vec())?;
        seed.create_set(b"live-set".to_vec())?;
        seed.create_list(b"live-list".to_vec())?;
        seed.create_stream(b"live-stream".to_vec())?;
        seed.create_sorted_set(b"live-sorted".to_vec())?;
        seed.create_search_index(index, "documents")?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        super::FAIL_FULL_STATE_LOAD.set(true);
        super::FAIL_FULL_STRUCTURE_STATE_LOAD.set(true);
        super::FAIL_FULL_CATALOG_STATE_LOAD.set(true);
        let delta_commit = (|| -> Result<_, Box<dyn std::error::Error>> {
            let mut rejected = database.begin_optimistic_delta(10, DurabilityClass::Memory)?;
            for key in [
                b"live-hash".as_slice(),
                b"live-set".as_slice(),
                b"live-list".as_slice(),
                b"live-stream".as_slice(),
                b"live-sorted".as_slice(),
            ] {
                assert!(matches!(
                    database.stage_delta_set(
                        &mut rejected,
                        key.to_vec(),
                        b"wrong-kind".to_vec(),
                        None,
                    ),
                    Err(NativeRuntimeError::StructureKindMismatch)
                ));
            }
            assert_eq!(rejected.mutation_count(), 0);

            let mut delta = database.begin_optimistic_delta(10, DurabilityClass::Strict)?;
            database.stage_delta_sql_dml(
                &mut delta,
                "UPDATE events SET body = ? WHERE id = ?",
                &[SqlValue::Text("v3".to_owned()), SqlValue::Signed(1)],
            )?;
            for key in [
                b"missing".as_slice(),
                b"existing-scalar".as_slice(),
                b"expired-hash".as_slice(),
                b"expired-set".as_slice(),
                b"expired-list".as_slice(),
                b"expired-stream".as_slice(),
                b"expired-sorted".as_slice(),
            ] {
                database.stage_delta_set(
                    &mut delta,
                    key.to_vec(),
                    [b"v3-".as_slice(), key].concat(),
                    None,
                )?;
            }
            database.stage_delta_index_document(
                &mut delta,
                index,
                b"doc-1".to_vec(),
                "native v3 delta".to_owned(),
            )?;
            Ok(database.commit_optimistic(delta)?)
        })();
        super::FAIL_FULL_STATE_LOAD.set(false);
        super::FAIL_FULL_STRUCTURE_STATE_LOAD.set(false);
        super::FAIL_FULL_CATALOG_STATE_LOAD.set(false);
        let committed = delta_commit?;
        assert!(committed.commit_csn.get() > 0);

        drop(database);
        let database = NativeDatabase::open(temporary.path())?;
        for key in [
            b"missing".as_slice(),
            b"existing-scalar".as_slice(),
            b"expired-hash".as_slice(),
            b"expired-set".as_slice(),
            b"expired-list".as_slice(),
            b"expired-stream".as_slice(),
            b"expired-sorted".as_slice(),
        ] {
            assert_eq!(
                database.get_latest_structure(key, 10)?,
                Some([b"v3-".as_slice(), key].concat())
            );
        }
        assert_eq!(database.hlen_latest_hash(b"live-hash")?, 0);
        assert_eq!(database.match_latest_text(index, "native", 10)?.len(), 1);
        Ok(())
    }

    #[test]
    fn delta_hash_v3_stays_point_resolved_through_commit_read_and_reopen()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"profile".to_vec())?;
        seed.hset(b"profile".to_vec(), b"counter".to_vec(), b"40".to_vec())?;
        seed.hset(b"profile".to_vec(), b"old".to_vec(), b"old".to_vec())?;
        seed.hset(b"profile".to_vec(), b"due".to_vec(), b"stale".to_vec())?;
        seed.hset(
            b"profile".to_vec(),
            b"blob".to_vec(),
            vec![0x41; super::STRUCTURE_INLINE_VALUE_LIMIT + 1],
        )?;
        assert!(seed.expire_hash_field(b"profile".to_vec(), b"due".to_vec(), 10)?);
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        let full_load_guard = FullLoadFailureGuard::install();
        let mut delta = database.begin_optimistic_delta(10, DurabilityClass::Strict)?;
        assert_eq!(
            database.stage_delta_hset(
                &mut delta,
                b"profile".to_vec(),
                b"old".to_vec(),
                b"new".to_vec(),
            )?,
            HashSetOutcome::Updated
        );
        assert_eq!(
            database.stage_delta_hset(
                &mut delta,
                b"profile".to_vec(),
                b"due".to_vec(),
                b"revived".to_vec(),
            )?,
            HashSetOutcome::Added
        );
        assert!(database.stage_delta_hdelete(&mut delta, b"profile".to_vec(), b"blob".to_vec(),)?);
        assert_eq!(
            database.stage_delta_hincrement(
                &mut delta,
                b"profile".to_vec(),
                b"counter".to_vec(),
                2,
            )?,
            42
        );
        assert_eq!(
            database.stage_delta_hincrement(
                &mut delta,
                b"profile".to_vec(),
                b"counter".to_vec(),
                1,
            )?,
            43
        );
        database.commit_optimistic(delta)?;
        assert_eq!(
            database.hget_latest_hash_at(b"profile", b"old", 10)?,
            Some(b"new".to_vec())
        );
        assert_eq!(
            database.hget_latest_hash_at(b"profile", b"due", 10)?,
            Some(b"revived".to_vec())
        );
        assert_eq!(
            database.hget_latest_hash_at(b"profile", b"counter", 10)?,
            Some(b"43".to_vec())
        );
        assert_eq!(database.hget_latest_hash_at(b"profile", b"blob", 10)?, None);
        // Open deliberately performs complete semantic recovery validation;
        // only the reopened point read belongs to this lazy-delta contract.
        drop(full_load_guard);
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        let _reopened_read_guard = FullLoadFailureGuard::install();
        assert_eq!(
            reopened.hget_latest_hash_at(b"profile", b"counter", 10)?,
            Some(b"43".to_vec())
        );
        assert_eq!(reopened.hget_latest_hash_at(b"profile", b"blob", 10)?, None);
        Ok(())
    }

    #[derive(Debug, Eq, PartialEq)]
    struct HashDeltaAccountingSnapshot {
        mutation_count: usize,
        dirty: [bool; 4],
        overlay_count: usize,
        hash_memory: u64,
        retained_memory: u64,
    }

    fn hash_delta_accounting_snapshot(
        batch: &NativeDeltaWriteBatch,
    ) -> Result<HashDeltaAccountingSnapshot, NativeRuntimeError> {
        let delta = batch
            .inner
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        Ok(HashDeltaAccountingSnapshot {
            mutation_count: batch.mutation_count(),
            dirty: batch.inner.dirty,
            overlay_count: delta.structure_hash_fields.len(),
            hash_memory: delta.structure_hash_memory_bytes,
            retained_memory: delta.retained_memory_bytes,
        })
    }

    fn assert_rejected_hash_stage_preserved_accounting(
        batch: &NativeDeltaWriteBatch,
        before: &HashDeltaAccountingSnapshot,
        rejected_identity: &(Vec<u8>, Vec<u8>),
    ) -> Result<(), NativeRuntimeError> {
        assert_eq!(&hash_delta_accounting_snapshot(batch)?, before);
        let delta = batch
            .inner
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        assert!(!delta.structure_hash_fields.contains_key(rejected_identity));
        Ok(())
    }

    fn assert_oversized_hash_value_operations(
        database: &NativeDatabase,
    ) -> Result<(), NativeRuntimeError> {
        let mut increment = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        assert!(matches!(
            database.stage_delta_hincrement(
                &mut increment,
                b"budget".to_vec(),
                b"oversized-old".to_vec(),
                1,
            ),
            Err(NativeRuntimeError::ResourceAdmission(
                GovernorAdmissionError::ParentCapacity
            ))
        ));
        assert_eq!(increment.mutation_count(), 0);
        let mut replace = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        assert_eq!(
            database.stage_delta_hset(
                &mut replace,
                b"budget".to_vec(),
                b"oversized-old".to_vec(),
                b"small".to_vec(),
            )?,
            HashSetOutcome::Updated
        );
        let mut remove = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        assert!(database.stage_delta_hdelete(
            &mut remove,
            b"budget".to_vec(),
            b"oversized-old".to_vec(),
        )?);
        Ok(())
    }

    #[test]
    fn delta_hash_value_budget_is_fail_closed_before_publication()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"budget".to_vec())?;
        seed.hset(
            b"budget".to_vec(),
            b"oversized-old".to_vec(),
            vec![b'1'; usize::try_from(super::DELTA_HASH_MEMORY_BUDGET)? + 1],
        )?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;
        let physical_before = database.physical_observation()?;
        assert_oversized_hash_value_operations(&database)?;

        let mut delta = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        assert_eq!(
            database.delta_hget(&mut delta, b"budget", b"maximum")?,
            None
        );
        let mutation_key = super::hash_field_identity(b"budget", b"maximum")?;
        let retained_before_value = delta
            .inner
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_hash_memory_bytes
            .checked_add(super::DELTA_HASH_MUTATION_OVERHEAD)
            .and_then(|bytes| bytes.checked_add(u64::try_from(mutation_key.capacity()).ok()?))
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?;
        let maximum_value_bytes = usize::try_from(
            super::DELTA_HASH_MEMORY_BUDGET
                .checked_sub(retained_before_value)
                .ok_or(NativeRuntimeError::InvalidPreparedMutation)?,
        )?;
        assert_eq!(
            database.stage_delta_hset(
                &mut delta,
                b"budget".to_vec(),
                b"maximum".to_vec(),
                vec![0; maximum_value_bytes],
            )?,
            HashSetOutcome::Added
        );
        let accounting_before = hash_delta_accounting_snapshot(&delta)?;
        let rejected_identity = (b"budget".to_vec(), b"overflow".to_vec());
        assert!(matches!(
            database.stage_delta_hset(
                &mut delta,
                b"budget".to_vec(),
                b"overflow".to_vec(),
                vec![0],
            ),
            Err(NativeRuntimeError::ResourceAdmission(
                GovernorAdmissionError::ParentCapacity
            ))
        ));
        assert_rejected_hash_stage_preserved_accounting(
            &delta,
            &accounting_before,
            &rejected_identity,
        )?;
        let physical_after = database.physical_observation()?;
        assert_eq!(physical_after.page_count, physical_before.page_count);
        assert_eq!(physical_after.wal_bytes, physical_before.wal_bytes);
        assert_eq!(database.hget_latest_hash(b"budget", b"maximum")?, None);

        let mut spare_capacity = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        let mut tiny = Vec::with_capacity(maximum_value_bytes);
        tiny.push(7);
        database.stage_delta_hset(
            &mut spare_capacity,
            b"budget".to_vec(),
            b"canonical".to_vec(),
            tiny,
        )?;
        assert_eq!(spare_capacity.inner.mutations[0].value, vec![7]);
        assert_eq!(spare_capacity.inner.mutations[0].value.capacity(), 1);
        Ok(())
    }

    #[test]
    fn delta_hash_missing_field_identities_are_bounded_before_retention()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"identity-budget".to_vec())?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;
        let physical_before = database.physical_observation()?;

        let mut delta = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        let mut accepted = 0_u64;
        loop {
            let mut field = vec![b'x'; hyphae_native_btree::BTREE_MAX_KEY_SIZE - 512];
            field[..8].copy_from_slice(&accepted.to_be_bytes());
            match database.delta_hget(&mut delta, b"identity-budget", &field) {
                Ok(None) => accepted += 1,
                Err(NativeRuntimeError::ResourceAdmission(
                    GovernorAdmissionError::ParentCapacity,
                )) => break,
                Ok(Some(_)) => return Err("missing field unexpectedly resolved a value".into()),
                Err(error) => return Err(error.into()),
            }
        }
        assert!(accepted > 1);
        assert_eq!(delta.mutation_count(), 0);
        let retained = delta
            .inner
            .delta
            .as_ref()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_hash_memory_bytes;
        assert!(retained <= super::DELTA_HASH_MEMORY_BUDGET);
        let physical_after = database.physical_observation()?;
        assert_eq!(physical_after.page_count, physical_before.page_count);
        assert_eq!(physical_after.wal_bytes, physical_before.wal_bytes);
        Ok(())
    }

    #[test]
    fn delta_hash_read_your_writes_and_internal_materialized_read_guards_are_exact()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"ryw".to_vec())?;
        seed.hset(b"ryw".to_vec(), b"counter".to_vec(), b"40".to_vec())?;
        seed.hset(b"ryw".to_vec(), b"due".to_vec(), b"stale".to_vec())?;
        seed.hset(
            b"ryw".to_vec(),
            b"blob".to_vec(),
            vec![0x41; super::STRUCTURE_INLINE_VALUE_LIMIT + 1],
        )?;
        assert!(seed.expire_hash_field(b"ryw".to_vec(), b"due".to_vec(), 10)?);
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        let _full_load_guard = FullLoadFailureGuard::install();
        let mut delta = database.begin_optimistic_delta(10, DurabilityClass::Memory)?;
        assert_eq!(database.delta_hget(&mut delta, b"ryw", b"due")?, None);
        assert_eq!(
            database.delta_ttl_hash_field(&mut delta, b"ryw", b"due")?,
            super::Ttl::Missing
        );
        assert_eq!(
            database.stage_delta_hset(
                &mut delta,
                b"ryw".to_vec(),
                b"due".to_vec(),
                b"revived".to_vec(),
            )?,
            HashSetOutcome::Added
        );
        assert_eq!(
            database.delta_hget(&mut delta, b"ryw", b"due")?,
            Some(b"revived".to_vec())
        );
        assert_eq!(
            database.delta_ttl_hash_field(&mut delta, b"ryw", b"due")?,
            super::Ttl::Persistent
        );
        assert_eq!(
            database.delta_hget(&mut delta, b"ryw", b"blob")?,
            Some(vec![0x41; super::STRUCTURE_INLINE_VALUE_LIMIT + 1])
        );
        assert_eq!(
            database.stage_delta_hincrement(&mut delta, b"ryw".to_vec(), b"counter".to_vec(), 2,)?,
            42
        );
        assert_eq!(
            database.stage_delta_hincrement(&mut delta, b"ryw".to_vec(), b"counter".to_vec(), 1,)?,
            43
        );
        assert_eq!(
            database.delta_hget(&mut delta, b"ryw", b"counter")?,
            Some(b"43".to_vec())
        );
        assert_eq!(
            database.delta_ttl_hash_field(&mut delta, b"ryw", b"counter")?,
            super::Ttl::Persistent
        );
        assert!(database.stage_delta_hdelete(&mut delta, b"ryw".to_vec(), b"counter".to_vec(),)?);
        assert_eq!(database.delta_hget(&mut delta, b"ryw", b"counter")?, None);
        assert_eq!(
            database.delta_ttl_hash_field(&mut delta, b"ryw", b"counter")?,
            super::Ttl::Missing
        );
        assert!(matches!(
            delta.inner.hget(b"ryw", b"blob"),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.hget_many(b"ryw", &[b"blob".to_vec()]),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.hlen(b"ryw"),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.hscan(b"ryw", None, 1),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert!(matches!(
            delta.inner.hscan_reverse(b"ryw", None, 1),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        Ok(())
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn delta_hash_v3_shape_rejects_unhydrated_or_malformed_field_mutations()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"shape".to_vec())?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        let mut unhydrated = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        database.stage_delta_hset(
            &mut unhydrated,
            b"shape".to_vec(),
            b"hydrated".to_vec(),
            b"value".to_vec(),
        )?;
        unhydrated.inner.mutations[0].key = super::hash_field_identity(b"shape", b"forged")?;
        let before_unhydrated = database.physical_observation()?;
        assert!(matches!(
            database.commit_optimistic(unhydrated),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert_local_storage_unchanged(before_unhydrated, database.physical_observation()?);

        let mut malformed = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        assert!(!database.stage_delta_hdelete(
            &mut malformed,
            b"shape".to_vec(),
            b"missing".to_vec(),
        )?);
        database.stage_delta_hset(
            &mut malformed,
            b"shape".to_vec(),
            b"missing".to_vec(),
            b"value".to_vec(),
        )?;
        malformed.inner.mutations[0].opcode = Opcode::DeleteHashField;
        let before_malformed = database.physical_observation()?;
        let malformed_error = database
            .commit_optimistic(malformed)
            .err()
            .ok_or("malformed hash mutation unexpectedly committed")?;
        assert!(
            matches!(malformed_error, NativeRuntimeError::InvalidPreparedMutation),
            "unexpected malformed shape error: {malformed_error:?}"
        );
        assert_local_storage_unchanged(before_malformed, database.physical_observation()?);

        let mut forged_index = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        database.stage_delta_hset(
            &mut forged_index,
            b"shape".to_vec(),
            b"index".to_vec(),
            b"value".to_vec(),
        )?;
        forged_index
            .inner
            .delta
            .as_mut()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_hash_fields
            .insert(
                (b"shape".to_vec(), b"index".to_vec()),
                super::DeltaHashFieldOverlay::Staged(usize::MAX),
            );
        let before_index = database.physical_observation()?;
        let index_error = database
            .commit_optimistic_resolved(forged_index, [5; 32], [6; 32])
            .err()
            .ok_or("forged staged index unexpectedly committed")?;
        assert_eq!(index_error.resolution(), None);
        assert!(matches!(
            index_error.source(),
            NativeRuntimeError::InvalidPreparedMutation
        ));
        assert_local_storage_unchanged(before_index, database.physical_observation()?);

        let mut forged_accounting = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        database.stage_delta_hset(
            &mut forged_accounting,
            b"shape".to_vec(),
            b"accounting".to_vec(),
            vec![0x41; super::STRUCTURE_INLINE_VALUE_LIMIT + 1],
        )?;
        forged_accounting
            .inner
            .delta
            .as_mut()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .structure_hash_memory_bytes += 1;
        let before_accounting = database.physical_observation()?;
        let accounting_error = database
            .commit_optimistic_resolved(forged_accounting, [7; 32], [8; 32])
            .err()
            .ok_or("forged accounting unexpectedly committed")?;
        assert_eq!(accounting_error.resolution(), None);
        assert!(matches!(
            accounting_error.source(),
            NativeRuntimeError::InvalidPreparedMutation
        ));
        assert_local_storage_unchanged(before_accounting, database.physical_observation()?);

        let mut forged_total = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        database.stage_delta_set(
            &mut forged_total,
            b"ledger".to_vec(),
            b"value".to_vec(),
            None,
        )?;
        forged_total
            .inner
            .delta
            .as_mut()
            .ok_or(NativeRuntimeError::InvalidPreparedMutation)?
            .retained_memory_bytes += 1;
        let before_total = database.physical_observation()?;
        let total_error = database
            .commit_optimistic_resolved(forged_total, [9; 32], [10; 32])
            .err()
            .ok_or("forged total memory ledger unexpectedly committed")?;
        assert_eq!(total_error.resolution(), None);
        assert!(matches!(
            total_error.source(),
            NativeRuntimeError::InvalidPreparedMutation
        ));
        assert_local_storage_unchanged(before_total, database.physical_observation()?);
        Ok(())
    }

    fn assert_local_storage_unchanged(
        before: super::NativePhysicalObservation,
        after: super::NativePhysicalObservation,
    ) {
        assert_eq!(after.page_count, before.page_count);
        assert_eq!(after.physical_page_reads, before.physical_page_reads);
        assert_eq!(after.wal_bytes, before.wal_bytes);
    }

    #[test]
    fn delta_batches_are_bound_to_their_origin_directory_before_reads_or_wal()
    -> Result<(), Box<dyn std::error::Error>> {
        let first_directory = TestDirectory::new();
        let second_directory = TestDirectory::new();
        let mut first = NativeDatabase::create(first_directory.path())?;
        let mut second = NativeDatabase::create(second_directory.path())?;
        for database in [&mut first, &mut second] {
            let mut seed = database.begin(1, DurabilityClass::Strict)?;
            seed.create_hash(b"authority".to_vec())?;
            seed.commit()?;
            database.migrate_structure_to_v3(DurabilityClass::Strict)?;
        }

        let mut staged_by_first = first.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        let second_before_stage = second.physical_observation()?;
        assert!(matches!(
            second.stage_delta_hset(
                &mut staged_by_first,
                b"authority".to_vec(),
                b"field".to_vec(),
                b"wrong".to_vec(),
            ),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert_eq!(staged_by_first.mutation_count(), 0);
        assert!(
            staged_by_first
                .inner
                .delta
                .as_ref()
                .is_some_and(|delta| delta.structure_hash_fields.is_empty())
        );
        assert_local_storage_unchanged(second_before_stage, second.physical_observation()?);
        first.stage_delta_hset(
            &mut staged_by_first,
            b"authority".to_vec(),
            b"field".to_vec(),
            b"right".to_vec(),
        )?;
        first.commit_optimistic(staged_by_first)?;

        let mut resolved_by_first = first.begin_optimistic_delta(3, DurabilityClass::Memory)?;
        first.stage_delta_hset(
            &mut resolved_by_first,
            b"authority".to_vec(),
            b"resolved".to_vec(),
            b"value".to_vec(),
        )?;
        let second_before_resolved = second.physical_observation()?;
        let resolved_error = second
            .commit_optimistic_resolved(resolved_by_first, [1; 32], [2; 32])
            .err()
            .ok_or("foreign resolved batch unexpectedly committed")?;
        assert_eq!(resolved_error.resolution(), None);
        assert!(matches!(
            resolved_error.source(),
            NativeRuntimeError::InvalidPreparedMutation
        ));
        assert_local_storage_unchanged(second_before_resolved, second.physical_observation()?);

        let mut grouped_by_first = first.begin_optimistic_delta(3, DurabilityClass::Memory)?;
        first.stage_delta_hset(
            &mut grouped_by_first,
            b"authority".to_vec(),
            b"grouped".to_vec(),
            b"value".to_vec(),
        )?;
        let second_before_group = second.physical_observation()?;
        assert!(matches!(
            second.commit_group(vec![grouped_by_first]),
            Err(NativeRuntimeError::InvalidPreparedMutation)
        ));
        assert_local_storage_unchanged(second_before_group, second.physical_observation()?);

        let mut malformed = second.begin_optimistic_delta(3, DurabilityClass::Memory)?;
        second.stage_delta_hset(
            &mut malformed,
            b"authority".to_vec(),
            b"format".to_vec(),
            b"value".to_vec(),
        )?;
        malformed.inner.structure_format = super::StructureFormat::BTreeV2;
        let second_before_format = second.physical_observation()?;
        let format_error = second
            .commit_optimistic_resolved(malformed, [3; 32], [4; 32])
            .err()
            .ok_or("malformed resolved batch unexpectedly committed")?;
        assert_eq!(format_error.resolution(), None);
        assert!(matches!(
            format_error.source(),
            NativeRuntimeError::InvalidPreparedMutation
        ));
        assert_local_storage_unchanged(second_before_format, second.physical_observation()?);
        Ok(())
    }

    #[test]
    fn delta_v3_scalar_conflicts_with_an_intervening_writer()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.set(b"shared".to_vec(), b"seed".to_vec(), None)?;
        seed.commit()?;
        database.migrate_structure_to_v3(DurabilityClass::Strict)?;

        let mut stale = database.begin_optimistic_delta(2, DurabilityClass::Memory)?;
        database.stage_delta_set(&mut stale, b"shared".to_vec(), b"stale".to_vec(), None)?;
        let mut winner = database.begin(2, DurabilityClass::Memory)?;
        winner.set(b"shared".to_vec(), b"winner".to_vec(), None)?;
        winner.commit()?;

        assert!(matches!(
            database.commit_optimistic(stale),
            Err(NativeRuntimeError::WriteConflict(_))
        ));
        assert_eq!(
            database.get_latest_structure(b"shared", 2)?,
            Some(b"winner".to_vec())
        );
        Ok(())
    }

    #[test]
    fn every_delta_v3_commit_boundary_recovers_prior_or_complete_state()
    -> Result<(), Box<dyn std::error::Error>> {
        for boundary in commit_crash_boundaries() {
            let temporary = TestDirectory::new();
            let mut database = NativeDatabase::create(temporary.path())?;
            let mut seed = database.begin(1, DurabilityClass::Strict)?;
            seed.set(b"shared".to_vec(), b"seed".to_vec(), None)?;
            seed.commit()?;
            database.migrate_structure_to_v3(DurabilityClass::Strict)?;

            super::FAIL_FULL_STATE_LOAD.set(true);
            super::FAIL_FULL_STRUCTURE_STATE_LOAD.set(true);
            let interrupted = (|| -> Result<_, NativeRuntimeError> {
                let mut delta = database.begin_optimistic_delta(2, DurabilityClass::Strict)?;
                database.stage_delta_set(
                    &mut delta,
                    b"shared".to_vec(),
                    b"delta".to_vec(),
                    None,
                )?;
                database.commit_optimistic_with_interruption(delta, boundary)
            })();
            super::FAIL_FULL_STATE_LOAD.set(false);
            super::FAIL_FULL_STRUCTURE_STATE_LOAD.set(false);
            assert!(matches!(
                interrupted,
                Err(NativeRuntimeError::InjectedCrash(found)) if found == boundary
            ));
            drop(database);

            let reopened = NativeDatabase::open(temporary.path())?;
            let recovered = reopened
                .get_latest_structure(b"shared", 2)?
                .ok_or("delta V3 crash recovery lost the scalar")?;
            if recovered != b"seed" && recovered != b"delta" {
                return Err(
                    format!("partial delta V3 state at {boundary:?}: {recovered:?}").into(),
                );
            }
        }
        Ok(())
    }

    #[test]
    fn delta_latest_update_reads_only_the_version_chain_head()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.execute_sql(
            "CREATE TABLE events (
                id BIGINT PRIMARY KEY,
                body TEXT NOT NULL
            )",
            &[],
        )?;
        seed.execute_sql("INSERT INTO events (id, body) VALUES (1, 'version-0')", &[])?;
        seed.commit()?;

        for version in 1..=32 {
            let mut delta =
                database.begin_optimistic_delta(version + 1, DurabilityClass::Memory)?;
            database.stage_delta_sql_dml(
                &mut delta,
                "UPDATE events SET body = ? WHERE id = ?",
                &[
                    SqlValue::Text(format!("version-{version}")),
                    SqlValue::Signed(1),
                ],
            )?;
            database.commit_optimistic(delta)?;
        }

        let mut delta = database.begin_optimistic_delta(40, DurabilityClass::Memory)?;
        database.stage_delta_sql_dml(
            &mut delta,
            "UPDATE events SET body = 'latest' WHERE id = 1",
            &[],
        )?;
        super::DELTA_LATEST_VERSION_PAGE_READS.set(0);
        database.commit_optimistic(delta)?;
        assert_eq!(super::DELTA_LATEST_VERSION_PAGE_READS.get(), 1);
        Ok(())
    }

    #[test]
    fn retained_historical_root_reads_only_its_visible_version_head()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let table = ObjectId::new(1)?;
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_relation(table, "events")?;
        seed.insert(table, b"key".to_vec(), b"version-0".to_vec())?;
        seed.commit()?;
        let historical = database.coordinator.snapshot(1)?;

        for version in 1..=32 {
            let mut update = database.begin(version + 1, DurabilityClass::Memory)?;
            update.update(
                table,
                b"key".to_vec(),
                format!("version-{version}").into_bytes(),
            )?;
            update.commit()?;
        }

        let root = historical
            .roots()
            .root(super::SLOT_RELATIONAL)
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        let encoded = BTree::from_root(root)
            .get(&database.pages, &super::relational_row_key(table, b"key"))?
            .ok_or(NativeRuntimeError::InvalidRelationalTree)?;
        super::DELTA_LATEST_VERSION_PAGE_READS.set(0);
        assert_eq!(
            super::decode_relational_chain_head(
                &database.pages,
                table,
                b"key",
                &encoded,
                historical.visible_csn,
                &database.blobs,
            )?,
            Some(b"version-0".to_vec())
        );
        assert_eq!(super::DELTA_LATEST_VERSION_PAGE_READS.get(), 1);
        Ok(())
    }

    #[test]
    fn hystrbt2_cleanup_coalesces_physical_copy_on_write_paths()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        for index in 0..512_u32 {
            let key = index.to_be_bytes().to_vec();
            seed.set(key.clone(), key, Some(10))?;
        }
        seed.commit()?;
        assert!(database.latest_structure_tree_height()? >= 2);
        let pages_before = database.pages.page_count();

        let cleanup = database.expire_due_structures(10, 64, DurabilityClass::Memory)?;
        let pages_appended = database
            .pages
            .page_count()
            .checked_sub(pages_before)
            .ok_or("cleanup page count regressed")?;

        assert_eq!(cleanup.expired_keys, 64);
        assert!(cleanup.more_due);
        assert!(
            pages_appended < u64::try_from(cleanup.expired_keys)?,
            "cleanup appended {pages_appended} pages for {} keys",
            cleanup.expired_keys
        );
        Ok(())
    }

    #[test]
    fn structure_compaction_drops_only_current_tombstones_and_retains_history()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.set(b"expired".to_vec(), b"gone".to_vec(), Some(10))?;
        seed.set(b"persistent".to_vec(), b"kept".to_vec(), None)?;
        seed.create_hash(b"profile".to_vec())?;
        seed.hset(b"profile".to_vec(), b"live".to_vec(), b"yes".to_vec())?;
        seed.hset(b"profile".to_vec(), b"dead".to_vec(), b"no".to_vec())?;
        seed.create_set(b"members".to_vec())?;
        seed.sadd(b"members".to_vec(), b"live".to_vec())?;
        seed.sadd(b"members".to_vec(), b"dead".to_vec())?;
        seed.create_list(b"queue".to_vec())?;
        seed.lpush(b"queue".to_vec(), b"gone".to_vec())?;
        seed.create_sorted_set(b"rank".to_vec())?;
        seed.zadd(b"rank".to_vec(), 1.0, b"live".to_vec())?;
        seed.zadd(b"rank".to_vec(), 2.0, b"dead".to_vec())?;
        seed.commit()?;

        let mut deletes = database.begin(2, DurabilityClass::Strict)?;
        assert!(deletes.hdelete(b"profile".to_vec(), b"dead".to_vec())?);
        assert!(deletes.srem(b"members".to_vec(), b"dead".to_vec())?);
        assert_eq!(deletes.lpop(b"queue".to_vec())?, Some(b"gone".to_vec()));
        assert!(deletes.zrem(b"rank".to_vec(), b"dead".to_vec())?);
        deletes.commit()?;
        database.expire_due_structures(10, 1, DurabilityClass::Strict)?;

        let before_snapshot = database.snapshot(100)?;
        let before_roots = before_snapshot.metadata.roots().clone();
        let before_structure_root = before_roots
            .root(super::SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let before_entries =
            hyphae_native_btree::BTree::from_root(before_structure_root).scan(&database.pages)?;
        let before_tombstones = before_entries
            .iter()
            .filter(|(key, value)| is_compactable_structure_tombstone(key, value))
            .count();
        assert_eq!(before_tombstones, 7);
        let file_bytes_before = fs::metadata(temporary.path().join(PAGE_FILE))?.len();

        let receipt = database.compact_structure(DurabilityClass::Strict)?;

        assert_eq!(receipt.scanned_entries, before_entries.len());
        assert_eq!(receipt.dropped_tombstones, before_tombstones);
        assert_eq!(
            receipt.retained_entries,
            before_entries.len() - before_tombstones
        );
        assert!(receipt.reachable_pages_before >= receipt.reachable_pages_after);
        assert!(receipt.reachable_pages_after > 0);
        assert!(receipt.pages_appended > 0);
        assert!(receipt.commit.is_some());
        let after_snapshot = database.snapshot(100)?;
        assert_eq!(after_snapshot.state, before_snapshot.state);
        let after_roots = after_snapshot.metadata.roots();
        for slot in super::ROOT_SLOTS {
            if slot == super::SLOT_STRUCTURE {
                assert_ne!(after_roots.root(slot), before_roots.root(slot));
            } else {
                assert_eq!(after_roots.root(slot), before_roots.root(slot));
            }
        }
        let after_structure_root = after_roots
            .root(super::SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        let after_entries =
            hyphae_native_btree::BTree::from_root(after_structure_root).scan(&database.pages)?;
        assert_eq!(after_entries.len(), receipt.retained_entries);
        assert!(
            after_entries
                .iter()
                .all(|(key, value)| !is_compactable_structure_tombstone(key, value))
        );
        assert_eq!(
            hyphae_native_btree::BTree::from_root(before_structure_root).scan(&database.pages)?,
            before_entries
        );
        assert!(fs::metadata(temporary.path().join(PAGE_FILE))?.len() > file_bytes_before);

        let csn_after_first = after_snapshot.visible_csn();
        let pages_after_first = database.pages.page_count();
        let no_op = database.compact_structure(DurabilityClass::Strict)?;
        assert_eq!(no_op.dropped_tombstones, 0);
        assert_eq!(no_op.pages_appended, 0);
        assert!(no_op.commit.is_none());
        assert_eq!(database.pages.page_count(), pages_after_first);
        assert_eq!(database.snapshot(100)?.visible_csn(), csn_after_first);
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        assert_eq!(reopened.snapshot(100)?.state, before_snapshot.state);
        let reopened_root = reopened
            .coordinator
            .snapshot(100)?
            .roots()
            .root(super::SLOT_STRUCTURE)
            .ok_or(NativeRuntimeError::InvalidCommittedRoot)?;
        assert!(
            hyphae_native_btree::BTree::from_root(reopened_root)
                .scan(&reopened.pages)?
                .iter()
                .all(|(key, value)| !is_compactable_structure_tombstone(key, value))
        );
        Ok(())
    }

    #[test]
    fn whole_hash_tombstones_compact_without_resurrecting_retired_fields()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let mut seed = database.begin(1, DurabilityClass::Strict)?;
        seed.create_hash(b"retired".to_vec())?;
        seed.hset(b"retired".to_vec(), b"first".to_vec(), b"one".to_vec())?;
        seed.hset(b"retired".to_vec(), b"second".to_vec(), b"two".to_vec())?;
        seed.commit()?;

        let mut replace = database.begin(2, DurabilityClass::Strict)?;
        assert!(replace.delete_hash(b"retired".to_vec())?);
        replace.set(b"retired".to_vec(), b"scalar".to_vec(), None)?;
        replace.commit()?;
        let receipt = database.compact_structure(DurabilityClass::Strict)?;
        assert_eq!(receipt.dropped_tombstones, 3);
        assert_eq!(
            database.get_latest_structure(b"retired", 3)?,
            Some(b"scalar".to_vec())
        );
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        assert_eq!(
            reopened.get_latest_structure(b"retired", 4)?,
            Some(b"scalar".to_vec())
        );
        assert!(matches!(
            reopened.hlen_latest_hash(b"retired"),
            Err(NativeRuntimeError::StructureKindMismatch)
        ));
        Ok(())
    }

    #[test]
    fn structure_compaction_is_noop_on_empty_and_rejects_legacy_without_writes()
    -> Result<(), Box<dyn std::error::Error>> {
        let empty_directory = TestDirectory::new();
        let mut empty = NativeDatabase::create(empty_directory.path())?;
        let empty_pages = empty.pages.page_count();
        let empty_receipt = empty.compact_structure(DurabilityClass::Strict)?;
        assert_eq!(
            empty_receipt,
            super::StructureCompactionReceipt {
                scanned_entries: 0,
                retained_entries: 0,
                dropped_tombstones: 0,
                reachable_pages_before: 0,
                reachable_pages_after: 0,
                pages_appended: 0,
                commit: None,
            }
        );
        assert_eq!(empty.pages.page_count(), empty_pages);
        assert_eq!(empty.snapshot(0)?.visible_csn(), None);

        let legacy_directory = TestDirectory::new();
        let mut legacy = NativeDatabase::create(legacy_directory.path())?;
        legacy.structure_format = super::StructureFormat::BTreeV1;
        let mut seed = legacy.begin(1, DurabilityClass::Strict)?;
        seed.set(b"legacy".to_vec(), b"value".to_vec(), None)?;
        seed.commit()?;
        let pages_before = legacy.pages.page_count();
        let csn_before = legacy.snapshot(2)?.visible_csn();
        assert!(matches!(
            legacy.compact_structure(DurabilityClass::Strict),
            Err(NativeRuntimeError::StructureCompactionUnsupported)
        ));
        assert_eq!(legacy.pages.page_count(), pages_before);
        assert_eq!(legacy.snapshot(2)?.visible_csn(), csn_before);
        Ok(())
    }

