    #[test]
    fn pending_commit_cancel_and_drop_release_retained_batch_memory()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let governor = Arc::new(NativeResourceGovernor::new(engine_admission_test_policy()));
        database.set_resource_governor_with_queue_wait(Arc::clone(&governor), Duration::ZERO)?;
        let scheduler =
            NativeCommitScheduler::start(database, GroupCommitConfig::new(4, Duration::ZERO, 4)?)?;
        let client = scheduler.client();
        let collection_guard = client.block_cohort_collection_for_test()?;

        let mut committed = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
        client.stage_delta_set(
            &mut committed,
            b"pending-committed".to_vec(),
            b"visible".to_vec(),
            None,
        )?;
        let committed = client.enqueue(committed)?;

        let mut cancelled = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
        client.stage_delta_set(
            &mut cancelled,
            b"pending-cancelled".to_vec(),
            b"absent".to_vec(),
            None,
        )?;
        let cancelled = client.enqueue(cancelled)?;
        assert_eq!(cancelled.cancel(), CommitCancellationOutcome::Cancelled);

        let mut dropped = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
        client.stage_delta_set(
            &mut dropped,
            b"pending-dropped".to_vec(),
            b"absent".to_vec(),
            None,
        )?;
        drop(client.enqueue(dropped)?);

        let failed = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
        let failed = client.enqueue(failed)?;
        assert!(governor.usage_snapshot().memory_bytes > 0);
        drop(collection_guard);

        assert_eq!(committed.wait()?.commit_csn, Csn::new(1)?);
        assert!(matches!(
            cancelled.wait(),
            Err(GroupCommitSubmitError::Cancelled)
        ));
        let Err(failed) = failed.wait() else {
            return Err("empty batch unexpectedly committed".into());
        };
        assert!(
            matches!(
                failed,
                GroupCommitSubmitError::Runtime { ref source }
                    if matches!(
                        source.as_ref(),
                        NativeRuntimeError::WalSemantic(_)
                            | NativeRuntimeError::InvalidPreparedMutation
                    )
            ),
            "unexpected empty-batch failure: {failed:?}"
        );
        scheduler.shutdown()?;
        assert_eq!(governor.usage_snapshot().compute_threads, 0);
        assert_eq!(governor.usage_snapshot().io_slots, 0);
        assert_eq!(governor.usage_snapshot().memory_bytes, 0);

        let reopened = NativeDatabase::open(temporary.path())?;
        assert_eq!(
            reopened.get_latest_structure(b"pending-committed", 2)?,
            Some(b"visible".to_vec())
        );
        assert_eq!(
            reopened.get_latest_structure(b"pending-cancelled", 2)?,
            None
        );
        assert_eq!(reopened.get_latest_structure(b"pending-dropped", 2)?, None);
        Ok(())
    }

    #[test]
    fn pending_commit_end_to_end_is_sealed_before_consumers_wait()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let database = NativeDatabase::create(temporary.path())?;
        let scheduler = NativeCommitScheduler::start(
            database,
            GroupCommitConfig::new(4, Duration::from_millis(1), 4)?,
        )?;
        let client = scheduler.client();
        let collection_guard = client.block_cohort_collection_for_test()?;
        let mut pending = Vec::with_capacity(4);
        for request_index in 0..4 {
            let mut batch = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
            client.stage_delta_set(
                &mut batch,
                format!("sealed-end-to-end-{request_index}").into_bytes(),
                b"visible".to_vec(),
                None,
            )?;
            pending.push(client.enqueue(batch)?);
        }
        drop(collection_guard);

        let completion_deadline = Instant::now() + Duration::from_secs(2);
        while pending.iter().any(|commit| !commit.completed_for_test()) {
            if Instant::now() >= completion_deadline {
                return Err("pending cohort did not complete".into());
            }
            std::thread::yield_now();
        }
        std::thread::sleep(Duration::from_millis(60));

        let consumer_elapsed = pending[0].submitted_at_for_test().elapsed();
        let mut end_to_end = Vec::with_capacity(pending.len());
        for commit in pending {
            end_to_end.push(commit.wait()?.end_to_end);
            std::thread::sleep(Duration::from_millis(30));
        }
        let minimum = end_to_end.iter().min().ok_or("missing end-to-end")?;
        let maximum = end_to_end.iter().max().ok_or("missing end-to-end")?;
        assert!(minimum.saturating_add(Duration::from_millis(40)) < consumer_elapsed);
        assert!(maximum.saturating_sub(*minimum) < Duration::from_millis(10));
        scheduler.shutdown()?;
        Ok(())
    }

    fn staged_group_delta_batches(
        client: &NativeCommitClient,
        logical_time_micros: i64,
        count: usize,
        prefix: &str,
    ) -> Result<Vec<NativeCommitBatch>, GroupCommitSubmitError> {
        let mut batches = Vec::with_capacity(count);
        for request_index in 0..count {
            let mut batch =
                client.begin_optimistic_delta(logical_time_micros, DurabilityClass::Group)?;
            client.stage_delta_set(
                &mut batch,
                format!("{prefix}-{request_index}").into_bytes(),
                b"visible".to_vec(),
                None,
            )?;
            batches.push(batch.into());
        }
        Ok(batches)
    }

    fn cohort_preparation_policy() -> NativeGovernorPolicy {
        let mut policy = engine_admission_test_policy();
        policy.schedulable_compute_threads = 2;
        policy.io_slots = 2;
        let mut mutation_limits = 0;
        for limit in &mut policy.class_limits {
            if limit.class == WorkloadClass::Mutation {
                limit.compute_threads = 2;
                limit.io_slots = 2;
                mutation_limits += 1;
            }
        }
        assert_eq!(mutation_limits, 1, "test policy mutation class drifted");
        policy
    }

    fn prepare_retained_cohort(
        client: &NativeCommitClient,
        concurrency: usize,
        prefix: &str,
    ) -> Result<Vec<NativeCommitBatch>, Box<dyn std::error::Error>> {
        const COHORT_SIZE: usize = 32;
        let start = Arc::new(Barrier::new(concurrency));
        let mut batches = std::thread::scope(|scope| {
            let producers = (0..concurrency)
                .map(|producer| {
                    let client = client.clone();
                    let start = Arc::clone(&start);
                    scope.spawn(move || {
                        start.wait();
                        (producer..COHORT_SIZE)
                            .step_by(concurrency)
                            .map(|position| {
                                let mut batch =
                                    client.begin_optimistic_delta(1, DurabilityClass::Group)?;
                                client.stage_delta_set(
                                    &mut batch,
                                    format!("{prefix}-{concurrency}-{position}").into_bytes(),
                                    b"visible".to_vec(),
                                    None,
                                )?;
                                client
                                    .retain_cohort_batch(batch)
                                    .map(|batch| (position, batch))
                            })
                            .collect::<Result<Vec<_>, _>>()
                    })
                })
                .collect::<Vec<_>>();
            producers
                .into_iter()
                .map(|producer| {
                    producer
                        .join()
                        .map_err(|_| "cohort preparation producer panicked")?
                        .map_err(Into::into)
                })
                .collect::<Result<Vec<Vec<_>>, Box<dyn std::error::Error>>>()
        })?
        .into_iter()
        .flatten()
        .collect::<Vec<_>>();
        batches.sort_unstable_by_key(|(position, _)| *position);
        if batches.len() != COHORT_SIZE
            || batches
                .iter()
                .enumerate()
                .any(|(position, (observed, _))| position != *observed)
        {
            return Err("retained cohort lost canonical order".into());
        }
        Ok(batches.into_iter().map(|(_, batch)| batch).collect())
    }

    #[test]
    fn explicit_cohort_preparation_releases_compute_and_io_at_c1_c8_c32()
    -> Result<(), Box<dyn std::error::Error>> {
        for concurrency in [1_usize, 8, 32] {
            let temporary = TestDirectory::new();
            let mut database = NativeDatabase::create(temporary.path())?;
            let governor = Arc::new(NativeResourceGovernor::new(cohort_preparation_policy()));
            database.set_resource_governor_with_queue_wait(
                Arc::clone(&governor),
                Duration::from_secs(2),
            )?;
            let scheduler = NativeCommitScheduler::start(
                database,
                GroupCommitConfig::new(32, Duration::ZERO, 32)?
                    .with_execution_admission_wait(Duration::from_secs(2))?,
            )?;
            let client = scheduler.client();
            let batches = prepare_retained_cohort(&client, concurrency, "retained-cohort")?;
            let retained = governor.usage_snapshot();
            assert_eq!(retained.compute_threads, 0, "{retained:?}");
            assert_eq!(retained.io_slots, 0, "{retained:?}");
            assert!(retained.memory_bytes > 0, "{retained:?}");

            let completions = client
                .enqueue_cohort(batches)?
                .into_iter()
                .map(NativePendingCommit::wait_with_evidence)
                .collect::<Result<Vec<_>, _>>()?;
            assert_eq!(completions.len(), 32);
            assert!(completions.iter().all(|completion| {
                completion.receipt.durability_cohort_size == 32
                    && completion.page_synchronizations == 1
                    && completion.wal_synchronizations == 1
            }));
            assert_eq!(
                completions
                    .iter()
                    .map(|completion| completion.receipt.durability_cohort_position)
                    .collect::<Vec<_>>(),
                (0..32).collect::<Vec<_>>()
            );
            scheduler.shutdown()?;
            assert_eq!(governor.usage_snapshot().compute_threads, 0);
            assert_eq!(governor.usage_snapshot().io_slots, 0);
            assert_eq!(governor.usage_snapshot().memory_bytes, 0);
        }
        Ok(())
    }

    #[test]
    fn retained_cohort_batches_are_idempotent_through_atomic_enqueue()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let governor = Arc::new(NativeResourceGovernor::new(cohort_preparation_policy()));
        database.set_resource_governor_with_queue_wait(
            Arc::clone(&governor),
            Duration::from_millis(200),
        )?;
        let scheduler = NativeCommitScheduler::start(
            database,
            GroupCommitConfig::new(32, Duration::ZERO, 32)?
                .with_execution_admission_wait(Duration::from_millis(200))?,
        )?;
        let client = scheduler.client();

        let mut valid = client.begin_optimistic_delta(1, DurabilityClass::Group)?;
        client.stage_delta_set(
            &mut valid,
            b"retained-idempotent".to_vec(),
            b"visible".to_vec(),
            None,
        )?;
        let retained = client.retain_cohort_batch(valid)?;
        let first_retention = governor.usage_snapshot();
        assert_eq!(first_retention.compute_threads, 0);
        assert_eq!(first_retention.io_slots, 0);
        assert!(first_retention.memory_bytes > 0);
        let retained = client.retain_cohort_batch(retained)?;
        assert_eq!(governor.usage_snapshot(), first_retention);

        let collection_guard = client.block_cohort_collection_for_test()?;
        let pending = client.enqueue_cohort(vec![retained])?;
        assert_eq!(governor.usage_snapshot(), first_retention);
        drop(collection_guard);
        assert_eq!(
            pending
                .into_iter()
                .next()
                .ok_or("missing pending")?
                .wait()?
                .commit_csn,
            Csn::new(1)?
        );
        assert_eq!(governor.usage_snapshot().memory_bytes, 0);
        scheduler.shutdown()?;
        let database = NativeDatabase::open(temporary.path())?;
        assert_eq!(
            database.get_latest_structure(b"retained-idempotent", 2)?,
            Some(b"visible".to_vec())
        );
        Ok(())
    }

