    fn seed_scaled_secondary_index(
        database: &mut NativeDatabase,
    ) -> Result<(ObjectId, ObjectId), Box<dyn std::error::Error>> {
        let mut transaction = database.begin_sql(10, DurabilityClass::Strict)?;
        let created = transaction.execute_sql(
            "CREATE TABLE people (
                id BIGINT PRIMARY KEY,
                email TEXT NOT NULL,
                name TEXT NOT NULL
            )",
            &[],
        )?;
        let SqlResult::Command {
            object_id: Some(table),
            ..
        } = created
        else {
            return Err("missing table identity".into());
        };
        for id in 0_i64..512 {
            let email = if matches!(id, 7 | 23 | 511) {
                "family@celiums.test".to_owned()
            } else {
                format!("person-{id:04}@celiums.test")
            };
            transaction.execute_sql(
                "INSERT INTO people (id, email, name) VALUES (?, ?, ?)",
                &[
                    SqlValue::Signed(id),
                    SqlValue::Text(email),
                    SqlValue::Text(format!("person-{id:04}")),
                ],
            )?;
        }
        let created =
            transaction.execute_sql("CREATE INDEX people_email ON people (email)", &[])?;
        let SqlResult::Command {
            object_id: Some(index),
            ..
        } = created
        else {
            return Err("missing secondary-index identity".into());
        };
        transaction.commit()?;
        Ok((table, index))
    }

    #[test]
    fn latest_sql_uses_exact_physical_secondary_index_without_materialized_state()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let (table, index) = seed_scaled_secondary_index(&mut database)?;
        assert!(database.latest_relational_tree_height()? >= 2);

        let query = "SELECT id, name FROM people WHERE email = ?";
        let parameters = [SqlValue::Text("family@celiums.test".to_owned())];
        let materialized = database.snapshot(11)?;
        let materialized_plan = materialized.prepare_sql(query)?;
        let expected = materialized.execute_prepared(&materialized_plan, &parameters)?;
        let physical_plan = database.prepare_sql_latest(query)?;
        assert_eq!(
            database.execute_prepared_latest(&physical_plan, &parameters)?,
            expected
        );
        assert_eq!(
            database.execute_prepared_latest(&physical_plan, &[SqlValue::Null])?,
            SqlResult::Rows {
                columns: vec!["id".to_owned(), "name".to_owned()],
                rows: Vec::new(),
            }
        );

        let index_key = parameters[0].encode_ordered_component(&LogicalType::Text)?;
        let physical_rows = database.select_latest_secondary_index(index, &index_key)?;
        assert_eq!(physical_rows.len(), 3);
        assert!(physical_rows.iter().all(|row| row.table == table));
        assert!(
            physical_rows
                .windows(2)
                .all(|rows| { rows[0].primary_key.as_slice() < rows[1].primary_key.as_slice() })
        );
        for row in &physical_rows {
            assert_eq!(
                database.select_latest_relational(table, &row.primary_key)?,
                Some(row.row.clone())
            );
        }
        assert!(matches!(
            database.select_latest_secondary_index(ObjectId::new(9_999)?, &index_key),
            Err(NativeRuntimeError::UnknownSecondaryIndex { index: missing })
                if missing == ObjectId::new(9_999)?
        ));

        let historical = database.snapshot(12)?;
        let mut catalog_change = database.begin_sql(13, DurabilityClass::Strict)?;
        catalog_change.execute_sql("CREATE TABLE audit (id BIGINT PRIMARY KEY, note TEXT)", &[])?;
        catalog_change.commit()?;
        assert!(matches!(
            database.execute_prepared_latest(&physical_plan, &parameters),
            Err(SqlError::CatalogChanged)
        ));
        assert_eq!(
            historical.execute_prepared(&physical_plan, &parameters)?,
            expected
        );
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        let reopened_plan = reopened.prepare_sql_latest(query)?;
        assert_eq!(
            reopened.execute_prepared_latest(&reopened_plan, &parameters)?,
            expected
        );
        assert_eq!(
            reopened.select_latest_secondary_index(index, &index_key)?,
            physical_rows
        );
        Ok(())
    }

    fn assert_latest_relational_range_contract(
        database: &NativeDatabase,
        table: ObjectId,
    ) -> Result<Vec<RelationalScanRow>, Box<dyn std::error::Error>> {
        let lower = 2_u32.to_be_bytes();
        let upper = 10_u32.to_be_bytes();
        let half_open = database.scan_latest_relational_range(
            table,
            Bound::Included(lower.as_slice()),
            Bound::Excluded(upper.as_slice()),
            16,
        )?;
        assert_eq!(
            half_open
                .iter()
                .map(|row| row.primary_key.clone())
                .collect::<Vec<_>>(),
            [2_u32, 4, 5, 6]
                .iter()
                .map(|index| index.to_be_bytes().to_vec())
                .collect::<Vec<_>>()
        );
        let mixed = database.scan_latest_relational_range(
            table,
            Bound::Excluded(lower.as_slice()),
            Bound::Included(upper.as_slice()),
            16,
        )?;
        assert_eq!(
            mixed
                .iter()
                .map(|row| row.primary_key.clone())
                .collect::<Vec<_>>(),
            [4_u32, 5, 6, 10]
                .iter()
                .map(|index| index.to_be_bytes().to_vec())
                .collect::<Vec<_>>()
        );
        let reversed = database.scan_latest_relational_range(
            table,
            Bound::Included(upper.as_slice()),
            Bound::Excluded(lower.as_slice()),
            16,
        )?;
        assert!(reversed.is_empty());
        Ok(half_open)
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn latest_relational_scan_is_bounded_resumable_and_skips_tombstones()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let table = ObjectId::new(77)?;
        let mut seed = database.begin(10, DurabilityClass::Strict)?;
        seed.create_relation(table, "events")?;
        for index in 0..512_u32 {
            seed.insert(
                table,
                index.to_be_bytes().to_vec(),
                format!("event-{index:04}").into_bytes(),
            )?;
        }
        seed.commit()?;
        assert!(database.latest_relational_tree_height()? >= 2);

        let mut mutation = database.begin(11, DurabilityClass::Strict)?;
        mutation.update(table, 2_u32.to_be_bytes().to_vec(), b"updated".to_vec())?;
        for index in [1_u32, 3, 7, 8, 9] {
            mutation.delete(table, index.to_be_bytes().to_vec())?;
        }
        mutation.commit()?;

        let first = database.scan_latest_relational(table, None, 5)?;
        assert_eq!(
            first
                .iter()
                .map(|row| row.primary_key.clone())
                .collect::<Vec<_>>(),
            [0_u32, 2, 4, 5, 6]
                .iter()
                .map(|index| index.to_be_bytes().to_vec())
                .collect::<Vec<_>>()
        );
        assert!(first.iter().all(|row| row.table == table));
        assert_eq!(first[1].row, b"updated");

        let cursor = first
            .last()
            .ok_or("missing first scan page")?
            .primary_key
            .clone();
        let second = database.scan_latest_relational(table, Some(&cursor), 4)?;
        assert_eq!(
            second
                .iter()
                .map(|row| row.primary_key.clone())
                .collect::<Vec<_>>(),
            [10_u32, 11, 12, 13]
                .iter()
                .map(|index| index.to_be_bytes().to_vec())
                .collect::<Vec<_>>()
        );
        assert!(database.scan_latest_relational(table, None, 0)?.is_empty());
        let half_open = assert_latest_relational_range_contract(&database, table)?;
        let segment_lower = 100_u32.to_be_bytes();
        let segment_upper = 400_u32.to_be_bytes();
        let segmented = database.scan_latest_relational_range_profiled(
            table,
            Bound::Included(segment_lower.as_slice()),
            Bound::Excluded(segment_upper.as_slice()),
            512,
        )?;
        assert_eq!(segmented.snapshot_csn, Some(Csn::new(2)?));
        assert_eq!(segmented.rows.len(), 300);
        assert!(segmented.planned_segments > 1);
        assert!(segmented.planned_physical_entries >= segmented.rows.len());
        assert!(segmented.planning.is_none());
        assert!(segmented.execution.is_none());
        assert_eq!(segmented.planned_workers, 1);
        assert_eq!(segmented.worker_batches, 0);
        assert_eq!(
            segmented.rows.first().map(|row| row.primary_key.as_slice()),
            Some(segment_lower.as_slice())
        );
        assert_eq!(
            segmented.rows.last().map(|row| row.primary_key.as_slice()),
            Some(399_u32.to_be_bytes().as_slice())
        );
        assert!(matches!(
            database.scan_latest_relational(ObjectId::new(9_999)?, None, 1),
            Err(NativeRuntimeError::UnknownRelation { table: missing })
                if missing == ObjectId::new(9_999)?
        ));

        let policy = parallel_engine_admission_test_policy();
        let profile = portable_execution_profile(&policy);
        let governor = Arc::new(NativeResourceGovernor::new(policy.clone()));
        let execution_pool = Arc::new(NativeExecutionPool::new(&profile, &policy)?);
        database.set_resource_governor_with_execution_pool(
            Arc::clone(&governor),
            Arc::clone(&execution_pool),
            Duration::ZERO,
        )?;
        let parallel = database.scan_latest_relational_range_profiled(
            table,
            Bound::Included(segment_lower.as_slice()),
            Bound::Excluded(segment_upper.as_slice()),
            512,
        )?;
        assert_eq!(parallel.rows, segmented.rows);
        let expected_workers = u64::try_from(parallel.planned_segments)?.min(4);
        assert_eq!(parallel.planned_workers, expected_workers);
        assert_eq!(u64::try_from(parallel.worker_batches)?, expected_workers);
        assert!(parallel.planning.is_some());
        let execution = parallel
            .execution
            .ok_or_else(|| std::io::Error::other("missing segment execution admission"))?;
        assert_eq!(execution.request.compute_threads, expected_workers);
        assert_eq!(execution.request.io_slots, expected_workers);
        assert_eq!(governor.usage_snapshot().compute_threads, 0);
        assert_eq!(governor.usage_snapshot().io_slots, 0);

        drop(database);
        let reopened = NativeDatabase::open(temporary.path())?;
        assert_eq!(reopened.scan_latest_relational(table, None, 5)?, first);
        assert_eq!(
            reopened.scan_latest_relational(table, Some(&cursor), 4)?,
            second
        );
        assert_eq!(
            reopened.scan_latest_relational_range(
                table,
                Bound::Included(2_u32.to_be_bytes().as_slice()),
                Bound::Excluded(10_u32.to_be_bytes().as_slice()),
                16,
            )?,
            half_open
        );
        Ok(())
    }

    fn seed_bounded_sql_scan(
        database: &mut NativeDatabase,
    ) -> Result<ObjectId, Box<dyn std::error::Error>> {
        let mut seed = database.begin_sql(10, DurabilityClass::Strict)?;
        let created = seed.execute_sql(
            "CREATE TABLE events (
                tenant BIGINT NOT NULL,
                sequence BIGINT NOT NULL,
                payload TEXT NOT NULL,
                PRIMARY KEY (tenant, sequence)
            )",
            &[],
        )?;
        let SqlResult::Command {
            object_id: Some(table),
            ..
        } = created
        else {
            return Err("missing events table identity".into());
        };
        for sequence in 0_i64..512 {
            seed.execute_sql(
                "INSERT INTO events (tenant, sequence, payload) VALUES (?, ?, ?)",
                &[
                    SqlValue::Signed(1),
                    SqlValue::Signed(sequence),
                    SqlValue::Text(format!("event-{sequence:04}")),
                ],
            )?;
        }
        assert_eq!(
            seed.execute_sql(
                "SELECT sequence, payload FROM events ORDER BY tenant, sequence LIMIT 2",
                &[],
            )?,
            SqlResult::Rows {
                columns: vec!["sequence".to_owned(), "payload".to_owned()],
                rows: vec![
                    vec![SqlValue::Signed(0), SqlValue::Text("event-0000".to_owned()),],
                    vec![SqlValue::Signed(1), SqlValue::Text("event-0001".to_owned()),],
                ],
            }
        );
        assert_eq!(
            seed.execute_sql(
                "EXPLAIN SELECT payload FROM events ORDER BY tenant, sequence LIMIT 5",
                &[],
            )?,
            SqlResult::Rows {
                columns: vec!["plan".to_owned()],
                rows: vec![vec![SqlValue::Text(format!(
                    "PrimaryKeyScan(table={table},limit=5)"
                ))]],
            }
        );
        seed.commit()?;
        Ok(table)
    }

    fn mutate_bounded_sql_scan(
        database: &mut NativeDatabase,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let mut mutation = database.begin_sql(11, DurabilityClass::Strict)?;
        mutation.execute_sql(
            "UPDATE events SET payload = ? WHERE tenant = ? AND sequence = ?",
            &[
                SqlValue::Text("updated".to_owned()),
                SqlValue::Signed(1),
                SqlValue::Signed(2),
            ],
        )?;
        for sequence in [1_i64, 3, 7, 8, 9] {
            mutation.execute_sql(
                "DELETE FROM events WHERE tenant = ? AND sequence = ?",
                &[SqlValue::Signed(1), SqlValue::Signed(sequence)],
            )?;
        }
        mutation.commit()?;
        Ok(())
    }

    fn expected_bounded_sql_scan() -> SqlResult {
        SqlResult::Rows {
            columns: vec!["sequence".to_owned(), "payload".to_owned()],
            rows: vec![
                vec![SqlValue::Signed(0), SqlValue::Text("event-0000".to_owned())],
                vec![SqlValue::Signed(2), SqlValue::Text("updated".to_owned())],
                vec![SqlValue::Signed(4), SqlValue::Text("event-0004".to_owned())],
                vec![SqlValue::Signed(5), SqlValue::Text("event-0005".to_owned())],
                vec![SqlValue::Signed(6), SqlValue::Text("event-0006".to_owned())],
            ],
        }
    }

    #[test]
    fn bounded_sql_scan_matches_transaction_snapshot_and_physical_execution()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let _table = seed_bounded_sql_scan(&mut database)?;
        let query = "SELECT sequence, payload FROM events ORDER BY tenant, sequence LIMIT 5";
        assert!(database.latest_relational_tree_height()? >= 2);
        mutate_bounded_sql_scan(&mut database)?;
        let expected = expected_bounded_sql_scan();
        let materialized = database.snapshot(12)?;
        let materialized_plan = materialized.prepare_sql(query)?;
        assert_eq!(
            materialized.execute_prepared(&materialized_plan, &[])?,
            expected
        );
        let physical_plan = database.prepare_sql_latest(query)?;
        assert_eq!(
            database.execute_prepared_latest(&physical_plan, &[])?,
            expected
        );
        assert_eq!(
            database.execute_prepared_latest(
                &database.prepare_sql_latest("SELECT sequence, payload FROM events LIMIT 5")?,
                &[],
            )?,
            expected
        );
        assert_eq!(
            database.execute_prepared_latest(
                &database.prepare_sql_latest("SELECT payload FROM events LIMIT 0")?,
                &[],
            )?,
            SqlResult::Rows {
                columns: vec!["payload".to_owned()],
                rows: Vec::new(),
            }
        );
        assert!(matches!(
            database
                .prepare_sql_latest("SELECT payload FROM events ORDER BY sequence, tenant LIMIT 5"),
            Err(SqlError::InvalidPrimaryKey)
        ));
        assert!(matches!(
            database.execute_prepared_latest(&physical_plan, &[SqlValue::Signed(1)]),
            Err(SqlError::ParameterMismatch)
        ));

        let mut catalog_change = database.begin_sql(13, DurabilityClass::Strict)?;
        catalog_change.execute_sql("CREATE TABLE audit (id BIGINT PRIMARY KEY)", &[])?;
        catalog_change.commit()?;
        assert!(matches!(
            database.execute_prepared_latest(&physical_plan, &[]),
            Err(SqlError::CatalogChanged)
        ));
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        let reopened_plan = reopened.prepare_sql_latest(query)?;
        assert_eq!(
            reopened.execute_prepared_latest(&reopened_plan, &[])?,
            expected
        );
        Ok(())
    }

    #[test]
    fn vectorized_sql_scan_matches_scalar_oracle_and_uses_governed_pool()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        seed_bounded_sql_scan(&mut database)?;
        mutate_bounded_sql_scan(&mut database)?;
        let query = "SELECT sequence, payload FROM events
            WHERE tenant = ? AND payload != ?
            ORDER BY tenant, sequence LIMIT 400";
        let parameters = [SqlValue::Signed(1), SqlValue::Text("event-0256".to_owned())];
        let materialized = database.snapshot(12)?;
        let scalar_plan = materialized.prepare_sql(query)?;
        let expected = materialized.execute_prepared(&scalar_plan, &parameters)?;
        let SqlResult::Rows { rows, .. } = &expected else {
            return Err("expected scalar rows".into());
        };
        assert_eq!(rows.len(), 400);

        let physical_plan = database.prepare_sql_latest(query)?;
        let serial = database.execute_prepared_latest_profiled(&physical_plan, &parameters)?;
        assert_eq!(serial.result, expected);
        assert_eq!(serial.path, super::NativeSqlExecutionPath::VectorizedSerial);
        assert_eq!(serial.vector_batches, 1);
        assert!(serial.candidate_rows >= 400);
        assert_eq!(serial.planned_workers, 1);
        assert_eq!(serial.worker_batches, 0);

        let small_plan = database
            .prepare_sql_latest("SELECT sequence FROM events ORDER BY tenant, sequence LIMIT 16")?;
        let small = database.execute_prepared_latest_profiled(&small_plan, &[])?;
        assert_eq!(small.path, super::NativeSqlExecutionPath::Direct);
        assert_eq!(small.candidate_rows, 16);
        assert_eq!(small.vector_batches, 0);

        let policy = parallel_engine_admission_test_policy();
        let profile = portable_execution_profile(&policy);
        let governor = Arc::new(NativeResourceGovernor::new(policy.clone()));
        let execution_pool = Arc::new(NativeExecutionPool::new(&profile, &policy)?);
        database.set_resource_governor_with_execution_pool(
            Arc::clone(&governor),
            Arc::clone(&execution_pool),
            Duration::ZERO,
        )?;
        let parallel = database.execute_prepared_latest_profiled(&physical_plan, &parameters)?;
        assert_eq!(parallel.result, expected);
        assert_eq!(
            parallel.path,
            super::NativeSqlExecutionPath::VectorizedParallel
        );
        assert_eq!(parallel.vector_batches, serial.vector_batches);
        assert_eq!(parallel.candidate_rows, serial.candidate_rows);
        assert_eq!(parallel.planned_workers, 2);
        assert_eq!(parallel.worker_batches, 2);
        let execution = parallel
            .execution
            .ok_or_else(|| std::io::Error::other("missing SQL execution admission"))?;
        assert_eq!(execution.class, WorkloadClass::ForegroundBounded);
        assert_eq!(execution.request.compute_threads, 2);
        assert_eq!(execution.request.io_slots, 2);
        assert_eq!(governor.usage_snapshot().compute_threads, 0);
        assert_eq!(governor.usage_snapshot().io_slots, 0);
        assert_eq!(governor.usage_snapshot().memory_bytes, 0);
        Ok(())
    }

    #[test]
    fn vectorized_sql_scan_observes_deterministic_mid_execution_cancellation()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        seed_bounded_sql_scan(&mut database)?;
        let plan = database.prepare_sql_latest(
            "SELECT sequence FROM events ORDER BY tenant, sequence LIMIT 400",
        )?;
        let mut checkpoints = 0_usize;
        let result = database.execute_prepared_latest_profiled_with_checkpoint(&plan, &[], || {
            checkpoints = checkpoints.saturating_add(1);
            checkpoints < 40
        });
        assert!(matches!(result, Err(SqlError::ExecutionInterrupted)));
        assert_eq!(checkpoints, 40);
        Ok(())
    }

    const SECONDARY_INTERSECTION_QUERY: &str = "SELECT id FROM events
        WHERE tenant = ? AND active = ?
        ORDER BY id LIMIT 10";

    fn secondary_intersection_parameters() -> [SqlValue; 2] {
        [SqlValue::Text("alpha".to_owned()), SqlValue::Boolean(true)]
    }

    fn expected_secondary_intersection() -> SqlResult {
        SqlResult::Rows {
            columns: vec!["id".to_owned()],
            rows: vec![
                vec![SqlValue::Signed(1)],
                vec![SqlValue::Signed(4)],
                vec![SqlValue::Signed(5)],
            ],
        }
    }

    fn seed_secondary_intersection(
        database: &mut NativeDatabase,
    ) -> Result<ObjectId, Box<dyn std::error::Error>> {
        let mut seed = database.begin_sql(20, DurabilityClass::Strict)?;
        let SqlResult::Command {
            object_id: Some(table),
            ..
        } = seed.execute_sql(
            "CREATE TABLE events (
                id BIGINT PRIMARY KEY,
                tenant TEXT NOT NULL,
                active BOOLEAN NOT NULL
            )",
            &[],
        )?
        else {
            return Err("missing events table".into());
        };
        for (id, tenant, active) in [
            (1_i64, "alpha", true),
            (2, "alpha", false),
            (3, "beta", true),
            (4, "alpha", true),
            (5, "alpha", true),
        ] {
            seed.execute_sql(
                "INSERT INTO events (id, tenant, active) VALUES (?, ?, ?)",
                &[
                    SqlValue::Signed(id),
                    SqlValue::Text(tenant.to_owned()),
                    SqlValue::Boolean(active),
                ],
            )?;
        }
        let SqlResult::Command {
            object_id: Some(tenant_index),
            ..
        } = seed.execute_sql("CREATE INDEX events_tenant ON events (tenant)", &[])?
        else {
            return Err("missing tenant index".into());
        };
        let SqlResult::Command {
            object_id: Some(active_index),
            ..
        } = seed.execute_sql("CREATE INDEX events_active ON events (active)", &[])?
        else {
            return Err("missing active index".into());
        };
        assert_eq!(
            seed.execute_sql(
                SECONDARY_INTERSECTION_QUERY,
                &secondary_intersection_parameters(),
            )?,
            expected_secondary_intersection()
        );
        assert_eq!(
            seed.execute_sql(
                "EXPLAIN SELECT id FROM events
                 WHERE tenant = 'alpha' AND active = TRUE
                 ORDER BY id LIMIT 10",
                &[],
            )?,
            SqlResult::Rows {
                columns: vec!["plan".to_owned()],
                rows: vec![vec![SqlValue::Text(format!(
                    "SecondaryIndexIntersection(table={table},indexes=[{tenant_index},{active_index}],limit=10)",
                ))]],
            }
        );
        seed.commit()?;
        Ok(table)
    }

    #[test]
    fn secondary_index_intersection_matches_every_executor_and_prefers_composite_key()
    -> Result<(), Box<dyn std::error::Error>> {
        let temporary = TestDirectory::new();
        let mut database = NativeDatabase::create(temporary.path())?;
        let table = seed_secondary_intersection(&mut database)?;
        let parameters = secondary_intersection_parameters();
        let expected = expected_secondary_intersection();

        let snapshot = database.snapshot(21)?;
        let snapshot_plan = snapshot.prepare_sql(SECONDARY_INTERSECTION_QUERY)?;
        assert_eq!(
            snapshot.execute_prepared(&snapshot_plan, &parameters)?,
            expected
        );
        let latest_plan = database.prepare_sql_latest(SECONDARY_INTERSECTION_QUERY)?;
        let intersection = database.execute_prepared_latest_profiled(&latest_plan, &parameters)?;
        assert_eq!(intersection.result, expected);
        assert_eq!(
            intersection.path,
            super::NativeSqlExecutionPath::IndexIntersection
        );
        assert_eq!(intersection.candidate_rows, 3);
        assert_eq!(intersection.index_stream_rows, 8);
        assert_eq!(intersection.intersection_start_rows, 4);
        assert_eq!(intersection.vector_batches, 0);
        assert_eq!(
            database.execute_prepared_latest(
                &latest_plan,
                &[SqlValue::Text("alpha".to_owned()), SqlValue::Null],
            )?,
            SqlResult::Rows {
                columns: vec!["id".to_owned()],
                rows: Vec::new(),
            }
        );

        let mut composite = database.begin_sql(22, DurabilityClass::Strict)?;
        let SqlResult::Command {
            object_id: Some(composite_index),
            ..
        } = composite.execute_sql(
            "CREATE INDEX events_tenant_active ON events (tenant, active)",
            &[],
        )?
        else {
            return Err("missing composite index".into());
        };
        assert_eq!(
            composite.execute_sql(
                "EXPLAIN SELECT id FROM events
                 WHERE tenant = 'alpha' AND active = TRUE
                 ORDER BY id LIMIT 10",
                &[],
            )?,
            SqlResult::Rows {
                columns: vec!["plan".to_owned()],
                rows: vec![vec![SqlValue::Text(format!(
                    "SecondaryIndexLookup(table={table},index={composite_index},limit=10)",
                ))]],
            }
        );
        composite.commit()?;
        assert!(matches!(
            database.execute_prepared_latest(&latest_plan, &parameters),
            Err(SqlError::CatalogChanged)
        ));
        drop(database);

        let reopened = NativeDatabase::open(temporary.path())?;
        let reopened_plan = reopened.prepare_sql_latest(SECONDARY_INTERSECTION_QUERY)?;
        assert_eq!(
            reopened.execute_prepared_latest(&reopened_plan, &parameters)?,
            expected
        );
        Ok(())
    }

